  str_homestory_800601001_10_dialog_content = "แต่ทำไมคนที่แข็งแรงและมีพลังทำสิ่งต่าง ๆ ได้ ถึงต้องพึ่งพา \"การภาวนา\" ด้วยล่ะ?",
