  str_homestory_800601001_28_dialog_content = "ฉันรู้สึกขอบคุณมากที่มีเพื่อน ๆ เหล่านี้",
  str_homestory_800601001_29_dialog_content = "จริงด้วย! โชคดีที่เรามีกันและกันในการเดินทางครั้งนี้",
