  str_homestory_800601001_33_dialog_content = "ไม่มีสงคราม ไม่มีเจ้าชายและขุนนางนิสัยแย่ ทุกอย่างเงียบสงบ",
  str_homestory_800601001_34_dialog_content = "ถ้างั้นฉันไปแล้วดีกว่า ขอให้เพลิดเพลินกับการใช้เวลาตามลำพังนะ",
