  str_homestory_800201001_21_dialog_content = "พูดอีกอย่างก็คือ การสวดภาวนาที่นี่ช่วยให้เราเข้าใจความปรารถนาของตัวเองมากขึ้น",
  str_homestory_800201001_22_dialog_content = "อ๋อ...เข้าใจแล้ว",
  str_homestory_800201001_23_dialog_content = "เหมือนการตามหา \"ภารกิจที่เราอยากทำให้สำเร็จ\" อะไรประมาณนั้นใช่มั้ยครับ?",
  str_homestory_800201001_24_dialog_content = "ใช่แล้ว",
  str_homestory_800201001_25_dialog_content = "แล้ว... คุณเจอหรือยังครับ?",
  str_homestory_800201001_26_dialog_content = "เจอแล้วล่ะ",
  str_homestory_800201001_27_dialog_content = "แม้ว่า \"คำภาวนา\" นี้จะไม่ชัดเจนอย่างที่คิด... แต่อย่างน้อยฉันก็เจอเส้นทางของตัวเอง",
  str_homestory_800201001_28_dialog_content = "คุณรู้มาก่อนแล้วไม่ใช่เหรอ ว่าตัวเองจะต้องไปทางไหน?",
