  str_homestory_800201001_34_dialog_content = "สำหรับผู้ที่ดิ้นรนหาเลี้ยงชีพ การสวดภาวนาคือปัจจัยยังชีพให้มีชีวิตต่อไป",
  str_homestory_800201001_35_dialog_content = "นั่นคือเหตุผลว่าทำไมน้ำพุแห่งความหวังถึงสำคัญ",
  str_homestory_800201001_36_dialog_content = "เธอกับไวซ์พยายามอย่างหนักเพื่อสร้างสถานที่แห่งนี้",
