  str_homestory_800201001_38_dialog_content = "ฉันจะไม่รบกวนเวลาอันมีค่าของนายไปมากกว่านี้แล้ว ไปสวดภาวนาเถอะ PlayerName",
  str_homestory_800201001_39_dialog_content = "แล้วเจอกัน",
  str_homestory_800201001_40_dialog_content = "เอ่อ... ครับ ผู้บัญชาการฮิอิโระ!",
