  str_homestory_802501001_19_dialog_content = "ผลงานอินดี้มักได้รับการชื่นชมจากผู้ที่มีความสนใจพิเศษเพียงไม่กี่คนเท่านั้น!",
  str_homestory_802501001_20_dialog_content = "อย่างไรก็ตาม ผมเชื่อว่าละครของคุณน่าจะเหมาะกับตอนกลางคืนอันเงียบสงัดมากกว่า",
