  str_homestory_802501001_22_option_content = "ปฏิเสธ",
  str_homestory_802501001_23_dialog_content = "ฉันจะทำยังไงดี?",
  str_homestory_802501001_24_dialog_content = "การปฏิเสธอย่างเย็นชาของนาย เพิ่งจุดประกายไอเดียในหัวของฉัน!",
  str_homestory_802501001_25_dialog_content = "ไอเดียที่เชื่อมโยงกันกำลังคำรามและดิ่งลึกลงไปในจิตวิญญาณของฉันราวกับม้าพยศ!",
  str_homestory_802501001_26_dialog_content = "เสียงคำรามคืออะไร? มันคือศิลปะ! มันคือการแสดงที่อยู่เหนือการควบคุม...",
