  str_homestory_802501001_34_dialog_content = "...",
  str_homestory_810501001_0_dialog_content = "เธอนี่งานยุ่งมากเลยนะเนี่ย อีฟ!",
  str_homestory_810501001_1_dialog_content = "ดีใจจังที่ได้เจอคุณนะ ผู้นำทาง! <sprite=emo_aixin size=60 />",
  str_homestory_810501001_2_dialog_content = "เดี๋ยวฉันจะไปหาคุณนะ แต่ตอนนี้ต้องคิดก่อนว่ายังต้องการอะไรอีก...",
