  str_homestory_810501001_4_dialog_content = "ถ้าเธอต้องการอะไร ฉันอาจจะช่วยได้นะ",
  str_homestory_810501001_5_dialog_content = "โอ้...อย่าพูดอย่างนั้นเลย คุณเตรียมช่วยเรามามากแล้วล่ะ!",
