  str_homestory_810501001_7_dialog_content = "แค่กำลังคิดว่าจะใช้สีอะไรสำหรับดอกไม้ปักผ้า แล้วก็ที่ใส่กระติกน้ำ",
  str_homestory_810501001_8_dialog_content = "ดอกไม้ปักผ้า? ที่ใส่กระติกน้ำ?",
  str_homestory_810501001_9_dialog_content = "ใช่",
  str_homestory_810501001_10_dialog_content = "ฉันจะทำชุดให้ดอว์น<sprite=emo_qunzi size=60 /> และฉันก็อยากปักดอกรุ่งอรุณบนผ้านิดหน่อย...",
  str_homestory_810501001_11_dialog_content = "อืมม... ที่ใส่กระติกน้ำ... คุณรู้ใช่มั้ยว่าพี่ชายพกกระติกน้ำติดตัวเสมอเพื่อให้ฉันดื่ม...",
  str_homestory_810501001_12_dialog_content = "ที่ใส่กระติกน้ำน่ารัก ๆ สักอันน่าจะเป็นของขวัญที่เหมาะมาก",
  str_homestory_810501001_13_dialog_content = "ฮี่ฮี่ คุณคิดว่าไง ผู้นำทาง?",
  str_homestory_810501001_14_dialog_content = "เยี่ยมมาก!",
  str_homestory_810501001_15_dialog_content = "นี่เป็นของขวัญที่ตั้งใจคิดมาอย่างดี ฉันมั่นใจว่าดอว์นกับพี่ชายของเธอจะต้องดีใจแน่ ๆ",
  str_homestory_810501001_16_dialog_content = "อื้ม! ดีใจจังที่ได้ยินแบบนี้...",
  str_homestory_810501001_17_dialog_content = "แล้ว... ฉันควรเลือกสีอะไรดีล่ะ?",
  str_homestory_810501001_18_dialog_content = "ดอกรุ่งอรุณมักจะเป็นสีขาว แต่ฉันรู้สึกว่าถ้าใช้สีอื่นน่าจะน่าสนใจกว่า",
  str_homestory_810501001_19_dialog_content = "ส่วนที่ใส่กระติกน้ำ ฉันก็เลือกไม่ถูกเหมือนกันว่าจะเอาสีแดงหรือสีดำ พี่ชายจะชอบสีไหนนะ?",
  str_homestory_810501001_20_dialog_content = "เฮ้อ... เลือกยากจัง",
  str_homestory_810501001_21_dialog_content = "อืมม...",
  str_homestory_810501001_22_dialog_content = "แล้วชุดที่ตั้งใจจะให้ดอว์นเป็นสีอะไรเหรอ?",
  str_homestory_810501001_23_dialog_content = "สีดำ!",
  str_homestory_810501001_24_dialog_content = "ฉันว่าดอกรุ่งอรุณสีขาวน่าจะเข้ามาก ๆ เลย",
  str_homestory_810501001_25_dialog_content = "ลองทำลวดลายที่นูนขึ้นจากบนผ้าสิ ดอว์นจะได้สัมผัสถึงดอกรุ่งอรุณด้วยมือของเธอไงล่ะ",
  str_homestory_810501001_26_dialog_content = "ยกดอกรุ่งอรุณสีขาวขึ้น...",
  str_homestory_810501001_27_dialog_content = "อ๋า... เป็นความคิดที่ยอดไปเลย!",
  str_homestory_810501001_28_dialog_content = "ยินดีที่ได้ช่วยนะ",
  str_homestory_810501001_29_dialog_content = "แล้วที่ใส่กระติกน้ำของพี่ชายฉันล่ะ? ผู้นำทางมีคำแนะนำอะไรไหม?",
  str_homestory_810501001_30_option_content = "มีสิ",
  str_homestory_810501001_31_dialog_content = "ถ้าเธอตัดสินใจเลือกระหว่างสองสีนี้ไม่ได้ ทำไมไม่ทำลายหมากรุกสีแดงดำซะเลยล่ะ?",
  str_homestory_810501001_32_dialog_content = "แต่ว่า อีฟ...",
  str_homestory_810501001_33_option_content = "คิดไม่ออกแฮะ",
  str_homestory_810501001_34_dialog_content = "อีฟ ที่จริงแล้ว...",
  str_homestory_810501001_35_dialog_content = "ไม่ว่าเธอจะให้อะไรกับซินซา เขาก็ดีใจทั้งนั้นแหละ",
  str_homestory_810501001_36_dialog_content = "แม้แต่ใบไม้ที่บังเอิญเก็บได้ หรือทรายแค่หยิบกำมือจากเธอ เขาก็ถือว่าสิ่งเหล่านั้นเป็นสมบัติล้ำค่าแล้ว",
  str_homestory_810501001_37_dialog_content = "อืมม...",
  str_homestory_810501001_38_dialog_content = "ฉันก็คิดอย่างนั้นเหมือนกัน...",
  str_homestory_810501001_39_dialog_content = "ถ้าอย่างนั้น ฉันจะเลือกที่ตัวเองชอบละกัน อิอิ",
  str_homestory_810501001_40_dialog_content = "อื้ม... ฉันว่าก็ได้นะ",
  str_homestory_810501001_41_dialog_content = "อีฟ... เธอพยายามหาของขวัญให้ดอว์นกับซินซาแบบนี้ แล้วไม่มีให้ตัวเองบ้างเหรอ?",
  str_homestory_810501001_42_dialog_content = "หืม? โทษทีนะผู้นำทาง ฉันไม่ค่อยเข้าใจน่ะ...",
  str_homestory_810501001_43_dialog_content = "ฉันต้องเตรียมอะไรให้ตัวเองงั้นเหรอ?",
  str_homestory_810501001_44_dialog_content = "เอ่อ... ฉันหมายถึง...",
  str_homestory_810501001_45_dialog_content = "คืองี้นะ ก่อนหน้านี้ที่เธอขอดินที่มีสารอาหารอุดมสมบูรณ์ และขอเมล็ดดอกรุ่งอรุณจากฉัน ทั้งหมดนั่นก็เพื่อดอว์นไม่ใช่เหรอ?",
  str_homestory_810501001_46_dialog_content = "เพื่อที่เธอจะได้ปลูกดอกไม้ที่นี่อย่างมีความสุข",
  str_homestory_810501001_47_dialog_content = "และเธอก็ยังสั่งขนมเรดีเซล เวรนช์จากไวซ์ เพราะเป็นห่วงว่าซินซาจะไม่มีอะไรกินกับเครื่องดื่มของเขา",
  str_homestory_810501001_48_dialog_content = "โอ๊ะ... ผู้นำทางรู้ทุกอย่างซะแล้วสิ...",
  str_homestory_810501001_49_dialog_content = "คุณพูดถูก",
  str_homestory_810501001_50_dialog_content = "แต่ว่า...",
  str_homestory_810501001_51_dialog_content = "ทำไมถึงไม่เตรียมอะไรให้ตัวเองบ้างล่ะ?",
  str_homestory_810501001_52_dialog_content = "อืมม... ฉันเตรียมทั้งหมดนี้สำหรับดอว์นและพี่ชาย เพื่อให้พวกเขาอยู่ที่นี่อย่างมีความสุขก็เท่านั้น",
  str_homestory_810501001_53_dialog_content = "แค่ได้อยู่กับพวกเขาฉันก็มีความสุขมากพอแล้ว",
  str_homestory_810501001_54_dialog_content = "อ้อ... รวมถึงคุณกับไวซ์ด้วยนะ!",
  str_homestory_810501001_55_dialog_content = "แค่มีพวกคุณอยู่ก็ทำให้ฉันมีความสุขแล้วล่ะ!",
  str_homestory_810501001_56_dialog_content = "ฉันไม่จำเป็นต้องให้ของขวัญตัวเองหรอก",
  str_homestory_810501001_57_dialog_content = "งั้นเหรอ?",
  str_homestory_810501001_58_dialog_content = "เธอนี่ใจดีและน่ารักจริง ๆ นะ...",
  str_homestory_810501001_59_dialog_content = "คุณก็เหมือนกันนั่นแหละ ผู้นำทาง!",
  str_homestory_810501001_60_dialog_content = "ฮือ-ฮือ...",
  str_homestory_810501001_61_dialog_content = "เป็นอะไรไปเหรอ?",
  str_homestory_810501001_62_dialog_content = "ผู้นำทาง ทำไมจู่ ๆ ถึงร้องไห้ล่ะ?",
  str_homestory_810501001_63_dialog_content = "*สะอื้น* ฉันอยากมีน้องสาวเหมือนอีฟบ้างจัง...<sprite=emo_daku size=60 />",
  str_homestory_811201001_0_dialog_content = "สโมกกี้?",
  str_homestory_811201001_1_dialog_content = "เกิดอะไรขึ้นเหรอ สโมกกี้?",
  str_homestory_811201001_2_dialog_content = "คุณ ท่าทางโมโหจัดเลย",
  str_homestory_811201001_3_dialog_content = "นี่ ผู้นำทาง",
  str_homestory_811201001_4_dialog_content = "นายคิดว่าร้านนี้มีของให้เลือกน้อยไปรึเปล่า?<sprite=emo_shengqi size=60 />",
  str_homestory_811201001_5_dialog_content = "อ๋อ! กำลังโกรธเรื่องนี้อยู่เหรอ?",
  str_homestory_811201001_6_dialog_content = "คุณคิดว่าที่ร้านยังขาดอะไรอีกล่ะ? ลองบอกผมมาสิ",
  str_homestory_811201001_7_dialog_content = "แน่ใจนะว่านายอยากได้ยินน่ะ?",
  str_homestory_811201001_8_dialog_content = "แน่ใจสิ ว่ามาเลย",
  str_homestory_811201001_9_dialog_content = "งั้นฉันจะเข้าประเด็นเลยแล้วกัน",
  str_homestory_811201001_10_dialog_content = "อย่างแรกเลย ที่ร้านไม่มีน้ำยาทำความสะอาดเครื่องประดับ",
  str_homestory_811201001_11_dialog_content = "สอง สไตล์ของกระดุมในร้านนี่ห่วยสุด ๆ!",
  str_homestory_811201001_12_dialog_content = "เชื่อฉันเหอะ ไม่มีใครอยากเอาไปติดไว้บนเสื้อผ้าตัวเองแน่",
  str_homestory_811201001_13_dialog_content = "อ้อ ไม่แน่ พวกอิลลูมินาอาจจะชอบก็ได้",
  str_homestory_811201001_14_dialog_content = "กระดุม... แค่ใช้งานได้ก็พอแล้วไม่ใช่เหรอ...",
  str_homestory_811201001_15_dialog_content = "จะโทษนายคงไม่ได้ ยังไงนายก็ไม่ค่อยรู้เรื่องแฟชั่นอยู่แล้ว",
  str_homestory_811201001_16_dialog_content = "แต่อย่าท้อใจไป เดี๋ยวฉันจะสอนนายเอง",
  str_homestory_811201001_17_dialog_content = "ขอบคุณนะ...",
  str_homestory_811201001_18_dialog_content = "อีกอย่าง ที่นี่ร้อนแล้วก็แดดจ้ายิ่งกว่าอัมบราตันซะอีก",
  str_homestory_811201001_19_dialog_content = "ถึงจะมีร่ม แต่แว่นกับครีมกันแดดล่ะ? ไม่มีเลยสักอย่าง!",
  str_homestory_811201001_20_dialog_content = "อืม คุณพูดถูก...",
  str_homestory_811201001_21_dialog_content = "(สโมกกี้ไม่ใช่ออโรเรียนเพียงคนเดียวที่ขาดของใช้ที่ตัวเองต้องการ)",
  str_homestory_811201001_22_dialog_content = "(ฉันควรทำยังไงดี? ถ้าไล่ถามทีละคนคงเสียเวลามากแน่ ๆ...)",
  str_homestory_811201001_23_dialog_content = "เฮ้ พึมพำอะไรของนายน่ะ?",
  str_homestory_811201001_24_dialog_content = "ฉันเรื่องมากเกินไปรึเปล่า? กลัวว่าจะมีนักช้อปที่จู้จี้แบบฉันอีกงั้นเหรอ?",
  str_homestory_811201001_25_option_content = "พยักหน้า",
  str_homestory_811201001_26_dialog_content = "ดี ยอมรับตรง ๆ ก็ดีเหมือนกัน",
  str_homestory_811201001_27_dialog_content = "ผมไม่ได้มีปัญหากับคุณนะ แค่กังวลใจมากกว่า...",
  str_homestory_811201001_28_option_content = "ส่ายหัว",
  str_homestory_811201001_29_dialog_content = "เปล่า สโมกกี้ ผมไม่มีปัญหาอะไร...",
  str_homestory_811201001_30_dialog_content = "ที่จริง ประเด็นไม่ได้อยู่ที่ว่าคุณเรื่องมากหรืออะไรแบบนั้นด้วยซ้ำ",
  str_homestory_811201001_31_dialog_content = "ในอนาคตอาจจะมีคนที่ประสบปัญหาเหมือนกับคุณ แต่ผมไม่รู้ว่าจะจัดการยังไงดี...",
  str_homestory_811201001_32_dialog_content = "...นายต้องพัฒนาระบบสั่งซื้อสินค้าให้กับอีราเวล",
  str_homestory_811201001_33_dialog_content = "ทุกคนสามารถสั่งของที่ต้องการในระบบได้เรื่อย ๆ จากนั้นก็เอาใบสั่งไปซื้อของจากพ่อค้าแม่ค้าทั่วแอสตรา",
  str_homestory_811201001_34_dialog_content = "ส่วนการส่งสินค้า... ฉันว่านายคงรู้อยู่แล้วล่ะว่าจะใช้อะไร",
  str_homestory_811201001_35_dialog_content = "สหภาพผู้ส่งสาร<sprite=emo_gezitou size=60 /> หิ่งห้อยอะไรพวกนั้น",
  str_homestory_811201001_36_dialog_content = "อ๋า... เป็นความคิดที่ดี...",
  str_homestory_811201001_37_dialog_content = "ถ้าทำอย่างนี้ นายก็ไม่ต้องไล่ถามพวกเราทีละคน แล้วก็ไม่ต้องมาฟังคำติแบบฉันไงล่ะ",
  str_homestory_811201001_38_dialog_content = "นายรู้ไหมว่าออโรเรียนบางคนค่อนข้างพิเศษ",
  str_homestory_811201001_39_dialog_content = "บางคนอาจจะชอบโลงศพ บางคนอาจจะชอบแปรงทาสีทุกแบบ หรือบางคนอาจจะชอบแมลงแปลก ๆ...",
  str_homestory_811201001_40_dialog_content = "และบางคนก็อยู่ไม่ได้ถ้าไม่มีเหล้าจิน",
  str_homestory_811201001_41_dialog_content = "เดี๋ยวนะ... คุณบอกว่าจิน?",
  str_homestory_811201001_42_dialog_content = "หมายถึง... คุณเจเนวีฟเหรอ?",
  str_homestory_811201001_43_dialog_content = "แม่นั่นเป็นคนเดียวในโลกที่รักการดื่มเหล้าหรือไงกัน?",
  str_homestory_811201001_44_dialog_content = "...ฉันไม่เข้าใจเลยจริง ๆ สมองนายทำงานยังไงกันเนี่ย!",
  str_homestory_811201001_45_dialog_content = "โอเค... คุณไม่ได้พูดถึงเจเนวีฟ แต่หมายถึงคนที่ชอบดื่มจินคนอื่น!",
  str_homestory_811201001_46_dialog_content = "ใช่! มีผู้คนมากมายที่รักการดื่ม เข้าใจมั้ย?<sprite=emo_nuhuo size=60 />",
  str_homestory_811201001_47_dialog_content = "แน่นอน... อย่าโกรธเลยนะครับ! แล้วก็ อย่าจุดไฟเผาอะไรเลยนะ...",
  str_homestory_811201001_48_dialog_content = "ฮึ่ม",
  str_homestory_811201001_49_dialog_content = "ขอบคุณนะ สโมกกี้!",
  str_homestory_811201001_50_dialog_content = "คำแนะนำของคุณมีประโยชน์มากเลย!",
  str_homestory_811201001_51_dialog_content = "ฉันต้องไปแล้ว ไว้เจอกัน",
  str_homestory_811201001_52_dialog_content = "แล้วเจอกัน!",
  str_homestory_807101001_0_dialog_content = "ว่าวของทาคิ...",
  str_homestory_807101001_1_dialog_content = "อะแฮ่ม... ทาคิ...",
  str_homestory_807101001_2_dialog_content = "หา? PlayerName?",
  str_homestory_807101001_3_dialog_content = "เอ่อ... ผมเห็นว่าวของคุณ...",
  str_homestory_807101001_4_dialog_content = "มันวางอยู่บนพื้น",
  str_homestory_807101001_5_dialog_content = "...โอ้",
  str_homestory_807101001_6_dialog_content = "แต่ฉันก็เก็บมันมาได้เร็วมากเลยนะ",
  str_homestory_807101001_7_dialog_content = "...<sprite=emo_yihuo size=60 />",
  str_homestory_807101001_8_dialog_content = "(เหมือนจะไม่ใช่ประเด็นสำคัญนะ...)",
  str_homestory_807101001_9_dialog_content = "เอ่อ คือ ผมคิดว่าทักษะการเล่นว่าวของคุณ...",
  str_homestory_807101001_10_option_content = "ค่อนข้างดีเลย!",
  str_homestory_807101001_11_dialog_content = "เจ้าหนู พยายามจะปลอบใจฉันงั้นเหรอ?",
  str_homestory_807101001_12_dialog_content = "เอ่อ... ผมแค่อยากจะให้กำลังใจคุณน่ะ...",
  str_homestory_807101001_13_dialog_content = "ฉันเข้าใจ แต่คำชมที่ไม่จริงใจแบบนั้น ฉันไม่ต้องการหรอก",
  str_homestory_807101001_14_dialog_content = "เข้าใจแล้ว แค่คุณไม่หมดกำลังใจก็พอแล้วล่ะ...",
  str_homestory_807101001_15_option_content = "แย่ชะมัด!",
  str_homestory_807101001_16_dialog_content = "ให้ผมสอนคุณดีกว่า",
  str_homestory_807101001_17_dialog_content = "ได้ งั้นช่วยสอนฉันทีสิ",
  str_homestory_807101001_18_dialog_content = "หา? ตกลงง่ายขนาดนั้นเลย",
  str_homestory_807101001_19_dialog_content = "แน่นอน",
  str_homestory_807101001_20_dialog_content = "ไม่ใช่เรื่องน่าอายอยู่แล้วที่จะเรียนรู้จากคนที่เก่งกว่า",
  str_homestory_807101001_21_dialog_content = "การยอมรับในสิ่งที่ไม่เข้าใจ จะช่วยให้การสื่อสารมีประสิทธิภาพมากขึ้น นี่เป็นเรื่องจำเป็นอย่างยิ่งสำหรับนักธุรกิจทุกคน",
  str_homestory_807101001_22_dialog_content = "เจ้าของร้านรับสารพัดงานจิปาถะไม่เคยทำให้ผมผิดหวังจริง ๆ!",
  str_homestory_807101001_23_dialog_content = "แล้วเทคนิคของการเล่นว่าวคืออะไรล่ะ? บอกฉันมาสิ",
  str_homestory_807101001_24_dialog_content = "อย่างแรก คุณต้องยืนต้านทิศทางลม",
  str_homestory_807101001_25_dialog_content = "ว่าวจะเริ่มลอยตามลมด้วยวิธีนี้",
  str_homestory_807101001_26_dialog_content = "จากนั้นก็ค่อย ๆ ปล่อยสายเพื่อให้ว่าวลอยขึ้นไปในอากาศ หากลมไม่เพียงพอ คุณต้องรีบกรอสายกลับ",
  str_homestory_807101001_27_dialog_content = "คุณสามารถวิ่งช้า ๆ ในระหว่างเล่นว่าว และคอยจับตาดูว่าวอยู่เสมอ",
  str_homestory_807101001_28_dialog_content = "หากว่าวของคุณลอยขึ้นไปสูงในอากาศอย่างต่อเนื่อง...",
  str_homestory_807101001_29_dialog_content = "คุณสามารถผูกสายว่าวไว้กับต้นไม้หรือป้ายบอกทาง และหาจุดที่สบายเพื่อชื่นชมว่าวของคุณ",
  str_homestory_807101001_30_dialog_content = "โอเค... ทิศทางลม... แรงลม... วิ่งช้า ๆ... และโต้ตอบกับว่าว...<sprite=emo_wuyu size=60 />",
  str_homestory_807101001_31_dialog_content = "หา? คุณกำลังท่องมันอยู่งั้นเหรอ?",
  str_homestory_807101001_32_dialog_content = "ผมพูดใหม่อีกรอบก็ได้นะ ถ้าคุณต้องการ...",
  str_homestory_807101001_33_dialog_content = "ไม่จำเป็นหรอก ฉันจำได้หมดแล้วล่ะ",
  str_homestory_807101001_34_dialog_content = "หืมม? ถ้างั้นทำไมคุณถึงยังพึมพำกับตัวเองอยู่อีกล่ะ?",
  str_homestory_807101001_35_dialog_content = "อืมม... ผมหมายถึง... ทำไมไม่ลองทำดูเลยล่ะ?",
  str_homestory_807101001_36_dialog_content = "ฉันกำลังคิดว่าจะตีพิมพ์หนังสือ \"วิธีการเล่นว่าว\" เพื่อเพิ่มยอดขายยังไงดีน่ะ",
  str_homestory_807101001_37_dialog_content = "...หา?",
  str_homestory_807101001_38_dialog_content = "ลองจินตนาการดูสิ ถ้าเจ้าของร้านรับสารพัดงานจิปาถะเริ่มขายว่าวและโฆษณากระตุ้นความสนใจไปด้วย...",
  str_homestory_807101001_39_dialog_content = "ซื้อว่าวแล้วรับฟรี คอร์สฝึกสอนเล่นว่าวภายในเวลาจำกัด",
  str_homestory_807101001_40_dialog_content = "จะเกิดอะไรขึ้นถ้าพวกเขาเล่นว่าวไม่ได้หลังจากจบคอร์ส? พวกเขาก็จะมาซื้อหนังสือ \"วิธีการเล่นว่าว\" ไงล่ะ",
  str_homestory_807101001_41_dialog_content = "เราสามารถทำว่าวได้ทุกแบบ แม้กระทั่งรูปใบหน้าของเจ้าแห่งเงา...",
  str_homestory_807101001_42_dialog_content = "โว่ว ด-เดี๋ยวนะ!",
  str_homestory_807101001_43_dialog_content = "ที่คุณมาเล่นว่าวและเรียนรู้เทคนิคการเล่นว่าวจากผม...",
  str_homestory_807101001_44_dialog_content = "เพื่อการหาเงินเหรอเนี่ย?",
  str_homestory_807101001_45_dialog_content = "ก็ใช่น่ะสิ",
  str_homestory_807101001_46_dialog_content = "เจ้าหนู ฉันเป็นนักธุรกิจนะ",
  str_homestory_807101001_47_dialog_content = "นายมีปัญหาอะไรหรือเปล่า?",
  str_homestory_807101001_48_dialog_content = "เปล่า ไม่ใช่อย่างนั้น...",
  str_homestory_807101001_49_dialog_content = "ผมชื่นชมเซนส์ทางธุรกิจอันยอดเยี่ยมของคุณน่ะ!",
  str_homestory_807101001_50_dialog_content = "ถ้าผมรู้วิธีการหาเงินจากสิ่งรอบตัว ผมก็คงจะมีเงินพอใช้ทุกวัน...",
  str_homestory_807101001_51_dialog_content = "อืมม... นายกังวลเรื่องเงินอยู่สินะ",
  str_homestory_807101001_52_dialog_content = "ฟังนะ ในเมื่อฉันได้แรงบันดาลใจมาจากธุรกิจนี้...",
  str_homestory_807101001_53_dialog_content = "กำไรครึ่งหนึ่งของธุรกิจนี้จะเป็นของนาย เมื่อมันเกิดขึ้นจริงในร้านรับสารพัดงานจิปาถะ",
  str_homestory_807101001_54_dialog_content = "?!",
  str_homestory_807101001_55_dialog_content = "คุณพูดจริงเหรอ?",
  str_homestory_807101001_56_dialog_content = "ใช่ แต่ไม่ต้องตกใจไปหรอก",
  str_homestory_807101001_57_dialog_content = "บางทีธุรกิจนี้อาจจะพังไม่เป็นท่าก็ได้",
  str_homestory_807101001_58_dialog_content = "ไม่เป็นไร ทาคิ ผมเชื่อในตัวคุณ!",
  str_homestory_807101001_59_dialog_content = "โอเค ฉันต้องฝึกเล่นว่าวให้เก่งกว่านี้แล้วล่ะ",
  str_homestory_807101001_60_dialog_content = "เจ้าหนู นายคงจะยุ่งน่าดู ไปทำงานของนายเถอะ",
  str_homestory_807101001_61_dialog_content = "ยังไงก็สู้ ๆ นะ! ทาคิ!",
  str_homestory_807101001_62_dialog_content = "(...ใช่! ฉันตัดสินใจแล้ว!)",
  str_homestory_807101001_63_dialog_content = "(เพื่อกำไรครึ่งหนึ่งของฉัน... ฉันต้องแน่ใจว่าทาคิฝึกฝนและพัฒนาตัวเองขึ้นทุกวัน!)<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_0_dialog_content = "ไวซ์?",
  str_homestory_803301001_1_dialog_content = "หายใจสิ... ไวซ์ เธอทำได้!",
  str_homestory_803301001_2_dialog_content = "หายใจเข้าลึก ๆ... หายใจออก...<sprite=emo_tanqi size=60 />",
  str_homestory_803301001_3_dialog_content = "หายใจออก?",
  str_homestory_803301001_4_dialog_content = "ไวซ์ ธ-เธอกำลังฝึกหายใจเหรอ?",
  str_homestory_803301001_5_dialog_content = "อ๋าา! PlayerName?",
  str_homestory_803301001_6_dialog_content = "...ฝึกหายใจ?",
  str_homestory_803301001_7_dialog_content = "เปล่าสักหน่อย...",
  str_homestory_803301001_8_dialog_content = "ถ้างั้นเธอทำอะไรอยู่ล่ะ?",
  str_homestory_803301001_9_dialog_content = "ฉันกำลังทำบัญชีอยู่น่ะ",
  str_homestory_803301001_10_dialog_content = "เฮ้อ... บัญชีรายจ่ายพวกนี้ทำให้ฉันปวดหัวชะมัดเลย",
  str_homestory_803301001_11_dialog_content = "ฉันล่ะอยากให้เป็นแค่การฝึกหายใจจริง ๆ...",
  str_homestory_803301001_12_dialog_content = "อย่างน้อยการฝึกหายใจก็ไม่มีค่าใช้จ่าย",
  str_homestory_803301001_13_option_content = "ถามไวซ์",
  str_homestory_803301001_14_dialog_content = "ให้ฉันช่วยไหม?",
  str_homestory_803301001_15_dialog_content = "เมื่อคืนฉันเปิดอ่านสมุดบัญชีของเราแล้ว",
  str_homestory_803301001_16_dialog_content = "ฉันไม่เก่งเรื่องทำบัญชี แต่ก็ยินดีจะช่วยนะ",
  str_homestory_803301001_17_option_content = "นิ่งเงียบต่อไป",
  str_homestory_803301001_18_dialog_content = "ทำไมถึงเงียบไปล่ะ?",
  str_homestory_803301001_19_dialog_content = "เอ่อ... ฉันไม่ได้จะว่านายหรอกนะ...",
  str_homestory_803301001_20_dialog_content = "ฉันรู้ ฉันแค่กำลังคิดว่าฉันจะช่วยอะไรได้บ้าง",
  str_homestory_803301001_21_dialog_content = "เมื่อคืนฉันเปิดดูสมุดบัญชีของเรา เราใช้เงินเกินตัวไปหน่อยน่ะ...",
  str_homestory_803301001_22_dialog_content = "อ้อ... ไวซ์... ขอบคุณสำหรับทุกอย่างนะ!",
  str_homestory_803301001_23_dialog_content = "ขอฉันคิดก่อนนะว่าฉันเห็นอะไรในสมุดบัญชีเมื่อคืนบ้าง...",
  str_homestory_803301001_24_dialog_content = "\"แค่ส่วนประกอบสำหรับน้ำพุแห่งความหวัง จัตุรัส และก้อนหินตกแต่งก็ใช้เงินมหาศาลแล้ว\"",
  str_homestory_803301001_25_dialog_content = "\"วัสดุสำหรับหอพักหรือพิพิธภัณฑ์นี่ยิ่งไม่ต้องพูดถึงเลย\"",
  str_homestory_803301001_26_dialog_content = "\"เราต้องคำนึงถึงความชอบของเพื่อน ๆ ทุกคนด้วย...\"",
  str_homestory_803301001_27_dialog_content = "\"อย่างเช่น ม้าโยก ชิงช้า และประติมากรรม...\"",
  str_homestory_803301001_28_dialog_content = "\"ถึงแม้ของเหล่านี้จะไม่ได้มีราคาสูงมาก แต่ตัวเลขก็เพิ่มขึ้นอย่างรวดเร็วเหมือนกัน\"",
  str_homestory_803301001_29_dialog_content = "\"การสื่อสารกับช่างฝีมือก็ยังมีอะไรให้เรียนรู้อีกมาก การติดตั้งสิ่งเหล่านี้เป็นอะไรที่ท้าทายจริง ๆ\"",
  str_homestory_803301001_30_dialog_content = "\"อย่างไรก็ตาม... ฉันคิดว่าความพยายามของ PlayerName กับฉันจะไม่สูญเปล่า หากแขกได้พักผ่อนที่นี่อย่างสบาย\"",
  str_homestory_803301001_31_dialog_content = "โอ๊ะ... นายเห็นทุกอย่างแล้ว",
  str_homestory_803301001_32_dialog_content = "ใช่... ฉันไม่สามารถทิ้งนิสัยเก่า ๆ ที่ชอบเขียนความคิดของตัวเองแบบนี้ได้...",
  str_homestory_803301001_33_dialog_content = "ไวซ์ พูดตามตรงนะ เธอยอดเยี่ยมมากจริง ๆ!",
  str_homestory_803301001_34_dialog_content = "ผู้นำทาง ทำไมจู่ ๆ ก็มาชมกันเยอะแยะขนาดนี้ล่ะ?",
  str_homestory_803301001_35_dialog_content = "ฉันคิดแบบนั้นจริง ๆ นี่นา!",
  str_homestory_803301001_36_dialog_content = "ดูสิ เธอวาดแผนการก่อสร้าง จัดตารางโครงการ และยังวางแผนจัดการพื้นที่อีก...",
  str_homestory_803301001_37_dialog_content = "ฉันไม่ได้ช่วยอะไรเลย ฉันวาดรูปไม่เป็น วางแผนก็ไม่ได้ แถมยังจัดการไม่เก่งอีกด้วย",
  str_homestory_803301001_38_dialog_content = "สวนลอยฟ้าเป็นอย่างทุกวันนี้ได้ก็เพราะเธอ",
  str_homestory_803301001_39_dialog_content = "...เอ่อ... ก็จริงนะ...",
  str_homestory_803301001_40_dialog_content = "แต่ไม่จำเป็นต้องขอบคุณหรอก!",
  str_homestory_803301001_41_dialog_content = "ฉันแค่อยากให้กำลังใจเธอ",
  str_homestory_803301001_42_dialog_content = "พวกเรามาช่วยกันและผ่านช่วงวิกฤตินี้ไปด้วยกันเถอะนะ",
  str_homestory_803301001_43_dialog_content = "อื้ม! จริงด้วย! นายพูดถูก!",
  str_homestory_803301001_44_dialog_content = "เอ่อ... ในเมื่อการซื้อของให้สวนลอยฟ้าค่อนข้างลำบาก",
  str_homestory_803301001_45_dialog_content = "ทำไมเราไม่ขึ้นราคาสินค้าที่ขายในร้านเป็นสิบเท่าเลยล่ะ?<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_46_dialog_content = "...เอ่อ... ฉันว่ามันไม่จำเป็นหรอกมั้ง...",
  str_homestory_803301001_47_dialog_content = "ฮ่าฮ่า ผู้นำทาง ฉันแค่ล้อเล่นน่ะ!",
  str_homestory_803301001_48_dialog_content = "แต่ว่า เราจะหาเงินเยอะกว่านี้ได้ยังไงนะ? ขอฉันคิดดูก่อน...",
  str_homestory_804101001_0_dialog_content = "มิสบลังค์...",
  str_homestory_804101001_1_dialog_content = "สวัสดี PlayerName",
  str_homestory_804101001_2_dialog_content = "วันนี้เป็นวันที่ดีนะ<sprite=emo_pugongying size=60 /> มิสบลังค์",
  str_homestory_804101001_3_dialog_content = "ใช่แล้ว",
  str_homestory_804101001_4_dialog_content = "เธอกำลังจะไปเดินเล่นหรือเตรียมจะไปไหนหรือเปล่า?",
  str_homestory_804101001_5_option_content = "แค่ไปเดินเล่น",
  str_homestory_804101001_6_dialog_content = "เป็นตัวเลือกที่ดีนี่",
  str_homestory_804101001_7_dialog_content = "ทิวทัศน์ที่นี่สวยงามมาก มีสิ่งอำนวยความสะดวกมากมาย...",
  str_homestory_804101001_8_dialog_content = "และยังมีผู้คนมากมายที่ฉันไม่เคยพบเจอมาก่อน",
  str_homestory_804101001_9_option_content = "ไปตกปลา",
  str_homestory_804101001_10_dialog_content = "อ๋า เธอตกปลาเก่งหรือเปล่าล่ะ?",
  str_homestory_804101001_11_option_content = "เก่งมาก",
  str_homestory_804101001_12_dialog_content = "จริงเหรอ?",
  str_homestory_804101001_13_dialog_content = "งั้นเดี๋ยวฉันจะตามไปดู",
  str_homestory_804101001_14_dialog_content = "ได้เสมอครับ!",
  str_homestory_804101001_15_dialog_content = "หึหึ ช่างเป็นชายหนุ่มที่มีความมั่นใจจริง ๆ!",
  str_homestory_804101001_16_option_content = "ก็เรื่อย ๆ",
  str_homestory_804101001_17_dialog_content = "การตกปลาต้องใช้ความอดทนอย่างมาก",
  str_homestory_804101001_18_dialog_content = "ฉันคิดว่าเธอยังเด็กเกินไปสำหรับเรื่องนี้นะ",
  str_homestory_804101001_19_dialog_content = "เอ่อ... ผมคิดว่าการตกปลาช่วยให้มีสมาธิมากขึ้นน่ะครับ",
  str_homestory_804101001_20_dialog_content = "อืม...",
  str_homestory_804101001_21_dialog_content = "เฉพาะคนที่ \"มีปัญหาเรื่องการทำสมาธิ\" เท่านั้นแหละที่ต้องทำสิ่งเหล่านี้เพื่อฝึกให้ตัวเองมีสมาธิน่ะ",
  str_homestory_804101001_22_dialog_content = "แต่เมื่อเวลาผ่านไปมันก็จะช่วยได้",
  str_homestory_804101001_23_dialog_content = "ว่าแต่...",
  str_homestory_804101001_24_dialog_content = "มิสบลังค์ ทำไมคุณถึงยืนใต้ป้ายไม้นี้ล่ะ?",
  str_homestory_804101001_25_dialog_content = "ฉันกำลังสังเกตสิ่งต่าง ๆ",
  str_homestory_804101001_26_dialog_content = "สังเกต?",
  str_homestory_804101001_27_dialog_content = "ช่วยไม่ได้แหละนะ",
  str_homestory_804101001_28_dialog_content = "พอเห็นอาคารและถนนใหม่ ๆ เหล่านี้... ฉันก็อดไม่ได้ที่จะจดจำมันไว้ในหัวสมอง",
  str_homestory_804101001_29_dialog_content = "เข้าใจแล้ว",
  str_homestory_804101001_30_dialog_content = "ถนนที่นี่ไม่ซับซ้อน บางทีมิสบลังค์อาจจะได้พักผ่อนบ้าง",
  str_homestory_804101001_31_dialog_content = "พักผ่อนงั้นรึ?",
  str_homestory_804101001_32_dialog_content = "ถ้าได้แบบนั้นก็ดีมากเลยล่ะ...",
  str_homestory_804101001_33_dialog_content = "แต่ฉันจะฟังคำแนะนำของเธอก็แล้วกัน",
  str_homestory_804101001_34_dialog_content = "PlayerName เธอเองก็พักผ่อนบ้างล่ะ",
  str_homestory_804101001_35_dialog_content = "ถ้าทำงานหนักเกินจะแก่เร็วนะ<sprite=emo_guilian size=60 />",
  str_homestory_804101001_36_dialog_content = "โอเค...",
  str_homestory_804101001_37_dialog_content = "ผมก็หวังว่าจะได้พักผ่อนเหมือนกันครับ! มิสบลังค์!",
  str_homestory_813801001_0_dialog_content = "คุณเชอวาน!",
  str_homestory_813801001_1_dialog_content = "PlayerName?",
  str_homestory_813801001_2_dialog_content = "โอ๊ะ... โชคดีจริง ๆ ที่เธอมาพอดี...<sprite=emo_tanqi size=60 />",
  str_homestory_813801001_3_dialog_content = "มีอะไรเหรอ คุณเชอวาน? คุณดูเหนื่อย ๆ นะ",
  str_homestory_813801001_4_dialog_content = "เพราะว่า... ฉันอดนอนทั้งคืนเพื่อดูสิ่งของที่เก็บรวบรวมไว้ในพิพิธภัณฑ์ให้หมด",
  str_homestory_813801001_5_dialog_content = "ของสะสมเหล่านี้เป็นเหมือนบันทึกที่บอกเล่าอดีตของอีราเวลได้อย่างสมบูรณ์แบบ รวมถึงวิทยาการทั้งหมดที่เคเลสไทต์พัฒนาขึ้นด้วย...",
  str_homestory_813801001_6_dialog_content = "ฉันยอมรับในความก้าวหน้าทางวิทยาศาสตร์ของพวกเธอจริง ๆ",
  str_homestory_813801001_7_dialog_content = "ขอบคุณครับ อิลลูมินาเองก็เก่งในเรื่องวิทยาศาสตร์และวิทยาการเหมือนกันนี่",
  str_homestory_813801001_8_dialog_content = "ไม่รู้เหมือนกันว่าทำไม แต่ฉันไม่สามารถสลัดความรู้สึกนี้ออกไปได้เลย...",
  str_homestory_813801001_9_dialog_content = "วิทยาการของเคเลสไทต์ไม่เหมือนกับของอิลลูมินาแม้แต่น้อย",
  str_homestory_813801001_10_dialog_content = "วิทยาการชั้นสูงของอิลลูมินามีพื้นฐานมาจากเครือข่ายกลไกที่ซับซ้อน ซึ่งพัฒนาด้วยความรู้ที่มั่นคงและมีความแม่นยำ...",
  str_homestory_813801001_11_dialog_content = "แต่วิทยาการของเคเลสไทต์... มักให้ความรู้สึกที่ใหม่และแตกต่างเสมอ",
  str_homestory_813801001_12_dialog_content = "คล้ายกับพวกวิทยาการโบราณเลย",
  str_homestory_813801001_13_dialog_content = "เอ่อ ผมไม่รู้เรื่องอะไรพวกนี้เลย...",
  str_homestory_813801001_14_dialog_content = "โอ๊ะ-อืม...",
  str_homestory_813801001_15_dialog_content = "จู่ ๆ ก็รู้สึกง่วงขึ้นมาแฮะ...<sprite=emo_xuanyun size=60 />",
  str_homestory_813801001_16_dialog_content = "แล้วคุณรออะไรอยู่ล่ะ? กลับไปนอนพักสิครับ",
  str_homestory_813801001_17_dialog_content = "ฉันกำลังพยายามเชื่อมโยงของสะสมเหล่านี้กับเอกสารที่ฉันเคยอ่าน เผื่อว่าจะค้นพบอะไรที่น่าสนใจบ้างน่ะ",
  str_homestory_813801001_18_dialog_content = "อาจจะมีชาวเคเลสไทต์อาศัยอยู่ที่อื่นในทวีปเมื่อนานมาแล้วก็ได้...",
  str_homestory_813801001_19_dialog_content = "เพียงแต่ผู้คนไม่รู้ว่าพวกเขาเป็นชาวเคเลสไทต์ และเข้าใจผิดคิดว่าวิทยาการดังกล่าวเป็นของโบราณ",
  str_homestory_813801001_20_dialog_content = "...ฮ่าฮ่าฮ่า ช่างเถอะ",
  str_homestory_813801001_21_dialog_content = "ฉันเริ่มรู้สึกว่ามันเพ้อฝันไปหน่อยแล้วล่ะ ฉันน่าจะต้องไปนอนสักหน่อยแล้ว",
  str_homestory_813801001_22_dialog_content = "เชอวาน ผมเป็นห่วงคุณนะ",
  str_homestory_813801001_23_dialog_content = "ทำไมคุณต้องทำงานให้เสร็จตอนนี้ด้วยล่ะ?",
  str_homestory_813801001_24_dialog_content = "ทำงานในสภาพแบบนี้ ผมว่าผลลัพธ์ก็คงออกมาได้ไม่ดีนักหรอก...",
  str_homestory_813801001_25_dialog_content = "นายมีแขกจากลูโมโพลิสอยู่ด้วยใช่มั้ย?",
  str_homestory_813801001_26_dialog_content = "ถึงที่นี่จะมีเคเลสไทต์อย่างเธอคอยดูแล ทำให้พวกนั้นไม่กล้าทำลายพิพิธภัณฑ์...",
  str_homestory_813801001_27_dialog_content = "ต-แต่ฉันก็กังวลน่ะ!",
  str_homestory_813801001_28_dialog_content = "ฉันรู้สึกว่าตัวเองต้องบันทึกและวิเคราะห์ทุกอย่างให้เร็วที่สุด",
  str_homestory_813801001_29_dialog_content = "ใครจะรู้ว่าคนที่ต่อต้านเทคโนโลยีพวกนั้นจะคิดเห็นเกี่ยวกับที่นี่ยังไง?",
  str_homestory_813801001_30_dialog_content = "เข้าใจแล้ว...",
  str_homestory_813801001_31_dialog_content = "ไม่ต้องห่วง เท่าที่ผมรู้ ลูโมโพลิสเองก็มีพิพิธภัณฑ์แบบนี้มากมายหลายแห่ง",
  str_homestory_813801001_32_dialog_content = "และพวกเขาเป็นแขกของที่นี่ สิ่งที่คุณเป็นกังวลจะไม่มีทางเกิดขึ้นแน่",
  str_homestory_813801001_33_dialog_content = "ฉันคิดมากไปเองงั้นเหรอ?",
  str_homestory_813801001_34_dialog_content = "หรือการทำงานเยอะเกินไปทำให้ฉันกังวลเกินเหตุ? <sprite=emo_sikao size=60 />",
  str_homestory_813801001_35_dialog_content = "ผมว่าคุณแค่เหนื่อยเท่านั้นเอง",
  str_homestory_813801001_36_dialog_content = "พวกเราไปพักกันก่อน แล้วค่อยมาว่ากันต่อทีหลังดีไหม?",
  str_homestory_813801001_37_dialog_content = "ก็ได้ งั้นเอาตามที่เธอว่าละกัน...PlayerName",
  str_homestory_813801001_38_dialog_content = "ฉันไปนอนก่อนนะ แล้วเธอล่ะ?",
  str_homestory_813801001_39_dialog_content = "ฉันว่าเธอเองก็คงอยากพักเหมือนกันสินะ?",
  str_homestory_813801001_40_option_content = "เห็นด้วย",
  str_homestory_813801001_41_dialog_content = "ใช่ ผมก็เหนื่อยเหมือนกัน",
  str_homestory_813801001_42_dialog_content = "แต่ว่า...",
  str_homestory_813801001_43_option_content = "คัดค้าน",
  str_homestory_813801001_44_dialog_content = "ถึงแม้ร่างกายจะเหนื่อย แต่จิตวิญญาณของผมเต็มอิ่มมาก!",
  str_homestory_813801001_45_dialog_content = "ตราบใดที่ทุกคนได้ใช้เวลาที่มีอย่างมีความสุข ผมก็ไม่รู้สึกเหน็ดเหนื่อยหรอก",
  str_homestory_813801001_46_dialog_content = "ถึงจะอายุน้อย แต่ก็มีความเป็นผู้นำสูงเกินวัย",
  str_homestory_813801001_47_dialog_content = "ขอบคุณครับ...",
  str_homestory_813801001_48_dialog_content = "ไม่รู้ทำไมฉันถึงอยากไปที่แม่น้ำตลอดเลย แต่ฉันง่วงเกินกว่าที่จะไปได้",
  str_homestory_813801001_49_dialog_content = "ไว้ค่อยคุยเรื่องวิทยาการเคเลสไทต์หลังจากที่ฉันตื่นละกันนะ PlayerName",
  str_homestory_813801001_50_dialog_content = "พักให้เต็มที่นะ คุณเชอวาน",
  str_homestory_814501001_0_dialog_content = "เธอกำลังมองอะไรอยู่น่ะ?",
  str_homestory_814501001_1_dialog_content = "อาเมะโมริ?",
  str_homestory_814501001_2_dialog_content = "ชู่ว<sprite=emo_baiyan size=60 />",
  str_homestory_814501001_3_dialog_content = "?",
  str_homestory_814501001_4_dialog_content = "คุณกำลังทำอะไรน่ะ",
  str_homestory_814501001_5_dialog_content = "สังเกตการณ์อยู่",
  str_homestory_814501001_6_dialog_content = "ฉันกำลังตรวจสอบสถานที่นี้อย่างระมัดระวังและถี่ถ้วน",
  str_homestory_814501001_7_dialog_content = "มีอะไรผิดปกติหรือเปล่า?",
  str_homestory_814501001_8_dialog_content = "นายไม่คิดว่าการออกแบบของสวนลอยฟ้านี้ซับซ้อนและประณีตเป็นพิเศษเหรอ?",
  str_homestory_814501001_9_dialog_content = "ฉันเคยจินตนาการถึงการสร้างสถานที่แบบนี้ตอนที่ยังเด็ก",
  str_homestory_814501001_10_dialog_content = "ยามรุกสามารถบุกโจมตีได้ ยามถอยก็สามารถป้องกันได้สะดวก และเป็นที่ชุมนุมใหญ่สำหรับคนที่มีความคิดเหมือน ๆ กัน",
  str_homestory_814501001_11_dialog_content = "โอ้!",
  str_homestory_814501001_12_dialog_content = "คุณอาเมะโมริวางแผนเรื่องระยะยาวตั้งแต่ยังเด็กเลยเหรอ?",
  str_homestory_814501001_13_dialog_content = "อืม ความฝันของฉันในตอนนั้น อาจจะเป็นแค่แรงผลักดันให้ \"พยายามมีชีวิตต่อไป\" เท่านั้น",
  str_homestory_814501001_14_dialog_content = "แต่ตอนนี้ฉันก็ได้มาอยู่บนนี้แล้ว ถือว่าไม่เลวเลยล่ะ",
  str_homestory_814501001_15_dialog_content = "โอ้ ขอโทษที",
  str_homestory_814501001_16_dialog_content = "คุณอยากให้ผมพาไปเดินรอบ ๆ ไหม?",
  str_homestory_814501001_17_dialog_content = "ไม่ต้องหรอก",
  str_homestory_814501001_18_dialog_content = "ฉันจำตำแหน่งของสถานที่ต่าง ๆ ได้ตั้งแต่วันแรกที่มาถึงแล้วล่ะ",
  str_homestory_814501001_19_dialog_content = "โห เก่งจัง!",
  str_homestory_814501001_20_dialog_content = "นั่นคืองานของนินจาน่ะ",
  str_homestory_814501001_21_dialog_content = "อันที่จริง ฉันก็อยากรู้เหมือนกันว่าใครเป็นคนออกแบบสถานที่แห่งนี้?",
  str_homestory_814501001_22_dialog_content = "ผู้นำทาง นายรู้หรือเปล่า?",
  str_homestory_814501001_23_option_content = "รู้ครับ",
  str_homestory_814501001_24_dialog_content = "ไวซ์เป็นคนออกแบบตามคำแนะนำของผมแล้วก็ช่างฝีมือ",
  str_homestory_814501001_25_option_content = "ไม่รู้ครับ",
  str_homestory_814501001_26_dialog_content = "ผมช่วยถามไวซ์ได้นะถ้าคุณอยากรู้",
  str_homestory_814501001_27_dialog_content = "ผมมีส่วนร่วมในการออกแบบจริงบ้างนิดหน่อย แต่เธอรู้ดีที่สุด",
  str_homestory_814501001_28_dialog_content = "คุณอาเมะโมริ ทำไมถึงอยากรู้ขนาดนั้นล่ะครับ?",
  str_homestory_814501001_29_dialog_content = "หรือว่าคุณสนใจอยากจะสร้างสวนลอยฟ้าบนเกาะเมฆาอีกแห่งหนึ่ง?",
  str_homestory_814501001_30_dialog_content = "ที่จริงฉันก็คิดแบบนั้นเหมือนกัน",
  str_homestory_814501001_31_dialog_content = "ลองนึกภาพว่าหากบนเกาะเมฆามีสถานที่ระดับนี้อยู่ ผู้คนก็จะมีชีวิตที่ดีขึ้นอย่างแน่นอน",
  str_homestory_814501001_32_dialog_content = "แน่นอนว่านี่เป็นเพียงแค่จุดเริ่มต้นเท่านั้น...",
  str_homestory_814501001_33_dialog_content = "หากเราเรียนรู้วิทยาการขั้นสูงนี้อย่างจริงจัง เราก็จะป้องกันศัตรูได้ง่ายขึ้น",
  str_homestory_814501001_34_dialog_content = "วิทยาการของเคเลสไทต์และแนวคิดการวางผังเมืองอันชาญฉลาดนี้... ควรค่าที่เราจะเรียนรู้",
  str_homestory_814501001_35_dialog_content = "เข้าใจแล้ว",
  str_homestory_814501001_36_dialog_content = "ผมจะไปหาคำตอบมาให้นะ!",
  str_homestory_814501001_37_dialog_content = "ขอบคุณนะ ผู้นำทาง",
  str_homestory_814601001_0_dialog_content = "มองซ้ายมองขวา...",
  str_homestory_814601001_1_dialog_content = "ออโรเรียนทุกคน...",
  str_homestory_814601001_2_dialog_content = "เดินผ่านสวนลอยฟ้า",
  str_homestory_814601001_3_dialog_content = "?",
  str_homestory_814601001_4_dialog_content = "ประตูโค้งตั้งขึ้นจากพื้นราบ...",
  str_homestory_814601001_5_dialog_content = "และในมือก็ถือซาลาเปา!<sprite=emo_yaosu size=60 />",
  str_homestory_814601001_6_dialog_content = "...",
  str_homestory_814601001_7_dialog_content = "เหยา คุณกำลังท่องบทกวีเหรอ?",
  str_homestory_814601001_8_dialog_content = "เฮ้ ผู้นำทาง!",
  str_homestory_814601001_9_dialog_content = "ฉันไม่ได้ท่อง",
  str_homestory_814601001_10_dialog_content = "แต่กำลังแต่งน่ะ! นายคิดว่าไง?",
  str_homestory_814601001_11_option_content = "ดีเลย!",
  str_homestory_814601001_12_dialog_content = "เยี่ยมเลย!",
  str_homestory_814601001_13_dialog_content = "เหยา คุณเป็นนักกวีที่มีพรสวรรค์!",
  str_homestory_814601001_14_option_content = "ไม่เลว",
  str_homestory_814601001_15_dialog_content = "ผมคิดว่าบทกวีนี้... อยู่กลาง ๆ ระหว่างบทกวีของคารอนกับไวซ์",
  str_homestory_814601001_16_dialog_content = "นอกจากจะพูดแบบไม่เวอร์วังหรือเกินจริงจนเกินไปแล้ว ยังเผยให้เห็นความปรารถนาที่แท้จริงของนักกวีอีกด้วย...",
  str_homestory_814601001_17_dialog_content = "อืมม... แต่ประตูโค้งอะไรนั่นเกี่ยวอะไรกับซาลาเปาเหรอ?",
  str_homestory_814601001_18_dialog_content = "ดูประตูโค้งนั่นสิ นายมองไม่เห็นร้านขายซาลาเปาในอนาคตของฉันเหรอ?",
  str_homestory_814601001_19_dialog_content = "คุณยังคิดจะเปิดร้านซาลาเปาอยู่อีกเหรอ?",
  str_homestory_814601001_20_dialog_content = "เบื่อกับการรักษาความยุติธรรมและช่วยเหลือผู้อ่อนแอแล้วเหรอครับ?",
  str_homestory_814601001_21_dialog_content = "ฉันอยากทำทั้งสองอย่างนั่นแหละ",
  str_homestory_814601001_22_dialog_content = "ฉันอยากทำร้านซาลาเปานี้เป็นสถานที่พักผ่อนหลังเกษียณ นายคิดว่าไงล่ะ?",
  str_homestory_814601001_23_dialog_content = "รู้ไหม จอมยุทธ์ในตำนานมักจะเลือกเกษียณที่ไหนสักแห่งในตลาดที่พลุกพล่าน...",
  str_homestory_814601001_24_dialog_content = "จะได้ฟังตำนานที่พวกเขาทิ้งไว้เบื้องหลังบ่อย ๆ ไงล่ะ!",
  str_homestory_814601001_25_dialog_content = "จอมยุทธ์พวกนี้ไม่มีอะไรสร้างสรรค์กว่านี้ให้ทำแล้วหรือไงนะ?",
  str_homestory_814601001_26_dialog_content = "อย่าสนใจพวกนั้นเลย มาดูแผนของฉันดีกว่า!",
  str_homestory_814601001_27_dialog_content = "ว่ามาเลยครับ ผมรอฟังอยู่",
  str_homestory_814601001_28_dialog_content = "อย่างแรกเลย ร้านซาลาเปาของฉันต้องมีสามชั้น",
  str_homestory_814601001_29_dialog_content = "ครึ่งหนึ่งของชั้นแรกเป็นที่ให้อันสึกับโมโมะขายของอร่อย ส่วนอีกครึ่งหนึ่งก็เป็นเมนูเลิศรสของฉันเอง!",
  str_homestory_814601001_30_dialog_content = "ชั้นสองเป็นที่สำหรับพักผ่อน เพื่อให้เพื่อนของฉันไม่ต้องเป็นกังวลเรื่องที่นอนเวลาที่เราพูดคุยกันจนดึกดื่น!",
  str_homestory_814601001_31_dialog_content = "ส่วนชั้นสามก็คือที่อยู่ของฉัน!",
  str_homestory_814601001_32_dialog_content = "ก็จะมีห้องสำหรับฉัน อาเมะโมริ รินเนะ แล้วก็มีให้ผู้นำทางกับไวซ์ด้วยนะ...",
  str_homestory_814601001_33_dialog_content = "นอกจากนี้ยังมีสำหรับคายาโนะ และเพื่อนจากตระกูลหลินของฉัน สำหรับพี่สาวร่วมสาบานแล้วก็พ่อแม่...",
  str_homestory_814601001_34_dialog_content = "ฉันทำห้องเผื่อทาคิด้วยดีไหม? มีสาว ๆ ห้อมล้อมขนาดนี้เขาอาจจะไม่ค่อยชอบใจรึเปล่านะ?<sprite=emo_sikao size=60 />",
  str_homestory_814601001_35_dialog_content = "ยังมีเดย์นากับโรบินด้วย?",
  str_homestory_814601001_36_dialog_content = "เดี๋ยวนะ...เหยา ผมว่าถ้าทำแบบนี้คุณจะไม่ได้กำไรอะไรเลยนะ...",
  str_homestory_814601001_37_dialog_content = "ลำพังแค่เตรียมห้องให้เพื่อน ๆ ทั้งหมดของคุณก็น่าจะใช้เงินมหาศาลแล้ว",
  str_homestory_814601001_38_dialog_content = "บางคนชอบความสันโดษ การอยู่รวมกันแบบชุมชนอาจจะไม่เหมาะกับทุกคนก็ได้...",
  str_homestory_814601001_39_dialog_content = "เงินไม่ใช่ปัญหาสำหรับฉัน!",
  str_homestory_814601001_40_dialog_content = "อืมม... แต่เรื่องความชอบส่วนตัวที่ว่านี่สิเป็นปัญหา...",
  str_homestory_814601001_41_dialog_content = "ช่างเถอะ ยังไงทุกคนก็เป็นเพื่อนของฉัน และฉันจะเตรียมห้องทั้งหมดไว้เอง",
  str_homestory_814601001_42_dialog_content = "แต่พวกเขาจะอยากมาอยู่หรือไม่นั้นก็ขึ้นอยู่กับพวกเขาละกัน",
  str_homestory_814601001_43_dialog_content = "ฮิฮิ เท่านี้ทุกคนก็มีความสุขโดยไม่ต้องฝืนใจหรือบังคับขู่เข็ญกันแล้ว",
  str_homestory_814601001_44_dialog_content = "ใช่ จริงด้วย...",
  str_homestory_814601001_45_dialog_content = "นี่เป็นทางออกที่มีแต่คนรวยสุด ๆ เท่านั้นที่ทำได้...",
  str_homestory_816301001_0_dialog_content = "คุณวาดรูปอยู่เหรอ?",
  str_homestory_816301001_1_dialog_content = "ว้าว! <sprite=emo_wuzui size=60 />คุณเจ้าของเรือเหาะPlayerName!",
  str_homestory_816301001_2_dialog_content = "ในที่สุด! ผมอุตส่าห์ตามหาคุณไปทุกที่เลย...",
  str_homestory_816301001_3_dialog_content = "เอ่อ... มีอะไรให้ช่วยรึเปล่าครับ?",
  str_homestory_816301001_4_dialog_content = "ผมกำลังเดินทางเพื่อว่าจ้างคนให้มาช่วยงานน่ะ แล้วก็บังเอิญพบกระดานวาดภาพนี้...",
  str_homestory_816301001_5_dialog_content = "คุณไวซ์บอกว่าคุณซื้อมันมา แม้ว่าจะโดนผู้คนคัดค้าน",
  str_homestory_816301001_6_dialog_content = "ดังนั้น ผมจะถือว่า...",
  str_homestory_816301001_7_dialog_content = "ในที่สุดคุณก็ยอมตกลงที่จะเขียนอาร์ตเวิร์กให้โปรเจ็กต์ Al***my St**s? ของผมแล้วสินะ?<sprite=emo_yaosu size=60 />",
  str_homestory_816301001_8_option_content = "ยืนยัน",
  str_homestory_816301001_9_dialog_content = "ใช่ ผมคิดแบบนั้นมาสักพักแล้ว",
  str_homestory_816301001_10_dialog_content = "โว่ว! ในที่สุดคุณก็ยอมเผชิญหน้ากับพรสวรรค์ของตัวเอง!",
  str_homestory_816301001_11_dialog_content = "เอ่อ... ผมต้องทำอะไรสักอย่างเพื่อให้รอดพ้นจากวิกฤติทางการเงินน่ะ",
  str_homestory_816301001_12_dialog_content = "แต่ฝีมือวาดภาพของผมคงไม่ดีขึ้นในเร็ว ๆ นี้หรอก",
  str_homestory_816301001_13_dialog_content = "ผมขอยกมันให้กับใครสักคนที่มีความสุขกับการวาดรูปอย่างคุณจะดีกว่า...",
  str_homestory_816301001_14_option_content = "ปฏิเสธ",
  str_homestory_816301001_15_dialog_content = "อืมม... ผมรู้ความสามารถของตัวเองดี...",
  str_homestory_816301001_16_dialog_content = "กระดานนี้เหมาะสำหรับผู้ที่หลงใหลในการวาดภาพ",
  str_homestory_816301001_17_dialog_content = "คุณเจ้าของเรือเหาะ จงยกมือของคุณทาบบนหน้าอก",
  str_homestory_816301001_18_dialog_content = "และสัมผัสกับเสียงหัวใจที่เต้นด้วยความรักการวาดภาพ",
  str_homestory_816301001_19_dialog_content = "ถ้าพูดถึงความรักในการวาดภาพ ผมเชื่อมั่นว่าคุณไม่เป็นสองรองใคร",
  str_homestory_816301001_20_dialog_content = "คุณทัวร์ด็อก",
  str_homestory_816301001_21_dialog_content = "...!",
  str_homestory_816301001_22_dialog_content = "คุณตามหาคนมาช่วยงานโปรเจ็กต์เกมทั้งวันทั้งคืน คุณได้พักผ่อนเต็มที่บ้างมั้ยเนี่ย?",
  str_homestory_816301001_23_dialog_content = "เพื่อเกมของผมแล้ว ผมไม่จำเป็นต้องกินหรือนอน",
  str_homestory_816301001_24_dialog_content = "แล้วนานแค่ไหนแล้ว ที่คุณไม่ได้วาดรูปอย่างอิสระ?",
  str_homestory_816301001_25_dialog_content = "โอ้ว...",
  str_homestory_816301001_26_dialog_content = "คุณอยากให้ผมวาดรูปลงบนกระดานของคุณจริง ๆ เหรอ?<sprite=emo_yihuo size=60 />",
  str_homestory_816301001_27_dialog_content = "ถ้าคุณทัวร์ด็อกผู้เป็นคนดังแห่งแอสตรา วาดบางสิ่งบางอย่างลงบนนี้...",
  str_homestory_816301001_28_dialog_content = "มันคงจะดีมากแน่ ๆ!",
  str_homestory_816301001_29_dialog_content = "อันดับแรก หาจุดอ่อนของอีกฝ่ายและพูดให้กำลังใจ จากนั้นชมอีกฝ่ายก่อนที่จะนำเสนอความต้องการของคุณเอง<sprite=emo_sikao size=60 />",
  str_homestory_816301001_30_dialog_content = "นี่คือเกมจิตวิทยาของคุณสินะ?",
  str_homestory_816301001_31_dialog_content = "หลังจากขอให้คนมากมายมาช่วยงาน ผมก็เกือบจะตกหลุมพรางของคุณซะแล้ว น่าสนใจจริง ๆ!",
  str_homestory_816301001_32_dialog_content = "สมกับเป็นตัวเอกที่ได้รับการคัดเลือกจากนักลงทุนจริง ๆ!",
  str_homestory_816301001_33_dialog_content = "ตราบใดที่คุณยังอยู่ เนื้อเรื่องเกมก็จะไม่น่าเบื่ออย่างแน่นอน",
  str_homestory_816301001_34_option_content = "ถามเกี่ยวกับนักลงทุน",
  str_homestory_816301001_35_dialog_content = "นักลงทุน?",
  str_homestory_816301001_36_dialog_content = "กลุ่มของหัวหน้าผู้มากความสามารถที่มีศรัทธาในตัวคุณ",
  str_homestory_816301001_37_dialog_content = "คุณไม่จำเป็นต้องรู้หรอกว่าพวกเขาเป็นใคร",
  str_homestory_816301001_38_option_content = "ถามเกี่ยวกับตัวเอก",
  str_homestory_816301001_39_dialog_content = "ตัวเอก?",
  str_homestory_816301001_40_dialog_content = "ตัวละครหลักที่เป็นศูนย์กลางของเกมนี้ ดาวเด่นที่ใคร ๆ ต่างก็รัก",
