  str_homestory_816301001_42_dialog_content = "ยิ่งฟังยิ่งสับสนแฮะ",
  str_homestory_816301001_43_dialog_content = "ผมขอสรุปเลยก็แล้วกัน คุณเจ้าของเรือเหาะ",
  str_homestory_816301001_44_dialog_content = "ผมยินดีวาดรูปสวนลอยฟ้าลงบนม้วนกระดาษให้คุณฟรี!",
  str_homestory_816301001_45_dialog_content = "ถือเป็นค่าตอบแทนที่ได้เรียนรู้เกมจิตวิทยาที่ไม่เหมือนใครจากคุณ",
  str_homestory_816301001_46_dialog_content = "หวังว่าเราจะได้ร่วมงานกันนะ <sprite=emo_guilian size=60 />",
  str_homestory_816301001_47_dialog_content = "อื้ม... เช่นกันครับ...",
  str_homestory_816301001_48_dialog_content = "เยี่ยม ผมคงต้องวางแผนองค์ประกอบของภาพนี้แล้วสิ",
  str_homestory_816301001_49_dialog_content = "โดยปกติผมมักจะใช้เวลาวาดภาพไม่เกิน 3 วินาที แต่สำหรับคุณเจ้าของเรือเหาะ ผมต้องทำให้ดีที่สุด",
