  str_homestory_814801001_47_dialog_content = "บอกร้านของเธอให้สั่งไวน์ชั้นดีมาด้วยนะ",
  str_homestory_814801001_48_dialog_content = "ฉันรอไม่ไหวแล้วล่ะ โอเคไหม?",
  str_homestory_814801001_49_dialog_content = "ได้เลยครับ...",
  str_homestory_814801001_50_dialog_content = "จะรออะไรอยู่ล่ะ?<sprite=emo_emo size=60 />",
  str_homestory_814801001_51_dialog_content = "ผมจะจัดการให้เดี๋ยวนี้แหละ!",
  str_homestory_815001001_0_dialog_content = "นิ่งสุด ๆ...",
  str_homestory_815001001_1_dialog_content = "สวัสดี PlayerName<sprite=emo_heimao size=60 />",
  str_homestory_815001001_2_dialog_content = "เลนอร์ ดีใจจังที่ได้เจอเธอ",
  str_homestory_815001001_3_dialog_content = "เลนอร์ ทำไมเธอยืนนิ่งอยู่ที่เดิมเหมือนรูปปั้นเลยล่ะ?",
  str_homestory_815001001_4_dialog_content = "อยากออกไปเดินเล่นรอบ ๆ ไหม?",
  str_homestory_815001001_5_dialog_content = "เดินเล่นรอบ ๆ?",
  str_homestory_815001001_6_dialog_content = "นี่เป็นคำสั่งใหม่จาก PlayerName หรือเปล่า?",
  str_homestory_815001001_7_dialog_content = "ฉันควรจะไปไหนดี?",
  str_homestory_815001001_8_dialog_content = "เลนอร์ นี่ไม่ใช่คำสั่งหรอกนะ คิดว่าเป็นคำแนะนำละกัน",
  str_homestory_815001001_9_dialog_content = "คำสั่งและคำแนะนำต่างกันยังไงเหรอ?",
  str_homestory_815001001_10_dialog_content = "หืมม... ขอคิดก่อนนะ",
  str_homestory_815001001_11_dialog_content = "คำสั่งคือสิ่งที่เธอต้องทำ",
  str_homestory_815001001_12_dialog_content = "ส่วนคำแนะนำเป็นแค่การแนะนำเฉย ๆ เธอจะทำหรือไม่ทำก็ได้",
  str_homestory_815001001_13_dialog_content = "เข้าใจแล้ว",
  str_homestory_815001001_14_dialog_content = "PlayerName บอกให้เลนอร์ออกไปเดินเล่นข้างนอก เป็นแค่คำแนะนำ",
  str_homestory_815001001_15_dialog_content = "เลนอร์จะเลือกไปหรือไม่ไปก็ได้",
  str_homestory_815001001_16_dialog_content = "ฉลาดมาก! เธอเข้าใจถูกต้องแล้วล่ะ",
  str_homestory_815001001_17_dialog_content = "ขอบคุณสำหรับคำชมนะ PlayerName",
  str_homestory_815001001_18_dialog_content = "ยินดีเสมอ",
  str_homestory_815001001_19_dialog_content = "...",
  str_homestory_815001001_20_dialog_content = "...",
  str_homestory_815001001_21_dialog_content = "...",
  str_homestory_815001001_22_dialog_content = "เอ่อ... เลนอร์?",
  str_homestory_815001001_23_dialog_content = "แล้วเธอไม่อยากไปเดินเล่นเหรอ?",
  str_homestory_815001001_24_dialog_content = "นั่นเป็นแค่คำแนะนำไม่ใช่เหรอ?",
  str_homestory_815001001_25_dialog_content = "เลนอร์ไม่จำเป็นต้องทำก็ได้",
  str_homestory_815001001_26_dialog_content = "อา...",
  str_homestory_815001001_27_dialog_content = "ฉันปลูกดอกไม้ต้นไม้สวย ๆ ไว้เยอะแยะเลย แถมยังติดตั้งอุปกรณ์นันทนาการใหม่อีกเพียบ!",
  str_homestory_815001001_28_dialog_content = "เธออยากไปดูมั้ย?",
  str_homestory_815001001_29_dialog_content = "เลนอร์ควร \"อยากไปดู\" ดีมั้ยคะ?",
  str_homestory_815001001_30_option_content = "ออกคำสั่ง",
  str_homestory_815001001_31_dialog_content = "เฮ้อ... ช่วยไม่ได้แหละนะ งั้นฉันขอสั่งให้เลนอร์ไปเดินเล่นรอบ ๆ ก็แล้วกัน",
  str_homestory_815001001_32_dialog_content = "รับทราบ เลนอร์จะทำภารกิจให้สำเร็จ",
  str_homestory_815001001_33_option_content = "แนะนำ",
  str_homestory_815001001_34_dialog_content = "ฉันรู้ว่าถ้าพูดไปจะดูขี้โม้ไปหน่อย แต่ฉันว่าฉันทำได้ดีมาก ๆ เลยนะ",
  str_homestory_815001001_35_dialog_content = "เพราะงั้น... เธอไม่อยากไปดูหน่อยเหรอ",
  str_homestory_815001001_36_dialog_content = "ในเมื่อ PlayerName พูดแบบนั้น งั้นเลนอร์ก็จะไป",
  str_homestory_815001001_37_dialog_content = "ใช่ ไปสนุกกัน",
  str_homestory_815001001_38_dialog_content = "แต่เลนอร์ควรจะไปที่ไหนเหรอ?",
  str_homestory_815001001_39_dialog_content = "PlayerName พอจะมีคำแนะนำให้เลนอร์มั้ย?",
  str_homestory_815001001_40_dialog_content = "อ๊ะ!",
  str_homestory_815001001_41_dialog_content = "เป็นอะไรไป PlayerName?",
  str_homestory_815001001_42_dialog_content = "ไม่มีอะไร...",
  str_homestory_815001001_43_dialog_content = "แค่รู้สึกว่าเลนอร์จะเข้าใจว่า \"แนะนำ\" จริง ๆ แล้วน่ะ",
  str_homestory_815001001_44_dialog_content = "ฉันเลยประทับใจนิดหน่อย...",
  str_homestory_801901001_0_dialog_content = "คุณวิกตอเรีย...",
  str_homestory_801901001_1_dialog_content = "สวัสดี PlayerName",
  str_homestory_801901001_2_dialog_content = "คุณวิกตอเรีย ดีใจที่ได้เจอนะ",
  str_homestory_801901001_3_dialog_content = "ฉันกำลังชื่นชมลำธารที่สุขสันต์เหล่านี้ เธอมาดูด้วยกันมั้ย?",
  str_homestory_801901001_4_dialog_content = "ชื่นชมลำธาร?",
  str_homestory_801901001_5_dialog_content = "ขอโทษนะ... ลำธารที่ไหลลงมาจากหินนี่มีอะไรพิเศษเหรอครับ?",
  str_homestory_801901001_6_dialog_content = "สายน้ำที่ไหลรินเข้าสู่วังวนวัฏจักรอันไม่รู้จบโดยไม่รู้ตัว",
  str_homestory_801901001_7_dialog_content = "เธอไม่คิดว่ามันคล้ายกับออโรเรียนอย่างพวกเราหรอกเหรอ?",
  str_homestory_801901001_8_option_content = "พยักหน้า",
  str_homestory_801901001_9_dialog_content = "อื้ม ก็นิดหน่อย...",
  str_homestory_801901001_10_dialog_content = "แต่ผมไม่ค่อยเข้าใจสิ่งที่คุณพูด...",
  str_homestory_801901001_11_option_content = "ส่ายหัว",
  str_homestory_801901001_12_dialog_content = "ขอโทษนะ คุณวิกตอเรีย...",
  str_homestory_801901001_13_dialog_content = "ผมไม่ค่อยเข้าใจ",
  str_homestory_801901001_14_dialog_content = "ไม่เป็นไร ก็แค่คำพูดที่ไม่มีความหมายอะไรนัก",
  str_homestory_801901001_15_dialog_content = "คุณวิกตอเรียเข้าใจว่ายังไงเหรอ?",
  str_homestory_801901001_16_dialog_content = "สายน้ำไม่เคยรู้ว่าตัวเองอยู่ในวัฏจักร",
  str_homestory_801901001_17_dialog_content = "เพราะมันไหลไปอย่างไร้จุดหมาย",
  str_homestory_801901001_18_dialog_content = "มันไม่รู้ว่าทำไมถึงต้องไหลไป และไม่รู้ว่าจะหลุดจากวงจรนี้ได้อย่างไร หรือจะไปสิ้นสุดที่ใด",
  str_homestory_801901001_19_dialog_content = "พวกเราส่วนใหญ่ต่างก็ใช้ชีวิตกันแบบนี้ เธอคิดว่างั้นมั้ย?",
  str_homestory_801901001_20_dialog_content = "ฉันไม่ได้ตำหนิหรือสงสารพวกเขาแต่อย่างใด",
  str_homestory_801901001_21_dialog_content = "การใช้ชีวิตของแต่ละคน สำหรับฉันแล้วมันไม่ได้แตกต่างกันเลย",
  str_homestory_801901001_22_dialog_content = "ฉันแค่ลองคิดดูเท่านั้น",
  str_homestory_801901001_23_dialog_content = "...ลองคิด?",
  str_homestory_801901001_24_dialog_content = "ใช่",
  str_homestory_801901001_25_dialog_content = "เราต้องเคารพความคิดของเรา อะไรก็ตามที่ทำให้เธอคิดนั้น อยู่นอกเหนือความเข้าใจในปัจจุบันของเธอด้วย",
  str_homestory_801901001_26_dialog_content = "...คุณหมายถึง... เราต้องเคารพสิ่งที่ไม่รู้งั้นเหรอ?",
  str_homestory_801901001_27_dialog_content = "ประมาณนั้นแหละ ที่รัก",
  str_homestory_801901001_28_dialog_content = "ลำธารเหล่านี้อาจมีช่วงเวลาที่สนุกสนาน พวกเขาไม่ต้องการเสียงของเราในกระแสของพวกเขาหรอก",
  str_homestory_801901001_29_dialog_content = "มันเป็นเรื่องที่ดีที่จะมีความสุขและพอใจกับวัฏจักรนี้",
  str_homestory_801901001_30_dialog_content = "เพราะงั้น... พวกเขาก็ไม่ต้องเป็นอารมณ์กับเรื่องแบบนี้เหมือนกับที่คุณเป็นใช่มั้ย?",
  str_homestory_801901001_31_dialog_content = "หึหึ ใครจะไปรู้ล่ะ?",
  str_homestory_801901001_32_dialog_content = "ว่าแต่... แดดที่นี่ร้อนจังเลยนะ<sprite=emo_taiyang size=60 />",
  str_homestory_801901001_33_dialog_content = "เอ่อ... ตรงนั้นมีร่มกันแดดอยู่นะ คุณวิกตอเรียอยากเข้าไปหลบในนั้นมั้ย?",
  str_homestory_801901001_34_dialog_content = "ขอบคุณที่เป็นห่วงนะ PlayerName แต่ฉันว่าฉันไปพักผ่อนดีกว่า",
  str_homestory_801901001_35_dialog_content = "ขอความจริงจงสถิตกับเธอ",
  str_homestory_800901001_0_dialog_content = "คุณเฟาสต์?",
  str_homestory_800901001_1_dialog_content = "สวัสดีผู้นำทาง ดีใจที่ได้เจอกันอีกนะ",
  str_homestory_800901001_2_dialog_content = "เช่นกันครับ",
  str_homestory_800901001_3_dialog_content = "อันที่จริง ผมไม่คิดว่าจะเจอคุณในตอนกลางวันแบบนี้",
  str_homestory_800901001_4_dialog_content = "อย่าเข้าใจฉันผิดน่า ฉันแค่ชอบตอนกลางคืนมากกว่าก็เท่านั้น แต่ฉันก็ไม่ได้ต่อต้านพลังงานของกลางวันสักหน่อย",
  str_homestory_800901001_5_dialog_content = "วิสปี้ดูจะชอบที่นี่นะ",
  str_homestory_800901001_6_dialog_content = "...เดี๋ยวนะ วิสปี้ชอบที่นี่เหรอ?",
  str_homestory_800901001_7_dialog_content = "ที่นี่มีความโศกเศร้าและความสิ้นหวังมากมายขนาดนั้นเลยเหรอ?",
  str_homestory_800901001_8_dialog_content = "ฉันยังจำได้ดีว่ากระเป๋าอันแสนพิเศษนั่นน้ำลายสอกับอารมณ์สิ้นหวังมากแค่ไหน...",
  str_homestory_800901001_9_dialog_content = "วิสปี้ชอบกินหลายอย่างนะ",
  str_homestory_800901001_10_dialog_content = "ความทรงจำที่เศร้าโศก ฝันร้าย ความเชื่อที่สิ้นหวัง แล้วก็น้ำเย็น ๆ...",
  str_homestory_800901001_11_dialog_content = "หา?!",
  str_homestory_800901001_12_dialog_content = "(พอนึกถึงตอนที่เคยดูแลวิสปี้แล้ว...<sprite=emo_sikao size=60 />)",
  str_homestory_800901001_13_dialog_content = "(แสดงว่าผู้คนที่นี่เศร้าโศกเสียใจแล้วก็ฝันร้ายงั้นเหรอ?)",
  str_homestory_800901001_14_dialog_content = "ผู้นำทาง อย่าคิดมากนักเลย",
  str_homestory_800901001_15_dialog_content = "ของโปรดของวิสปี้...",
  str_homestory_800901001_16_dialog_content = "อาจจะมาจากอดีตของออโรเรียน ไม่ใช่ความรู้สึกในปัจจุบัน",
  str_homestory_800901001_17_dialog_content = "เท่าที่ฉันรู้ ผู้คนไม่น้อยมีอดีตที่ขมขื่นและเจ็บปวด",
  str_homestory_800901001_18_dialog_content = "ถ้าพูดแบบนั้น...",
  str_homestory_800901001_19_dialog_content = "อื้ม... มันก็จริงนั่นแหละ",
  str_homestory_800901001_20_dialog_content = "ผมหวังว่าทุกคนจะอยู่ที่นี่อย่างมีความสุข",
  str_homestory_800901001_21_dialog_content = "บางทีความทรงจำและความรู้สึกก็อยู่เหนือการควบคุมนะ ผู้นำทาง",
  str_homestory_800901001_22_dialog_content = "การไม่กังวัลกับคนอื่นมากเกินไป ก็เป็นนิสัยที่ควรมีเหมือนกัน",
  str_homestory_800901001_23_dialog_content = "ให้ธรรมชาติดำเนินไปตามครรลองของมันเถอะ",
  str_homestory_800901001_24_dialog_content = "...ครับ",
  str_homestory_800901001_25_dialog_content = "แล้วคุณมาทำอะไรที่นี่เหรอ?",
  str_homestory_800901001_26_option_content = "เผยแพร่ความจริง?",
  str_homestory_800901001_27_dialog_content = "ไม่ใช่หรอก ผู้นำทาง",
  str_homestory_800901001_28_option_content = "มาให้อาหารวิสปี้เหรอ?",
  str_homestory_800901001_29_dialog_content = "ใช่แล้วล่ะ ผู้นำทาง",
  str_homestory_800901001_30_dialog_content = "นี่เป็นที่ที่เหมาะจะให้อาหารวิสปี้...",
  str_homestory_800901001_31_dialog_content = "วิสปี้จะได้สัมผัสกับคนที่ผ่านไปผ่านมาด้วย",
  str_homestory_800901001_32_dialog_content = "ให้วิสปี้สัมผัสอย่างอิสระ...",
  str_homestory_800901001_33_dialog_content = "เอ่อ... ทุกคนมีความเจ็บปวดที่บรรยายไม่ได้ในหัวใจมากขนาดนั้นเลยเหรอ?",
  str_homestory_800901001_34_dialog_content = "ฉันก็ไม่รู้เหมือนกัน ผู้นำทาง",
  str_homestory_800901001_35_dialog_content = "แต่อย่างไรก็ตาม มีสิ่งหนึ่งที่ฉันรู้แน่ชัดดี",
  str_homestory_800901001_36_dialog_content = "อะไรเหรอ?",
  str_homestory_800901001_37_dialog_content = "ก่อนที่เราจะออกบ้าน วิสปี้ดื่มน้ำเย็นเป็นตันเลย",
  str_homestory_800901001_38_dialog_content = "?",
  str_homestory_800901001_39_dialog_content = "งั้นที่วิสปี้รู้สึกสบายก็เป็นเพราะน้ำเย็นเจี๊ยบที่เพิ่งดื่มไปงั้นเหรอ?",
  str_homestory_800901001_40_dialog_content = "นั่นหมายความว่าอาจจะไม่มีความเศร้าโศก ความเจ็บปวด หรือความรู้สึกด้านลบอื่น ๆ เลยก็ได้",
  str_homestory_800901001_41_dialog_content = "คุณแกล้งผม!",
  str_homestory_800901001_42_dialog_content = "เหมือนจะเป็นแบบนั้น ผู้นำทาง",
  str_homestory_800901001_43_dialog_content = "แต่ฉันแค่ไม่อยากให้นายจมอยู่กับงานและเครียดจนเกินไปน่ะ",
  str_homestory_800901001_44_dialog_content = "สิ่งต่าง ๆ ไม่เห็นจำเป็นต้องสมบูรณ์แบบเลย ว่ามั้ย?",
  str_homestory_800901001_45_dialog_content = "ขอความจริงจงสถิตกับนาย!",
  str_homestory_800901001_46_dialog_content = "คุณนี่นะ...!<sprite=emo_shengqi size=60 />",
  str_homestory_815101001_0_dialog_content = "นี่มันเพลงกล่อมเด็ก...",
  str_homestory_815101001_1_dialog_content = "มีแกะดำตัวหนึ่งชื่อไอแซค ขนของมันน่ากลัวถึงขั้นเผาแขนคุณได้!",
  str_homestory_815101001_2_dialog_content = "หวัดดี ไจลส์",
  str_homestory_815101001_3_dialog_content = "อ๋า ผู้นำทาง",
  str_homestory_815101001_4_dialog_content = "ฉันเกือบลืมไปเลย นายเคยได้ยินเพลงกล่อมเด็กนี้แล้ว",
  str_homestory_815101001_5_dialog_content = "ดูเหมือนจะถึงเวลาสำหรับสิ่งใหม่ ๆ แล้ว?",
  str_homestory_815101001_6_dialog_content = "ผลงานใหม่ ๆ ที่มีลักษณะเหมือนคำพยากรณ์ โดยมีเคเลสไทต์เป็นศูนย์กลาง...<sprite=emo_baimao size=60 />",
  str_homestory_815101001_7_dialog_content = "เอ่อ...",
  str_homestory_815101001_8_dialog_content = "นายดูลังเลนะ ผู้นำทาง?",
  str_homestory_815101001_9_dialog_content = "แบบนี้ฉันก็เสียใจแย่เลย...",
  str_homestory_815101001_10_dialog_content = "เมื่อก่อนนายเคยบอกว่าชอบเพลงกล่อมเด็กของฉันนี่นา...",
  str_homestory_815101001_11_dialog_content = "(...ฉันเคยพูดแบบนั้นด้วยเหรอ?)",
  str_homestory_815101001_12_option_content = "นายแต่งเสร็จหรือยัง?",
  str_homestory_815101001_13_dialog_content = "ตราบใดที่มีแรงบันดาลใจก็ใช้เวลาไม่นานหรอก",
  str_homestory_815101001_14_dialog_content = "ประจวบเหมาะกับว่าแรงบันดาลใจมาอยู่ตรงหน้าฉันพอดีด้วยสิ...",
  str_homestory_815101001_15_option_content = "นายรอก่อนได้ไหม?",
  str_homestory_815101001_16_dialog_content = "นี่ไม่คิดแม้แต่จะหาข้ออ้างด้วยซ้ำหรือนี่",
  str_homestory_815101001_17_dialog_content = "พูดแบบนี้มันคือการปฏิเสธฉันชัด ๆ เลยนี่นา",
  str_homestory_815101001_18_dialog_content = "เคเลสไทต์ที่มีเสน่ห์และปราดเปรียว สามารถขโมยหัวใจของคุณได้อย่างง่ายดาย...",
  str_homestory_815101001_19_dialog_content = "...เริ่มแล้วเหรอ?",
  str_homestory_815101001_20_dialog_content = "ลา ลา ลา～ ลา ลา ลา～♫ บ้านที่มีเสน่ห์ เปี่ยมไปด้วยดอกไม้",
  str_homestory_815101001_21_dialog_content = "ปลาตัวเล็ก กุ้งตัวจ้อย ต่างเรียกมันว่าบ้าน",
  str_homestory_815101001_22_dialog_content = "เธออาศัยอยู่ที่นี่ ร่วมโอบกอดเคเลสไทต์ผู้กล้าหาญ",
  str_homestory_815101001_23_dialog_content = "หยาดเยิ้ม... หยาดฝน... สายฝนโปรดปราย",
  str_homestory_815101001_24_dialog_content = "สร้างหอคอยสูง เสริมความแข็งแกร่ง ด้วยอิฐปูนและกระเบื้อง เฟ้นหาหนทางแห่งความแข็งแกร่ง",
  str_homestory_815101001_25_dialog_content = "ลา ลา ลา～ ลา ลา ลา～♫ เคเลสไทต์อยู่แห่งหนใด?",
  str_homestory_815101001_26_dialog_content = "บ้านหลังใหญ่และสูง มองไปยังเคเลสไทต์เหนือเมฆ โดยไม่กะพริบตา",
  str_homestory_815101001_27_dialog_content = "ลา ลา ลา～ ลา ลา ลา～♫ บ้านที่มีเสน่ห์ เปี่ยมไปด้วยดอกไม้...",
  str_homestory_815101001_28_dialog_content = "...นี่คือคำทำนายของนายงั้นเหรอ?",
  str_homestory_815101001_29_dialog_content = "ก็แค่เพลงกล่อมเด็กธรรมดาน่า ผู้นำทาง",
  str_homestory_815101001_30_dialog_content = "นายกลัวเหรอ? มันเป็นแค่ผลงานของฉันน่ะ...",
  str_homestory_815101001_31_dialog_content = "ใช่ ฉันรู้",
  str_homestory_815101001_32_dialog_content = "ฉันรู้สึกว่าว่าเพลงกล่อมเด็กของนายมักจะเรียบง่ายแต่มีความหมายที่คลุมเครืออยู่เสมอ",
  str_homestory_815101001_33_dialog_content = "เพลงกล่อมเด็กก็คือเพลงกล่อมเด็กน่า",
  str_homestory_815101001_34_dialog_content = "ผู้นำทาง อย่าคิดมากเลย",
  str_homestory_815101001_35_dialog_content = "ก็ได้ งั้นมาเข้าเรื่องชีวิตจริงกันเถอะ...",
  str_homestory_815101001_36_dialog_content = "นายอยู่ที่นี่แล้วเป็นยังไงบ้าง?",
  str_homestory_815101001_37_dialog_content = "ไอแซคกับฉันชอบมากเลย",
  str_homestory_815101001_38_dialog_content = "ที่นี่ทำให้ฉันอยากเขียนเพลงเพิ่มสุด ๆ... ฮ่าฮ่า!",
  str_homestory_815101001_39_dialog_content = "ไม่ว่าจะเป็นผู้สัญจรไปมาหรือผู้นำทาง ล้วนเป็นแรงบันดาลใจสำหรับฉันทั้งนั้น <sprite=emo_emo size=60 />",
  str_homestory_815101001_40_dialog_content = "ดีใจที่ได้รู้นะ...",
  str_homestory_815101001_41_dialog_content = "แบะ... แบะ...",
  str_homestory_815101001_42_dialog_content = "ฉันอยากอยู่ตามลำพังกับไอแซคน่ะ ขอตัวก่อนนะผู้นำทาง",
  str_homestory_815101001_43_dialog_content = "ไว้เจอกันใหม่ก็แล้วกัน",
  str_homestory_815101001_44_dialog_content = "ได้เลย... ไว้เจอกัน",
  str_homestory_815301001_0_dialog_content = "ท่านจอมทัพ?",
  str_homestory_815301001_1_dialog_content = "โครงสร้างพื้นฐานของเธอทำได้ดีมากเลยนะ <sprite=emo_dianzan size=60 />",
  str_homestory_815301001_2_dialog_content = "ขอบคุณสำหรับคำชมครับ ท่านจอมทัพ!",
  str_homestory_815301001_3_dialog_content = "ฉันเคยชินกับสี่เหลี่ยมที่เรียบร้อยและสม่ำเสมอในอิลลูมินา แต่ที่นี่แตกต่างและแปลกใหม่",
  str_homestory_815301001_4_dialog_content = "ผู้คนต่างดูถูกอิลลูมินา ถึงรสนิยมทางศิลปะที่แย่และมาตรฐานความงามที่ต่ำต้อย",
  str_homestory_815301001_5_dialog_content = "แต่ก็น่าเศร้า เพราะสถานที่มากมายที่แสวงหาความสมบูรณ์แบบทางศิลปะนั้น ก็ไม่อาจเลี้ยงผู้คนของตัวเองให้อิ่มท้อง",
  str_homestory_815301001_6_dialog_content = "สิ่งที่มีโครงสร้างเป็นระเบียบนั้นใช้ต้นทุนต่ำและให้ผลลัพธ์ที่มีประสิทธิภาพมากกว่า นี่เป็นความจริงที่เข้าใจได้ง่าย ๆ",
  str_homestory_815301001_7_dialog_content = "แต่ฉันต้องยอมรับว่าที่นี่สวยจริง ๆ",
  str_homestory_815301001_8_dialog_content = "สวยและเรียบง่าย เธอกับไวซ์คงพยายามทำงานกันอย่างหนัก",
  str_homestory_815301001_9_option_content = "พยักหน้า",
  str_homestory_815301001_10_dialog_content = "ส่วนใหญ่เป็นเพราะไวซ์มากกว่า... ผมไม่ค่อยรู้อะไรหรอกครับ",
  str_homestory_815301001_11_dialog_content = "อื้ม การยอมรับข้อด้อยของตัวเองถือเป็นเรื่องที่ดีมากนะ",
  str_homestory_815301001_12_option_content = "ส่ายหัว",
  str_homestory_815301001_13_dialog_content = "ไม่หรอกครับ หิ่งห้อยช่วยไว้เยอะเลย และยังมีเพื่อนของเราจากสหภาพผู้ส่งสารด้วย",
  str_homestory_815301001_14_dialog_content = "แค่ทุกคนมีช่วงเวลาที่ดีในที่แห่งนี้ พวกเราก็มีความสุขแล้วล่ะครับ",
  str_homestory_815301001_15_dialog_content = "นั่นเป็นนิสัยที่ยอดเยี่ยมที่สุดของพวกเธอสองคนนะ",
  str_homestory_815301001_16_dialog_content = "สำหรับฉันแล้ว การมีความสุขที่ได้ดูแลผู้อื่นนั้น ถือเป็นของขวัญพิเศษล้ำค่า",
  str_homestory_815301001_17_dialog_content = "ตามที่พวกเธอได้ตระเตรียมวางแผนไว้...",
  str_homestory_815301001_18_dialog_content = "ฉันพักอยู่ในห้องเหมือนกันกับไวซ์ และเราก็ทานอาหารเหมือนกันทุกวัน",
  str_homestory_815301001_19_dialog_content = "นั่นก็เรียกได้ว่าเธอดูแลฉันได้ดีกว่าคนส่วนใหญ่",
  str_homestory_815301001_20_dialog_content = "เพราะมันเป็นการยากที่จะปฏิบัติต่อทุกคนอย่างเท่าเทียมกัน โดยไม่คำนึงถึงสถานะและตำแหน่งใด ๆ",
  str_homestory_815301001_21_dialog_content = "(คิดไม่ถึงว่าท่านจอมทัพจะมองในมุมนี้แฮะ...)",
  str_homestory_815301001_22_dialog_content = "(ฉันควรบอกความจริงกับเธอมั้ยนะ?)",
  str_homestory_815301001_23_dialog_content = "(โอเค... พูดตรง ๆ เลยดีกว่า...)",
