  str_homestory_803801001_7_dialog_content = "หืมม เข้าใจแล้ว! PlayerName ผู้น่ารักต้องมาที่นี่เพื่อคลายความเบื่อหน่ายให้ฉันใช่มั้ยล่ะ?",
