  str_homestory_808501001_26_dialog_content = "จะเกิดอะไรขึ้นหากการเข้าไปยุ่งของฉันเปลี่ยนแปลงสิ่งที่จะเกิดขึ้น?",
  str_homestory_808501001_27_dialog_content = "เมื่อผู้บันทึกเรื่องราวลังเล เรื่องราวของเธอก็จะไม่เป็นกลางอีกต่อไป",
  str_homestory_808501001_28_dialog_content = "บางทีสาวน้อยคนนั้นอาจมีชะตาต้องหายไปจากโลก และนั่นเป็นผลมาจากการต่อสู้ของแก๊งในครั้งนี้",
  str_homestory_808501001_29_dialog_content = "แต่ฉันก็ได้ช่วยเธอไว้...",
  str_homestory_808501001_30_dialog_content = "...และการเฝ้ามองอย่างไม่เป็นกลาง มันก็ไร้ความหมาย",
  str_homestory_808501001_31_dialog_content = "อย่างแรก คุณเป็นคนเห็นใจคน และอย่างที่สอง คุณเป็นผู้บันทึกเรื่องราวที่พยายามอย่างเต็มที่เพื่อรักษาความเป็นกลางของตัวเอง",
  str_homestory_808501001_32_dialog_content = "เรื่องนี้ผมเข้าใจดี",
  str_homestory_808501001_33_dialog_content = "...",
  str_homestory_808501001_34_dialog_content = "...รู้แล้ว",
  str_homestory_808501001_35_dialog_content = "ทำไมคุณไม่เขียนเรื่องของตัวคุณเองลงในบันทึกด้วยล่ะ?",
  str_homestory_808501001_36_dialog_content = "เรื่องของฉันเหรอ?",
  str_homestory_808501001_37_dialog_content = "ใช่ เขียนทุกอย่างด้วยความสัตย์จริง",
  str_homestory_808501001_38_dialog_content = "ผู้บันทึกเรื่องราวที่เข้าไปแทรกแซงในกระบวนการเพราะอารมณ์ที่ถูกกระตุ้น หลังจากการต่อสู้ของแก๊งนี้... อาจเกิดผลกระทบบางอย่าง",
  str_homestory_808501001_39_dialog_content = "...อะไรประมาณนั้น",
  str_homestory_808501001_40_dialog_content = "...",
  str_homestory_808501001_41_dialog_content = "ที่พูดมาก็มีเหตุผล",
  str_homestory_808501001_42_dialog_content = "ฉันจะลองจดบันทึกในลักษณะนี้ดูก็แล้วกัน",
  str_homestory_808501001_43_dialog_content = "ขอบคุณนะ",
  str_homestory_808801001_0_dialog_content = "แม็กกี้!",
  str_homestory_808801001_1_dialog_content = "ผู้นำทาง... นายมาที่นี่เพื่อฟังเรื่องราวเหมือนกันเหรอ?<sprite=emo_wuzui size=60 />",
  str_homestory_808801001_2_dialog_content = "เรื่องราว? เรื่องราวอะไรเหรอ?",
  str_homestory_808801001_3_dialog_content = "ฉันว่าเราต้องคุยกันหน่อยแล้ว พอเธอพูดแล้วฉันก็สนใจขึ้นมาเลย",
  str_homestory_808801001_4_dialog_content = "โอ๊ะโอ... เผลอหลุดปากไปซะแล้ว...",
  str_homestory_808801001_5_dialog_content = "หืม? แม็กกี้ไม่อยากให้ฉันรู้เหรอ?",
  str_homestory_808801001_6_dialog_content = "ไม่ใช่อย่างนั้นหรอก...",
  str_homestory_808801001_7_dialog_content = "ก็ได้... ยังไงมันก็ไม่ใช่ความลับแล้วล่ะ...",
  str_homestory_808801001_8_dialog_content = "เรื่องมันเป็นยังไงเหรอ?",
  str_homestory_808801001_9_dialog_content = "อืมม... คือเมื่อหลายวันก่อน ฉันไปสำรวจทะเลทราย...",
  str_homestory_808801001_10_dialog_content = "แล้วบังเอิญเจอเด็กสองสามคน",
  str_homestory_808801001_11_dialog_content = "เห็นได้ชัดเลยว่าพวกเขาหนีออกจากบ้าน และกำลังหลงทางอยู่ในทะเลทรายอันกว้างใหญ่...",
  str_homestory_808801001_12_dialog_content = "ฉันเห็นพวกเขาเดินหลงทางเป็นวงกลม ก็เลยเสนอตัวช่วย",
  str_homestory_808801001_13_dialog_content = "หลังจากพาพวกเขาไปที่ที่ปลอดภัยแล้ว พวกเขาถามชื่อฉันและอยากจะมาตอบแทนฉันในสักวันหนึ่ง",
  str_homestory_808801001_14_dialog_content = "แต่ก่อนจะแนะนำตัว พวกเขาก็เห็นหางของฉันเข้า... พวกเขา...",
  str_homestory_808801001_15_option_content = "พวกเขาหัวเราะเยาะเธอเหรอ?",
  str_homestory_808801001_16_dialog_content = "ไม่ใช่...",
  str_homestory_808801001_17_dialog_content = "พวกเขาบอกว่ามันน่ารักมาก!",
  str_homestory_808801001_18_dialog_content = "ก็ดีแล้วไม่ใช่เหรอ?",
  str_homestory_808801001_19_option_content = "พวกเขาจำเธอได้?",
  str_homestory_808801001_20_dialog_content = "ไม่ใช่...",
  str_homestory_808801001_21_dialog_content = "ฉันไม่ได้ป๊อปเหมือนเฟลอร์นะ...",
  str_homestory_808801001_22_dialog_content = "แต่พวกเขา...",
  str_homestory_808801001_23_dialog_content = "พวกเขาเข้าใจผิดว่าฉันเป็นมังกร!",
  str_homestory_808801001_24_dialog_content = "?",
  str_homestory_808801001_25_dialog_content = "ฉันเองก็ตกใจเหมือนกัน...",
  str_homestory_808801001_26_dialog_content = "พวกนั้นล้ำเส้นเกินไปแล้ว!",
  str_homestory_808801001_27_dialog_content = "พวกเขาบอกฉันว่าไม่เคยเห็นมังกรที่มีขนปุกปุยมาก่อน...",
  str_homestory_808801001_28_dialog_content = "แถมยังขอจับหางฉันอีก...",
  str_homestory_808801001_29_dialog_content = "น่าโมโหชะมัดเลย!<sprite=emo_wuyun size=60 />",
  str_homestory_808801001_30_dialog_content = "ทำไมล่ะ? แค่อธิบายความจริงไปก็น่าจะหมดเรื่องแล้วนี่?",
  str_homestory_808801001_31_dialog_content = "ฉันไม่ได้ถือสาที่พวกเขาเข้าใจผิดหรอกนะ แต่ฉันไม่ชอบทัศนคติของเด็กพวกนั้นเลย!",
  str_homestory_808801001_32_dialog_content = "\"ขอจับหางของคุณหน่อยได้มั้ย?\"",
  str_homestory_808801001_33_dialog_content = "ใครเขาขอแบบนี้กัน?",
  str_homestory_808801001_34_dialog_content = "คนเราจะพูดแบบนี้เฉพาะกับสัตว์เลี้ยงเท่านั้นแหละ",
  str_homestory_808801001_35_dialog_content = "ฉ-ฉันโมโหสุด ๆ เลย...",
  str_homestory_808801001_36_dialog_content = "ฉันอยากเผาทุกอย่างให้วอดจริง ๆ <sprite=emo_nuhuo size=60 />! ตอนนี้เลยได้มั้ย!",
  str_homestory_808801001_37_dialog_content = "(เอาอีกแล้ว!)",
  str_homestory_808801001_38_dialog_content = "ใจเย็น ๆ ก่อนนะ แม็กกี้",
  str_homestory_808801001_39_dialog_content = "พวกนั้นอาจจะรู้สึกว่าหางของเธอน่ารักมากเฉย ๆ ก็ได้?",
  str_homestory_808801001_40_dialog_content = "นะ-นี่ก็เป็นสิ่งที่ฉันคิดอยู่ตลอดเวลาเหมือนกัน!",
  str_homestory_808801001_41_dialog_content = "...พูดตามตรงนะ ฉันจินตนาการไม่ออกเลยว่าแม็กกี้จะมีสภาพยังไง ถ้าไม่มีหางสวย ๆ นี่",
  str_homestory_808801001_42_dialog_content = "...",
  str_homestory_808801001_43_dialog_content = "... จริงเหรอ?",
  str_homestory_808801001_44_dialog_content = "(ฟู่ว... ดูเหมือนเธอจะโกรธน้อยลงแล้ว...)",
  str_homestory_808801001_45_dialog_content = "ใช่แล้ว! ฉันสาบานเลย!",
  str_homestory_808801001_46_dialog_content = "...งั้นก็ได้...",
  str_homestory_808801001_47_dialog_content = "โอ๊ะ! ว่าแต่....",
  str_homestory_808801001_48_dialog_content = "ทำไมก่อนหน้านี้เธอถึงบอกว่าไม่ใช่ความลับอีกต่อไปแล้วล่ะ?",
  str_homestory_808801001_49_dialog_content = "ฉันว่าไม่น่าจะมีใครรู้เรื่องนี้เท่าไหร่นะ...",
  str_homestory_808801001_50_dialog_content = "เพราะว่า...",
  str_homestory_808801001_51_dialog_content = "โจมูได้รวบรวมเรื่องนี้ไว้ในคอลเลกชันเรื่องสั้นล่าสุดของเขาน่ะสิ...",
  str_homestory_808801001_52_dialog_content = "...อืมม... ฉันน่าจะคิดได้ตั้งแต่แรกแล้วว่าเรื่องจะเป็นแบบนี้...",
  str_homestory_800801001_0_dialog_content = "บร็อค?",
  str_homestory_800801001_1_dialog_content = "ฮ่าฮ่า! ดีใจที่ได้เจอนะ <sprite=emo_yaosu size=60 />",
  str_homestory_800801001_2_dialog_content = "เห็นรึยัง? เจ๋งใช่มั้ยล่ะ?",
  str_homestory_800801001_3_dialog_content = "เอ่อ... นายพูดถึงเรื่องอะไรเหรอบร็อค?",
  str_homestory_800801001_4_dialog_content = "หมัดของฉันไง! ชัดเจน! เท่ระเบิด!",
  str_homestory_800801001_5_dialog_content = "อืมม... ก็ไม่เลวนะ!",
  str_homestory_800801001_6_dialog_content = "ก็ไม่เลว? แค่เนี้ย?",
  str_homestory_800801001_7_dialog_content = "ไม่เป็นไร ยังไงนายก็ไม่รู้เรื่องมวยอยู่แล้ว ฉันว่าตอนนี้นายอาจจะอิจฉาฉันอยู่ก็ได้",
  str_homestory_800801001_8_dialog_content = "?",
  str_homestory_800801001_9_dialog_content = "ไม่ต้องห่วง PlayerName! ถึงแม้ตอนนี้นายจะอิจฉาฉัน แต่ฉันก็ยังดีกับนายเสมอ!",
  str_homestory_800801001_10_dialog_content = "แต่ฉันไม่ได้อิจฉานายนะ...",
  str_homestory_800801001_11_dialog_content = "ชู่วว... ฉันเข้าใจ ๆ",
  str_homestory_800801001_12_dialog_content = "ตอนที่ฉันอายุเท่านาย ฉันก็ปรารถนาจะเป็นลูกผู้ชายตัวจริงเหมือนที่ตัวเองเป็นในตอนนี้เหมือนกัน<sprite=emo_mojing size=60 />",
  str_homestory_800801001_13_dialog_content = "ฟังนะ PlayerName! ไม่มีอะไรที่เป็นไปไม่ได้สำหรับหัวใจที่มุ่งมั่นหรอก!",
  str_homestory_800801001_14_dialog_content = "...ก็ได้ บร็อค",
  str_homestory_800801001_15_dialog_content = "ไม่เป็นไร เป็นหน้าที่ของฉันอยู่แล้วที่ต้องเติมพลังเชื้อเพลิงให้กับสวนลอยฟ้า",
  str_homestory_800801001_16_dialog_content = "เรื่องการดูแลเด็ก ๆ น่ะ ไม่มีใครทำได้ดีกว่าฉันคนนี้อีกแล้ว",
  str_homestory_800801001_17_dialog_content = "เดี๋ยวนะ... หน้าที่อะไร? แล้วเชื้อเพลิงอะไร?",
  str_homestory_800801001_18_dialog_content = "ดูเหมือนนายยังไม่รู้ถึงการเสียสละของฉันนะ?",
  str_homestory_800801001_19_dialog_content = "...บอกฉันมา",
  str_homestory_800801001_20_dialog_content = "เอาล่ะ หลายวันก่อนฉันไปเยี่ยมโอดี เพื่อให้เธอย้อมสีของบร็อคคนนี้เป็นสีรุ้ง",
  str_homestory_800801001_21_dialog_content = "เธอทำหน้าตาเป็นกังวลสุด ๆ และขอร้องให้ฉันช่วยนายทำสิ่งนี้",
  str_homestory_800801001_22_dialog_content = "ทำอะไร?",
  str_homestory_800801001_23_dialog_content = "โอดีบอกฉันว่า...",
  str_homestory_800801001_24_dialog_content = "หุ่นจำลองของนายมีเครื่องยนต์ความร้อนติดตั้งอยู่ภายใน",
  str_homestory_800801001_25_dialog_content = "?",
  str_homestory_800801001_26_dialog_content = "เครื่องยนต์นี้เป็นแหล่งพลังงานของสวนลอยฟ้าทั้งหมด",
  str_homestory_800801001_27_dialog_content = "หรือพูดง่าย ๆ ก็คือ การที่ฉันชกเป็นพัน ๆ ครั้งในทุก ๆ วันนั้น ทำให้สวนลอยฟ้าทำงานต่อไป",
  str_homestory_800801001_28_dialog_content = "ฮ่าฮ่า! ทำไมทำหน้าแบบนั้นล่ะ? ฉันมีความสุขดี!",
  str_homestory_800801001_29_dialog_content = "ฉันยินดีที่จะช่วยนะ!",
  str_homestory_800801001_30_dialog_content = "...เอ่อ... บร็อค... ฉันคิดว่า...",
  str_homestory_800801001_31_option_content = "นายถูกหลอกแล้วล่ะ",
  str_homestory_800801001_32_dialog_content = "หุ่นจำลองนี้ไม่อะไรเลยนอกจากวัสดุไส้ใน...",
  str_homestory_800801001_33_dialog_content = "พูดอีกอย่างก็คือ มันไม่มีส่วนเกี่ยวข้องกับสวนลอยฟ้าเลย",
  str_homestory_800801001_34_dialog_content = "แต่ว่า!",
  str_homestory_800801001_35_dialog_content = "การฝึกชกมวยเป็นประจำทุกวันของนาย ก็ยังดีต่อสุขภาพร่างกายและจิตใจนะ",
  str_homestory_800801001_36_option_content = "ขอบใจ!",
  str_homestory_800801001_37_dialog_content = "แต่ว่า...",
  str_homestory_800801001_38_dialog_content = "ฉันว่าโอดีเองก็คงไม่คุ้นเคยเกี่ยวกับโครงสร้างของสวนลอยฟ้ามากนักหรอก",
  str_homestory_800801001_39_dialog_content = "ฉันหมายถึง...",
  str_homestory_800801001_40_dialog_content = "หุ่นจำลองนี้ไม่อะไรเลยนอกจากวัสดุไส้ใน...",
  str_homestory_800801001_41_dialog_content = "โอ้! งั้นเหรอ?",
  str_homestory_800801001_42_dialog_content = "ฮ่าฮ่า ดูเหมือนว่าโอดีจะไม่ได้ถูกเสมอไปนะ!",
  str_homestory_800801001_43_dialog_content = "อืม... บร็อค...",
  str_homestory_800801001_44_dialog_content = "นายน่าจะถูกหลอกแล้วล่ะ",
  str_homestory_800801001_45_dialog_content = "ฉันก็ว่าอย่างนั้น แล้วก็ไม่ใช่ครั้งแรกด้วยสิ",
  str_homestory_800801001_46_dialog_content = "นายโกรธหรือเปล่า?",
  str_homestory_800801001_47_dialog_content = "ทำไมต้องโกรธด้วยล่ะ?",
  str_homestory_800801001_48_dialog_content = "พวกเขาชอบแกล้งฉันก็เพราะพวกเขาชอบฉันไงละ!",
  str_homestory_800801001_49_dialog_content = "...อืมม... ก็ถูกของนาย",
  str_homestory_800801001_50_dialog_content = "อย่างน้อย...",
  str_homestory_800801001_51_dialog_content = "การที่พวกเขาแกล้งฉันก็เพราะพวกเขาชื่นชมและเชื่อใจฉันไงละ",
  str_homestory_800801001_52_dialog_content = "...ชื่นชม? นายแน่ใจเหรอ?",
  str_homestory_800801001_53_dialog_content = "ถ้างั้นทำไมพวกเขาถึงไม่เคยแกล้งซินซาเลยล่ะ?",
  str_homestory_800801001_54_dialog_content = "เรื่องความสนิทสนมฉันน่ะชนะเห็น ๆ ! ฮ่าฮ่าฮ่าฮ่า!<sprite=emo_dianzan size=60 />",
  str_homestory_806501001_0_dialog_content = "ทวีตตี้?",
  str_homestory_806501001_1_dialog_content = "โว้ว! ผู้นำทาง! ดีใจที่ได้เจอนะ",
  str_homestory_806501001_2_dialog_content = "ทวีตตี้ เป็นอะไรไป? ทำไมต้องประหม่าเวลาที่เจอฉันด้วยล่ะ?",
  str_homestory_806501001_3_dialog_content = "เอ่อ... ฉันเหรอ?",
  str_homestory_806501001_4_dialog_content = "ดูสิ เธอทำของตกเต็มไปหมดเลย",
  str_homestory_806501001_5_dialog_content = "หา! อยู่ไหน ๆ?",
  str_homestory_806501001_6_dialog_content = "ก้อนขนปุยสีขาวที่อยู่ใต้ฝ่าเท้าของเธอ...",
  str_homestory_806501001_7_dialog_content = "อ๋า... ขอฉันดูโหน่ย...",
  str_homestory_806501001_8_dialog_content = "โว้ว! นี่มันขนหางจากทวีตตี้นี่นา!",
  str_homestory_806501001_9_dialog_content = "เง้อ... ไม่น่าทำเรื่องไม่ดีเยย",
  str_homestory_806501001_10_dialog_content = "เรื่องไม่ดี?",
  str_homestory_806501001_11_dialog_content = "ไม่แปลกใจเลยที่วันนี้หางของเธอตกลง",
  str_homestory_806501001_12_dialog_content = "อืมม...",
  str_homestory_806501001_13_dialog_content = "เกิดอะไรขึ้นเหรอ? บอกฉันได้มั้ย?",
  str_homestory_806501001_14_dialog_content = "ฉันบอกผู้นำทางดีกว่า...",
  str_homestory_806501001_15_dialog_content = "วันนี้ทวีตตี้มาเพื่อส่งจดหมาย",
  str_homestory_806501001_16_dialog_content = "โอเค ส่งไปที่สำนักงานไปรษณีย์แล้วใช่มั้ย? งั้นฉันจะรีบไปเดี๋ยวนี้!",
  str_homestory_806501001_17_dialog_content = "แต่... เดี๋ยวก่อน!",
  str_homestory_806501001_18_dialog_content = "จดหมายน่ะ... ยังไม่ได้ส่งไปที่ไปรษณีย์หรอก",
  str_homestory_806501001_19_dialog_content = "ทวีตตี้เห็นว่าที่สวนลอยฟ้าเปลี่ยนไปมาก!",
  str_homestory_806501001_20_dialog_content = "ทวีตตี้ไปที่นั่นแล้วก็ไปที่นี่ เลยลืมเรื่องจดหมายน่ะ...",
  str_homestory_806501001_21_dialog_content = "นี่คือ \"เรื่องไม่ดี\" ที่เธอทำงั้นเหรอ?",
  str_homestory_806501001_22_option_content = "โกรธ",
  str_homestory_806501001_23_dialog_content = "การละเลยหน้าที่ไม่ใช่เรื่องเล็ก ๆ นะ",
  str_homestory_806501001_24_dialog_content = "ในฐานะเจ้าของสวนลอยฟ้า ฉันควรจะทำโทษเธอดีมั้ย?",
  str_homestory_806501001_25_dialog_content = "หวา! ลงโทษงั้นเหยอ?",
  str_homestory_806501001_26_dialog_content = "เหมือนขนหางจะร่วงอีกแล้วสิ...",
  str_homestory_806501001_27_dialog_content = "โอเค... งั้นฉันจะลงโทษเธอ...",
  str_homestory_806501001_28_option_content = "ปลอบเธอ",
  str_homestory_806501001_29_dialog_content = "แต่ไม่ต้องห่วง ไม่ใช่เรื่องเร่งด่วนอะไร",
  str_homestory_806501001_30_dialog_content = "ฉันดีใจนะที่เธอชอบการเปลี่ยนแปลงของที่นี่",
  str_homestory_806501001_31_dialog_content = "ขอบคุณนะ ผู้นำทาง คุณใจดีที่ซู้ดเยย!",
  str_homestory_806501001_32_dialog_content = "แล้วใครส่งจดหมายมาล่ะ?",
  str_homestory_806501001_33_dialog_content = "เอามาให้ฉันดูหน่อยสิ",
  str_homestory_806501001_34_dialog_content = "โอเก! สหภาพผู้ฉ่งฉาร จดหมายทุกฉบับฉ่งถึงมือแน่นอน!",
  str_homestory_806501001_35_dialog_content = "หวา! จดหมายอยู่ไหนหว่า?",
  str_homestory_806501001_36_dialog_content = "ไม่อยู่ในกระเป๋า...",
  str_homestory_806501001_37_dialog_content = "ไม่อยู่ในหมวก!",
  str_homestory_806501001_38_dialog_content = "ใจเย็น ๆ เธอทำตกไว้ที่ไหนรึเปล่า?",
  str_homestory_806501001_39_dialog_content = "ก่อนหน้านี้เธอไปไหนมาเหรอ ทวีตตี้?",
  str_homestory_806501001_40_dialog_content = "ทุกที่... ทวีตตี้ไปมาทู้กที่เลย",
  str_homestory_806501001_41_dialog_content = "...งั้นก็คงยากที่จะหาแล้วล่ะ",
  str_homestory_806501001_42_dialog_content = "ทวีตตี้ไม่อยากกลายเป็นโดฟคนต่อไป...",
  str_homestory_806501001_43_dialog_content = "เอ๊ะ? มีบางอย่างเพิ่งตกมาจากหางของเธอ...",
  str_homestory_806501001_44_dialog_content = "ขนหลุดออกมาจากหางทวีตตี้อีกแล้วเหยอ? ทวีตตี้จะขนย่วงหมดตัวแล้วเนี่ย!",
  str_homestory_806501001_45_dialog_content = "ไม่ มันดูไม่เหมือนขนเลย...",
  str_homestory_806501001_46_dialog_content = "เอ...",
  str_homestory_806501001_47_dialog_content = "อ๋อ! มันคือจดหมายนี่เอง!",
  str_homestory_806501001_48_dialog_content = "มันซ่อนอยู่ในหางของทวีตตี้น่ะ!",
  str_homestory_805501001_0_dialog_content = "นี่มัน...",
  str_homestory_805501001_1_dialog_content = "คุณพิตต์แมน?",
  str_homestory_805501001_2_dialog_content = "...!",
  str_homestory_805501001_3_dialog_content = "คุณพิตต์แมน?",
  str_homestory_805501001_4_dialog_content = "เอ่อ... นายคงจำผิดคนแล้วล่ะ",
  str_homestory_805501001_5_dialog_content = "หืม? แต่ชุดข้าราชการ... แล้วก็รอยดำใต้ตาของคุณ!",
  str_homestory_805501001_6_dialog_content = "คุณคือพิตต์แมนชัด ๆ เลย",
  str_homestory_805501001_7_dialog_content = "ชู่ว...",
  str_homestory_805501001_8_dialog_content = "เงียบ ๆ หน่อย อย่าให้คนอื่นได้ยินสิ...",
  str_homestory_805501001_9_option_content = "ถามเขา",
  str_homestory_805501001_10_dialog_content = "หืมม? ผู้พิพากษาแห่งลูโมโพลิสกลัวคนอื่นจำได้งั้นเหรอ?",
  str_homestory_805501001_11_option_content = "เห็นใจเขา",
  str_homestory_805501001_12_dialog_content = "ได้ครับ",
  str_homestory_805501001_13_dialog_content = "คุณไม่อยากให้คนอื่นรู้ว่าคุณอยู่ที่นี่สินะ!",
  str_homestory_805501001_14_dialog_content = "คุณโดนประกาศจับในลูโมโพลิสเหรอ?",
  str_homestory_805501001_15_dialog_content = "ฉันเป็นเจ้าหน้าที่ตุลาการผู้เที่ยงธรรม เป็นสาวกผู้เปี่ยมศรัทธาของเทพแห่งแสงสว่าง และเป็นข้ารับใช้ผู้ซื่อสัตย์แห่งลูโมโพลิส",
  str_homestory_805501001_16_dialog_content = "ฉันจะโดนประกาศจับได้ยังไง?",
  str_homestory_805501001_17_dialog_content = "อาจจะเพราะ...",
  str_homestory_805501001_18_dialog_content = "คุณแอบมาขี่ม้าโยกอย่างสนุกสนานล่ะมั้ง!",
  str_homestory_805501001_19_dialog_content = "น-นายเห็นงั้นเหรอ?<sprite=emo_daomei size=60 />",
  str_homestory_805501001_20_dialog_content = "อะฮ่า! คุณมาขี่ม้าโยกจริง ๆ สินะ!",
  str_homestory_805501001_21_dialog_content = "อะแฮ่ม ฉันแค่อยากจะตรวจสอบให้แน่ใจว่าคุณภาพดีน่ะ",
  str_homestory_805501001_22_dialog_content = "ช่วงนี้มีของปลอมในตลาดเยอะแยะไปหมด",
  str_homestory_805501001_23_dialog_content = "ผู้พิพากษาอย่างพวกเราก็มีหน้าที่ต้องปราบปรามคนขายที่ไร้ยางอายเหล่านั้น",
  str_homestory_805501001_24_dialog_content = "แต่ไม่ต้องห่วงหรอก ม้าโยกของนายแข็งแรงและออกแบบมาอย่างดี รับน้ำหนักได้อย่างน้อย 84 กก.",
  str_homestory_805501001_25_dialog_content = "ใช้งานได้สบายหายห่วงเลย",
  str_homestory_805501001_26_dialog_content = "เอ่อ... ขอบคุณนะครับ",
  str_homestory_805501001_27_dialog_content = "ที่ผมติดตั้งม้าโยกไว้ที่นี่ก็เพื่อให้ทุกคนได้เพลิดเพลินไปกับมัน",
  str_homestory_805501001_28_dialog_content = "ไม่จำเป็นต้องแอบมาเล่นอย่างหลบ ๆ ซ่อน ๆ หรอกนะ!",
  str_homestory_805501001_29_dialog_content = "ทำไมจู่ ๆ ก็พูดแบบนี้ล่ะ?",
  str_homestory_805501001_30_dialog_content = "ก็ทุกอย่างมันเขียนอยู่บนหน้าคุณไง",
  str_homestory_805501001_31_dialog_content = "คุณเป็นคนโกหกไม่เก่งนะ ฮ่าฮ่าฮ่า",
  str_homestory_805501001_32_dialog_content = "...ก็ได้",
  str_homestory_805501001_33_dialog_content = "ช่วยเก็บไว้เป็นความลับระหว่างเราด้วยนะ",
  str_homestory_805501001_34_dialog_content = "ทำไมล่ะ? ไม่เห็นจะต้องเก็บเป็นความลับเลย...",
  str_homestory_805501001_35_dialog_content = "ผมเองก็ชอบเล่นม้าโยกเหมือนกัน",
  str_homestory_805501001_36_dialog_content = "เพื่อรักษาความยุติธรรม ผู้พิพากษาจะต้องเป็นคนที่น่าเชื่อถือและไว้ใจได้",
  str_homestory_805501001_37_dialog_content = "หากผู้คนค้นพบด้านที่ไร้เดียงสาแบบเด็ก ๆ ของฉันล่ะก็...",
  str_homestory_805501001_38_dialog_content = "พวกเขาคงไม่เชื่อถือคำตัดสินในศาลของฉันแน่",
  str_homestory_805501001_39_dialog_content = "งั้นเหรอ?",
  str_homestory_805501001_40_dialog_content = "เพราะฉะนั้น PlayerName ช่วยเก็บความลับของฉันได้มั้ย?",
  str_homestory_805501001_41_dialog_content = "ก็ได้ ถึงผมจะยังไม่เห็นความเชื่อมโยงระหว่างการขี่ม้าโยกกับการพิจารณาคดี...",
  str_homestory_805501001_42_dialog_content = "แต่ผมสัญญาว่าจะไม่บอกใคร!",
  str_homestory_805501001_43_dialog_content = "ขอบคุณที่เข้าใจนะ!",
  str_homestory_805501001_44_dialog_content = "อีกอย่างนะ...",
  str_homestory_805501001_45_dialog_content = "ถ้านายตกเป็นเหยื่อของสินค้าปลอมละก็ ฉันจะช่วยทวงความยุติธรรมให้นายเอง!<sprite=emo_qingsong size=60 />",
  str_homestory_815501001_0_dialog_content = "เหมือนจะเป็นเสียงชักดาบออกจากฝักเลย?",
  str_homestory_815501001_1_dialog_content = "อีราเวลนี่มีอะไรน่าประหลาดใจเยอะเลย PlayerName!",
  str_homestory_815501001_2_dialog_content = "ก็ไม่เลวนะ... ผมว่า...",
  str_homestory_815501001_3_dialog_content = "เคเลสไทต์นี่ยังมีความลับที่เก็บซ่อนพวกเราอีกมากแค่ไหนกันนะ?",
  str_homestory_815501001_4_dialog_content = "...อยากรู้จริง ๆ เลย",
  str_homestory_815501001_5_dialog_content = "อื้มม... ที่ของนายนี่มันสวยดีจริง ๆ เจ้าหนู",
  str_homestory_815501001_6_dialog_content = "อุปกรณ์ครบครัน อยู่ในทำเลที่ดี และยากที่จะเข้าถึงได้",
  str_homestory_815501001_7_dialog_content = "เมื่อไหร่ที่มีสงคราม มันจะต้องเป็นฐานทัพที่ดีแน่ ๆ!",
  str_homestory_815501001_8_dialog_content = "โห... นี่คุณคิดไปไกลกว่าผมเยอะเลยนะ คุณบาร์ตัน",
  str_homestory_815501001_9_dialog_content = "แน่นอน!",
  str_homestory_815501001_10_dialog_content = "การแสวงหาความแข็งแกร่งอย่างต่อเนื่อง และรู้จักวางแผนทรัพยากรที่ตัวเองมีอย่างสมเหตุสมผล ทั้งสองเป็นเรื่องสำคัญไม่แพ้กัน",
  str_homestory_815501001_11_dialog_content = "(วันนี้บาร์ตันดูต่างจากทุกวัน...)",
  str_homestory_815501001_12_dialog_content = "ให้ตายสิ... ฉันน่าจะคิดออกให้เร็วกว่านี้...",
  str_homestory_815501001_13_dialog_content = "...เจ้าหนู นายคิดว่าไง?",
  str_homestory_815501001_14_dialog_content = "อะไรคือสิ่งที่สำคัญสำหรับนายมากกว่ากัน พัฒนาตัวเองให้แข็งแกร่งขึ้น หรือวางแผนทรัพยากรอย่างมีเหตุผล<sprite=emo_sikao size=60 />",
  str_homestory_815501001_15_option_content = "แข็งแกร่งขึ้น",
  str_homestory_815501001_16_dialog_content = "ถ้าผมมีไนท์เทียมเพียง 10 เหรียญ วางแผนไปมันก็ไม่มีประโยชน์...",
  str_homestory_815501001_17_dialog_content = "ผมต้องแข็งแกร่งก่อน หรือพูดอีกอย่างก็คือ ผมต้องสร้างความมั่งคั่งให้ตัวเองก่อน",
  str_homestory_815501001_18_option_content = "วางแผนอย่างมีเหตุผล",
  str_homestory_815501001_19_dialog_content = "ถ้าผมมีไนท์เทียมเพียง 10 เหรียญ ผมต้องหาทางให้ตัวเองมีชีวิตรอดก่อน แล้วค่อยคิดต่อว่าจะหาเงินยังไง...",
  str_homestory_815501001_20_dialog_content = "หา? พูดเป็นเล่นน่า?",
  str_homestory_815501001_21_dialog_content = "ทั้งเนื้อทั้งตัวนายมีแค่ 10 ไนท์เทียมเองเหรอ?",
  str_homestory_815501001_22_dialog_content = "...ผมแค่ยกตัวอย่างเฉย ๆ!",
  str_homestory_815501001_23_dialog_content = "ก็ได้",
  str_homestory_815501001_24_dialog_content = "ฉันกำลังคิดว่าจะให้นายยืมเงินเผื่อว่านายถังแตกน่ะ",
  str_homestory_815501001_25_dialog_content = "มองอย่างนี้อิลลูมินาก็ดีมากแล้ว อย่างน้อยหลาย ๆ อย่างก็ไม่ต้องใช้เงิน",
  str_homestory_815501001_26_dialog_content = "?",
  str_homestory_815501001_27_dialog_content = "โทษที ฉันพูดนอกเรื่องไปหน่อย...",
  str_homestory_815501001_28_dialog_content = "ตอนนี้ฉันมาคิดได้ว่า การแสวงหาความแข็งแกร่งและการวางแผนสามารถดำเนินการไปพร้อม ๆ กันได้",
  str_homestory_815501001_29_dialog_content = "ไม่เห็นจำเป็นต้องเลือกอย่างใดอย่างหนึ่ง",
  str_homestory_815501001_30_dialog_content = "แต่ก่อนฉันให้ความสนใจกับการพัฒนาพลังตัวเองอย่างเดียว ทำให้ละเลยเรื่องสำคัญต่าง ๆ ไปมากมาย",
  str_homestory_815501001_31_dialog_content = "การวางแผนสิ่งที่มีอยู่แล้วจะช่วยให้เราเข้าใจอนาคตได้ดีขึ้น!",
  str_homestory_815501001_32_dialog_content = "การเข้าใจตัวเองอย่างถ่องแท้จะช่วยให้ก้าวไปบนเส้นทางนี้ได้อย่างราบรื่นและแข็งแกร่งขึ้น",
  str_homestory_815501001_33_dialog_content = "พลังที่มากขึ้น จะช่วยให้เรามีอำนาจต่อรองมากขึ้น",
  str_homestory_815501001_34_dialog_content = "อืม... ผมเห็นด้วยระดับหนึ่ง",
  str_homestory_815501001_35_dialog_content = "งั้นแปลว่านายตกลงให้ฉันยืมที่นี่เป็นฐานทัพแล้วสินะ?",
  str_homestory_815501001_36_dialog_content = "?!",
  str_homestory_815501001_37_dialog_content = "ผมไม่เคยพูดอย่างนั้นนะ!",
  str_homestory_815501001_38_dialog_content = "แนวคิดเรื่องฐานทัพนี่ไม่เหมาะกับสวนลอยฟ้าเลย!",
  str_homestory_815501001_39_dialog_content = "ฮ่าฮ่า ใครจะไปรู้? ไม่มีใครรับประกันได้ว่านายจะอยู่อย่างสงบสุขตลอดไปนี่นะ!",
  str_homestory_815501001_40_dialog_content = "เฮ้! อย่าพูดอย่างนั้นสิ!<sprite=emo_shengqi size=60 />",
  str_homestory_815501001_41_dialog_content = "พูดหรือไม่พูดมันก็ไม่ต่างกันหรอก เราต้องเตรียมพร้อมรับความเสี่ยงที่อาจเกิดขึ้น!",
  str_homestory_815501001_42_dialog_content = "ใช่ ดูเหมือนว่าเราจะต้องเล่นเกมสงครามกันซักหน่อยแล้ว เดี๋ยวนี้เลย",
  str_homestory_815501001_43_dialog_content = "ส่วนแผนการในหัวของฉัน... ฉันค่อยบอกวิเวียนพรุ่งนี้ละกัน",
  str_homestory_815501001_44_dialog_content = "อืมม... ฉันไม่มีเวลาค้นหาเอกสารสำหรับเขียนรายงานหรอกนะ!",
  str_homestory_815501001_45_dialog_content = "(ฉันขอถอนคำพูดเมื่อกี้ละกัน...)",
  str_homestory_815501001_46_dialog_content = "(คุณบาร์ตันไม่เปลี่ยนไปเลยสักนิด)",
  str_homestory_801101001_0_dialog_content = "คุณชาโรนา!",
  str_homestory_801101001_1_dialog_content = "นี่คุณ...",
  str_homestory_801101001_2_dialog_content = "กำลังฝึกท่าต่อสู้ใหม่เหรอครับ?",
  str_homestory_801101001_3_dialog_content = "ใช่",
  str_homestory_801101001_4_dialog_content = "ขยันจังเลยครับ <sprite=emo_yaling size=60 /> ไม่แปลกใจเลยที่คุณได้มาเป็นหัวหน้ากองพลที่ 1 ซึ่งเป็นกำลังรบหลักของอิลลูมินา...",
  str_homestory_801101001_5_dialog_content = "ฉันว่านายเข้าใจผิดนิดหน่อยนะ PlayerName",
  str_homestory_801101001_6_dialog_content = "เหตุผลที่ฉันฝึกท่าใหม่ ไม่ใช่เพราะฉันจะเอาไปใช้ฝึกพวกทหาร",
  str_homestory_801101001_7_dialog_content = "นี่เป็นไม้ตายใหม่ที่ฉันเพิ่งได้มาจากนิยายน่ะ",
  str_homestory_801101001_8_dialog_content = "ค-คุณอ่านนิยายด้วยเหรอ?",
  str_homestory_801101001_9_dialog_content = "เดี๋ยวก่อน... คุณฝึกท่าไม้ตายจากนิยายเนี่ยนะ?",
  str_homestory_801101001_10_dialog_content = "ฟ-ฟังดูไม่เหมือนผู้บัญชาการชาโรนาที่ผมรู้จักเลย!",
  str_homestory_801101001_11_dialog_content = "ตกใจงั้นรึ?",
  str_homestory_801101001_12_option_content = "พยักหน้า",
  str_homestory_801101001_13_dialog_content = "ผมนึกว่าคุณยุ่งอยู่กับเรื่องสำคัญเสมอ แต่การอ่านนิยาย...",
  str_homestory_801101001_14_dialog_content = "อย่าเข้าใจผิดนะ ผมไม่ได้ว่าการอ่านไม่ดีนะ!",
  str_homestory_801101001_15_option_content = "ส่ายหัว",
  str_homestory_801101001_16_dialog_content = "หลังจากคิดอย่างรอบคอบแล้ว เราไม่ควรเอาความประทับใจแรกเห็นมาตัดสินคนคนหนึ่งว่าเขาเป็นแบบไหน...",
  str_homestory_801101001_17_dialog_content = "สำหรับผมแล้ว ผู้บัญชาการชาโรนาดูเหมือนจะงานยุ่งตลอดเวลา ผมแค่ไม่คิดว่าคุณจะมีเวลาว่างอ่านนิยายด้วย",
  str_homestory_801101001_18_dialog_content = "นายพูดถูก ฉันไม่ใช่นักอ่านตัวยงขนาดนั้นหรอก",
  str_homestory_801101001_19_dialog_content = "แต่ชื่อหนังสือทำให้ฉันสนใจ: \"พันธนาการพันปีแห่งสองมังกรกบฏ\"",
  str_homestory_801101001_20_dialog_content = "...",
  str_homestory_801101001_21_dialog_content = "คุณได้หนังสือนี่มาจากไหนเนี่ย?",
  str_homestory_801101001_22_dialog_content = "อย่าบอกนะว่าซื้อมาจากออโรเรียนคนนึง!",
  str_homestory_801101001_23_dialog_content = "ใช่ พ่อค้าในอัมบราตันขายให้ฉันน่ะ",
  str_homestory_801101001_24_dialog_content = "คุณดูไม่ได้ทุกข์ร้อนอะไรเลยแฮะ...",
  str_homestory_801101001_25_dialog_content = "ผมเดาว่าเนื้อเรื่องในหนังสือไม่ได้เอาคุณไปแซวล้ำเส้นสินะ",
  str_homestory_801101001_26_dialog_content = "เขาบอกฉันว่าจุดขายของหนังสือเล่มนี้คือ...",
  str_homestory_801101001_27_dialog_content = "วิชาลับของมังกรที่หายสาบสูญไปเนิ่นนาน และเรื่องราวความรักของสายเลือดโบราณ...",
  str_homestory_801101001_28_dialog_content = "เอ๋? แล้วคุณไม่โกรธเหรอ?",
  str_homestory_801101001_29_dialog_content = "ก็ไม่ค่อยนะ",
  str_homestory_801101001_30_dialog_content = "ยังไงฉันก็ทำอะไรไม่ได้มากอยู่ดี",
  str_homestory_801101001_31_dialog_content = "การตีพิมพ์และการขายหนังสือเล่มนี้อยู่ในอัมบราตัน ซึ่งอยู่นอกเหนือเขตอำนาจของฉัน",
  str_homestory_801101001_32_dialog_content = "สำหรับฉันแล้ว เนื้อหาในหนังสือแทบไม่ได้มีผลอะไรกับฉันเลย",
  str_homestory_801101001_33_dialog_content = "แต่สำหรับนักเขียนเหล่านั้น หนังสืออาจจะเป็นสิ่งเดียวที่เขาใช้เลี้ยงชีพก็ได้",
  str_homestory_801101001_34_dialog_content = "...อื้ม ก็ถูกของคุณ...",
  str_homestory_801101001_35_dialog_content = "คุณชาโรนา... คุณเป็นผู้บัญชาการที่ยอดเยี่ยมจริง ๆ!",
  str_homestory_801101001_36_dialog_content = "ส่วนไม้ตายลับของมังกรที่เขียนในหนังสือเล่มนี้ก็ค่อนข้างไร้สาระ...",
  str_homestory_801101001_37_dialog_content = "แต่มันก็ช่วยเติมสีสันให้กับการออกกำลังกายประจำวันของฉันนิดหน่อย",
  str_homestory_801101001_38_dialog_content = "อยากลองไหม?",
  str_homestory_801101001_39_dialog_content = "ตามที่เขียนไว้ในหนังสือ เราจะเริ่มต้นด้วยท่าสควอตง่าย ๆ 200 ครั้ง จากนั้นก็ไปต่อที่...",
  str_homestory_801101001_40_dialog_content = "ไม่ ไม่ดีกว่า...",
  str_homestory_801101001_41_dialog_content = "ผมว่าผมควรเน้นการฝึกความสามารถของเคเลสไทต์มากกว่าน่ะ ผู้บัญชาการชาโรนา",
  str_homestory_801101001_42_dialog_content = "งั้นผมไม่รบกวนการออกกำลังกายของคุณแล้วล่ะ... แล้วเจอกันครับ!",
  str_homestory_801101001_43_dialog_content = "แล้วเจอกัน",
  str_homestory_810301001_0_dialog_content = "เอซี่ใช่มั้ยนั่น?",
  str_homestory_810301001_1_dialog_content = "เอซี่ อยากไปดูข้างในมั้ย?",
  str_homestory_810301001_2_dialog_content = "ฉันจำได้ว่าเธอชอบช้อปปิ้ง",
  str_homestory_810301001_3_dialog_content = "PlayerName ในเมื่อนายรู้งานอดิเรกของฉันแล้ว...",
  str_homestory_810301001_4_dialog_content = "ทำไมนายถึงได้ขี้งกสร้างแค่ร้านเดียว?",
  str_homestory_810301001_5_dialog_content = "เอ่อ... ฉันมีเหตุผลหลายอย่างน่ะ...",
  str_homestory_810301001_6_dialog_content = "ว่ามาซิ",
  str_homestory_810301001_7_dialog_content = "ถ้านายลืมกะทันหัน ฉันถอดผ้าปิดตาออกก็ได้...",
  str_homestory_810301001_8_dialog_content = "ดวงตาว่างเปล่าของฉัน<sprite=emo_baimao size=60 />จะช่วยให้นายจำได้เอง",
  str_homestory_810301001_9_option_content = "อธิบาย",
  str_homestory_810301001_10_dialog_content = "ก็ได้ ขอเวลาเดี๋ยวนะ!",
  str_homestory_810301001_11_dialog_content = "สาเหตุหลักก็คือ เรามีงบจำกัดมาก...",
  str_homestory_810301001_12_dialog_content = "พวกเรามีสิ่งที่ต้องสร้างมากเกินไป เป็นไปไม่ได้ที่จะทำให้ทุกอย่างสมบูรณ์แบบตั้งแต่เริ่มต้น",
  str_homestory_810301001_13_option_content = "ตอบแบบคลุมเครือ",
  str_homestory_810301001_14_dialog_content = "ถึงสอบปากคำฉันไปก็ไม่ได้ประโยชน์หรอก...",
  str_homestory_810301001_15_dialog_content = "งบประมาณของเรามีจำกัด เราสร้างอีกร้านไม่ไหวหรอก..",
  str_homestory_810301001_16_dialog_content = "แต่ฉันคิดว่า... มีร้านเดียวก็ยังดีกว่าไม่มีเลย!",
  str_homestory_810301001_17_dialog_content = "กล้าหาญและตรงไปตรงมาดีนี่",
  str_homestory_810301001_18_dialog_content = "แต่ร้านเดียวของเราก็ครอบคลุมทุกความต้องการของเธอนะ!",
  str_homestory_810301001_19_dialog_content = "ฉันพยายามอย่างหนักหน่วงเพื่อร่วมมือกับกิลด์ต่าง ๆ ในอัมบราตัน",
  str_homestory_810301001_20_dialog_content = "และยังขอให้สหภาพผู้ส่งสารจัดส่งพัสดุให้เป็นครั้งคราว",
  str_homestory_810301001_21_dialog_content = "เข้าไปดูข้างในก่อนดีมั้ย? ถ้าอยากได้อะไรก็บอกฉันได้เลยนะ",
  str_homestory_810301001_22_dialog_content = "ไม่ต้องหรอก ฉันเข้าไปดูมาแล้วล่ะ",
  str_homestory_810301001_23_dialog_content = "อันที่จริง เพื่อเป็นการสนับสนุนนาย ฉันได้ซื้อของทุกอย่างในร้านเรียบร้อยแล้ว",
  str_homestory_810301001_24_dialog_content = "ทุกอย่าง?",
  str_homestory_810301001_25_dialog_content = "ใช่",
  str_homestory_810301001_26_dialog_content = "รวมถึงปลาที่เราเพิ่งจับมาจากแม่น้ำด้วยเหรอ?",
  str_homestory_810301001_27_dialog_content = "ปลาหลากสีพวกนั้นน่ะเหรอ? ใช่ พวกมันน่ารักมากเลย",
  str_homestory_810301001_28_dialog_content = "ฉันหาตู้ปลาไม่ได้ ก็เลยเอาพวกมันไปปล่อยในแม่น้ำแถวนี้แล้ว",
  str_homestory_810301001_29_dialog_content = "แม้แต่รองเท้าหนังขาดรุ่งริ่งที่ไม่มีใครอยากได้ด้วยเหรอ?",
  str_homestory_810301001_30_dialog_content = "รองเท้าขาดรุ่งริ่ง? อ๋อใช่ นั่นไม่ใช่กระถางดอกไม้สไตล์ใหม่ล่าสุดหรอกเหรอ?",
  str_homestory_810301001_31_dialog_content = "ฉันฝากสหภาพผู้ส่งสารให้ส่งมันกลับไปที่ทรู ออเดอร์แล้วล่ะ",
  str_homestory_810301001_32_dialog_content = "แล้ว...แผนที่อีราเวลวาดมือของฉันล่ะ?",
  str_homestory_810301001_33_dialog_content = "นายหมายถึงภาพวาดเขาวงกตยึกยือนั่นน่ะนะ?",
  str_homestory_810301001_34_dialog_content = "นายเป็นคนวาดเหรอ? งั้นฉันต้องใส่กรอบแขวนไว้บนผนังแล้วล่ะ",
  str_homestory_810301001_35_dialog_content = "ขอบคุณนะเอซี่... เธอเป็นลูกค้าที่ใจดีที่สุดเท่าที่ฉันเคยพบมาเลย!",
  str_homestory_810301001_36_dialog_content = "ไม่เป็นไรหรอกน่า สาระสำคัญของการช้อปปิ้งก็คือการฟุ่มเฟือยเพื่อซื้อความสุขนั่นแหละ",
  str_homestory_810301001_37_dialog_content = "แต่หลังจากนี้ก็ไม่มีร้านไหนให้ฉันช้อปแล้วสิ น่าหงุดหงิดชะมัดเลย",
  str_homestory_810301001_38_dialog_content = "เอซี่ เธอไปเดินเล่นรอบ ๆ ก็ได้นะ",
  str_homestory_810301001_39_dialog_content = "มีพิพิธภัณฑ์อยู่ทางนั้น แล้วก็มีน้ำพุแห่งความหวังด้วย...",
  str_homestory_810301001_40_dialog_content = "ฉันรับรองได้เลยว่าเธอจะไม่ได้เห็นวิวสวย ๆ แบบนี้จากที่ไหนอีกแน่นอน",
  str_homestory_810301001_41_dialog_content = "ได้ น่าสนใจดีนี่",
  str_homestory_810301001_42_dialog_content = "ฉันนึกอะไรดี ๆ ออกแล้ว ฉันตัดสินใจซื้อ<sprite=emo_baiyebi size=60 />นายละกัน",
  str_homestory_810301001_43_dialog_content = "หา? ซื้อฉันเนี่ยนะ?",
  str_homestory_810301001_44_dialog_content = "แค่วันเดียวก็พอ นายช่วยพาฉันไปเดินเล่นรอบ ๆ หน่อยสิ",
  str_homestory_810301001_45_dialog_content = "บอกค่าเสียเวลาของนายมาได้เลย",
  str_homestory_810301001_46_dialog_content = "ได้เลย! เป็นเกียรติมากครับที่ได้ดูแลคุณ!",
  str_homestory_802301001_0_dialog_content = "คอนนอลลี...",
  str_homestory_802301001_1_dialog_content = "แสงอ่อน ๆ...",
  str_homestory_802301001_2_dialog_content = "คอนนอลลี คุณว่าไงนะ?",
  str_homestory_802301001_3_dialog_content = "ผ-ผู้นำทาง!<sprite=emo_wuzui size=60 />",
  str_homestory_802301001_4_dialog_content = "ฉันแค่บ่นไปเรื่อยน่ะ อย่าสนใจฉันเลยนะ...",
  str_homestory_802301001_5_dialog_content = "...ไม่สิ ไม่ใช่อย่างนั้น!",
  str_homestory_802301001_6_dialog_content = "คุณสนใจฉันนิดหน่อยก็ได้... ฉ-ฉันกำลังฝึกฝนวิธีลดความวิตกน่ะ...",
  str_homestory_802301001_7_dialog_content = "ฝึกฝนวิธีลดความวิตก?",
  str_homestory_802301001_8_dialog_content = "ใช่... ไวซ์เป็นคนบอกเรื่องนี้กับฉันเอง...",
  str_homestory_802301001_9_dialog_content = "ฉันพยายามอย่างหนักเพื่อปรับตัวกับแสงสว่างของที่นี่...",
  str_homestory_802301001_10_dialog_content = "ไวซ์เห็นฉันหลบอยู่ในมุม...",
  str_homestory_802301001_11_dialog_content = "เธอก็เลยรู้ว่าคุณต้องการความช่วยเหลือใช่มั้ย?",
  str_homestory_802301001_12_dialog_content = "ใช่แล้ว...",
  str_homestory_802301001_13_dialog_content = "เธอบอกฉันว่าให้ลองทำสิ่งที่ชอบและไม่ต้องสนใจคนอื่น...",
  str_homestory_802301001_14_dialog_content = "หรือสมมุติว่าที่นี่คือฮอลิเดย์คาเฟ่ และทำเหมือนกับว่าทุกคนคือลูกค้า...",
  str_homestory_802301001_15_dialog_content = "ฉันกำลังพยายามอยู่...",
  str_homestory_802301001_16_option_content = "แล้วตอนนี้เป็นยังไงบ้างครับ?",
  str_homestory_802301001_17_dialog_content = "ก็ดีขึ้นนิดหน่อย...",
  str_homestory_802301001_18_dialog_content = "บนโคลอสซัสก็มีผู้คนมากมายเหมือนกัน...",
  str_homestory_802301001_19_option_content = "ถ้าไม่ไหวก็อย่าฝืนตัวเองจนเกินไปนะ",
  str_homestory_802301001_20_dialog_content = "ถ้าอยู่ในห้องแล้วสบายใจกว่า ที่จริงไม่ต้องออกมานอกห้องก็ได้",
  str_homestory_802301001_21_dialog_content = "ที่จริง ฉันมีเรื่องจะบอกคุณน่ะ ผู้นำทาง...",
  str_homestory_802301001_22_dialog_content = "หืม? เรื่องอะไรเหรอ?",
  str_homestory_802301001_23_dialog_content = "ฉันฟังคำแนะนำของไวซ์ และลองมาเล่นเพลงกับแอนตันที่นี่<sprite=emo_yinfu size=60 />...",
  str_homestory_802301001_24_dialog_content = "แต่คิดไม่ถึงเลยว่า... จะมีผู้หญิงแต่งชุดลูโมโพลิสมาชมเชยฉันด้วย...",
  str_homestory_802301001_25_dialog_content = "ฉัน...",
  str_homestory_802301001_26_dialog_content = "อา... จู่ ๆ สถานที่ที่สว่างแบบนี้ก็ไม่เลวร้ายอีกต่อไปแล้วใช่มั้ย?",
  str_homestory_802301001_27_dialog_content = "บางครั้งคำชมเชยก็เป็นกำลังใจที่ดีจริง ๆ",
  str_homestory_802301001_28_dialog_content = "คอนนอลลี ผมคิดว่าคุณยอดเยี่ยมมากเลย!",
  str_homestory_802301001_29_dialog_content = "คุณเป็นคนที่ชงกาแฟอร่อยที่สุด และเป็นนักสู้ที่อ่อนหวานแต่ก็แข็งแกร่งมาก ๆ...",
  str_homestory_802301001_30_dialog_content = "ขอบคุณสำหรับคำชมนะผู้นำทาง ด-ได้รู้แบบนี้แล้วฉันพูดไม่ออกเลย...",
  str_homestory_802301001_31_dialog_content = "แต่คำชมของผู้หญิงคนนั้น... รู้สึกแตกต่างไปจากของคุณ!",
  str_homestory_802301001_32_dialog_content = "ผู้นำทางและไวซ์เป็นเพื่อนที่ดีของคอนนอลลี...",
  str_homestory_802301001_33_dialog_content = "พวกคุณคอยสนับสนุน ปลอบโยน และให้กำลังใจฉันเสมอมา...",
  str_homestory_802301001_34_dialog_content = "แต่ผู้หญิงคนนั้นเป็นคนแปลกหน้า!",
  str_homestory_802301001_35_dialog_content = "คำชมของเธอนั้นบริสุทธิ์และมีความหมายสำหรับคอนนอลลีมากกว่าสินะ",
  str_homestory_802301001_36_dialog_content = "ใช่... ฉันรู้สึกแบบนั้นแหละ...",
  str_homestory_802301001_37_dialog_content = "ผู้นำทาง ช่วยบอกไวซ์ทีได้มั้ย ว่าฉันขอบคุณจริง ๆ ที่เธอช่วยเหลือ",
  str_homestory_802301001_38_dialog_content = "ถ้าไม่ได้ไวซ์ ป่านนี้ฉันคงเอาแต่ซ่อนตัวอยู่ในห้องไม่ยอมออกไปไหนแน่...",
  str_homestory_802301001_39_dialog_content = "ได้เลย!",
  str_homestory_802301001_40_dialog_content = "ขอบคุณนะ ผู้นำทาง!",
  str_homestory_802301001_41_dialog_content = "ฉันตั้งใจว่าจะฝึกเล่นเพลงนั้นกับแอนตันอีกครั้ง...",
  str_homestory_802301001_42_dialog_content = "คุณลองฝึกอะไรใหม่ ๆ ด้วยก็ได้นะ",
  str_homestory_802301001_43_dialog_content = "ผมมั่นใจว่าผู้หญิงลึกลับคนนั้นต้องอยากฟังแน่",
  str_homestory_802301001_44_dialog_content = "อา! นั่นสินะ...",
  str_homestory_802301001_45_dialog_content = "โอเค! ผู้นำทาง ฉันจะไปฝึกเดี๋ยวนี้แหละ!",
  str_homestory_802301001_46_dialog_content = "ยังไงก็สู้ ๆ นะ!",
  str_homestory_803001001_0_dialog_content = "ซินซา...",
  str_homestory_803001001_1_dialog_content = "สวัสดี ซินซา!",
  str_homestory_803001001_2_dialog_content = "อ่า <sprite=emo_yaosu size=60 />! ดีใจที่ได้เจอนะPlayerName เคเลสไทต์คนสุดท้าย!",
  str_homestory_803001001_3_dialog_content = "เป็นไงบ้าง?",
  str_homestory_803001001_4_dialog_content = "ทุกอย่างเรียบร้อยดี แล้วคุณล่ะ? คุ้นเคยกับที่นี่รึยัง?",
  str_homestory_803001001_5_dialog_content = "ก็ไม่เลวนะ",
  str_homestory_803001001_6_dialog_content = "ใช้เวลาแป๊บ ๆ นายก็แปลงโฉมที่นี่ได้สมบูรณ์แบบ...",
  str_homestory_803001001_7_dialog_content = "สมกับที่ซินซาคนนี้คาดหวังไว้จริง ๆ อ่าฮ่าฮ่า",
  str_homestory_803001001_8_dialog_content = "แล้วนายตัดสินใจรึยังล่ะ?",
  str_homestory_803001001_9_dialog_content = "ว่าจะเข้าร่วมเรดีเซล เวรนช์เมื่อไหร่?",
  str_homestory_803001001_10_dialog_content = "อืมม...เอ่อ...",
  str_homestory_803001001_11_dialog_content = "ตามมาตรฐานของเรดีเซล เวรนช์แล้ว...",
  str_homestory_803001001_12_dialog_content = "ที่นี่ยังต้องการพื้นที่สำหรับการต่อสู้และการแข่งรถประลองความเร็ว!",
  str_homestory_803001001_13_option_content = "ปฏิเสธ",
  str_homestory_803001001_14_dialog_content = "ผมไม่อยากให้เกิดความขัดแย้งที่นี่...",
  str_homestory_803001001_15_dialog_content = "เราคงปล่อยให้มีความรุนแรงแบบนั้นไม่ได้",
  str_homestory_803001001_16_dialog_content = "เฮ้อ... นี่ฉันถูกนายปฏิเสธนับครั้งไม่ถ้วนเลยนะ",
  str_homestory_803001001_17_dialog_content = "แต่อย่างไรก็ตาม PlayerName ความคิดแบบนี้ของนายค่อนข้างเด็กไปหน่อยนะ",
  str_homestory_803001001_18_dialog_content = "เชื่อฉันได้เลย สิ่งที่นายห้ามจะเกิดขึ้นอย่างแน่นอน",
  str_homestory_803001001_19_dialog_content = "ไม่ต้องถามหรอกนะว่าฉันรู้ได้ไง",
  str_homestory_803001001_20_dialog_content = "...",
  str_homestory_803001001_21_option_content = "ยอมรับ",
  str_homestory_803001001_22_dialog_content = "อืม... ถึงแม้นี่ไม่ใช่ส่วนหนึ่งของแผนเดิมของเรา...",
  str_homestory_803001001_23_dialog_content = "แต่การต่อสู้แบบสุ่มและแข่งรถอาจจะสร้างความเสียหายกับบ้านที่ผมพยายามสร้างมาได้",
  str_homestory_803001001_24_dialog_content = "เพราะงั้นทางที่ดี เราควรจัดสนามให้โดยเฉพาะจะดีกว่า...",
  str_homestory_803001001_25_dialog_content = "ฮ่าฮ่าฮ่า โตขึ้นแล้วนี่นาเจ้าหนู",
  str_homestory_803001001_26_dialog_content = "ตอนนี้นายรู้จักฟังคนอื่นแล้ว!",
  str_homestory_803001001_27_dialog_content = "ช่วยพาฉันไปดูหอพักหญิงของสวนลอยฟ้าหน่อยได้มั้ย?",
  str_homestory_803001001_28_dialog_content = "หา?!",
  str_homestory_803001001_29_dialog_content = "ทำไมต้องมองฉันด้วยสายตาหวาดกลัวแบบนั้นด้วยล่ะ?",
  str_homestory_803001001_30_dialog_content = "คุณจะไปทำอะไรที่นั่นน่ะ คงมีเหตุผลที่ดีใช่มั้ย?",
  str_homestory_803001001_31_dialog_content = "ฉันอยากจะไปตรวจดูน่ะ",
  str_homestory_803001001_32_dialog_content = "ตรวจดู?",
  str_homestory_803001001_33_dialog_content = "ใช่<sprite=emo_qingsong size=60 /> ฉันอยากแน่ใจว่ามันดีพอสำหรับอีฟรึเปล่า",
  str_homestory_803001001_34_dialog_content = "เฮ่อ... เข้าใจแล้ว",
  str_homestory_803001001_35_dialog_content = "ฉันต้องไปเช็กให้ชัวร์ว่าเตียงนุ่มพอรึเปล่า...",
  str_homestory_803001001_36_dialog_content = "โคมไฟข้างเตียงดีต่อสายตามั้ย...",
  str_homestory_803001001_37_dialog_content = "ผ้าปูที่นอนใช่ลายโปรดของอีฟรึเปล่า",
  str_homestory_803001001_38_dialog_content = "แล้วก็มีตู้เสื้อผ้าสำหรับชุดสวย ๆ ของอีฟด้วยรึเปล่า",
  str_homestory_803001001_39_dialog_content = "อ้อ! และที่สำคัญที่สุด! มีกระติกน้ำร้อนในห้องด้วยรึเปล่า!",
  str_homestory_803001001_40_option_content = "ยอมรับ",
  str_homestory_803001001_41_dialog_content = "ผมจะบอกให้ไวซ์ไปเช็กทุกอย่างอีกรอบละกัน...",
  str_homestory_803001001_42_dialog_content = "ฮ่าฮ่าฮ่าฮ่า สมแล้วที่เป็นน้องชายของฉัน!",
  str_homestory_803001001_43_option_content = "ปฏิเสธ",
  str_homestory_803001001_44_dialog_content = "ซินซา ผมว่าถึงเวลาที่คุณควรจะเคารพความเป็นส่วนตัวของอีฟได้แล้วนะ",
  str_homestory_803001001_45_dialog_content = "นายว่าไงนะ?",
  str_homestory_803001001_46_dialog_content = "ไม่มีอะไรครับ! ผมจะบอกให้ไวซ์ไปเช็กทุกอย่างอีกรอบละกัน...",
  str_homestory_811601001_0_dialog_content = "ตัดสินใจลำบากจัง!",
  str_homestory_811601001_1_dialog_content = "ผู้นำทาง มีอะไรจะซ่อมมั้ย?",
  str_homestory_811601001_2_dialog_content = "นายมาได้จังหวะพอดี! วันนี้ฉันยังว่าง!",
  str_homestory_811601001_3_dialog_content = "ซ่อม?",
  str_homestory_811601001_4_dialog_content = "นี่คุณกำลังรอรับออเดอร์...ที่ศูนย์ส่งสินค้าเหรอ?",
  str_homestory_811601001_5_dialog_content = "ใช่ ฉันรับออเดอร์ลูกค้าที่นี่ แล้วก็เอาเครื่องจักรกลับไปซ่อมในห้องตัวเอง",
  str_homestory_811601001_6_dialog_content = "อ้อ ไม่ต้องห่วง ฉันไม่คิดค่าบริการหรอก...",
  str_homestory_811601001_7_dialog_content = "แล้วทำไมคุณถึง..",
  str_homestory_811601001_8_dialog_content = "ทำไมฉันถึงซ่อมให้ฟรี ๆ น่ะเหรอ?",
  str_homestory_811601001_9_dialog_content = "นายก็คงรู้ ปกติฉันมักจะยุ่งอยู่กับงานอดิเรก...",
  str_homestory_811601001_10_dialog_content = "อย่างวิจัยอะไหล่หรือส่วนประกอบต่าง ๆ",
  str_homestory_811601001_11_dialog_content = "เพราะว่าที่นี่มีผู้คนมากมายมาจากหลายที่หลายทาง<sprite=emo_sikao size=60 />",
  str_homestory_811601001_12_dialog_content = "ของที่พวกเขาเอามาให้ซ่อมก็แตกต่างและน่าสนใจมาก",
  str_homestory_811601001_13_dialog_content = "ก่อนหน้านี้ คารอนก็ขอให้ฉันช่วยทำให้เครื่องเล่นแผ่นเสียงของเขา<sprite=emo_yinfu size=60 />ดังกว่านี้...",
  str_homestory_811601001_14_dialog_content = "ฉันคิดว่ามันเป็นแค่เครื่องเล่นแผ่นเสียงจากอิลลูมินา และไม่ได้สนใจมันมากนัก",
  str_homestory_811601001_15_dialog_content = "แต่นายรู้อะไรมั้ย? มันเป็นรุ่นวินเทจที่ฉันไม่รู้ด้วยซ้ำว่ามาจากไหน!",
  str_homestory_811601001_16_dialog_content = "ฮ่าฮ่า ฉันก็เลยได้ศึกษาเครื่องเล่นแผ่นเสียงอย่างละเอียด!",
  str_homestory_811601001_17_dialog_content = "เอ่อ... แล้วนายช่วยทำให้เครื่องเล่นของคารอนดังขึ้นรึเปล่า?",
  str_homestory_811601001_18_dialog_content = "อืมม ก็นิดหน่อย ถือเป็นค่าตอบแทนสำหรับการเรียนรู้สิ่งใหม่ ๆ ซึ่งเป็นโอกาสที่หาได้ยาก...",
  str_homestory_811601001_19_dialog_content = "แต่ว่า! ฉันรู้ว่าบางครั้งเขาชอบเปิดเพลงเสียงดัง ฉันก็เลยเพิ่มให้แค่นิดหน่อยน่ะ!",
  str_homestory_811601001_20_dialog_content = "อืมม... ดูเหมือนคุณจะสนุกกับชีวิตที่นี่นะ",
  str_homestory_811601001_21_dialog_content = "สนุกมากเลยล่ะ!",
  str_homestory_811601001_22_dialog_content = "มีเทคโนโลยี อะไหล่ และอุปกรณ์ใหม่ ๆ มากมายให้ฉันได้ศึกษา... นี่มันสวรรค์ชัด ๆ!<sprite=emo_aixin size=60 />",
  str_homestory_811601001_23_dialog_content = "โอเค ตราบใดที่คุณอยู่สุขสบายที่นี่ก็ดีแล้วล่ะ",
  str_homestory_811601001_24_dialog_content = "เยี่ยมเลย เดี๋ยวอีกไม่นานฉันว่าจะสร้างหุ่นยนต์ใหม่ล่ะ!",
  str_homestory_811601001_25_dialog_content = "...เอาอีกแล้วเหรอ!",
  str_homestory_811601001_26_dialog_content = "อย่าพูดอย่างนั้นสิ! ฉันเป็นห่วงนายมากนะ! ฉันตรวจสอบโครงสร้างของคลังขนส่งสินค้าให้นายแล้ว",
  str_homestory_811601001_27_dialog_content = "ประแจและไขควงของฉันได้พิสูจน์แล้วว่าอาคารแห่งนี้มีความมั่นคงมาก ไม่จำเป็นต้องใช้บริการของฉันหรอก",
  str_homestory_811601001_28_dialog_content = "มันสร้างมาจากวัสดุของอีราเวลน่ะ",
  str_homestory_811601001_29_dialog_content = "เห็นมั้ย? พอได้อยู่นี่ ฉันก็สามารถศึกษาวัสดุจากอีราเวลได้ด้วย วิเศษจริง ๆ!",
  str_homestory_811601001_30_dialog_content = "ก็ได้ งั้นผมไม่รบกวนคุณ...รับออเดอร์แล้วดีกว่า",
  str_homestory_811601001_31_dialog_content = "นายไม่ได้รบกวนฉันเลย ที่จริงนายจะอยู่ต่อแล้วสั่งงานฉันก็ได้นะ",
  str_homestory_811601001_32_option_content = "ยอมรับ",
  str_homestory_811601001_33_dialog_content = "ก็ได้... ขอผมคิดดูก่อนว่ามีอะไรต้องซ่อมบ้าง",
  str_homestory_811601001_34_dialog_content = "ยอดเลย!",
  str_homestory_811601001_35_dialog_content = "...วันนี้ไม่ค่อยมีลูกค้าเท่าไหร่",
  str_homestory_811601001_36_dialog_content = "...แล้วถ้าไม่มีใครเอาของมาให้ซ่อม คุณจะทำยังไงเหรอ?",
  str_homestory_811601001_37_option_content = "ปฏิเสธ",
  str_homestory_811601001_38_dialog_content = "ไว้วันหลังละกัน ผมยังมีเรื่องต้องจัดการน่ะ...",
  str_homestory_811601001_39_dialog_content = "โอ๊ะ! ว่าแต่....",
  str_homestory_811601001_40_dialog_content = "...แล้วถ้าไม่มีใครเอาของมาให้ซ่อม คุณจะทำยังไงเหรอ?",
  str_homestory_811601001_41_dialog_content = "คุณก็จะยืนเอ้อระเหยอยู่ตรงนี้ต่อเหรอ?",
  str_homestory_811601001_42_dialog_content = "ใช่แล้ว",
  str_homestory_811601001_43_dialog_content = "แต่ว่าผู้นำทาง นายยังเข้าใจผิดอยู่นิดหน่อย",
  str_homestory_811601001_44_dialog_content = "ฉันไม่ได้ยืนเอ้อระเหยอยู่ตรงนี้ แต่สงครามหุ่นยนต์กำลังฟาดฟันกันในหัวของฉันต่างหาก",
  str_homestory_811601001_45_dialog_content = "ก่อนที่นายจะมา ฉันกำลังคิดอยู่ว่าใครจะเป็นฝ่ายชนะ หากหุ่นยนต์ของ PlayerName กับหุ่นยนต์ของโอดีสู้กัน",
  str_homestory_811601001_46_dialog_content = "หุ่นยนต์ PlayerName ขึ้นชื่อในเรื่องการโจมตีที่รวดเร็วและเบา ในขณะที่หุ่นยนต์โอดีนั้นติดตั้งอุปกรณ์ครบครันกว่ามาก...",
  str_homestory_811601001_47_dialog_content = "เป็นการต่อสู้ที่ดุเดือดจริง ๆ!",
  str_homestory_811601001_48_dialog_content = "โอเค... ผมไปดีกว่า...",
  str_homestory_811701001_0_dialog_content = "แกรม?",
  str_homestory_811701001_1_dialog_content = "คุณแกรม มาทำอะไรที่ร้านเหรอ?",
  str_homestory_811701001_2_dialog_content = "เอ่อ... คุณกำลังคิดอะไรอยู่รึเปล่า?",
  str_homestory_811701001_3_dialog_content = "หรือว่ามีอะไรที่คุณหาไม่เจอ?",
  str_homestory_811701001_4_dialog_content = "เจ้าหนู",
  str_homestory_811701001_5_dialog_content = "ฉันต้องการส่วนผสมสำหรับทำเนื้อเสียบไม้ย่าง โดยใช้เนื้อจากเสบียงปันส่วนที่ใกล้หมดอายุ",
  str_homestory_811701001_6_dialog_content = "เนื้อหมดอายุ<sprite=emo_rou size=60 />...",
  str_homestory_811701001_7_dialog_content = "แค่ใกล้หมดอายุน่ะ แต่ยังไม่ถึงเวลา แน่นอนว่าไม่มีปัญหา",
  str_homestory_811701001_8_dialog_content = "อีกอย่าง รสชาติของอาหารนั้นขึ้นอยู่กับฝีมือของเชฟเท่านั้น ไม่เกี่ยวอะไรกับคุณภาพของวัตถุดิบ",
  str_homestory_811701001_9_dialog_content = "คุณแกรมพูดถูก!",
  str_homestory_811701001_10_dialog_content = "ที่จริง ผมก็ยังไม่เคยลองเนื้อย่างฝีมือคุณเลย",
  str_homestory_811701001_11_dialog_content = "เดี๋ยวก็ได้กินแน่",
  str_homestory_811701001_12_dialog_content = "เนื้อย่างเสียบไม้น่ะทำง่ายมาก",
  str_homestory_811701001_13_dialog_content = "...ง่าย?",
  str_homestory_811701001_14_dialog_content = "ผมรู้อยู่แล้ว คุณแกรมเป็นคนมีพรสวรรค์จริง ๆ..",
  str_homestory_811701001_15_dialog_content = "คนทำอาหารที่มีพรสวรรค์? ของแบบนั้นไม่มีอยู่จริงหรอกนะ",
  str_homestory_811701001_16_dialog_content = "ฮึ่ม! วัยรุ่นสมัยนี้นี่ชอบอ้างพรสวรรค์จริง ๆ!",
  str_homestory_811701001_17_dialog_content = "ความสำเร็จมากมายขึ้นอยู่กับการทำงานหนักและการฝึกฝนอย่างขยันขันแข็ง ลำพังแค่พรสวรรค์น่ะ พานายไปไม่ถึงไหนหรอก",
  str_homestory_811701001_18_dialog_content = "ฉันทำอาหารเก่งเพราะฉันทำงานในครัวมานานหลายปี",
  str_homestory_811701001_19_dialog_content = "การทำอาหารเป็นทักษะที่ไม่เกี่ยวกับพรสวรรค์",
  str_homestory_811701001_20_option_content = "ผมไม่ค่อยเข้าใจ",
  str_homestory_811701001_21_dialog_content = "ผมพยายามฝึกทำอาหารและทำตามสูตรอย่างเคร่งครัด...",
  str_homestory_811701001_22_dialog_content = "แต่มันก็ไม่ค่อยดีเท่าไหร่",
  str_homestory_811701001_23_option_content = "เหมือนนายจะเริ่มเข้าใจแล้ว",
  str_homestory_811701001_24_dialog_content = "ทักษะการทำอาหารพัฒนาได้ด้วยการฝึกฝน อย่างนั้นเหรอครับ?",
  str_homestory_811701001_25_dialog_content = "ทุกอย่างพัฒนาได้ด้วยการฝึกฝนต่างหาก",
  str_homestory_811701001_26_dialog_content = "การทำอาหารให้อร่อยนั้นต้องสัมผัสด้วยใจ",
  str_homestory_811701001_27_dialog_content = "สัมผัสด้วยใจ?",
  str_homestory_811701001_28_dialog_content = "งั้นแสดงว่าอาหารของไวซ์...",
  str_homestory_811701001_29_dialog_content = "ไม่มีความรู้สึกเลย หรือไม่ก็ใส่ความรู้สึกมากไปสินะ?",
  str_homestory_811701001_30_dialog_content = "ในกรณีของเธอ เห็นได้ชัดว่าเธอยึดตามสูตรเกินไปจนขาดความรู้สึก",
  str_homestory_811701001_31_dialog_content = "พูดง่าย ๆ ก็คือ เธอคิดเรื่องคุ้มไม่คุ้มมากเกินไป จนพลาดโอกาสในการฝึกฝน",
  str_homestory_811701001_32_dialog_content = "อืมม... จะว่าไปผมก็เป็นแบบนี้เหมือนกัน",
  str_homestory_811701001_33_dialog_content = "ผมกลัวจะทำสิ่งต่าง ๆ ผิดพลาด แต่ก็กระตือรือร้นอยากจะทำเมนูที่อร่อยและน่าทึ่ง มันเลยทำให้ผมสับสนและเครียด...",
  str_homestory_811701001_34_dialog_content = "ฉันจะยกตัวอย่างให้ง่าย ๆ นะ",
  str_homestory_811701001_35_dialog_content = "ตอนที่ฉันอยู่หน่วยพลาธิการ ฉันอยากไปอยู่แนวหน้า ๆ มาก แต่ก็ยังอยากจะทำอาหารอร่อย ๆ ทุกวันด้วยเหตุผลเดียว",
  str_homestory_811701001_36_dialog_content = "ฉันอยากให้พี่น้องของตัวเองได้กินอาหารดี ๆ เพื่อจะได้มีแรงต่อสู้ต่อ",
  str_homestory_811701001_37_dialog_content = "ตอนนี้ที่ฉันยังคงทำอาหารอยู่ก็เป็นเพราะเหตุผลเดียวกัน",
  str_homestory_811701001_38_dialog_content = "ฉันอยากให้คนหนุ่มสาวได้กินอาหารดี ๆ จะได้มีพลังที่จะสู้ต่อ!",
  str_homestory_811701001_39_dialog_content = "การทำอาหารให้อร่อยมันง่ายนิดเดียว",
  str_homestory_811701001_40_dialog_content = "แค่ทำตามสูตร และปล่อยวางความคิดที่ยุ่งเหยิงเหล่านั้น",
  str_homestory_811701001_41_dialog_content = "ยิ่งคิดมาก ก็ยิ่งทำให้เราทำผิดพลาดมากขึ้น เข้าใจมั้ย?",
  str_homestory_811701001_42_dialog_content = "อื้ม! ตอนนี้ผมเข้าใจแล้วล่ะ!",
  str_homestory_811701001_43_dialog_content = "คุณพูดถูกเลย คุณแกรม!",
  str_homestory_811701001_44_dialog_content = "บอกตามตรง ผมว่าคุณควรเขียนหนังสือเทคนิคการทำอาหารนะ",
  str_homestory_811701001_45_dialog_content = "แม้แต่พ่อครัวของทะเลทรายเรดีเซลยังตีพิมพ์หนังสือเลย... คุณเองก็ทำได้!",
  str_homestory_811701001_46_dialog_content = "ผมช่วยแนะนำสำนักพิมพ์ในอัมบราตันให้คุณได้นะ",
  str_homestory_811701001_47_dialog_content = "ไม่ใช่ตอนนี้ ไว้ฉันจะคิดดูก็แล้วกัน",
  str_homestory_811701001_48_dialog_content = "นายจะมากินเนื้อย่างเสียบไม้ของฉันมั้ยล่ะ เจ้าหนู?",
  str_homestory_811701001_49_dialog_content = "แน่นอน!",
  str_homestory_807701001_0_dialog_content = "องค์ราชินี?",
  str_homestory_807701001_1_dialog_content = "องค์ราชินี...",
  str_homestory_807701001_2_dialog_content = "สวัสดี ผู้กุมอนาคต",
  str_homestory_807701001_3_option_content = "ยินดีต้อนรับ",
  str_homestory_807701001_4_dialog_content = "เป็นเกียรติอย่างยิ่งที่ท่านมาเยือน",
  str_homestory_807701001_5_dialog_content = "PlayerName ไม่ต้องพิธีรีตองขนาดนั้นหรอก",
  str_homestory_807701001_6_dialog_content = "ฉันมองดูหอคอยไฮยาซินท์นี้มาสักพักแล้ว",
  str_homestory_807701001_7_option_content = "ผมรบกวนท่านรึเปล่า?",
  str_homestory_807701001_8_dialog_content = "ท่านดูจดจ่อมากเลย...",
  str_homestory_807701001_9_dialog_content = "ใช่ ฉันกำลังมองหอคอยไฮยาซินท์แห่งนี้",
  str_homestory_807701001_10_dialog_content = "หอคอยไฮยาซินท์? มีอะไรผิดปกติเหรอครับ?",
  str_homestory_807701001_11_dialog_content = "หืมม... หอคอยไฮยาซินท์แห่งนี้มีความหมายกับเคเลสไทต์มาก",
  str_homestory_807701001_12_dialog_content = "ใช่! มันเป็นสิ่งปลูกสร้างที่ใหญ่โตมาก ๆ",
  str_homestory_807701001_13_dialog_content = "จากตรงนี้ท่านอาจจะมองได้ไม่ชัด แต่ความจริงแล้วมันใหญ่มหึมา และภายในก็กว้างขวางมากเช่นกัน",
  str_homestory_807701001_14_dialog_content = "มันสามารถผลิตและซ่อมแซมโคลอสซัส",
  str_homestory_807701001_15_dialog_content = "ตามบันทึกที่มีอยู่ เคเลสไทต์ส่วนใหญ่ถูกฝึกมาจากที่นี่",
  str_homestory_807701001_16_dialog_content = "เปรียบเสมือนเป็นแหล่งกำเนิดของผู้นำทางเลยก็ว่าได้",
  str_homestory_807701001_17_dialog_content = "แหล่งกำเนิดงั้นรึ?",
  str_homestory_807701001_18_dialog_content = "เมื่อฉันได้เห็น ว่ามันส่องประกายเจิดจรัสเพียงใดภายใต้ผืนฟ้า",
  str_homestory_807701001_19_dialog_content = "ฉันก็รู้สึกว่า... มันเหมือนเป็นศูนย์รวมจิตวิญญาณของเคเลสไทต์มากกว่า",
  str_homestory_807701001_20_dialog_content = "PlayerName เธอรู้ไหมว่าคนเราผูกพันกันได้อย่างไร?",
  str_homestory_807701001_21_dialog_content = "เอ่อ จู่ ๆ ก็ถามเรื่องนี้...",
  str_homestory_807701001_22_dialog_content = "ผมไม่เคยคิดเลย ขอโทษครับ",
  str_homestory_807701001_23_dialog_content = "ไม่เป็นไร คำถามนี้ไม่เคยสำคัญกับเธอมาก่อน",
  str_homestory_807701001_24_dialog_content = "แต่ตอนนี้ทุกอย่างเปลี่ยนไปแล้ว เธอต้องมองทวีปแห่งนี้ในมุมมองใหม่ที่ต่างออกไป",
  str_homestory_807701001_25_dialog_content = "ทุกคนในที่นี้ ไม่ว่าจะสูงหรือเตี้ย เข้มแข็งหรืออ่อนแอ แก่ชราหรือเยาว์วัย...",
  str_homestory_807701001_26_dialog_content = "ตราบใดที่มีความเชื่อและศรัทธาร่วมกัน...",
  str_homestory_807701001_27_dialog_content = "พวกเขาก็จะอยู่ร่วมกันได้",
  str_homestory_807701001_28_dialog_content = "เราไม่สามารถเอาชนะธรรมชาติได้เพียงลำพัง",
  str_homestory_807701001_29_dialog_content = "เราไม่มีกรงเล็บหรือเขี้ยวที่แหลมคม ผิวของเราไม่ได้แข็งเหมือนหิน และแขนของเราไม่สามารถพาเราขึ้นไปบนฟ้าได้",
  str_homestory_807701001_30_dialog_content = "แต่หากเราต่อสู้ร่วมกันเป็นหนึ่งเดียว พลังของเราจะเหนือกว่าจินตนาการ..",
  str_homestory_807701001_31_dialog_content = "หากพูดเช่นนี้...",
  str_homestory_807701001_32_dialog_content = "ฝ่าบาท ท่านก็คือศูนย์รวมจิตวิญญาณของพวกเรา",
  str_homestory_807701001_33_dialog_content = "...",
  str_homestory_807701001_34_dialog_content = "อืมม... นั่นสินะ",
  str_homestory_807701001_35_dialog_content = "ไม่ว่าจะเพราะความไว้วางใจ เพราะความชื่นชม หรือเพราะพวกเขาต้องการการปกป้องจากฉัน",
  str_homestory_807701001_36_dialog_content = "มันก็ไม่ใช่อะไรที่แย่นักหรอก...",
  str_homestory_807701001_37_dialog_content = "กลุ่มคนที่รวมเป็นหนึ่งเดียว ย่อมแข็งแกร่งกว่าทรายที่หละหลวมเสมอ",
  str_homestory_807701001_38_dialog_content = "ทั้งอิลลูมินาและลูโมโพลิสต่างก็รักษาความสามัคคีนี้ในแบบของตัวเอง",
  str_homestory_807701001_39_dialog_content = "ใช่... ตอนนี้ผมเข้าใจแล้วล่ะ",
  str_homestory_807701001_40_dialog_content = "เธอเติบโตขึ้นแล้ว เคเลสไทต์ผู้กุมอนาคต",
  str_homestory_807701001_41_dialog_content = "หอคอยสีขาวแห่งนี้ ศูนย์รวมจิตใจของเคเลสไทต์ เปรียบเสมือนตัวเธอ...",
  str_homestory_807701001_42_dialog_content = "ทั้งสองมีพลังแห่งความสามัคคี",
  str_homestory_807701001_43_dialog_content = "ผมมีพลังที่จะรวมผู้คนและปกป้องอีราเวลด้วยเหรอ...? โอ๊ะ ฝ่าบาท ผมขอถามอะไรอย่างนึงได้ไหม?",
  str_homestory_807701001_44_dialog_content = "ว่ามาเลย",
  str_homestory_807701001_45_dialog_content = "ในนิมิตแห่งอนาคต ท่านเคยเห็นอีราเวลในวันนี้ด้วยหรือเปล่า?",
  str_homestory_807701001_46_dialog_content = "...แน่นอน และยังมีสิ่งอื่นอีกมากมายด้วย",
  str_homestory_804201001_0_dialog_content = "คุณบาร์ตัน!",
  str_homestory_804201001_1_dialog_content = "เฮ้ ผู้นำทาง!",
  str_homestory_804201001_2_dialog_content = "คุณบาร์ตัน...",
  str_homestory_804201001_3_dialog_content = "ชู่ว... มาดูกับฉันมา<sprite=emo_mojing size=60 />",
  str_homestory_804201001_4_dialog_content = "...หา?",
  str_homestory_804201001_5_dialog_content = "คุณกำลังดูอะไรอยู่เหรอ?",
  str_homestory_804201001_6_dialog_content = "นายเลี้ยงคนมีความสามารถไว้เยอะพอตัวเลยนะเนี่ย ผู้นำทาง!",
  str_homestory_804201001_7_dialog_content = "ทำไมตอนอยู่โคลอสซัสฉันถึงไม่เจอพวกเขานะ?",
  str_homestory_804201001_8_dialog_content = "อืม... สงสัยเป็นเพราะโคลอสซัสไม่มีที่ว่างพอที่จะให้พวกนั้นสยายปีก",
  str_homestory_804201001_9_dialog_content = "...คนมีความสามารถ?",
  str_homestory_804201001_10_dialog_content = "คุณกำลังรับสมัครทหารเข้าร่วมอิลลูมินาเหรอ?",
  str_homestory_804201001_11_dialog_content = "รับสมัคร? ไม่ พวกเขาไม่จำเป็นต้องสมัครเลย",
  str_homestory_804201001_12_dialog_content = "PlayerName นายรู้ใช่มั้ยว่าฉันเป็นหัวหน้ากองพลไหน?",
  str_homestory_804201001_13_option_content = "กองพลที่ 2",
  str_homestory_804201001_14_dialog_content = "ใช่!",
  str_homestory_804201001_15_option_content = "กองพลที่ 4",
  str_homestory_804201001_16_dialog_content = "เอาจริงดิ? <sprite=emo_shengqi size=60 />ไอ้หนู กองทัพของฉันใหญ่กว่าหน่วยของยัยนั่นตั้งเยอะ!",
  str_homestory_804201001_17_dialog_content = "หึ! กองหนุนทหารหน่วยพิเศษของวราธ แค่โดนเราบุกทีเดียวก็เละแล้ว!",
  str_homestory_804201001_18_dialog_content = "ฉันคือหัวหน้ากองพลที่ 2 ที่มีกำลังพลมากที่สุด จำเอาไว้ด้วยล่ะ",
  str_homestory_804201001_19_dialog_content = "ครับ...",
  str_homestory_804201001_20_dialog_content = "นายรู้มั้ย ว่าท่านจอมทัพมอบหมายหน้าที่อะไรให้ฉันโดยเฉพาะ!?",
  str_homestory_804201001_21_option_content = "การสนับสนุนการรบด้วยความเร็วสูง?",
  str_homestory_804201001_22_dialog_content = "...นั่นมันหน้าที่ของฮิอิโระกับไวซ์",
  str_homestory_804201001_23_dialog_content = "นี่! นายลืมสมองไว้ที่บ้านรึไง?",
  str_homestory_804201001_24_dialog_content = "ฉันเป็นผู้นำกองทหารรักษาการณ์!",
  str_homestory_804201001_25_dialog_content = "...ตอนนี้เข้าใจรึยัง?",
  str_homestory_804201001_26_dialog_content = "ครับ...",
  str_homestory_804201001_27_option_content = "การป้องกันและความมั่นคง",
  str_homestory_804201001_28_dialog_content = "ถูกต้อง! นายหัดเรียนรู้แล้วนี่!",
  str_homestory_804201001_29_dialog_content = "เมื่อรู้แบบนี้แล้ว นายน่าจะเข้าใจสิ่งที่ฉันทำอยู่",
  str_homestory_804201001_30_dialog_content = "นายได้รวบรวมคนที่มีความสามารถและทักษะเฉพาะตัวเอาไว้มากมาย...",
  str_homestory_804201001_31_dialog_content = "บางครั้งก็เกิดการทะเลาะและต่อสู้กันเองบ้าง...",
  str_homestory_804201001_32_dialog_content = "ทั้งการลอบโจมตี! อาวุธลับ! วิชาไทจุตสึ!",
  str_homestory_804201001_33_dialog_content = "ชิ... น่าทึ่งจริง ๆ",
  str_homestory_804201001_34_dialog_content = "ฉันไม่ต้องการให้พวกเขาเข้าร่วมอิลลูมินาหรอก เข้าใจมั้ย?",
  str_homestory_804201001_35_dialog_content = "แค่ดูการโจมตีและป้องกันของพวกเขาก็เพียงพอแล้ว",
  str_homestory_804201001_36_dialog_content = "ฉันกำลังเรียนรู้วิชาต่อสู้จากผู้คนที่หลากหลาย แล้วก็จะส่งต่อวิชาพวกนี้ให้ทหารของฉัน!",
  str_homestory_804201001_37_dialog_content = "นี่เป็นบทเรียนที่ล้ำค่ามากทีเดียว!",
  str_homestory_804201001_38_dialog_content = "แบบนี้นี่เอง...",
  str_homestory_804201001_39_dialog_content = "เดี๋ยวนะ ทำไมพวกเขาถึงสู้กันล่ะ?",
  str_homestory_804201001_40_dialog_content = "มันเป็นเรื่องปกติอยู่แล้วไม่ใช่เหรอ ที่ออโรเรียนจะไม่ถูกกัน?",
  str_homestory_804201001_41_dialog_content = "ฉันคิดว่านายคุ้นเคยกับเรื่องพวกนี้ในโคลอสซัสแล้วซะอีก",
  str_homestory_804201001_42_dialog_content = "แต่ว่า...",
  str_homestory_804201001_43_dialog_content = "แค่มองว่าพวกนั้นกำลังฝึกซ้อมกันก็สิ้นเรื่อง!",
  str_homestory_804201001_44_dialog_content = "เอาล่ะ ฉันจะไปฝึกท่าที่ฉันเห็นเมื่อวานแล้ว...",
  str_homestory_804201001_45_dialog_content = "เขารับลูกเตะของเธอได้ยังไงกันนะ?",
  str_homestory_804201001_46_dialog_content = "อืมม...ไว้ฉันเก่งเมื่อไหร่นะ ถ้าวราธกล้ามาหือกับฉันอีกล่ะก็!",
  str_homestory_804201001_47_dialog_content = "ฮึ่ย! ย่าห์! <sprite=emo_nuhuo size=60 />",
  str_homestory_804201001_48_dialog_content = "...โอเค งั้นโชคดีนะ คุณบาร์ตัน...",
  str_homestory_807601001_0_dialog_content = "เคลเคน...",
  str_homestory_807601001_1_dialog_content = "อ๋า! ในที่สุดผู้กล้านักเดินทางก็มาถึงจนได้",
  str_homestory_807601001_2_dialog_content = "สวัสดี เคลเคน",
  str_homestory_807601001_3_dialog_content = "คุณชอบน้ำตกหินนี่มากเลยเหรอ? ผมเห็นคุณชอบเดินเตร็ดเตร่อยู่แถวนี้...",
  str_homestory_807601001_4_dialog_content = "มันเป็นสายน้ำที่ล้ำค่ามาก ๆ เลยล่ะ!",
  str_homestory_807601001_5_dialog_content = "แม่น้ำและน้ำพุเหล่านี้ทำให้แทบน้ำตาไหล<sprite=emo_hanshui size=60 />",
  str_homestory_807601001_6_dialog_content = "นี่คุณประชดเหรอ?",
  str_homestory_807601001_7_dialog_content = "ที่เห็นอยู่ตอนนี้มันก็แค่ลำธารประดับสวนเท่านั้น...",
  str_homestory_807601001_8_dialog_content = "เทียบไม่ได้กับ \"มหาสมุทร\" และ \"การจมลึกสู่ท้องทะเล\" ที่คุณชอบพูดถึงหรอก",
  str_homestory_807601001_9_dialog_content = "ฉันอยากจะขอบคุณต่างหาก",
  str_homestory_807601001_10_dialog_content = "...เรื่องอะไรเหรอ?",
  str_homestory_807601001_11_dialog_content = "เดี๋ยวนายก็จะได้เห็นความสำเร็จของ \"เทคนิคการมองตา\" ที่ฉันฝึกจนสมบูรณ์",
  str_homestory_807601001_12_dialog_content = "ฉันสามารถบอกได้ว่าช่วงนี้สมองน้อย ๆ ของนายกำลังยุ่งอยู่กับเรื่องอะไร...",
  str_homestory_807601001_13_dialog_content = "แค่มองเข้าไปในดวงตาที่มีเสน่ห์ของนาย แค่นั้นฉันก็ได้คำตอบแล้ว",
  str_homestory_807601001_14_dialog_content = "ขอบคุณที่มาเป็นพยานคนแรกของฉันนะ",
  str_homestory_807601001_15_dialog_content = "เอ่อ...",
  str_homestory_807601001_16_option_content = "เทคนิคการมองตา?",
  str_homestory_807601001_17_dialog_content = "เริ่มสนใจขึ้นมาแล้วล่ะสิ เจ้าหนู...",
  str_homestory_807601001_18_option_content = "ผมขอปฏิเสธได้มั้ย?",
  str_homestory_807601001_19_dialog_content = "ได้สิ",
  str_homestory_807601001_20_dialog_content = "แต่เจ้าหนวดตัวน้อยแสนว่องไวข้างหลังฉันคงไม่ปล่อยนายไปหรอกนะ",
  str_homestory_807601001_21_dialog_content = "มันชอบดูนายหลับน่ะ PlayerName...",
  str_homestory_807601001_22_dialog_content = "(...ว่าไงนะ?)",
  str_homestory_807601001_23_dialog_content = "ก็ได้... อย่าให้นานนักล่ะ ผมยังมีเรื่องที่ต้องทำอีก",
  str_homestory_807601001_24_dialog_content = "แล้วเทคนิคการมองตาคืออะไรเหรอ?",
  str_homestory_807601001_25_dialog_content = "ฉันจะอธิบายให้ฟังเอง คุณนักรบ",
  str_homestory_807601001_26_dialog_content = "ฉันเชื่อว่านายเพิ่งไปอัมบราตันมาแน่ ๆ...",
  str_homestory_807601001_27_dialog_content = "นายกำลังเดินเล่นอยู่ตามถนนอย่างสบายใจ และได้พบเข้ากับสาวน้อยที่น่าสงสาร",
  str_homestory_807601001_28_dialog_content = "เธอขอให้นายช่วยไปเช็กราคาร้านอาหารแถวนั้นให้หน่อย...",
  str_homestory_807601001_29_dialog_content = "เธอมีเงินไม่พอ เลยไม่กล้าเข้าร้านอาหารแบบสุ่มสี่สุ่มห้า",
  str_homestory_807601001_30_dialog_content = "เธอไม่สามารถทนต่อการดูถูกของพนักงานในร้านได้ หากเธอสั่งขนมปังแค่แผ่นเดียว...",
  str_homestory_807601001_31_dialog_content = "นายพาเธอไปดูร้านอาหารร้านแล้วร้านเล่า หลังจากที่เห็นราคาแล้ว",
  str_homestory_807601001_32_dialog_content = "เธอก็จะส่ายหัวทุกครั้ง",
  str_homestory_807601001_33_dialog_content = "สุดท้ายนายก็ตัดสินใจซื้ออาหารดี ๆ ให้เธอกิน...",
  str_homestory_807601001_34_dialog_content = "หลังจากอาหารมื้อนั้น เธอก็รีบขอบคุณและจากไปอย่างรวดเร็ว แถมยังทิ้งเงินที่เพียงพอจะจ่ายค่าอาหารไว้บนโต๊ะด้วย",
  str_homestory_807601001_35_dialog_content = "...คุณรู้ได้ไงน่ะ?",
  str_homestory_807601001_36_dialog_content = "(เทคนิคการมองตามหัศจรรย์ขนาดนี้เลยเหรอ?)",
  str_homestory_807601001_37_dialog_content = "...อย่างไรก็ตาม ฉันรู้สึกสับสนมาก",
  str_homestory_807601001_38_dialog_content = "ถ้าเธอมีเงินอยู่แล้ว ทำไมถึงไม่เดินเข้าไปกินในร้านอาหารตรง ๆ เลยล่ะ?",
  str_homestory_807601001_39_dialog_content = "อย่างที่นายบอก... เธอเช็กราคาอาหารทุกจานจากทุกร้านในอัมบราตัน!",
  str_homestory_807601001_40_dialog_content = "ฮ่าฮ่า... ฮ่าฮ่าฮ่าฮ่า<sprite=emo_guilian size=60 />",
  str_homestory_807601001_41_dialog_content = "เพราะฉันขอให้เธอช่วยยังไงล่ะ",
  str_homestory_807601001_42_dialog_content = "มันเป็นงานที่มอบหมายโดยท่านอีสต์วาน...",
  str_homestory_807601001_43_dialog_content = "เพื่อให้ศึกษาราคาอาหารในอัมบราตันน่ะ",
  str_homestory_807601001_44_dialog_content = "ฉันกำลังช่วยผู้หญิงคนนี้อยู่ มอบโอกาสให้เธอได้ช่วยฉันเล็ก ๆ น้อย ๆ เพื่อให้เธอรู้สึกว่าตัวเองมีคุณค่า...",
  str_homestory_807601001_45_dialog_content = "ว่าแต่ ในเมื่อเคเลสไทต์ไม่มีอะไรทำอยู่แล้ว ทำไมไม่ให้เขามาช่วยงานล่ะ?",
  str_homestory_807601001_46_dialog_content = "เดี๋ยวนี้ฉันก็ไม่มีแรงพอจะเดินทั่วเมืองซะด้วย",
  str_homestory_807601001_47_dialog_content = "...",
  str_homestory_807601001_48_dialog_content = "นี่ล่ะ ความจริงของเทคนิคการมองตา PlayerName",
  str_homestory_807601001_49_dialog_content = "ดูท่าทางผิดหวังนะ... น่าสนใจจริง ๆ!",
  str_homestory_804601001_0_dialog_content = "เขานี่เอง",
  str_homestory_804601001_1_dialog_content = "ผู้นำทางมา และผู้นำทางก็ไป ♪",
  str_homestory_804601001_2_dialog_content = "ผู้นำทางยิ้มให้ปิแอร์ แต่ปิแอร์แค่อยากก่อเรื่อง",
  str_homestory_804601001_3_dialog_content = "เธอกำลังช้อปปิ้งอยู่เหรอ?",
  str_homestory_804601001_4_dialog_content = "ช้อปปิ้ง ผู้นำทางคิดว่าฉันกำลังช้อปปิ้ง<sprite=emo_yinfu size=60 />",
  str_homestory_804601001_5_dialog_content = "ดีแอนจะตอบว่าไม่ และคาราจะตอบว่า \"ใช่แล้ว!\" นีเอลจะบอกว่า \"ก็ประมาณนั้น...\" แต่ปิแอร์จะหัวเราะเฉย ๆ<sprite=emo_muji size=60 />",
  str_homestory_804601001_6_dialog_content = "เอาล่ะ คิดว่าฉันจะพูดอะไรล่ะ?",
  str_homestory_804601001_7_dialog_content = "...%^&",
  str_homestory_804601001_8_dialog_content = "ช่างเหอะ ฉันไม่มีอารมณ์จะเล่นเกมทายปัญหาซะด้วย",
  str_homestory_804601001_9_dialog_content = "ฉันแค่อยากมาถามว่าชีวิตที่นี่เป็นยังไงบ้าง...",
  str_homestory_804601001_10_dialog_content = "พอเห็นพวกเธอฉลาดแล้วก็เล่นซนได้เหมือนปกติก็ดีใจนะ",
  str_homestory_804601001_11_dialog_content = "ผู้นำทางใส่ใจกับคีตติง ปิแอร์รู้สึกเป็นเกียรติยิ่งนัก ♪",
  str_homestory_804601001_12_dialog_content = "ผู้นำทาง คุณอยากรู้เหรอว่าเมื่อกี้ฉันได้เจอกับใคร?",
  str_homestory_804601001_13_dialog_content = "... รู้สึกใจคอไม่ดีเลยแฮะ...<sprite=emo_tanqi size=60 />",
  str_homestory_804601001_14_dialog_content = "แล้ว เธอไปเจอใครมาน่ะ?",
  str_homestory_804601001_15_dialog_content = "พวกเธอต้องระวังหน่อยนะ การแหย่คนอื่นน่ะเป็นเรื่องไม่น่ารักเลย...",
  str_homestory_804601001_16_dialog_content = "เธอไม่ได้อยู่ในลูโมโพลิส แล้วออโรเรียนบางคนก็โมโหง่าย!",
  str_homestory_804601001_17_dialog_content = "แล้วก็ยังมีออโรเรียนที่อ่อนไหวมาก ๆ คำพูดใจร้ายของเธอน่ะ อาจทำให้พวกเขาร้องไห้ก็ได้...",
  str_homestory_804601001_18_dialog_content = "ผู้นำทางเป็นห่วงเรา ผู้นำทางเป็นห่วงเพื่อน ๆ ของเขา ♪",
  str_homestory_804601001_19_dialog_content = "เราเจอช่างซ่อมเครื่องจักรหางยาว แล้วเขาก็สร้างแขนหุ่นยนต์ให้เราจับเจ้าไก่",
  str_homestory_804601001_20_dialog_content = "เราเจอนกตัวจ้ำม่ำ แล้วเธอก็ให้บอลหิมะกับเราเยอะแยะเลย",
  str_homestory_804601001_21_dialog_content = "เราเจอสุนัขในชุดสูท โมโหเพราะไม่มีใครสนใจภาพวาดปลอมของเขา",
  str_homestory_804601001_22_dialog_content = "ปิแอร์เจอผู้นำทางเตี้ยล่ำ ยืนตรงหน้าฉันและเป็นห่วงเพื่อน ๆ ของเขา",
  str_homestory_804601001_23_dialog_content = "... ฟู่... ดีกว่าที่ฉันคิดแฮะ",
  str_homestory_804601001_24_dialog_content = "เอาจริง ๆ นี่อาจเป็นคำพูดที่สุภาพที่สุดเท่าที่ฉันเคยได้ยินจากพวกเธอ",
  str_homestory_804601001_25_dialog_content = "ที่สุภาพนี่มีเหตุผลนะ",
  str_homestory_804601001_26_dialog_content = "ในชั้นหนังสือก็มีหนังสือที่ดีแอนชอบ",
  str_homestory_804601001_27_dialog_content = "ในห้องก็มีผ้าเช็ดแว่นที่นีเอลต้องการ",
  str_homestory_804601001_28_dialog_content = "ในห้องกินข้าวก็มีที่วางหมวกให้คารา",
  str_homestory_804601001_29_dialog_content = "ส่วนบนหญ้า ก็มีของโปรดของคลักกี้กับปิแอร์♪",
  str_homestory_804601001_30_dialog_content = "ผู้นำทางผู้รอบคอบคือเพื่อนซี้ของเรา",
  str_homestory_804601001_31_dialog_content = "ผู้นำทางคือดวงดาวแห่งวันพรุ่งนี้",
  str_homestory_804601001_32_dialog_content = "และเป็นดวงดาวที่จะตัวสูงขึ้น♪",
  str_homestory_804601001_33_dialog_content = "... พูดจาดีมาตลอด มาสะดุดเอาประโยคสุดท้ายนี่แหละ",
  str_homestory_804601001_34_dialog_content = "ผู้นำทาง คิดจะทำอะไรต่อเหรอ?",
  str_homestory_804601001_35_option_content = "กลับไปพักผ่อนซักหน่อย",
  str_homestory_804601001_36_dialog_content = "ฉันว่าจะไปพักซักหน่อย",
  str_homestory_804601001_37_option_content = "เดินเล่น",
  str_homestory_804601001_38_dialog_content = "ฉันจะไปเช็กดูว่าคนอื่นทำอะไรอยู่",
  str_homestory_804601001_39_dialog_content = "เข้าใจแล้ว ปิแอร์เข้าใจแล้ว",
  str_homestory_804601001_40_dialog_content = "ถึงปิแอร์จะไม่สนใจ แต่ก็ขอฝากประโยคหนึ่งให้ผู้นำทาง",
  str_homestory_804601001_41_dialog_content = "เจ้าไก่คลักกี้กำลังวางไข่ใกล้ ๆ สวน กำลังวางไข่อยู่ ♪",
  str_homestory_804601001_42_dialog_content = "?!",
  str_homestory_804601001_43_dialog_content = "วางไข่เรอะ?",
  str_homestory_804601001_44_dialog_content = "ปิแอร์ใจดีมากเลย ถ้าว่างก็ไปดูมันหน่อยนะ ♪",
  str_homestory_804601001_45_dialog_content = "...ขอบคุณที่เป็นห่วงนะ!",
  str_homestory_805701001_0_dialog_content = "นี่มัน... ขนแมวงั้นเหรอ?",
  str_homestory_805701001_1_dialog_content = "หาว—",
  str_homestory_805701001_2_dialog_content = "หืมม? คุณฟิลิชี?",
  str_homestory_805701001_3_dialog_content = "ฟืด... ฟืด...<sprite=emo_kun size=60 />",
  str_homestory_805701001_4_dialog_content = "... ฟิลิชี?",
  str_homestory_805701001_5_dialog_content = "ฟู่... เมี้ยว!",
  str_homestory_805701001_6_dialog_content = "อะไรเนี่ย! PlayerName นี่นา เหมียว",
  str_homestory_805701001_7_dialog_content = "ไม่เห็นหรือไงว่าฉันหลับอยู่ เมี้ยว?",
  str_homestory_805701001_8_dialog_content = "รอฉันตื่นก่อนแล้วค่อยกลับมาได้มั้ย เมี้ยว",
  str_homestory_805701001_9_dialog_content = "ฉันขอนอนฝันดีในกองฟางก่อนล่ะ...",
  str_homestory_805701001_10_dialog_content = "เดี๋ยวสิ คุณฟิลิชี! ผมมีเรื่องบางอย่างจะบอกคุณ!",
  str_homestory_805701001_11_dialog_content = "ฟืด... ฟืด... เมี้ยว!",
  str_homestory_805701001_12_dialog_content = "หืมม... จะมาคุยอะไรน่ะ เมี้ยว?",
  str_homestory_805701001_13_dialog_content = "หวังว่าจะเป็นเรื่องสำคัญนะ!",
  str_homestory_805701001_14_dialog_content = "เอ่อ... มีออโรเรียนบางคนมาบอกฉันน่ะ...",
  str_homestory_805701001_15_dialog_content = "ฟิลิชี ช่วงนี้คุณ...",
  str_homestory_805701001_16_option_content = "รู้สึกไม่สบายรึเปล่า?",
  str_homestory_805701001_17_dialog_content = "คันมั้ย?",
  str_homestory_805701001_18_dialog_content = "เบื่ออาหารรึเปล่า?",
  str_homestory_805701001_19_dialog_content = "พูดอะไรแบบนั้นน่ะ เหมียว?",
  str_homestory_805701001_20_dialog_content = "ฟิลิชีไม่เข้าใจ",
  str_homestory_805701001_21_option_content = "ช่วงนี้เป็นฤดูผลัดขนรึเปล่า?",
  str_homestory_805701001_22_dialog_content = "ผลัดขน อะไรนะ... เหมียว?",
  str_homestory_805701001_23_dialog_content = "มันคืออะไรเหรอ?",
  str_homestory_805701001_24_dialog_content = "(โกหกไม่เนียนชะมัด!)",
  str_homestory_805701001_25_dialog_content = "เอาเถอะ ฟิลิชีสบายดีนะ!",
  str_homestory_805701001_26_dialog_content = "(ลูบหางของฟิลิชี)",
  str_homestory_805701001_27_dialog_content = "เมี้ยว!",
  str_homestory_805701001_28_dialog_content = "PlayerName มาแตะหางของสุภาพสตรีได้ไงน่ะ?",
  str_homestory_805701001_29_dialog_content = "แต่ก็รู้สึกดีเหมือนกันนะ เมี้ยว!",
  str_homestory_805701001_30_dialog_content = "ฟิลิชี ขนคุณร่วงออกมาเต็มเลย!",
  str_homestory_805701001_31_dialog_content = "ม-ไม่จริงซะหน่อย...!",
  str_homestory_805701001_32_dialog_content = "โฮว... เหมียว ฉันห้ามไม่ได้นี่นา!",
  str_homestory_805701001_33_dialog_content = "ช่วงนี้เป็นฤดูผลัดขนน่ะ... เมี้ยว!",
  str_homestory_805701001_34_dialog_content = "ขนของฉันดูดซับแสงแดดมากพอสำหรับการวิวัฒนาการน่ะ เมี้ยว!",
  str_homestory_805701001_35_dialog_content = "พอเสร็จเรียบร้อย... ฉันก็จะกลายเป็นซูเปอร์ฟิลิชีล่ะ เมี้ยว!",
  str_homestory_805701001_36_dialog_content = "แต่... ถ้าขนของคุณลอยไปทั่ว...",
  str_homestory_805701001_37_dialog_content = "ออโรเรียนบางคนอาจจะเกิดอาการแพ้น่ะสิ",
  str_homestory_805701001_38_dialog_content = "อืมม... แล้วให้ฉันทำไงดีล่ะ?",
  str_homestory_805701001_39_dialog_content = "ฟิลิชีเลือกไม่ได้ซะหน่อย<sprite=emo_tanqi size=60 />",
  str_homestory_805701001_40_dialog_content = "ก็จริงแฮะ... ขอคิดก่อนนะ...",
  str_homestory_805701001_41_dialog_content = "งั้น... ให้ผมแปรงขนให้ดีมั้ย!",
  str_homestory_805701001_42_dialog_content = "ขนของคุณจะเรียบและลื่นขึ้น ไม่ลอยฟ่องไปมา",
  str_homestory_805701001_43_dialog_content = "คุณอีสต์วานเคยสอนผม",
  str_homestory_805701001_44_dialog_content = "ก็ได้... เห็นว่านายเตรียมกองฟางสบาย ๆ พวกนี้ให้ในอีราเวลหรอกนะ",
  str_homestory_805701001_45_dialog_content = "ฉันอนุญาตให้แปรงขนได้ เมี้ยว!",
  str_homestory_803601001_0_dialog_content = "ไฮแดรด?",
  str_homestory_803601001_1_dialog_content = "คุณทำอะไรอยู่น่ะ?",
  str_homestory_803601001_2_dialog_content = "ไม่เห็นหรือไง?",
  str_homestory_803601001_3_dialog_content = "ฉันกำลังยืนอยู่",
  str_homestory_803601001_4_dialog_content = "... เรื่องนั้นผมรู้แล้ว",
  str_homestory_803601001_5_dialog_content = "...",
  str_homestory_803601001_6_dialog_content = "...",
  str_homestory_803601001_7_dialog_content = "นี่",
  str_homestory_803601001_8_dialog_content = "ครับ?",
  str_homestory_803601001_9_dialog_content = "เมื่อวานฉันบาดเจ็บ",
  str_homestory_803601001_10_dialog_content = "?!",
  str_homestory_803601001_11_option_content = "คุณไม่เป็นไรนะ?",
  str_homestory_803601001_12_dialog_content = "ฉันสบายดี",
  str_homestory_803601001_13_option_content = "คุณไปไหนมาเหรอ?",
  str_homestory_803601001_14_dialog_content = "ฉันรู้ว่านายกังวลเรื่องอะไร",
  str_homestory_803601001_15_dialog_content = "ฉันไม่ตีกับใครที่นี่หรอก",
  str_homestory_803601001_16_dialog_content = "ผ... ผมแค่เป็นห่วงสุขภาพของคุณน่ะ",
  str_homestory_803601001_17_dialog_content = "ตอนนี้เป็นไงบ้าง? ดีขึ้นรึยัง?",
  str_homestory_803601001_18_dialog_content = "ก็โอเคแล้ว",
  str_homestory_803601001_19_dialog_content = "ที่ฉันฟื้นตัวได้เร็วก็เพราะหมาป่าเงาช่วยไว้",
  str_homestory_803601001_20_dialog_content = "ยอดเลย เล่าให้ฟังหน่อยได้มั้ยว่าเกิดอะไรขึ้น?",
  str_homestory_803601001_21_dialog_content = "อย่าบอกนะว่าคุณชอบทะเลาะวิวาท",
  str_homestory_803601001_22_dialog_content = "ฉันต่อสู้เพราะของบางอย่าง",
  str_homestory_803601001_23_dialog_content = "ที่ตลาดมืดในอัมบราตันน่ะ",
  str_homestory_803601001_24_dialog_content = "เป็นของสำคัญขนาดนั้นเลยเหรอครับ?",
  str_homestory_803601001_25_dialog_content = "พวกนั้นอ้างว่าเป็นสินค้าจากอารยธรรมโบราณ",
  str_homestory_803601001_26_dialog_content = "อ้าง?",
  str_homestory_803601001_27_dialog_content = "แสดงว่าคุณก็ไม่แน่ใจงั้นเหรอ?",
  str_homestory_803601001_28_dialog_content = "มันก็ต้องลองดูน่ะนะ",
  str_homestory_803601001_29_dialog_content = "... มันคืออะไรเหรอครับ?",
  str_homestory_803601001_30_dialog_content = "อุปกรณ์บางอย่างที่ทำให้ภาพลวงตาหรือเวทมนตร์เงากลายเป็นของจริง",
  str_homestory_803601001_31_dialog_content = "เอ่อ... แต่หมาป่าเงามันก็อยู่กับคุณมาตลอดนะ",
  str_homestory_803601001_32_dialog_content = "นั่นก็ใช่ แต่ฉันอยากจะลูบขนมันทุกวันน่ะสิ",
  str_homestory_803601001_33_dialog_content = "ขนจริง ๆ ที่เติบโตจากผิวหนัง ไม่ใช่ขนที่ร่วงออกมาเวลาผลัดขน",
  str_homestory_803601001_34_dialog_content = "อ๋อ...",
  str_homestory_803601001_35_dialog_content = "(ไฮแดรด... คงจะเหงาสินะ?)",
  str_homestory_803601001_36_dialog_content = "ฉันว่ามันคงเป็นของปลอมนั่นแหละ",
  str_homestory_803601001_37_dialog_content = "เครื่องนั่นน่ะเหรอ?",
  str_homestory_803601001_38_dialog_content = "ใช่",
  str_homestory_803601001_39_dialog_content = "ฉันไม่เคยได้ยินเรื่องอะไรแบบนั้นมาก่อนเลย",
  str_homestory_803601001_40_dialog_content = "(เขาจะรู้สึกดีขึ้นรึเปล่านะ ถ้าเกิดมันเป็นของปลอม?)",
  str_homestory_803601001_41_dialog_content = "ผมก็ว่างั้นแหละ",
  str_homestory_803601001_42_dialog_content = "ของแบบนั้นจะต้องเป็นมรดกตกทอดที่มีมูลค่ามหาศาล...",
  str_homestory_803601001_43_dialog_content = "ไม่น่ามาลงเอยที่ตลาดมืดของอัมบราตันได้หรอก",
  str_homestory_803601001_44_dialog_content = "... ก็จริง",
  str_homestory_803601001_45_dialog_content = "ในเมื่อแม้แต่นายเองก็คิดแบบนั้น",
  str_homestory_803601001_46_dialog_content = "ฉันคงต้องไปแล้ว",
  str_homestory_803601001_47_dialog_content = "แล้วเจอกันครับ!",
  str_homestory_803601001_48_dialog_content = "(แต่ถ้ามันเป็นของจริง ฉันจะเอามันมาทำอะไรดีนะ?)",
  str_homestory_811401001_0_dialog_content = "ม้าตัวนี้...?",
  str_homestory_811401001_1_dialog_content = "อา ผู้นำทาง",
  str_homestory_811401001_2_dialog_content = "อันนาขวางนายอยู่เหรอ?",
  str_homestory_811401001_3_dialog_content = "หรือว่านายจะมาหาฉันกัน?",
  str_homestory_811401001_4_dialog_content = "ขอโทษที่อยู่นี่ซะนานเลย ดอกไม้ที่นี่หอมจริง ๆ...",
  str_homestory_811401001_5_dialog_content = "ไม่ต้องห่วงหรอกครับ เชิญชมดอกไม้ตามสบาย",
  str_homestory_811401001_6_dialog_content = "มาส่งเร็วจังแฮะ ดอกไม้พวกนี้...",
  str_homestory_811401001_7_dialog_content = "มีดอกไม้เยอะกว่าที่คิดไว้ซะอีกนะเนี่ย",
  str_homestory_811401001_8_dialog_content = "หืม? พูดอะไรน่ะ ผู้นำทาง?",
  str_homestory_811401001_9_dialog_content = "อ่า... ผมกำลังพูดถึงดอกไม้พวกนี้น่ะครับ",
  str_homestory_811401001_10_dialog_content = "ผมเพิ่งสั่งผ่านสหภาพผู้ส่งสาร<sprite=emo_gezitou size=60 /> ไปเมื่อไม่กี่วัน",
  str_homestory_811401001_11_dialog_content = "มีคนแนะนำว่าเราควรปลูกดอกไม้ตกแต่งหินแล้วก็ต้นไม้ที่เรามี",
  str_homestory_811401001_12_dialog_content = "โอ้? ฉันก็คิดเหมือนกันเลย!",
  str_homestory_811401001_13_dialog_content = "เพิ่งบอกอันนาไปเมื่อไม่กี่วัน ว่าที่นี่ควรปลูกดอกไม้มากกว่านี้",
  str_homestory_811401001_14_dialog_content = "ใช่ครับ ผมก็เลยติดต่อสหภาพผู้ส่งสารไป",
  str_homestory_811401001_15_dialog_content = "แต่ว่า นี่มันเยอะกว่าที่คิดนิดนึงแฮะ...",
  str_homestory_811401001_16_dialog_content = "ฉันเอาดอกไม้มาเพิ่มจากภารกิจล่าสุดด้วยน่ะ",
  str_homestory_811401001_17_dialog_content = "ถึงว่า...",
  str_homestory_811401001_18_dialog_content = "ผู้นำทาง อีรางเวลของนายนี่เยี่ยมเลยนะ",
  str_homestory_811401001_19_dialog_content = "ฉันแวะไปที่ร้านขายของมาแล้ว เจอเหล้าจินของโปรดด้วย...",
  str_homestory_811401001_20_dialog_content = "แถมยังมีสมุนไพร น้ำเชื่อม แล้วก็เครื่องเทศสำหรับทำค็อกเทลอร่อย ๆ ด้วย",
  str_homestory_811401001_21_dialog_content = "ฮ่าฮ่า ฉันนี่เซอร์ไพรส์สุด ๆ!",
  str_homestory_811401001_22_dialog_content = "เดี๋ยวนี้นายรอบคอบมากจริง ๆ",
  str_homestory_811401001_23_dialog_content = "รอบคอบ...",
  str_homestory_811401001_24_dialog_content = "อะไรกันนะ ที่ทำให้เด็กซื่อบื้อกลายมาเป็นคนที่น่ารักและเอื้อเฟื้อขนาดนี้?",
  str_homestory_811401001_25_dialog_content = "คุณเจเนวีฟยังพูดถึงเรื่องเหล้าจินในร้านอยู่อีกเหรอ?",
  str_homestory_811401001_26_dialog_content = "ไม่ใช่แค่นั้น เธอยังสั่งดอกไม้มาให้สาว ๆ อีกด้วย",
  str_homestory_811401001_27_dialog_content = "เอ่อ... ที่จริง...",
  str_homestory_811401001_28_dialog_content = "คนที่สั่งให้ผมเตรียมจินกับดอกไม้ก็คือ...",
  str_homestory_811401001_29_dialog_content = "... คุณสโมกกี้",
  str_homestory_811401001_30_dialog_content = "... หา?",
  str_homestory_811401001_31_dialog_content = "เธอขอเรื่องอื่น ๆ อีกเยอะแยะเลย ก็เลยคิดว่าคงไม่ได้ทำเพื่อคุณโดยเฉพาะหรอกครับ...",
  str_homestory_811401001_32_dialog_content = "จะว่าไป... วันที่ฉันคุยกับอันนา ฉันก็รู้สึกว่าอากาศรอบข้างมันร้อน",
  str_homestory_811401001_33_dialog_content = "ฉันไม่ได้นึกถึงเธอแม้แต่น้อย เพราะคนที่นี่ใช้พลังไฟกันเยอะน่ะนะ<sprite=emo_nuhuo size=60 />",
  str_homestory_811401001_34_dialog_content = "... แม่นั่น...",
  str_homestory_811401001_35_dialog_content = "คงไม่อยากให้ฉันรู้เรื่องนี้ล่ะมั้ง",
  str_homestory_811401001_36_dialog_content = "เอ่อ... ผมคิดว่า...",
  str_homestory_811401001_37_option_content = "เธอก็คงหวังให้เป็นแบบนั้นเหมือนกัน",
  str_homestory_811401001_38_dialog_content = "ไม่งั้น เธอคงหาจินกับดอกไม้เองง่าย ๆ อยู่แล้ว...",
  str_homestory_811401001_39_dialog_content = "คือ... เธอไม่จำเป็นต้องให้ผมเป็นคนทำน่ะ",
  str_homestory_811401001_40_option_content = "เธอไม่ได้คิดยังงั้นหรอก",
  str_homestory_811401001_41_dialog_content = "ที่จริง ผมถามไปว่าเหล้าจินนี่สำหรับคุณเจเนวีฟรึเปล่า แล้วเธอก็ปฏิเสธ...",
  str_homestory_811401001_42_dialog_content = "งั้นเหรอ?",
  str_homestory_811401001_43_dialog_content = "ทำตัวไม่ถูกเลยแฮะ",
  str_homestory_811401001_44_dialog_content = "แต่เอาเถอะ ผู้นำทาง ช่วยเก็บเรื่องที่เราคุยกันวันนี้เป็นความลับด้วย",
  str_homestory_811401001_45_dialog_content = "ถึงฉันจะรู้เรื่องที่เธอทำเพื่อฉัน แต่อย่าไปบอกเรื่องนี้ให้เธอรู้ซึ่งหน้าจะดีกว่า...",
  str_homestory_811401001_46_dialog_content = "ไม่งั้นเดี๋ยวเธอก็โวยวายหรือไม่ก็เผาข้าวของแก้เขินอีก",
  str_homestory_811401001_47_dialog_content = "เข้าใจแล้วครับ...",
  str_homestory_811401001_48_dialog_content = "คุณก็รู้จักคุณสโมกกี้ดีเหมือนกันนี่ครับ!",
  str_homestory_811401001_49_dialog_content = "งั้นรึ? ฉันไม่เห็นจะรู้ตัวเลยแฮะ",
  str_homestory_801801001_0_dialog_content = "ออร่าที่ดุเดือดนี่...",
  str_homestory_801801001_1_dialog_content = "ไม่สนใจ!",
  str_homestory_801801001_2_dialog_content = "และ... ไม่อยากเปลืองคำพูด!",
  str_homestory_801801001_3_dialog_content = "โลกนี้มีพวกงี่เง่าเยอะไปแล้ว! เปลวเพลิง! จงเผาผลาญ!<sprite=emo_nuhuo size=60 />",
  str_homestory_801801001_4_dialog_content = "(เธอกำลังมันสุดเหวี่ยงเลย!)",
  str_homestory_801801001_5_dialog_content = "เฮ้ เรจินา!",
  str_homestory_801801001_6_dialog_content = "ผู้นำทาง ฟังเดโม่ของฉันแล้วคิดว่าไงบ้าง?",
  str_homestory_801801001_7_dialog_content = "ผมนึกว่าคุณกำลังด่าใครอยู่ซะอีก...",
  str_homestory_801801001_8_dialog_content = "รู้ด้วยเหรอ?",
  str_homestory_801801001_9_dialog_content = "แหงสิครับ!",
  str_homestory_801801001_10_dialog_content = "โอ้... ฉันพยายามจะให้มันอ้อม ๆ แล้วนะ!",
  str_homestory_801801001_11_dialog_content = "แต่นายก็ยังรู้งั้นเหรอ?",
  str_homestory_801801001_12_dialog_content = "ไปเรียนคำหยาบพวกนั้นมาจากเด็กไม่ดีสินะ!",
  str_homestory_801801001_13_dialog_content = "?",
  str_homestory_801801001_14_dialog_content = "อะแฮ่ม... เปล่าซะหน่อย...",
  str_homestory_801801001_15_dialog_content = "ช่างเหอะ ใครจะสนเรื่องพวกนั้นกันล่ะ!",
  str_homestory_801801001_16_dialog_content = "เพลงใหม่ของฉันยังไม่เสร็จเลย มีไอเดียบ้างมั้ย? บอกฉันทีสิ!",
  str_homestory_801801001_17_dialog_content = "ธีม? เนื้อเพลง? ทำนอง?",
  str_homestory_801801001_18_dialog_content = "เรื่องดนตรีผมห่วยมากน่ะสิ",
  str_homestory_801801001_19_dialog_content = "แล้วไง? ฉันเกลียดที่สุดเลย เจ้าพวกคร่ำครึที่เอาแต่กำหนดมาตรฐานให้กับดนตรี!",
  str_homestory_801801001_20_dialog_content = "อะไรก็ได้น่า พูดมาเถอะ!",
  str_homestory_801801001_21_dialog_content = "...",
  str_homestory_801801001_22_option_content = "บาร์บาร่าเยี่ยมที่สุด",
  str_homestory_801801001_23_dialog_content = "หืม? พูดอะไรของนายน่ะ?",
  str_homestory_801801001_24_dialog_content = "เข้าใจแล้ว คำประชดสินะ",
  str_homestory_801801001_25_option_content = "เมทัลตลอดกาล!",
  str_homestory_801801001_26_dialog_content = "ใช่แล้ว!",
  str_homestory_801801001_27_dialog_content = "ขอจดก่อนนะ!",
  str_homestory_801801001_28_dialog_content = "ฮ่า! เพลงใหม่ที่ได้เคเลสไทต์ช่วยแต่งจะต้องยอดมากแน่ ๆ!",
  str_homestory_801801001_29_dialog_content = "คุณแข่งกับบาร์บาร่าในทุกด้าน แล้วก็แข่งกับเพื่อนชาวเมทัลกันเองด้วยเหรอ?",
  str_homestory_801801001_30_dialog_content = "ให้ตายสิ ไม่มีนักดนตรีคนไหนเคารพกันเองอย่างจริงใจหรอก <sprite=emo_shengqi size=60 />",
  str_homestory_801801001_31_dialog_content = "โดยเฉพาะพวกที่เล่นแนวฉันแล้ว ส่วนใหญ่มีแต่งี่เง่าแล้วก็ของปลอม!",
  str_homestory_801801001_32_dialog_content = "คิดว่าตัวเองเป็นคนกลุ่มสุดท้ายที่เข้าใจดนตรีร็อค แล้วก็อ้างตัวว่าเป็นรุ่นใหญ่... ที่จริงพวกนั้นไม่เคยเขียนเพลงเองด้วยซ้ำ!",
  str_homestory_801801001_33_dialog_content = "ฮึ่ม! ถ้าฉันเลือกได้ล่ะก็ ฉันจะเผาพวกมันให้หมด...",
  str_homestory_801801001_34_dialog_content = "คุยเรื่องดนตรีเมทัลกับคนพวกนั้นแล้ว มันแย่กว่าการฟังซิงเกิ้ลใหม่ของบาร์บาร่าซะอีก!",
  str_homestory_801801001_35_dialog_content = "... ผมนึกว่าคุณไม่ชอบบาร์บาร่ามาก ๆ ซะอีก?",
  str_homestory_801801001_36_dialog_content = "2 วินาที",
  str_homestory_801801001_37_dialog_content = "?",
  str_homestory_801801001_38_dialog_content = "ฉันยอมทนฟังเพลงใหม่ของบาร์บาร่า 2 วินาที",
  str_homestory_801801001_39_dialog_content = "อา...",
  str_homestory_809201001_0_dialog_content = "นั่นมัน...",
  str_homestory_809201001_1_dialog_content = "เฮ้ แพกต์",
  str_homestory_809201001_2_dialog_content = "ใครน่ะ?<sprite=emo_baiyan size=60 />",
  str_homestory_809201001_3_dialog_content = "อะแฮ่ม ชิงช้านี่มีคนชอบเยอะเหมือนกันนะเนี่ย...",
  str_homestory_809201001_4_dialog_content = "นี่... คุณก็ชอบเล่นชิงช้าเหรอ?",
  str_homestory_809201001_5_dialog_content = "คำถามของนายเรียงประโยคไม่ดีเลยนะ",
  str_homestory_809201001_6_dialog_content = "อย่างแรกเลยนะ คำว่า \"ชอบ\" ของนายนี่นิยามยังไง?",
  str_homestory_809201001_7_option_content = "นิยามให้ฟัง",
  str_homestory_809201001_8_dialog_content = "ผมคิดว่า ถ้าคุณชอบอะไรบางอย่าง คุณก็อยากจะทำมันบ่อย ๆ",
  str_homestory_809201001_9_dialog_content = "แล้วที่ว่า \"บ่อย\" นี่เท่าไหร่? มันไม่ชัดเจนเลย",
  str_homestory_809201001_10_dialog_content = "ประมาณว่า ทำเป็นประจำยังงั้นเหรอ?",
  str_homestory_809201001_11_dialog_content = "หรือเฉพาะแค่ตอนที่ฉันมีเวลา?",
  str_homestory_809201001_12_dialog_content = "หรือฉันอาจจะไม่ได้นึกถึงมันบ่อย ๆ ก็ได้ แต่พอฉันจะลงมือทำ ฉันก็ลุยเลย?",
  str_homestory_809201001_13_dialog_content = "(สวรรค์! นี่ฉันแค่จะชวนแพกต์คุยเล่นเฉย ๆ นะเนี่ย...)",
  str_homestory_809201001_14_dialog_content = "ผมว่า \"บ่อย\" เนี่ย ก็คือการลงมือทำทุกครั้งเมื่อมีเวลา",
  str_homestory_809201001_15_option_content = "(ไม่ยอมนิยาม)",
  str_homestory_809201001_16_dialog_content = "เราจะนิยามคำว่า \"ชอบ\" ไปทำไม?",
  str_homestory_809201001_17_dialog_content = "พอผมมีเวลา ผมก็จะชอบเดินเล่น",
  str_homestory_809201001_18_dialog_content = "ก็คือ มันเป็นสิ่งที่ฉันอยากทำตอนมีเวลาว่าง ๆ ใช่มั้ย?",
  str_homestory_809201001_19_dialog_content = "เข้าใจแล้ว",
  str_homestory_809201001_20_dialog_content = "ถ้าอย่างนั้น ฉันก็ชอบนั่งเล่นชิงช้านี่",
  str_homestory_809201001_21_dialog_content = "เก้าอี้ืั้แขวนเชือกแบบนี้ให้ความรู้สึกอ้อม ๆ ที่เหมือนเรากำลังร่วงลงมาจากที่สูง...",
  str_homestory_809201001_22_dialog_content = "มันสนุกในแบบที่ฉันอธิบายเป็นคำพูดไม่ได้",
  str_homestory_809201001_23_dialog_content = "จริงเหรอ? เยี่ยมเลย!",
  str_homestory_809201001_24_dialog_content = "ตอนแรกผมก็ไม่แน่ใจว่าชิงช้าจะเป็นไอเดียที่ดีรึเปล่า",
  str_homestory_809201001_25_dialog_content = "ผมดีใจจริง ๆ ที่คุณชอบนะ!",
  str_homestory_809201001_26_dialog_content = "แต่ว่า มันก็มีปัญหาตามมาด้วย",
  str_homestory_809201001_27_dialog_content = "หินแห่งการล่าเจอปัญหาในการคำนวณแรงที่เหมาะสมในการผลักฉัน",
  str_homestory_809201001_28_dialog_content = "มีครั้งนึงฉันตกลงมาด้วย!",
  str_homestory_809201001_29_dialog_content = "ฮะฮะฮะ...",
  str_homestory_809201001_30_dialog_content = "นี่หัวเราะเยาะกันเหรอ?<sprite=emo_shengqi size=60 />",
  str_homestory_809201001_31_option_content = "ปฏิเสธ",
  str_homestory_809201001_32_dialog_content = "ไม่มีทางอยู่แล้ว...",
  str_homestory_809201001_33_dialog_content = "แน่ใจเหรอ? แล้วทำไมมุมปากของนายมันเผยอขึ้นมานิดนึงล่ะ?",
  str_homestory_809201001_34_option_content = "ยอมรับ",
  str_homestory_809201001_35_dialog_content = "ขอโทษที...",
  str_homestory_809201001_36_dialog_content = "ผมเกือบจะนึกภาพในหัวออกเลยล่ะ...",
  str_homestory_809201001_37_dialog_content = "อะแฮ่ม... แล้วคุณบาดเจ็บรึเปล่า?",
  str_homestory_809201001_38_dialog_content = "คิดว่าฉันอ่อนแอขนาดนั้นเลยหรือไง?",
  str_homestory_809201001_39_dialog_content = "ค่อยยังชั่ว! ในเมื่อคุณชอบชิงช้ามาก ๆ...",
  str_homestory_809201001_40_dialog_content = "ให้ผมผลักให้มั้ย?",
  str_homestory_809201001_41_dialog_content = "หืมม? จะดีเหรอ?",
  str_homestory_809201001_42_dialog_content = "ก็ ถ้าคุณไม่รังเกียจผมก็ยินดี แต่ผมคงแรงเยอะไม่เท่าหินแห่งการล่าหรอก",
  str_homestory_809201001_43_dialog_content = "นั่นก็ขึ้นอยู่กับว่านายนิยามคำว่า \"รังเกียจ\" ยังไงน่ะนะ",
  str_homestory_809201001_44_dialog_content = "เอ่อ...",
  str_homestory_809201001_45_dialog_content = "เอาเถอะ ได้เวลาเล่นชิงช้าแล้ว!",
  str_homestory_809201001_46_dialog_content = "ก็ได้... นายเมื่อนายเต็มใจช่วย... งั้นก็ลุยกันเลย",
  str_homestory_809901001_0_dialog_content = "อาเรีย...",
  str_homestory_809901001_1_dialog_content = "อ๊ะ PlayerName...",
  str_homestory_809901001_2_dialog_content = "ขอบคุณนะที่ชวนฉันมา ฉันมีความสุขมากเลย!",
  str_homestory_809901001_3_dialog_content = "ด้วยความยินดี!",
  str_homestory_809901001_4_dialog_content = "ฉันว่าเธอยังไม่ชินทางที่นี่นะ อยากให้ฉันพาเที่ยวมั้ย?",
  str_homestory_809901001_5_dialog_content = "PlayerName คุณมีเวลาจริง ๆ เหรอ?",
  str_homestory_809901001_6_dialog_content = "แน่นอน ไม่มีใครรู้จักที่นี่ดีเท่าฉันแล้ว",
  str_homestory_809901001_7_dialog_content = "แต่...",
  str_homestory_809901001_8_dialog_content = "ฉ... ฉันควรกลับห้องตัวเองจะดีกว่า",
  str_homestory_809901001_9_dialog_content = "หา? อาเรีย เธอไม่ชอบวิวข้างนอกเหรอ?",
  str_homestory_809901001_10_dialog_content = "ตรงข้ามเลย ฉันชอบวิวที่นี่มาก ๆ!",
  str_homestory_809901001_11_dialog_content = "ฉันไม่เคยมาที่ที่ตัดขาดจากผู้คนและสบายแบบนี้มาก่อน",
  str_homestory_809901001_12_option_content = "แสดงความขอบคุณ",
  str_homestory_809901001_13_dialog_content = "ฉันดีใจจริง ๆ ที่เธอชอบนะ!",
  str_homestory_809901001_14_dialog_content = "นอกจากความสงบไม่วุ่นวายแล้ว เรายังมีอะไรสนุกสนานให้ทำด้วยนะ",
  str_homestory_809901001_15_dialog_content = "เดี๋ยวฉันพาเธอดูรอบ ๆ เอง",
  str_homestory_809901001_16_dialog_content = "แต่ฉันกลัวน่ะสิ...",
  str_homestory_809901001_17_option_content = "สอบถาม",
  str_homestory_809901001_18_dialog_content = "ทำไมเธอต้องรีบกลับห้องล่ะ?",
  str_homestory_809901001_19_dialog_content = "ฉันกลัว...",
  str_homestory_809901001_20_dialog_content = "ถ้าเกิดคำสาปกับหนามสีดำของฉันทำลายความงามของที่นี่ล่ะ?",
  str_homestory_809901001_21_dialog_content = "มันคงทำให้ PlayerName วุ่นวายมาก ๆ...",
  str_homestory_809901001_22_dialog_content = "อาเรีย เธอนี่ใจดีกับฉันจริง ๆ",
  str_homestory_809901001_23_dialog_content = "แต่ฉันไม่คิดว่าเธอจะทำลายความงามของที่นี่หรอกนะ",
  str_homestory_809901001_24_dialog_content = "หืมม?",
  str_homestory_809901001_25_dialog_content = "เรารู้จักกันมานานพอสมควร คำสาปของเธอไม่ได้มีผลกับฉันซักหน่อย",
  str_homestory_809901001_26_dialog_content = "แต่หนามสีดำของฉัน...",
  str_homestory_809901001_27_dialog_content = "พวกเขาเป็นเพื่อนที่ปกป้องร่างกายเธอจากคำสาปไม่ใช่เหรอ?",
  str_homestory_809901001_28_dialog_content = "ใช่...",
  str_homestory_809901001_29_dialog_content = "เพื่อนของอาเรียก็คือเพื่อนของฉันเหมือนกัน",
  str_homestory_809901001_30_dialog_content = "แล้วก็นะ...",
  str_homestory_809901001_31_dialog_content = "ฉันจำได้ว่าเธอกำลังมองหาวิธีถอนคำสาป",
  str_homestory_809901001_32_dialog_content = "ลองเดินดูรอบ ๆ สิ เธออาจจะเจออะไรบางอย่างที่ช่วยถอนคำสาปก็ได้",
  str_homestory_809901001_33_dialog_content = "หืม... ฉันไม่อยากเชื่อหรอกนะ PlayerName",
  str_homestory_809901001_34_dialog_content = "เวลาก็ผ่านไปหลายปีแล้ว แค่อยู่ที่นี่ มันจะเจอวิธีถอนคำสาปกันง่าย ๆ แบบนั้นเลยเหรอ?",
  str_homestory_809901001_35_dialog_content = "แสดงว่าเธอไม่ค่อยออกมาข้างนอกเท่าไหร่ นอกจากออกมาทำงานสินะ?",
  str_homestory_809901001_36_dialog_content = "ก็ใช่...",
  str_homestory_809901001_37_dialog_content = "พอเธอใช้เวลากับธรรมชาติ เธอก็จะอารมณ์ดีขึ้น",
  str_homestory_809901001_38_dialog_content = "ใครจะรู้ ถ้าเธออารมณ์ดี คำสาปอาจจะอ่อนกำลังลงก็ได้!",
  str_homestory_809901001_39_dialog_content = "...",
  str_homestory_809901001_40_dialog_content = "ฮะฮะฮะ...",
  str_homestory_809901001_41_dialog_content = "ขอบคุณนะ ตอนนี้ฉันรู้สึกดีมากเลย<sprite=emo_aixin size=60 />",
  str_homestory_809901001_42_dialog_content = "ถ้างั้น... ฉันขอไปดูเหมืองแร่ได้มั้ย?",
  str_homestory_809901001_43_dialog_content = "หืมม?",
  str_homestory_801601001_0_dialog_content = "คาฟกา?",
  str_homestory_801601001_1_dialog_content = "เดี๋ยวก่อน คาฟกา... คราบน้ำ<sprite=emo_hanshui size=60 /> บนพื้นนี่มันอะไรน่ะ?",
  str_homestory_801601001_2_dialog_content = "อา... ขอโทษนะ ฟรานซ์<sprite=emo_goutou size=60 /> น้ำลายไหลน่ะ ฉันเพิ่งเช็ดทำความสะอาดไป",
  str_homestory_801601001_3_dialog_content = "ดูเหมือนมันจะน้ำลายไหลเยอะเวลามีความสุข นี่เป็นปัญหาใหม่ที่ทำเอาฉันเหนื่อยเลย",
  str_homestory_801601001_4_dialog_content = "เอ่อ... แต่อย่างน้อยมันก็ทำเตียงเปียกน้อยกว่าแต่ก่อน",
  str_homestory_801601001_5_dialog_content = "งั้นก็เยี่ยมเลย... ฟรานซ์เป็นเด็กดีมาตลอดสินะ?",
  str_homestory_801601001_6_dialog_content = "คำชมของนายจะทำให้มันดีใจอย่างฉุดไม่อยู่",
  str_homestory_801601001_7_dialog_content = "ฉันรู้ว่ามันมีความสุขมาก ๆ ที่ได้อยู่นี่",
  str_homestory_801601001_8_dialog_content = "หืม? เพราะมันกว้างกว่าโคลอสซัสงั้นเหรอ?",
  str_homestory_801601001_9_dialog_content = "หรือไม่ก็เพราะมันเจอแต่คนแปลก ๆ มากหน้าหลายตา...",
  str_homestory_801601001_10_dialog_content = "อย่างที่นายรู้ มันชอบของแปลกน่ะ",
  str_homestory_801601001_11_dialog_content = "เช่นอะไรเหรอ?",
  str_homestory_801601001_12_dialog_content = "ฉันควรจะเรียกว่า \"สิ่งมีชีวิตประหลาด\" น่ะ",
  str_homestory_801601001_13_dialog_content = "สิ่งมีชีวิตประหลาด...",
  str_homestory_801601001_14_dialog_content = "เข้าใจแล้ว! คุณคงจะหมายถึง... เขา...",
  str_homestory_801601001_15_option_content = "ทัวร์ด็อก?",
  str_homestory_801601001_16_dialog_content = "อืมม... ก็ประมาณนั้นแหละ ฉันไม่ได้คุยกับเขาเท่าไหร่",
  str_homestory_801601001_17_dialog_content = "แต่ฟรานซ์กระดิกหางเอาเป็นเอาตายเวลามันเจอทัวร์ด็อก แถมยังพยายามไปงับหูทัวร์ด็อกทีนึงด้วย",
  str_homestory_801601001_18_dialog_content = "อา? ทัวร์ด็อกไปทำอะไรให้ล่ะนั่น?",
  str_homestory_801601001_19_dialog_content = "ก็ไม่ได้ทำอะไรเท่าไหร่ เขาจ้องฟรานซ์พักนึง ถือกระทะในมือ ฉันว่าเขาคงอยากพูดอะไรบางอย่าง",
  str_homestory_801601001_20_dialog_content = "(... คงอยากขอให้ฟรานซ์วาดรูปให้แน่ ๆ!)",
  str_homestory_801601001_21_dialog_content = "ท้ายที่สุดเขาก็เห็นอุ้งเท้าของฟรานซ์ แล้วก็เดินจากไปพร้อมส่ายหัว",
  str_homestory_801601001_22_dialog_content = "ฟู่... ค่อยยังชั่ว...",
  str_homestory_801601001_23_dialog_content = "แต่ว่า หูของเขาท่าทางนุ่มมาก",
  str_homestory_801601001_24_dialog_content = "คราวหน้าฉันน่าจะลองจับดู...",
  str_homestory_801601001_25_option_content = "ฮาชิกับกินน่ะเหรอ?",
  str_homestory_801601001_26_dialog_content = "เจ้าเด็กขนปุยสองตัวที่พยายามทำตัวเป็นผู้ใหญ่",
  str_homestory_801601001_27_dialog_content = "ทุกครั้งที่พวกนั้นเจอฟรานซ์ ก็จะตะโกนว่า \"ว้าว! หมาตัวจริง!\"",
  str_homestory_801601001_28_dialog_content = "ดูเหมือนฟรานซ์จะชอบพวกเขา แล้วก็ชอบวิ่งไล่หางของพวกนั้น",
  str_homestory_801601001_29_dialog_content = "ฟังดูแปลก ๆ แฮะ...",
  str_homestory_801601001_30_dialog_content = "ไม่รู้ว่าทำไม แต่อยากจะเห็นภาพนั้นด้วยตัวเองจัง...",
  str_homestory_801601001_31_dialog_content = "สรุปแล้วก็คือ ฟรานซ์มีชีวิตที่ดีมาก ๆ ที่นี่",
  str_homestory_801601001_32_dialog_content = "แต่... ช่วงนี้นายได้อยู่กับฟรานซ์บ่อย ๆ รึเปล่า?",
  str_homestory_801601001_33_dialog_content = "หืมม? ผมก็ไม่ค่อยได้เจอมันเลยนะ",
  str_homestory_801601001_34_dialog_content = "แต่ฉันได้กลิ่นนายจากตัวฟรานซ์นะ!",
  str_homestory_801601001_35_dialog_content = "มันอาจจะแอบเข้าไปในห้องนาย",
  str_homestory_801601001_36_dialog_content = "อืมม... ก็ใช่ว่าจะเป็นไปไม่ได้แฮะ",
  str_homestory_801601001_37_dialog_content = "เดี๋ยวนะ...",
  str_homestory_801601001_38_dialog_content = "เมื่อกี้คุณว่าไงนะ?",
  str_homestory_801601001_39_dialog_content = "ฟรานซ์ไม่ได้ทำเตียงเปียก<sprite=emo_hanshui size=60 /> บ่อย ๆ แล้วยังงั้นเหรอ?",
  str_homestory_801601001_40_dialog_content = "เอ่อ... อย่าบอกนะว่า...",
  str_homestory_801601001_41_dialog_content = "... ถึงว่า ทำไมเตียงถึงชื้น ๆ!",
  str_homestory_801601001_42_dialog_content = "แบบนี้นี่เอง...",
  str_homestory_801601001_43_dialog_content = "ฟรานซ์คงจะชอบนายมากจริง ๆ",
  str_homestory_801601001_44_dialog_content = "... ผมควรดีใจมั้ยเนี่ย?",
  str_homestory_801601001_45_dialog_content = "ขอคำแนะนำจากฉันงั้นเหรอ?",
  str_homestory_801601001_46_dialog_content = "เอ่อ... ถ้าฉันเป็นนาย ฉันจะรีบกลับไปซักผ้าปูที่นอนโดยด่วน",
  str_homestory_804501001_0_dialog_content = "เสียงอะไรน่ะ?",
  str_homestory_804501001_1_dialog_content = "เนลส์?",
  str_homestory_804501001_2_dialog_content = "ชู่ว... ช่วยรอสักครู่นะ...",
  str_homestory_804501001_3_dialog_content = "อ๊ะ! ใบหน้าของท่านสว่างและสะอาดเหมือนจานกระเบื้อง สะท้อนร่างกายอันโสมมของผม...",
  str_homestory_804501001_4_dialog_content = "ดวงตาของท่านลึกเหมือนฟ้ายามราตรี แทงทะลุบาปอันไม่อาจทานทนได้ในจิตใจของผม...",
  str_homestory_804501001_5_dialog_content = "กรุณายกโทษให้บาปกรรมของผมด้วย...",
  str_homestory_804501001_6_dialog_content = "หรือการที่ท่านอภัยโทษให้ผม จะทำให้ท่านเสื่อมเสียเกียรติกันนะ?",
  str_homestory_804501001_7_dialog_content = "...",
  str_homestory_804501001_8_dialog_content = "ขอโทษที่ให้รอนะ PlayerName!",
  str_homestory_804501001_9_dialog_content = "นี่ผมกวนคุณรึเปล่า?",
  str_homestory_804501001_10_dialog_content = "ต้องขออภัยอย่างสูง! เสียงของผมระคายเคืองหูของทุกคน เต็มเปี่ยมไปด้วยบาป...",
  str_homestory_804501001_11_dialog_content = "อย่าทำร้ายตัวเองแบบนั้นเลย ผมไม่รำคาญหรอก!",
  str_homestory_804501001_12_dialog_content = "แต่ผมสงสัย... ว่าคุณกำลังคุยกับใคร?",
  str_homestory_804501001_13_dialog_content = "คุณคงเข้าใจผิดแล้ว... ไม่มีใครทั้งนั้นแหละ ผมแค่สารภาพบาปของตัวเอง",
  str_homestory_804501001_14_dialog_content = "ต้องขอบคุณมาก ๆ เลยนะ ผู้นำทาง!",
  str_homestory_804501001_15_dialog_content = "เพราะคุณแท้ ๆ ผมเลยมีสถานที่สารภาพที่สมบูรณ์แบบเช่นนี้",
  str_homestory_804501001_16_dialog_content = "ในที่สุด ผมก็สามารถสารภาพบาปได้โดยที่ไม่ต้องรบกวนเลดี้วิกตอเรีย",
  str_homestory_804501001_17_option_content = "ปฏิเสธ",
  str_homestory_804501001_18_dialog_content = "ผมจำไม่ได้ว่าตัวเองสร้างสถานที่สารภาพบาปเอาไว้นะ...",
  str_homestory_804501001_19_dialog_content = "ช่างถ่อมตัวอะไรเช่นนี้ ผมมั่นใจว่าน้ำพุอันงดงามนี้คงใช้เวลาและแรงงานเยอะมากแน่ ๆ",
  str_homestory_804501001_20_dialog_content = "แต่นี่เป็นน้ำพุแห่งความหวังนะ",
  str_homestory_804501001_21_option_content = "ยอมรับ",
  str_homestory_804501001_22_dialog_content = "ด้วยความยินดีอย่างยิ่ง ดีใจที่คุณชอบนะ...",
  str_homestory_804501001_23_dialog_content = "เดี๋ยวนะ... คุณบอกว่าน้ำพุแห่งการสารภาพงั้นเหรอ?",
  str_homestory_804501001_24_dialog_content = "ไม่ใช่ว่าพูดถึงน้ำพุแห่งความหวังหรอกนะ?",
  str_homestory_804501001_25_dialog_content = "น้ำพุแห่งความหวัง... ช่างเป็นชื่อที่อ่อนโยนจริง ๆ!",
  str_homestory_804501001_26_dialog_content = "ผมเห็นผู้คนที่นี่พนมมืออย่างเคร่งเครียดและสารภาพอย่างจริงจัง ในที่สุดผมก็รู้ชื่อแล้ว!",
  str_homestory_804501001_27_dialog_content = "ผมมีความผิด จะต้องสารภาพบาป...",
  str_homestory_804501001_28_dialog_content = "จะมองแบบนั้นก็ไม่ผิดน่ะนะ... ผมเชื่อว่าผู้คนที่นี่ต่างก็ภาวนา",
  str_homestory_804501001_29_dialog_content = "ผมต้องสารภาพบาปในส่วนของ PlayerName ด้วย...",
