  str_homestory_804501001_32_dialog_content = "PlayerName กรุณายกโทษให้ผมด้วย ที่ไม่ได้อธิบายเรื่องนี้ให้ทราบก่อน",
  str_homestory_804501001_33_dialog_content = "สัจธรรมที่สถิตในน้ำพุแห่งความหวังเอ๋ย...",
  str_homestory_804501001_34_dialog_content = "โปรดให้อภัยเนลส์ที่รบกวนคุณอีกครั้ง!",
  str_homestory_804501001_35_dialog_content = "ผมมีความผิด และมาที่นี่เพื่อสารภาพบาป กรุณาลงโทษผมด้วย...",
  str_homestory_804501001_36_option_content = "ลงโทษเขาซะ",
  str_homestory_804501001_37_dialog_content = "ให้ตายสิ! ผมสัมผัสได้ถึงคำตอบของน้ำพุแห่งความหวัง!",
  str_homestory_804501001_38_dialog_content = "คำตอบงั้นเหรอ? ในที่สุดสัจธรรมก็ปรากฏสินะ!",
  str_homestory_804501001_39_dialog_content = "อะแฮ่ม... น้ำพุแห่งความหวังกล่าวว่า...",
  str_homestory_804501001_40_option_content = "ปลอบโยนเขา",
  str_homestory_804501001_41_dialog_content = "เนลส์ ผมว่าคุณไม่จำเป็นต้องสารภาพเรื่องแบบนั้นหรอกนะ",
  str_homestory_804501001_42_dialog_content = "แทนที่จะสารภาพบาป ทำไมไม่วางแผนสำหรับอนาคตล่ะ?",
  str_homestory_804501001_43_dialog_content = "!",
  str_homestory_804501001_44_dialog_content = "ทำไมผมไม่เคยนึกถึงเรื่องนี้เลยนะ?",
  str_homestory_804501001_45_dialog_content = "ผมรู้แล้ว... เพราะผมคือคนบาปนี่เอง...",
  str_homestory_804501001_46_dialog_content = "เอ่อ...",
  str_homestory_808601001_0_dialog_content = "ดอกไม้สีขาวที่คุ้นเคยนี่มัน...",
  str_homestory_808601001_1_dialog_content = "ผู้นำทาง PlayerName",
  str_homestory_808601001_2_dialog_content = "ฉันไม่นึกเลยว่าอีราเวลจะงดงามเพียงนี้",
  str_homestory_808601001_3_dialog_content = "ทุ่งหญ้ายาวไกลสุดสายตา... เราไม่สามารถหาสิ่งนี้ได้ที่ลูโมโพลิส",
  str_homestory_808601001_4_dialog_content = "แม้แต่ดอกไม้สีขาวเหล่านี้<sprite=emo_huaduo size=60 /> ก็ชอบอีราเวลเช่นกัน...",
