  str_homestory_808601001_8_dialog_content = "ฉันจำได้แล้ว... เธอจำเป็นต้องอพยพจากอีราเวลตั้งแต่ยังเล็ก",
  str_homestory_808601001_9_dialog_content = "ใช่ครับ ผมรู้จักอีราเวลก็เพราะเรียนกับโซรอซ...",
  str_homestory_808601001_10_dialog_content = "แต่ตอนที่มาเยือนอีราเวลครั้งแรก ผมก็ตื่นเต้นกับความงดงามของที่นี่เหมือนกัน<sprite=emo_pugongying size=60 />",
  str_homestory_808601001_11_dialog_content = "และความตื่นตาตื่นใจก็ไม่ได้เลือนหายไปกับกาลเวลาเลย",
  str_homestory_808601001_12_dialog_content = "อาจเป็นเพราะ มันคือความรู้สึกที่ได้กลับบ้าน ผมรู้ว่าอีราเวลนั้นเชื่อมโยงกับตัวผม",
  str_homestory_808601001_13_dialog_content = "ใช่แล้ว... ทุกสิ่ง ณ ที่แห่งนี้ล้วนมากด้วยสติปัญญาในเชิงจิตวิญญาณ สถาปัตยกรรมของเคเลสไทต์อยู่ร่วมกับธรรมชาติได้อย่างสมบูรณ์แบบ",
  str_homestory_808601001_14_dialog_content = "ฉันทำงานกับผู้ล่วงลับบ่อย ๆ และฉันก็สัมผัสได้...",
  str_homestory_808601001_15_dialog_content = "สถานที่แห่งนี้มีความงดงามในฐานะแหล่งกำเนิดของชีวิต",
  str_homestory_808601001_16_dialog_content = "ทุกสิ่งล้วนมีชีวิต และทุกคนที่ขับขานบทเพลงสรรเสริญแด่ชีวิตก็จะต้องตกหลุมรักอีราเวล",
  str_homestory_808601001_17_dialog_content = "บ้านเกิดของ PlayerName ช่างสวยงามเหลือเกิน",
  str_homestory_808601001_18_dialog_content = "ฉันดีใจที่เธอเลือกมาตั้งรกรากอยู่ที่นี่นะ",
  str_homestory_808601001_19_dialog_content = "ขอบคุณครับ ยูริอาห์",
  str_homestory_808601001_20_dialog_content = "ผมประทับใจจริง ๆ ที่คุณชื่นชมอีราเวลขนาดนี้",
