  str_homestory_808601001_25_dialog_content = "หรือมันจะมากกว่าการขอเดทกันนะ? เธอจะขอฉันแต่งงานหรือไงกัน?",
  str_homestory_808601001_26_dialog_content = "ว่าไงนะ?",
  str_homestory_808601001_27_dialog_content = "เปล่านะครับ!",
  str_homestory_808601001_28_dialog_content = "ฮะฮะฮะ... น่ารักจริง ๆ!",
  str_homestory_808601001_29_dialog_content = "อย่าล้อผมเล่นแบบนั้นสิ!",
  str_homestory_808601001_30_option_content = "ต้อนรับ",
  str_homestory_808601001_31_dialog_content = "อีราเวลต้อนรับคุณเสมอครับ คุณยูริอาห์ หวังว่าผมจะได้เจอคุณบ่อย ๆ นะ",
  str_homestory_808601001_32_dialog_content = "ด้วยความยินดี",
  str_homestory_808601001_33_dialog_content = "ทิวทัศน์อันงดงามของที่นี่ช่างน่าหลงใหล และที่นี่ก็เป็นบ้านของเธอ",
  str_homestory_808601001_34_dialog_content = "PlayerName ฉันคาดหวังอนาคตอันสดใสภายใต้การนำของเธอนะ",
  str_homestory_808601001_35_dialog_content = "ขอบคุณครับ... คุณยูริอาห์ เป็นแม่ชีที่ดูแลเรื่องการสวดภาวนาให้ผู้ล่วงลับใช่มั้ย?",
  str_homestory_808601001_36_dialog_content = "ใช่ นั่นเป็นงานของฉันที่ลูโมโพลิส",
