  str_homestory_808601001_40_dialog_content = "ฉันประทับใจจริง ๆ ที่เธอโตเป็นผู้ใหญ่ขึ้นมาก ในตอนนี้ เธอสามารถยอมรับในชีวิตและความตายได้อย่างแท้จริง",
  str_homestory_808601001_41_dialog_content = "ตัวฉัน ผู้สวดภาวนาพิธีศพ ซิสเตอร์ยูริอาห์ ขอสวดภาวนาแด่ดวงวิญญาณแห่งอีราเวล",
  str_homestory_808601001_42_dialog_content = "ขอวิญญาณของพวกเขาจงหลับอย่างสงบ! ขอดอกไม้สีขาวจงเบ่งบานทั่วอีราเวล",
  str_homestory_808601001_43_dialog_content = "ขอบคุณครับ",
  str_homestory_810201001_0_dialog_content = "กระแสไฟฟ้านี่มัน...",
  str_homestory_810201001_1_dialog_content = "เทสซา?",
  str_homestory_810201001_2_dialog_content = "ถ้าเธอเหนื่อย ไปพักในหอพักของสวนลอยฟ้าได้นะ",
