  str_homestory_810201001_4_dialog_content = "ว่างุยนะ? ออ เนิยนิเอง!",
  str_homestory_810201001_5_dialog_content = "ขอโทษที",
  str_homestory_810201001_6_dialog_content = "เฮ้อ... นี่ฉันต้องเอาลูกอมออกจากปากทุกครั้งเลยหรือไง นายถึงจะฟังฉันรู้เรื่อง?",
