  str_homestory_810201001_32_dialog_content = "ตอนแรกฉันก็นึกว่าเทสซาเป็นคนหยิบไป... แต่สงสัยมีใครหยิบไปกินก่อนแล้วล่ะมั้ง",
  str_homestory_810201001_33_dialog_content = "พูดเป็นเล่นน่า? ทำไมไม่บอกให้เร็วกว่านี้ล่ะ?",
  str_homestory_810201001_34_dialog_content = "ฉันนึกว่าทุกคนจะเข้าไปพักผ่อนในหอพักก่อนน่ะสิ...",
  str_homestory_810201001_35_dialog_content = "ฮึ่ม! ช่างเถอะ",
