  str_homestory_801501001_0_dialog_content = "นี่เป็นครั้งแรกเลยนะเนี่ย...",
  str_homestory_801501001_1_dialog_content = "ฉันไม่เคยเห็นนายแยกกับกินมาก่อนเลย",
