  str_homestory_801501001_5_dialog_content = "ฉันไม่เห็นได้กลิ่นเลย?",
  str_homestory_801501001_6_dialog_content = "ว่าแต่ไนท์เทียมมีกลิ่นด้วยเหรอ?",
  str_homestory_801501001_7_dialog_content = "PlayerName นั่นเป็นคำพูดเปรียบเปรยเฉย ๆ น่ะ ประเด็นคือ...",
