  str_homestory_801501001_11_dialog_content = "ไนท์เทียมกลิ่นเป็นยังไงเหรอ?",
  str_homestory_801501001_12_dialog_content = "ความหอมของสนิม 30% ผสมกับเหงื่อเค็ม ๆ 40%...",
