  str_homestory_801501001_36_dialog_content = "เข้าใจแล้ว",
  str_homestory_801501001_37_dialog_content = "PlayerName ไม่อยากให้ฉันเปลี่ยนแปลงสถาปัตยกรรมและพรรณไม้ของที่นี่",
