  str_homestory_801502001_15_dialog_content = "นายดมอะไรอยู่เหรอ?",
  str_homestory_801502001_16_dialog_content = "นายไม่ได้กลิ่นเหรอ? กลิ่นเหมือนเหรียญ",
  str_homestory_801502001_17_dialog_content = "ไนท์เทียม<sprite=emo_baiyebi size=60 />อีกแล้วเหรอ?",
  str_homestory_801502001_18_dialog_content = "ไม่ รอบนี้คนละเรื่องเลย!",
  str_homestory_801502001_19_dialog_content = "มันใหม่เอี่ยมและไม่เหมือนใคร... *ดม*",
  str_homestory_801502001_20_dialog_content = "มันกลิ่นฉุนกว่าและชื้นกว่าไนท์เทียม แล้วก็เก่าแก่กว่า...",
  str_homestory_801502001_21_dialog_content = "แถมลวดลายก็ซับซ้อนมากด้วย",
  str_homestory_801502001_22_dialog_content = "นายดมได้แม้กระทั่งลวดลายเลยเหรอ?",
  str_homestory_801502001_23_dialog_content = "อย่าประมาทจมูกของสุนัขเชียวล่ะ",
  str_homestory_801502001_24_dialog_content = "ไม่ว่าจะเป็นเทรนด์ธุรกิจหรือกลิ่นของเหรียญ ฉันก็สามารถชี้ให้นายไปในทางที่ถูกต้องได้",
  str_homestory_801502001_25_dialog_content = "ครั้งนี้ ฉันจะให้โอกาสนายค้นหาเหรียญPlayerName",
  str_homestory_801502001_26_dialog_content = "หา?",
  str_homestory_801502001_27_dialog_content = "หวังว่านายจะพิจารณาเรื่องการร่วมมือของเรานะ!",
  str_homestory_805602001_0_dialog_content = "คุณคอนสแตนติน?",
  str_homestory_805602001_1_dialog_content = "สวัสดี PlayerName",
  str_homestory_805602001_2_dialog_content = "ไปไหนมาเหรอ คุณคอนสแตนติน?",
  str_homestory_805602001_3_dialog_content = "ฉันเพิ่งกลับจากตกปลาน่ะ",
  str_homestory_805602001_4_dialog_content = "อ๋อ หลายวันมานี้ผมเห็นคุณไปตกปลาตลอดเลย",
  str_homestory_805602001_5_dialog_content = "คุณเป็นมืออาชีพ อย่างนี้คงจะจับปลามาได้เยอะเลยใช่มั้ย?",
  str_homestory_805602001_6_dialog_content = "ไม่ได้เลยสักตัว",
  str_homestory_805602001_7_dialog_content = "อะไรนะ? แต่คุณเป็นนักล่ามืออาชีพนี่นา!",
  str_homestory_805602001_8_dialog_content = "นายคงคิดว่าการตกปลาเหมือนกับการล่าสัตว์ แต่ความจริงแล้วสองอย่างนี้แตกต่างกันมากเลยนะ<sprite=emo_sikao size=60 />",
  str_homestory_805602001_9_dialog_content = "การล่าคือการใช้กำลังรุกเข้าไปกำราบเหยื่อ",
  str_homestory_805602001_10_dialog_content = "แต่การตกปลา เราต้องแสดงท่าทีให้น้อยที่สุด และรอให้อีกฝ่ายเข้ามาหาเราเอง",
  str_homestory_805602001_11_option_content = "เข้าใจแล้ว",
  str_homestory_805602001_12_dialog_content = "เวลาตกปลา ไม่มีใครรู้ว่าเราจะจับได้อะไร",
  str_homestory_805602001_13_dialog_content = "แต่เวลาล่าสัตว์ เราเจอเป้าหมายก่อนแล้วจึงลงมือล่า",
  str_homestory_805602001_14_option_content = "ไม่เข้าใจ",
  str_homestory_805602001_15_dialog_content = "แต่คุณบอกว่าการล่าต้องใช้ความอดทน นั่นก็จำเป็นสำหรับการตกปลาด้วยนี่นา",
  str_homestory_805602001_16_dialog_content = "ไม่มีใครรู้ว่าปลาจะกินเหยื่อเมื่อไหร่",
  str_homestory_805602001_17_dialog_content = "ใช่ นายพูดถูก",
  str_homestory_805602001_18_dialog_content = "บอกตามตรง ตอนแรกฉันก็แหกกฏเหมือนกัน...",
  str_homestory_805602001_19_dialog_content = "ฉันจะเพ่งไปที่เป้าหมายก่อนเสมอ จากนั้นก็พยายามจับมัน แล้วก็คว้าน้ำเหลวทุกครั้ง",
  str_homestory_805602001_20_dialog_content = "เพื่อเตือนตัวเองถึงบทเรียนที่ได้เรียนรู้ ฉันเลยดัดตะขอเบ็ดให้ตรง",
  str_homestory_805602001_21_dialog_content = "อะไรนะ? คุณจับปลาด้วยวิธีแบบนั้นได้ด้วยเหรอ?",
  str_homestory_805602001_22_dialog_content = "ฉันก็ไม่รู้ และก็ไม่สนใจด้วย ฉันแค่อยากจะฝึกฝนความอดทนของฉัน",
  str_homestory_805602001_23_dialog_content = "คุณจะตกปลาด้วยวิธีนี้ไปเรื่อย ๆ เลยเหรอ?",
  str_homestory_805602001_24_dialog_content = "ฉันมีกำหนดเวลาของตัวเองเหมือนกัน",
  str_homestory_805602001_25_dialog_content = "จนกว่าเหรียญที่ริมฝั่งน้ำจะถูกปกคลุมไปด้วยตะกอน ถูกแม่น้ำพัดพาไป...หรือมีคนตกมันไปได้",
  str_homestory_805602001_26_dialog_content = "ถึงตอนนั้นฉันจะตกปลาด้วยตะขอเบ็ดตรง",
  str_homestory_805602001_27_dialog_content = "(เหรียญ...?)",
  str_homestory_805602001_28_dialog_content = "(ไปลองบ้างดีกว่า ว่าจะตกเหรียญนั่นขึ้่นมาได้มั้ย)",
  str_homestory_808502001_0_dialog_content = "โห เร็วจัง...",
  str_homestory_808502001_1_dialog_content = "คุณกำลังจดบันทึกอยู่เหรอ เจน?",
  str_homestory_808502001_2_dialog_content = "ใช่ ฉันกำลังบันทึกทุกอย่างที่ฉันเห็นในสวนลอยฟ้า",
  str_homestory_808502001_3_dialog_content = "ถ้าผมไม่รู้ว่าคุณทำอาชีพอะไร ผมคงคิดว่าคุณกำลังวาดภาพอยู่",
  str_homestory_808502001_4_dialog_content = "แต่ฉันก็กำลังวาดภาพนะ",
  str_homestory_808502001_5_dialog_content = "หา...?<sprite=emo_wuzui size=60 />",
  str_homestory_808502001_6_dialog_content = "การบันทึกไม่เพียงต้องใช้คำพูดเท่านั้น แต่ภาพประกอบก็สำคัญเหมือนกัน",
  str_homestory_808502001_7_dialog_content = "แล้วเมื่อไหร่ที่ต้องใช้ภาพประกอบเหรอ?",
  str_homestory_808502001_8_dialog_content = "พูดง่าย ๆ ก็คือ เมื่อไหร่ที่คำพูดไม่สามารถอธิบายทุกสิ่งได้เพียงพอ เมื่อนั้นแหละที่เราต้องใช้ภาพประกอบ",
  str_homestory_808502001_9_dialog_content = "อย่างเช่น เมื่อกี้ฉันก็เพิ่งอธิบายทุกสิ่งที่พบเห็นในแม่น้ำ",
  str_homestory_808502001_10_dialog_content = "ฉันอาจจะใช้คำพูดเพื่ออธิบายปลากะพงครีบแดงได้ แต่ผู้อ่านก็จะทำได้แค่จินตนาการภาพในหัวเท่านั้น",
  str_homestory_808502001_11_dialog_content = "แต่ถ้าฉันวาดรูปร่างและสีของมันออกมา...",
  str_homestory_808502001_12_dialog_content = "พวกเขาก็จะเข้าใจในทันทีว่าหน้าตาของมันเป็นยังไง",
  str_homestory_808502001_13_dialog_content = "แบบนี้นี่เอง...",
  str_homestory_808502001_14_dialog_content = "หรืออีกสักตัวอย่าง ตอนที่ฉันกำลังเขียนบันทึกเรื่อง \"เหรียญที่แน่นิ่งอยู่ก้นแม่น้ำ\"...",
  str_homestory_808502001_15_dialog_content = "พวกเขาก็จินตนาการได้แค่ภาพเหรียญที่ตัวเองเคยเห็นเท่านั้น",
  str_homestory_808502001_16_dialog_content = "เพราะงั้นฉันเลยต้องวาดลวดลายของเหรียญที่ไม่เคยมีใครพบเห็นมาก่อน",
  str_homestory_808502001_17_dialog_content = "แบบนั้นก็จะทำให้พวกเขาเข้าใจอย่างแจ่มแจ้งว่าเหรียญที่อยู่ก้นแม่น้ำในสวนลอยฟ้าเป็นเหรียญแบบไหน",
  str_homestory_808502001_18_dialog_content = "แล้วตอนนี้เหรียญนั่นอยู่ไหนแล้วล่ะ?",
  str_homestory_808502001_19_dialog_content = "ก็ยังอยู่ในแม่น้ำน่ะสิ",
  str_homestory_808502001_20_dialog_content = "อะไรนะ? ทำไมคุณถึงไม่เก็บมันขึ้นมาล่ะ?",
  str_homestory_808502001_21_dialog_content = "ฉันแค่จดบันทึก ไม่ได้ไปก้าวก่ายอย่างอื่น",
  str_homestory_808502001_22_dialog_content = "นั่นหมายความว่า ฉันก็จะไม่ห้ามนายเก็บเหรียญนั่นเหมือนกัน",
  str_homestory_808502001_23_dialog_content = "แต่ฉันจะบันทึกทุกอย่างที่เกิดขึ้นตามความจริง",
  str_homestory_805502001_0_dialog_content = "อารมณ์ไม่ดีเหรอ?",
  str_homestory_805502001_1_dialog_content = "เกิดอะไรขึ้นเหรอคุณพิตต์แมน? คุณดูเหมือนโกรธอยู่นะ",
  str_homestory_805502001_2_dialog_content = "มาได้เวลาพอดีเลยนะ PlayerName ฉันกำลังตามหานายอยู่!",
  str_homestory_805502001_3_dialog_content = "หืม มันเกี่ยวอะไรกับผมงั้นเหรอ?",
  str_homestory_805502001_4_dialog_content = "เรื่องนั้นฉันก็ยังไม่แน่ใจ แต่ว่า...",
  str_homestory_805502001_5_dialog_content = "ขอเทิดทูนรัตติกาลสีขาว! ในนามของผู้พิพากษาแห่งลูโมโพลิส ข้าพเจ้าขอเปิดการไต่สวน...",
  str_homestory_805502001_6_dialog_content = "นายกำลังผลิตเหรียญไนท์เทียมที่สวนลอยฟ้าแห่งนี้รึเปล่า?",
  str_homestory_805502001_7_option_content = "เปล่านะครับ!",
  str_homestory_805502001_8_dialog_content = "ถึงผมจะต้องการไนท์เทียมก็จริง แต่ผมก็ไม่ได้สิ้นหวังขนาดนั้น!",
  str_homestory_805502001_9_option_content = "ผมก็อยากทำอย่างนั้น",
  str_homestory_805502001_10_dialog_content = "แต่ว่าการสร้างไนท์เทียมนั้นแพงเกินไป ผมต้องใช้เงินมหาศาลเพื่อสร้างโรงกษาปณ์หรืออะไรแบบนั้นขึ้นมา",
  str_homestory_805502001_11_dialog_content = "แล้วคุณก็รู้ว่าผมไม่ได้มีเงินมากขนาดนั้น!",
  str_homestory_805502001_12_dialog_content = "นายจะให้คำสาบานรึเปล่า?",
  str_homestory_805502001_13_dialog_content = "ผมขอสาบานว่า PlayerName ไม่เคยผลิตเหรียญไนท์เทียมแน่นอน",
  str_homestory_805502001_14_dialog_content = "ไม่งั้น... คุณจะลงโทษผมยังไงก็เชิญ!",
  str_homestory_805502001_15_dialog_content = "แล้วนายสังเกตเห็นผู้ต้องสงสัยหรือเบาะแสอะไรเกี่ยวกับเรื่องนี้ในสวนลอยฟ้าบ้างหรือเปล่า?",
  str_homestory_805502001_16_dialog_content = "โดยเฉพาะพวกที่มาจากอัมบราตันแล้วก็ทะเลทราย?",
  str_homestory_805502001_17_dialog_content = "พวกเขาเป็นเพื่อนของผม ผมเลยไม่อยากสงสัยพวกเขา...",
  str_homestory_805502001_18_dialog_content = "ไม่ว่าเขาจะเป็นใคร ทุกคนก็ควรได้รับการปฏิบัติอย่างเท่าเทียมในทางกฎหมาย",
  str_homestory_805502001_19_dialog_content = "แต่ทำไมคุณถึงสงสัยพวกเขาล่ะ?",
  str_homestory_805502001_20_dialog_content = "ในเมื่อนายให้คำสาบานแล้ว งั้นฉันจะบอกความลับกับนาย",
  str_homestory_805502001_21_dialog_content = "ฉันพบเหรียญที่ริมแม่น้ำที่มีลักษณะเหมือนไนท์เทียม!",
  str_homestory_805502001_22_dialog_content = "ผมขอดูเหรียญนั่นได้ไหม?",
  str_homestory_805502001_23_dialog_content = "ตอนนั้นฉันโกรธมาก เหรียญก็เลยหลุดมือและตกลงไปในแม่น้ำ",
  str_homestory_805502001_24_dialog_content = "ผมขอเดานะ... ผมคิดว่ามันน่าจะเป็นเหรียญโบราณของชาวเคเลสไทต์นั่นแหละ",
  str_homestory_805502001_25_dialog_content = "หา... จ-จริงเหรอ?",
  str_homestory_805502001_26_dialog_content = "ที่จริง ฉันก็ยังไม่ได้ดูให้ชัด ๆ เลย...",
  str_homestory_805502001_27_dialog_content = "ถ้านั่นเป็นเรื่องจริง ฉันต้องขอโทษด้วยที่เสียมารยาท",
  str_homestory_805502001_28_dialog_content = "ขอโทษนะ!",
  str_homestory_805502001_29_dialog_content = "ไม่เป็นไรครับ ผมก็ไม่รู้ว่าเหรียญนั่นมาจากไหนเหมือนกัน",
  str_homestory_805502001_30_dialog_content = "ไว้ผมจะให้คุณดูตอนที่หาเจอนะ",
  str_homestory_805502001_31_dialog_content = "ขอบคุณมากนะ...PlayerName!",
  str_homestory_815701001_0_dialog_content = "ซานาเอะ...",
  str_homestory_815701001_1_dialog_content = "หวาาาาาา! คุณผู้นำทาง...",
  str_homestory_815701001_2_dialog_content = "ฉันแค่กำลังชื่นชมดอกไม้อยู่น่ะ<sprite=emo_huaduo size=60 />!",
  str_homestory_815701001_3_dialog_content = "ไม่ใช่เพราะเพิ่งหกล้มแถวนี้แล้วนั่งพักหรอกนะ...",
  str_homestory_815701001_4_dialog_content = "เธอหกล้มเหรอ? บาดเจ็บตรงไหนรึเปล่า?",
  str_homestory_815701001_5_dialog_content = "ฉันชินแล้วล่ะค่ะ... อ๊ะ เผลอบอกความจริงไปแล้วสินะ?",
  str_homestory_815701001_6_dialog_content = "ซานาเอะ... เธอนี่อ่านออกง่ายจังเลยนะ",
  str_homestory_815701001_7_dialog_content = "ได้โปรดอย่าไล่ฉันเพราะทำตัวซุ่มซ่ามเลยนะคะ...",
  str_homestory_815701001_8_dialog_content = "ฉันไม่ทำแบบนั้นหรอก แต่... เธอกำลังคิดอะไรอยู่เหรอ?",
  str_homestory_815701001_9_dialog_content = "ถ้ามีคำแนะนำเกี่ยวกับการสร้างสวนลอยฟ้าล่ะก็ บอกฉันได้เลยนะ",
  str_homestory_815701001_10_dialog_content = "เอ่อ... ไม่ใช่แบบนั้นหรอกค่ะ...",
  str_homestory_815701001_11_dialog_content = "ฉันไม่ได้กำลังจินตนาการถึงเหตุผลที่คุณสร้างแปลงดอกไม้เลยนะคะ!",
  str_homestory_815701001_12_dialog_content = "เอ่อ นี่มันน่าสงสัยสุด ๆ เลยนี่นา...",
  str_homestory_815701001_13_dialog_content = "หา?",
  str_homestory_815701001_14_dialog_content = "เรื่องที่คุณต้องการฝังความทรงจำ เพื่อรำลึกถึงคนที่คุณรัก...",
  str_homestory_815701001_15_dialog_content = "ฉันคงไม่มีทางรู้ได้เลย...",
  str_homestory_815701001_16_option_content = "คนที่ฉันรัก?",
  str_homestory_815701001_17_dialog_content = "ค่ะ! คนที่คุณบังเอิญพบเจอ...",
  str_homestory_815701001_18_dialog_content = "คนที่ยอมสละสิ่งผูกมัดทางโลกทุกอย่างไป เพื่อมาพบคุณ...",
  str_homestory_815701001_19_dialog_content = "คนที่ให้คำแนะนำเรื่องการผจญภัยของคุณในแอสตรา...",
  str_homestory_815701001_20_dialog_content = "โอ เธอจะต้องเป็นผู้หญิงที่ยอดเยี่ยมมากแน่ ๆ!",
  str_homestory_815701001_21_dialog_content = "ดอกไม้ในสวนแห่งนี้จะต้องเป็นดอกไม้ที่เธอชอบ ใช่มั้ยคะ?",
  str_homestory_815701001_22_option_content = "ฝังความทรงจำ?",
  str_homestory_815701001_23_dialog_content = "ใครบางคนที่ยอมทิ้งทุกอย่างไว้เบื้องหลัง เพื่อเดินทางมาพบคุณ...",
  str_homestory_815701001_24_dialog_content = "ใครบางคนที่คอยดูแลคุณในการเดินทางอยู่ข้างหลัง...",
  str_homestory_815701001_25_dialog_content = "แต่ตอนนี้พวกคุณสองคนไม่อาจพบกันได้อีก เพราะภาระทางโลกบางอย่าง",
  str_homestory_815701001_26_dialog_content = "ดังนั้น เพื่อแสดงว่าคุณคิดถึงเธอมากแค่ไหน...",
  str_homestory_815701001_27_dialog_content = "คุณก็เลยสร้างแปลงดอกไม้ที่เธอชอบในสวนแห่งนี้!",
  str_homestory_815701001_28_dialog_content = "ฉันไม่รู้ว่าเธอพูดเรื่องอะไรนะ...",
  str_homestory_815701001_29_dialog_content = "งั้นเหรอคะ...<sprite=emo_sikao size=60 />!",
  str_homestory_815701001_30_dialog_content = "ว่าแล้วเชียว ข้อมูลแบบนี้คงไม่เปิดเผยให้คนนอกอย่างฉันง่าย ๆ อยู่แล้วสินะ...",
  str_homestory_815701001_31_dialog_content = "ถ้าเธออยากรู้ว่าแปลงดอกไม้ตรงนี้มีไว้ทำอะไร...",
  str_homestory_815701001_32_dialog_content = "ฉันก็จะตอบว่า มันเป็นส่วนหนึ่งของการออกแบบภูมิทัศน์น่ะ",
  str_homestory_815701001_33_dialog_content = "การออกแบบภูมิทัศน์? เป็นคำศัพท์ที่ยากจังค่ะ...",
  str_homestory_815701001_34_dialog_content = "ไวซ์เป็นคนวาดแบบแปลนทางวิศวกรรมเก่งมาก ๆ เธอก็เลยให้คำแนะนำกับฉันมากมายตอนที่เราออกแบบสวนลอยฟ้า",
  str_homestory_815701001_35_dialog_content = "แล้วกาบริเอล นิคินิส กับโจลาก็มีความรู้เรื่องต้นไม้เป็นอย่างดี...",
  str_homestory_815701001_36_dialog_content = "ฉันก็เลยขอคำแนะนำจากพวกเขา ว่าควรจะปลูกอะไรสวนถึงจะดูดี",
  str_homestory_815701001_37_dialog_content = "ที่สวนลอยฟ้าเป็นอย่างทุกวันนี้ได้ ก็เพราะความพยายามของทุกคน",
  str_homestory_815701001_38_dialog_content = "ความพยายามของทุกคน...",
  str_homestory_815701001_39_dialog_content = "ใช่แล้ว! อีกอย่างนะ อย่าบอกว่าตัวเองเป็น \"คนนอก\" สิ ซานาเอะ",
  str_homestory_815701001_40_dialog_content = "เธอเป็นส่วนหนึ่งของเราแล้ว ตั้งแต่วินาทีแรกที่มาที่นี่!",
  str_homestory_815701001_41_dialog_content = "ฮึก... โฮ...",
  str_homestory_815701001_42_dialog_content = "เอ่อ อย่าร้องไห้สิ ฉันไม่ได้จะว่าอะไรเธอนะ...",
  str_homestory_815701001_43_dialog_content = "คุณเป็นคนดีจริง ๆ คุณผู้นำทาง...",
  str_homestory_815701001_44_dialog_content = "ฉันเองก็จะ... ช่วยคุณด้วยเหมือนกัน",
  str_homestory_815701001_45_dialog_content = "คิดออกแล้วค่ะ! จากนี้ไป โปรดให้ฉันเป็นคนดูแล \"แปลงดอกไม้แห่งรัก<sprite=emo_aixin size=60 />\" ด้วยเถอะค่ะ!",
  str_homestory_815601001_0_dialog_content = "ไม่อยากเชื่อสายตาตัวเองเลย!",
  str_homestory_815601001_1_dialog_content = "นีน่าขี่ม้าโยกงั้นเหรอ?",
  str_homestory_815601001_2_dialog_content = "ม้าโยก?",
  str_homestory_815601001_3_dialog_content = "ฉันนึกว่าเธอเกลียดของเล่นพวกนี้ซะอีก",
  str_homestory_815601001_4_dialog_content = "ต-แต่ฉันก็ไม่ได้บอกว่าชอบมันซักหน่อย...",
  str_homestory_815601001_5_dialog_content = "ฉันแค่เดินจนเหนื่อยน่ะ ก็เลยอยากนั่งพักซักหน่อย",
  str_homestory_815601001_6_dialog_content = "ฉันไม่มีทางสนใจของแบบนั้นเด็ดขาด",
  str_homestory_815601001_7_dialog_content = "ก็มีเหตุผลนะ...",
  str_homestory_815601001_8_dialog_content = "ประเด็นมันควรจะเป็น \"ฉันเดินจนเหนื่อย แล้วก็ไม่มีที่ให้นั่งพัก\" ไม่ใช่หรือไง?",
  str_homestory_815601001_9_option_content = "ขอโทษ",
  str_homestory_815601001_10_dialog_content = "โอ๊ะ... ขอโทษนะ!",
  str_homestory_815601001_11_dialog_content = "ให้ฉันวางม้านั่งหินเพิ่มแถว ๆ นี้ดีมั้ย?",
  str_homestory_815601001_12_dialog_content = "ม้านั่งหินเรอะ? ฮ่าฮ่าฮ่า ล้อกันเล่นรึเปล่า?",
  str_homestory_815601001_13_dialog_content = "ไม่มีใครอยากนั่งอะไรแข็ง ๆ แบบนั้นเหรอ จริงมั้ย?",
  str_homestory_815601001_14_dialog_content = "ถ้านายสนใจ...",
  str_homestory_815601001_15_dialog_content = "ฉันก็ช่วยออกแบบที่นั่งสวย ๆ และนั่งสบายสำหรับแขกผู้มาเยือนได้นะ",
  str_homestory_815601001_16_dialog_content = "ถ้านายอธิบายได้ว่าม้าไม้นั่นมันมีอะไรน่าสนุกนักหนา...",
  str_homestory_815601001_17_option_content = "ถามเรื่องอารมณ์ของเธอ",
  str_homestory_815601001_18_dialog_content = "ดูเหมือนเธอจะไปที่โน่นที่นี่มาเยอะเลยนะ นีน่า",
  str_homestory_815601001_19_dialog_content = "เธอคิดว่าที่นี่เป็นยังไงบ้าง?",
  str_homestory_815601001_20_dialog_content = "ในเมื่อเอ่ยปากถามมาแล้ว ก็อย่าหาว่าฉันใจร้ายล่ะ",
  str_homestory_815601001_21_dialog_content = "ที่นี่อยู่ห่างไกลความเจริญสุด ๆ!",
  str_homestory_815601001_22_dialog_content = "ก็จริงน่ะนะ...",
  str_homestory_815601001_23_dialog_content = "แต่วิวที่นี่สวยมาก เรียกว่าอยู่ในลิสต์สถานที่พักร้อนสุดโปรดของฉันได้เลยล่ะ",
  str_homestory_815601001_24_dialog_content = "รู้มั้ยว่าความเห็นของฉันจะส่งผลกับผู้คนมากมาย หากมันเอาไปตีพิมพ์ในหนังสือพิมพ์ของอัมบราตัน",
  str_homestory_815601001_25_dialog_content = "ฉันช่วยนายได้ แต่มีข้อแม้ว่า... นายจะต้องอธิบายมาก่อน ว่าม้าไม้นั่นมันน่าสนใจตรงไหน...",
  str_homestory_815601001_26_dialog_content = "นึกว่าเธอจะไม่สนใจม้าไม้ซะอีก",
  str_homestory_815601001_27_dialog_content = "... ฉันเปลี่ยนใจแล้ว",
  str_homestory_815601001_28_dialog_content = "การรู้ว่าทุกคนสนใจอะไรเป็นส่วนหนึ่งในงานของฉัน",
  str_homestory_815601001_29_dialog_content = "ที่นั่งที่ไม่มั่นคงมันจะโคลงเคลงเวลาขึ้นไปนั่ง",
  str_homestory_815601001_30_dialog_content = "นี่เธอไม่เคยเล่นม้าโยกมาก่อนเหรอ?",
  str_homestory_815601001_31_dialog_content = "ก็ต้องเคยอยู่แล้วสิ ทำไมล่ะ?",
  str_homestory_815601001_32_dialog_content = "แต่... เป้าหมายหลักของการเล่นม้าโยกก็คือได้โยกไปมาไงล่ะ",
  str_homestory_815601001_33_dialog_content = "อ๋อ เข้าใจแล้ว... อย่าเข้าใจผิดล่ะ! ฉันรู้เรื่องนั้นอยู่แล้ว!",
  str_homestory_815601001_34_dialog_content = "มันก็เป็นแค่ แค่บททดสอบสำหรับนายน่ะ",
  str_homestory_815601001_35_option_content = "เชื่อเธอ",
  str_homestory_815601001_36_dialog_content = "งั้นฉันก็คงสอบผ่านแล้วใช่มั้ย...",
  str_homestory_815601001_37_dialog_content = "ใช่! นายฉลาดกว่าที่เห็นนะ PlayerName ฮ่าฮ่า",
  str_homestory_815601001_38_option_content = "ไม่เชื่อเธอ",
  str_homestory_815601001_39_dialog_content = "ฉันไม่เชื่อหรอก",
  str_homestory_815601001_40_dialog_content = "PlayerName นี่งี่เง่าชะมัด! ฮึ่ม",
  str_homestory_815601001_41_dialog_content = "...",
  str_homestory_815601001_42_dialog_content = "แต่...",
  str_homestory_815601001_43_dialog_content = "ทำไมคนเราถึงต้องมานั่งม้าโยกล่ะ ขี่ม้าจริง ๆ ไปเลยไม่ดีกว่าเหรอ?",
  str_homestory_815601001_44_dialog_content = "ฉันก็ไม่รู้เหมือนกันแฮะ...",
  str_homestory_815601001_45_dialog_content = "แต่ม้าโยกมันก็มีความสนุกในแบบของมัน แล้วก็ปลอดภัยกว่าเยอะเลย...",
  str_homestory_815601001_46_dialog_content = "ฉันว่าไม่ใช่ทุกคนจะมีโอกาสได้ขี่ม้าจริง ๆ หรอกนะ",
  str_homestory_815601001_47_dialog_content = "หมายถึง... พวกเขาไม่มีเงินซื้อยังงั้นเหรอ?<sprite=emo_wuzui size=60 />",
  str_homestory_815601001_48_dialog_content = "ที่จริงฉันว่าบางคนก็ไม่น่าจะมีเงินซื้อม้าโยกด้วยซ้ำ",
  str_homestory_815601001_49_dialog_content = "...",
  str_homestory_815601001_50_dialog_content = "... ฉันตัดสินใจแล้ว!",
  str_homestory_815601001_51_dialog_content = "เรื่องอะไรเหรอ?",
  str_homestory_815601001_52_dialog_content = "ฉันอยากเรียนวิชางานไม้แล้วก็สร้างม้าโยกสนุก ๆ ให้ได้เยอะ ๆ...",
  str_homestory_815601001_53_dialog_content = "ฉันจะได้เอาไปแจกให้เด็ก ๆ ที่ไม่มีโอกาสได้เล่นยังไงล่ะ!",
  str_homestory_810401001_0_dialog_content = "ดอว์น?",
  str_homestory_810401001_1_dialog_content = "เสียงฝีเท้าแบบนี้...",
  str_homestory_810401001_2_dialog_content = "จะใช่ PlayerName มั้ยนะ?",
  str_homestory_810401001_3_dialog_content = "อ๊ะ! เธอจำเสียงฝีเท้าของฉันได้ด้วยเหรอ?",
  str_homestory_810401001_4_dialog_content = "ช่าย!<sprite=emo_yaosu size=60 />",
  str_homestory_810401001_5_dialog_content = "ที่นี่น่ะ มีเสียงต่าง ๆ มากมายกว่าบนโคลอสซัสเยอะเลยนะ...",
  str_homestory_810401001_6_dialog_content = "แต่ยังไงฉันก็แยกแยะเสียงของคนคุ้นเคยได้อยู่ดี",
  str_homestory_810401001_7_dialog_content = "เหมือนอย่าง PlayerName กับอีฟไง พวกเธอมีวิธีเดินที่ไม่เหมือนใคร",
  str_homestory_810401001_8_dialog_content = "วิธีเดินที่ไม่เหมือนใคร...",
  str_homestory_810401001_9_option_content = "ฉันเดินแบบไหน",
  str_homestory_810401001_10_dialog_content = "นายจะเร่งรีบอยู่ตลอด แต่กลับมีความระมัดระวังเมื่อเข้าหาฉัน",
  str_homestory_810401001_11_dialog_content = "ฉันอาจจะอธิบายไม่ค่อยชัดเจน...",
  str_homestory_810401001_12_dialog_content = "แต่ช่างเถอะ ฉันรู้ว่าเป็นนายก็แล้วกัน!",
  str_homestory_810401001_13_dialog_content = "อ๊ะ! อีกอย่างนะ...",
  str_homestory_810401001_14_dialog_content = "เวลานายเข้ามาใกล้ ฉันจะรู้สึกมีความสุข",
  str_homestory_810401001_15_dialog_content = "ความสุขแบบนี้แหละที่บอกฉันว่า PlayerName กำลังมาแล้ว",
  str_homestory_810401001_16_option_content = "อีฟเดินแบบไหน",
  str_homestory_810401001_17_dialog_content = "อีฟมีเสียงฝีเท้าที่น่ารักสุด ๆ!",
  str_homestory_810401001_18_dialog_content = "เสียงฝีเท้า ...น่ารัก... ?",
  str_homestory_810401001_19_dialog_content = "ใช่แล้ว! ทุกอย่างเกี่ยวกับอีฟมันน่ารักไปหมด<sprite=emo_aixin size=60 />",
  str_homestory_810401001_20_dialog_content = "เอ่อ...",
  str_homestory_810401001_21_dialog_content = "คืองี้ ฉันอธิบายแบบนี้ดีกว่า ร่างกายของอีฟจะพิเศษหน่อย ๆ...",
  str_homestory_810401001_22_dialog_content = "เวลาเธอเดินแทบจะไม่ส่งเสียงอะไรเลย",
  str_homestory_810401001_23_dialog_content = "แต่พอเธอเข้ามาใกล้ ฉันจะรู้สึกมีความสุข",
  str_homestory_810401001_24_dialog_content = "ความสุขแบบนี้แหละที่บอกฉันว่าอีฟกำลังมาแล้ว",
  str_homestory_810401001_25_dialog_content = "แบบนี้น่ะเอง...",
  str_homestory_810401001_26_dialog_content = "เธอนี่น่าทึ่งจริง ๆ นะ!",
  str_homestory_810401001_27_dialog_content = "อาจเป็นเพราะว่าฉันมองไม่เห็น การได้ยินของฉันจึงไวมากน่ะ",
  str_homestory_810401001_28_dialog_content = "เอ๊ะ! ว่าแต่...",
  str_homestory_810401001_29_dialog_content = "ซินซาล่ะ เป็นยังไง?",
  str_homestory_810401001_30_dialog_content = "เธอสนิทกับเขาดีนี่นา เสียงฝีเท้าของซินซาเป็นยังไงเหรอ?",
  str_homestory_810401001_31_dialog_content = "อ้อ ถ้าเป็นตานั่น ฉันแยกแยะได้ง่ายมาก",
  str_homestory_810401001_32_dialog_content = "ยังไง?",
  str_homestory_810401001_33_dialog_content = "เขาน่ะ ตัวเหม็นฉึ่ง",
  str_homestory_810401001_34_dialog_content = "...?",
  str_homestory_810401001_35_dialog_content = "เขาไปไหนมาไหนอยู่ตลอด... น่าจะเหงื่อออกมากแหละนะ",
  str_homestory_810401001_36_dialog_content = "อย่างนี้นี่เอง...",
  str_homestory_810401001_37_dialog_content = "แน่นอนว่าเขาไม่ใช่ผู้ชายที่ตัวเหม็นสุดในเรดีเซล เวรนช์หรอก...",
  str_homestory_810401001_38_dialog_content = "แต่ยังไงก็ตัวเหม็นกว่านายกับอีฟล่ะนะ",
  str_homestory_810401001_39_dialog_content = "ฉันดีใจที่นายไม่ได้มีกลิ่นแบบเขานะ ผู้นำทาง",
  str_homestory_810401001_40_dialog_content = "เอ่อ... ขอบคุณนะ...",
  str_homestory_810401001_41_dialog_content = "แต่ทำไม... ฉันไม่ได้กลิ่นของซินซาเลยล่ะ?",
  str_homestory_810401001_42_dialog_content = "ไม่ได้กลิ่นเหรอ?",
  str_homestory_810401001_43_dialog_content = "หรือว่าฉันเซ็งที่อีฟใช้เวลากับเขามากเกินไป...<sprite=emo_sikao size=60 />",
  str_homestory_810401001_44_dialog_content = "... ก็เลยสร้างกลิ่นนั้นขึ้นมา?",
  str_homestory_810401001_45_dialog_content = "... ต้องเป็นแบบนั้นแน่ ๆ!",
  str_homestory_810401001_46_dialog_content = "... ยังไงก็เถอะ! ฉันมั่นใจว่าเขาน่ะตัวเหม็น",
  str_homestory_810401001_47_dialog_content = "เหม็น เหม็น ซินซาตัวเหม็น<sprite=emo_kulou size=60 />!",
  str_homestory_809001001_0_dialog_content = "บาร์บาร่า?",
  str_homestory_809001001_1_dialog_content = "รักแท้มันคืออะไร? ♪",
  str_homestory_809001001_2_dialog_content = "<sprite=emo_aixin size=60 />เกิดขึ้นได้ เมื่อเชื้อเพลิงเผาผลาญ ♪",
  str_homestory_809001001_3_dialog_content = "โว้ โววว รักแต่เธอ เธอคนเดียว ♪",
