  str_homestory_803304001_1_dialog_content = "นี่ รู้ได้ยังไงว่าฉันตามหานายอยู่?",
  str_homestory_803304001_2_dialog_content = "ฉันเจอสิ่งที่น่าสนใจมาล่ะ!<sprite=emo_yaosu size=60 />",
  str_homestory_803304001_3_dialog_content = "คราวนี้คงไม่ใช่แมงมุมยักษ์หรือจิ้งหรีดเต้นระบำอีกแล้วใช่มั้ย?",
  str_homestory_803304001_4_dialog_content = "ไม่ใช่หรอกน่า มันเป็นพิมพ์เขียวสำหรับเฟอร์นิเจอร์ใหม่!",
  str_homestory_803304001_5_dialog_content = "แต่มันอยู่ใต้น้ำ ดึงขึ้นมายากมากเลย",
  str_homestory_803304001_6_dialog_content = "ได้ เดี๋ยวฉันจัดการเอง เรื่องนี้ฉันถนัด",
  str_homestory_803304001_7_dialog_content = "มันอยู่แถว ๆ นั้น! ฉันจะพาไป!",
  str_homestory_809301001_0_dialog_content = "มันดู...",
  str_homestory_809301001_1_dialog_content = "มีอะไร... ให้ช่วย... รึเปล่าครับ?",
  str_homestory_809301001_2_dialog_content = "นายเติบโตขึ้นกว่าตอนที่เราพบกันครั้งล่าสุดนะ นายก็รู้ว่าฉันต้องการบางอย่างจากนาย",
  str_homestory_809301001_3_dialog_content = "ผมรู้สึกขนหัวลุกยังกับมีคนจ้องมองอยู่...",
  str_homestory_809301001_4_dialog_content = "แล้วพอมองขึ้นไป คุณก็จ้องมองผมอยู่ตรงนี้",
  str_homestory_809301001_5_dialog_content = "\"มองขึ้นไป\"? งั้นนายคงไม่ได้เติบโตมากเท่าที่ฉันคิดสินะ",
  str_homestory_809301001_6_option_content = "ผมสูงขึ้นแล้ว!",
  str_homestory_809301001_7_dialog_content = "จริงเหรอ? ทำไมดูไม่ออกเลยล่ะ? ไปห้องทดลองของฉันมั้ยจ๊ะ?",
  str_homestory_809301001_8_dialog_content = "ฉันจะได้ชำแหละดูว่ากระดูกของนายโตขึ้นรึเปล่า",
  str_homestory_809301001_9_option_content = "ใช่...",
  str_homestory_809301001_10_dialog_content = "ยอมแพ้ง่ายจัง ฉันช่วยนายดีกว่า ไปห้องทดลองของฉันมั้ยจ๊ะ?",
  str_homestory_809301001_11_dialog_content = "ฉันจะได้ชำแหละดูว่ากระดูกของนายโตขึ้นได้อีกรึเปล่า",
  str_homestory_809301001_12_dialog_content = "อ-เอ่อ ไม่จำเป็นมั้งครับ...",
  str_homestory_809301001_13_dialog_content = "ไม่ต้องห่วงหรอกนะ แค่ให้ฉันดูคร่าว ๆ แล้วฉันจะวางแผนยืดความสูงให้",
  str_homestory_809301001_14_dialog_content = "ไม่เป็นไรครับ ปล่อยให้มันเป็นไปตามธรรมชาติเถอะ",
  str_homestory_809301001_15_dialog_content = "ธรรมชาติงั้นเหรอ? นี่นายล้อเล่นรึเปล่า?",
  str_homestory_809301001_16_dialog_content = "ฉันบอกได้เลยว่าต้นไม้ในสวนลอยฟ้าเนี่ย ส่วนใหญ่ก็ดัดแปลงพันธุกรรมมาทั้งนั้น",
  str_homestory_809301001_17_dialog_content = "และวิธีการก็คือ...",
  str_homestory_809301001_18_dialog_content = "นำเมล็ดพืชต่าง ๆ มาประกบกันเป็นพันธุ์ใหม่ ที่มีเอกลักษณ์เฉพาะตัว",
  str_homestory_809301001_19_dialog_content = "แค่เห็นก็บอกได้เลยเหรอ?",
  str_homestory_809301001_20_dialog_content = "นายลืมแล้วหรือไง ว่าฉันเป็นเจ้าหน้าที่วิทยาการจากอิลลูมินา ที่เชี่ยวชาญด้านเทคโนโลยีชีวภาพ?",
  str_homestory_809301001_21_dialog_content = "ฉันทำการทดลองทางวิศวกรรมชีวภาพแบบนี้มานับไม่ถ้วนแล้ว",
  str_homestory_809301001_22_dialog_content = "แต่ไม่ได้คาดหวังว่านายจะต้องชำนาญเทคโนโลยีพวกนี้หรอกนะ",
  str_homestory_809301001_23_dialog_content = "ผมก็แค่วิ่งวุ่นไปทั่วน่ะ ไม่ได้ชำนาญอะไรเลย",
  str_homestory_809301001_24_dialog_content = "ใช่ ฉันก็ว่างั้นแหละ",
  str_homestory_809301001_25_dialog_content = "...",
  str_homestory_809301001_26_dialog_content = "นายไม่มีทางประสบความสำเร็จแบบนั้นได้ ถ้าไม่ล้มเหลวก่อน 99 ครั้ง",
  str_homestory_809301001_27_dialog_content = "นั่นคือสิ่งที่ฉันเรียนรู้จากความพยายามของตัวเอง ส่วนนาย...",
  str_homestory_809301001_28_dialog_content = "ถ้าอยากได้เมล็ดพันธุ์ที่หายากสุด ๆ ก็ต้องทำนั่นทำนี่",
  str_homestory_809301001_29_dialog_content = "\"ทำนั่นทำนี่\"? หมายถึงอะไรเหรอครับ?",
  str_homestory_809301001_30_dialog_content = "พูดไปก็เข้าใจยากถ้านายไม่มีพื้นฐานทางวิทยาศาสตร์ ไว้ค่อยคุยกันวันหลัง",
  str_homestory_809301001_31_dialog_content = "แต่ เราทำตอนนี้ก็ได้นะ",
  str_homestory_809301001_32_dialog_content = "ตอนนี้เนี่ยนะ? ขอฉันงีบก่อนเถอะ",
  str_homestory_809301001_33_dialog_content = "...",
  str_homestory_809301001_34_dialog_content = "โอ้ เดี๋ยวก่อน ฉันเกือบลืมสิ่งที่ว่าจะถามนาย",
  str_homestory_809301001_35_dialog_content = "ช่วยย้ายห้องฉันไปอยู่หอพักที่มีสาวสวยเยอะ ๆ หน่อยได้มั้ย?",
  str_homestory_809301001_36_option_content = "ตกลง",
  str_homestory_809301001_37_dialog_content = "ได้ แต่คุณต้องคุยกับทุกคนก่อนนะ",
  str_homestory_809301001_38_option_content = "ปฏิเสธ",
  str_homestory_809301001_39_dialog_content = "ผมละเมิดสิทธิการเข้าพักตามอัธยาศัยของใครไม่ได้หรอกครับ",
  str_homestory_809301001_40_dialog_content = "แต่ถ้าคุณตกลงกับพวกเขาได้ก็ไม่มีปัญหา",
  str_homestory_809301001_41_dialog_content = "นั่นล่ะปัญหา",
  str_homestory_809301001_42_dialog_content = "แต่ก็น่าลอง ถ้าไม่สำเร็จ ก็ลองไป 100 รอบ",
  str_homestory_809301001_43_dialog_content = "(เอาทัศนคติแบบนั้นมาใช้กับเรื่องนี้ด้วยเหรอ?)",
  str_homestory_815702001_0_dialog_content = "นั่นเธอจ้องอะไรอยู่น่ะ?",
  str_homestory_815702001_1_dialog_content = "อ๊าาาาาา!",
  str_homestory_815702001_2_dialog_content = "โทษทีนะ ฉันทำให้เธอตกใจอีกแล้วเหรอ?",
  str_homestory_815702001_3_dialog_content = "(แล้วทำไมฉันต้องพูดว่า \"อีกแล้ว\" ด้วยเล่า?)",
  str_homestory_815702001_4_dialog_content = "เปล่าค่ะ ฉันแค่กำลังคิดอะไรเพลิน ๆ อยู่",
  str_homestory_815702001_5_dialog_content = "ก็เลยไม่เห็นว่าคุณมาที่นี่",
  str_homestory_815702001_6_dialog_content = "ฉันต่างหากที่ควรเป็นฝ่ายขอโทษ",
  str_homestory_815702001_7_dialog_content = "ทุกอย่างเรียบร้อยดี อย่ากังวลไปเลย",
  str_homestory_815702001_8_dialog_content = "นี่เธอเพิ่งเดินมาจากแม่น้ำใช่มั้ย? อย่าบอกนะว่า เธอคิดจะ...",
  str_homestory_815702001_9_option_content = "ตกปลา?",
  str_homestory_815702001_10_dialog_content = "ตกปลา... มันต้องใช้อุปกรณ์แพง ๆ ไม่ใช่เหรอ?",
  str_homestory_815702001_11_dialog_content = "ความคิดแบบนั้น เอ่อ ไม่เคยอยู่ในสมองฉันหรอก...",
  str_homestory_815702001_12_option_content = "ว่ายน้ำ?",
  str_homestory_815702001_13_dialog_content = "ว่ายน้ำ... มันต้องใส่ชุดรัดรูปไม่ใช่เหรอ?",
  str_homestory_815702001_14_dialog_content = "แบบนั้นฉันอายน่ะค่ะ",
  str_homestory_815702001_15_dialog_content = "ที่จริงคือ ฉันกำลังคิดว่า...",
  str_homestory_815702001_16_dialog_content = "ชาวนาในอีราเวลจะทำงานหนักเหมือนที่เกาะเมฆารึเปล่านะ?",
  str_homestory_815702001_17_dialog_content = "ไม่แน่ใจเหมือนกัน แต่ฉันคิดว่า ไม่ว่าจะเป็นที่อีราเวลหรือเกาะเมฆา...",
  str_homestory_815702001_18_dialog_content = "พวกเขาน่าจะมีความสุขเมื่อได้ผลผลิตที่อุดมสมบูรณ์",
  str_homestory_815702001_19_dialog_content = "ว่าแต่ ทำไมถึงพูดเรื่องนี้ล่ะ?",
  str_homestory_815702001_20_dialog_content = "เมื่อกี้ฉันเจอวัตถุแวววาวที่ริมแม่น้ำ มันดูเหมือนจะเป็นเหรียญ<sprite=emo_baiyebi size=60 />",
  str_homestory_815702001_21_dialog_content = "เหรียญหมายถึงการค้า การค้าหมายถึงอาหาร และอาหารหมายถึง... ชาวนา!",
  str_homestory_815702001_22_dialog_content = "แล้วเธอก็วางทั้งหมดไว้อย่างนั้นเหรอ?",
  str_homestory_815702001_23_dialog_content = "โอ๊ะ ได้โปรดอย่าอารมณ์เสียเลยนะคะ!",
  str_homestory_815702001_24_dialog_content = "ฉันไม่เคยคิดจะเก็บเหรียญไว้ใช้เองเลย",
  str_homestory_815702001_25_dialog_content = "ฉันจะให้เหรียญคุณเดี๋ยวนี้..",
  str_homestory_815702001_26_dialog_content = "ไม่เป็นไร ใจเย็น ๆ",
  str_homestory_815702001_27_dialog_content = "ฉันหาก่อนนะว่าวางไว้ที่ไหน...",
  str_homestory_815702001_28_dialog_content = "มันหายไปแล้ว...",
  str_homestory_815702001_29_dialog_content = "อ๊ะ!",
  str_homestory_815702001_30_dialog_content = "มีอะไรเหรอ?",
  str_homestory_815702001_31_dialog_content = "ฉันจำได้ว่าได้ยินเสียงน้ำกระเซ็นตอนที่เดินออกจากฝั่งมา",
  str_homestory_815702001_32_dialog_content = "มันต้องตกน้ำไปแล้วแน่เลย!",
  str_homestory_815702001_33_dialog_content = "ไม่เป็นไร ฉันจะเก็บขึ้นมาก็แล้วกัน",
  str_homestory_815702001_34_dialog_content = "โอ๊ะ จริงเหรอ? ขอบคุณค่ะ!",
  str_homestory_815602001_0_dialog_content = "พวกเธอกำลังตามหาอะไรอยู่เหรอ?",
  str_homestory_815602001_1_dialog_content = "นี่ มานี่เร็ว!",
  str_homestory_815602001_2_dialog_content = "นีน่า?",
  str_homestory_815602001_3_dialog_content = "ถ้าฉันเข้าใจไม่ผิด เธอกำลังหาอะไรบางอย่างอยู่ใช่ไหม",
  str_homestory_815602001_4_dialog_content = "ใช่แล้ว",
  str_homestory_815602001_5_dialog_content = "นายเห็นอะไรกลม ๆ เล็ก ๆ บ้างไหม?",
  str_homestory_815602001_6_dialog_content = "ช่วยขยายความอีกนิดได้ไหม?",
  str_homestory_815602001_7_dialog_content = "อืม... แบบนี้น่ะ",
  str_homestory_815602001_8_dialog_content = "ฉันไม่เคยเห็นอะไรที่มีลวดลายแบบนั้นมาก่อนเลย",
  str_homestory_815602001_9_dialog_content = "ฉันถึงได้กำมือไว้แน่นเลยไงล่ะ!",
  str_homestory_815602001_10_dialog_content = "แต่ว่า... มันดันหลุดมือแล้วร่วงลงน้ำไปตอนที่ฉันเผลอขยับมือ",
  str_homestory_815602001_11_dialog_content = "เดี๋ยวก่อน ทำไมฉันรู้สึกว่า เธอกำลังพูดถึง—",
  str_homestory_815602001_12_dialog_content = "—ไม่ ๆ นายนั่นแหละเดี๋ยวก่อน!",
  str_homestory_815602001_13_dialog_content = "จากนั้นฉันก็เห็นว่าที่ฝ่ามือของฉันมีลวดลายแปลก ๆ!",
  str_homestory_815602001_14_option_content = "ลูมินากลายพันธุ์เหรอ?",
  str_homestory_815602001_15_dialog_content = "นี่นายอ่านนิยายแฟนตาซีมากไปรึเปล่า?",
  str_homestory_815602001_16_option_content = "นีน่าจะแปลงร่าง!",
  str_homestory_815602001_17_dialog_content = "หมายความว่าไง",
  str_homestory_815602001_18_dialog_content = "คือ \"สิ่งนั้น\" น่ะมีรูปร่างและลวดลายที่พิเศษ!",
  str_homestory_815602001_19_dialog_content = "นั่นแหละ มันก็เลยติดอยู่ที่ฝ่ามือของฉัน",
  str_homestory_815602001_20_dialog_content = "แต่ลวดลายที่ฝ่ามือนี้มันก็สวยแปลก ๆ อยู่นะ...",
  str_homestory_815602001_21_dialog_content = "ลองคิดดูสิ ถ้าฉันออกแบบเสื้อผ้าตามแบบลวดลายนี้...",
  str_homestory_815602001_22_dialog_content = "ไม่ได้แล้ว ต้องหาเหรียญนั่นให้เจอ!",
  str_homestory_815602001_23_dialog_content = "ว่าแล้วเชียว ว่าต้องเป็นเหรียญ",
  str_homestory_815602001_24_dialog_content = "เดี๋ยวช่วยหาให้นะ",
  str_homestory_815602001_25_dialog_content = "ถูกต้อง ขอบคุณมาก... เอ๊ะ เดี๋ยวนะ!<sprite=emo_wuzui size=60 />",
  str_homestory_815602001_26_dialog_content = "ฉันเจอเหรียญนั่นที่สวนลอยฟ้า ดังนั้น... ตามหลักแล้ว มันต้องเป็นของนายสิใช่ไหม?",
  str_homestory_815602001_27_dialog_content = "ดังนั้น ถ้าฉันยืมจากนายมาศึกษาดู...",
  str_homestory_815602001_28_dialog_content = "ไม่มีปัญหา แต่เราต้องหาให้เจอก่อน",
  str_homestory_815602001_29_dialog_content = "ฉันแปลกใจจังที่นายไม่ว่าอะไร",
  str_homestory_815602001_30_dialog_content = "อะแฮ่ม... มันไม่ใช่ว่าฉันต้องเอามาศึกษา \"จริง ๆ\" หรอกนะ...",
  str_homestory_815602001_31_dialog_content = "แค่เป็นแรงบันดาลใจออกแบบเสื้อผ้าเฉย ๆ น่ะ!",
  str_homestory_815602001_32_dialog_content = "นายเข้าใจใช่ไหม?",
  str_homestory_815602001_33_dialog_content = "เข้าใจ ๆ",
  str_homestory_815602001_34_dialog_content = "ฮึ่ม! ดีใจที่ได้ยินแบบนั้นนะ",
  str_homestory_812601001_0_dialog_content = "คิดอะไรอยู่เหรอ?",
  str_homestory_812601001_1_dialog_content = "เบเธล?",
  str_homestory_812601001_2_dialog_content = "ท่าทางเธอครุ่นคิดอะไรหนักเลยนะ...",
  str_homestory_812601001_3_dialog_content = "จุ๊ ๆ...<sprite=emo_chidai size=60 />",
  str_homestory_812601001_4_dialog_content = "ฉันเพิ่งเขียนถ้อยแถลงสำหรับกิลด์เสร็จ ฉันกำลังคิดอะไรบางอย่างอยู่",
  str_homestory_812601001_5_dialog_content = "คิดอะไรอยู่เหรอ?",
  str_homestory_812601001_6_dialog_content = "ละครใหม่ของฉันน่ะ!",
  str_homestory_812601001_7_dialog_content = "อืม งั้นถามเลยแล้วกันนะ",
  str_homestory_812601001_8_dialog_content = "เอาสิ ถ้าช่วยได้นะ",
  str_homestory_812601001_9_dialog_content = "อะแฮ่ม... ฟังนะ เรื่องราวมันเป็นแบบนี้...",
  str_homestory_812601001_10_dialog_content = "ตัวเอกผู้ชายกับผู้หญิงมาที่แม่น้ำกัน...",
  str_homestory_812601001_11_dialog_content = "แล้วจู่ ๆ ผ้าพันคอของผู้หญิงก็ปลิวตกน้ำไป!",
  str_homestory_812601001_12_dialog_content = "คำถามมีอยู่ว่า ผู้หญิงหรือผู้ชายที่ควรเป็นคนไปเก็บ?",
  str_homestory_812601001_13_option_content = "ตัวเอกผู้หญิง",
  str_homestory_812601001_14_dialog_content = "อืมม...",
  str_homestory_812601001_15_dialog_content = "ก็ใช่ นั่นจะแสดงให้เห็นว่าเธอเป็นคนพึ่งพาตัวเองได้และมีความสามารถมาก",
  str_homestory_812601001_16_option_content = "ตัวเอกผู้ชาย",
  str_homestory_812601001_17_dialog_content = "อืมม...",
  str_homestory_812601001_18_dialog_content = "แบบนั้นก็จะดำเนินเรื่องต่อไปได้ดีเลย แล้วจะได้พูดคุยกันเรื่องผ้าพันคอด้วย!",
  str_homestory_812601001_19_dialog_content = "ตกลง ได้การละ!",
  str_homestory_812601001_20_dialog_content = "ฉันจะเขียนไปตามนี้เลย!<sprite=emo_yaosu size=60 />",
  str_homestory_812601001_21_dialog_content = "ทำไมเธอถึงเขียนพลอตเรื่องแบบนั้นล่ะ?",
  str_homestory_812601001_22_dialog_content = "เพราะเมื่อกี้ฉันเห็นอะไรตกน้ำไปน่ะสิ",
  str_homestory_812601001_23_dialog_content = "ก็เลยคิดดูว่า มันอาจเป็นพลอตเรื่องที่ดีได้...",
  str_homestory_812601001_24_dialog_content = "ว่าแต่... อะไรตกน้ำไปเหรอ?",
  str_homestory_812601001_25_dialog_content = "ฉันดูไม่ทัน อะไรกลม ๆ เล็ก ๆ นี่แหละ<sprite=emo_sikao size=60 />",
  str_homestory_812601001_26_dialog_content = "กลม ๆ เล็ก ๆ...",
  str_homestory_812601001_27_dialog_content = "ฉันรู้แล้วว่าคืออะไร",
  str_homestory_816401001_0_dialog_content = "คาร์ลีน?",
  str_homestory_816401001_1_dialog_content = "PlayerName?",
  str_homestory_816401001_2_dialog_content = "ทำอะไรอยู่เหรอ คาร์ลีน?",
  str_homestory_816401001_3_dialog_content = "ฉัน... กำลังคิดเรื่องบางอย่างอยู่น่ะ",
  str_homestory_816401001_4_dialog_content = "มีอะไรรึเปล่า? เธอดู... ไม่ร่าเริงเลย",
  str_homestory_816401001_5_dialog_content = "ไม่ร่าเริงเหรอ? ก็เพราะว่า...",
  str_homestory_816401001_6_dialog_content = "ช่วงนี้ลูโมโพลิสต้องเผชิญกับภัยธรรมชาติหลายครั้งน่ะสิ",
  str_homestory_816401001_7_dialog_content = "เสียใจด้วยนะ...",
  str_homestory_816401001_8_dialog_content = "แล้วตอนนี้ที่เมืองเป็นยังไงบ้าง? มีอะไรที่ฉันพอจะช่วยได้รึเปล่า?",
  str_homestory_816401001_9_dialog_content = "ขอบคุณที่เป็นห่วงนะ PlayerName",
  str_homestory_816401001_10_dialog_content = "ตอนนี้เรากำลังสรุปจำนวนผู้เสียชีวิตและมูลค่าทรัพย์สินที่เสียหายอย่างเป็นทางการอยู่",
  str_homestory_816401001_11_dialog_content = "นอกจากเก็บกู้ร่างผู้เสียชีวิตส่งคืนให้ครอบครัวแล้ว...",
  str_homestory_816401001_12_dialog_content = "ฉันก็ไม่รู้ว่าตัวเองจะทำอะไรได้อีก เพื่อบรรเทาความเจ็บปวดของพวกเขา",
  str_homestory_816401001_13_dialog_content = "ฉันเข้าใจว่าเธอรู้สึกยังไงนะ คาร์ลีน",
  str_homestory_816401001_14_dialog_content = "ฟู่... <sprite=emo_tanqi size=60 />",
  str_homestory_816401001_15_dialog_content = "พอได้พูดเรื่องที่ติดค้างอยู่ ฉันก็รู้สึกปลอดโปร่งขึ้นบ้าง",
  str_homestory_816401001_16_dialog_content = "เธอกำลังคิดหาทางหลีกเลี่ยงภัยพิบัติในอนาคตอยู่เหรอ?",
  str_homestory_816401001_17_dialog_content = "ไม่ใช่หรอก",
  str_homestory_816401001_18_dialog_content = "มนุษย์ที่ต่ำต้อยอย่างเราไม่อาจต่อกรอะไรกับธรรมชาติได้เลย",
  str_homestory_816401001_19_dialog_content = "ฉันได้แต่ภาวนาอย่างเงียบ ๆ เพื่อยืนยันอะไรบางอย่างกับตัวเอง...",
  str_homestory_816401001_20_option_content = "ศรัทธาของเธอน่ะเหรอ?",
  str_homestory_816401001_21_dialog_content = "อืม...",
  str_homestory_816401001_22_option_content = "ผลที่ได้จากการภาวนาน่ะเหรอ?",
  str_homestory_816401001_23_dialog_content = "จะพูดยังไงดีล่ะ...",
  str_homestory_816401001_24_dialog_content = "ฉันแค่อยากจะยืนยันว่า การภาวนาจะยังมอบความสบายใจที่ฉันแสวงหาได้อยู่เหมือนเดิมหรือเปล่า",
  str_homestory_816401001_25_dialog_content = "เข้าใจแล้ว...",
  str_homestory_816401001_26_dialog_content = "เป็นเรื่องธรรมดาที่เราจะกลัว \"ความไม่จีรัง\"",
  str_homestory_816401001_27_dialog_content = "และเราก็แก้ไขมันไม่ได้ ทำได้แค่ปล่อยให้มันเป็นไป",
  str_homestory_816401001_28_dialog_content = "นั่นทำให้เธอไม่สบายใจใช่มั้ย?",
  str_homestory_816401001_29_dialog_content = "ใช่",
  str_homestory_816401001_30_dialog_content = "ฉันสวดภาวนาทุกครั้งที่ตัวเองรู้สึกพ่ายแพ้",
  str_homestory_816401001_31_dialog_content = "และขณะเดียวกัน ฉันก็ครุ่นคิดว่าจริง ๆ แล้วการภาวนามันให้อะไรกับฉันบ้าง",
  str_homestory_816401001_32_dialog_content = "หลังจากคิดใคร่ครวญมากมาย ฉันก็ได้ข้อสรุปว่า มันทำให้ฉันมีแรงใจ...",
  str_homestory_816401001_33_dialog_content = "และมีความมุ่งมั่นที่จะก้าวต่อไป",
  str_homestory_816401001_34_dialog_content = "ก็จริงนะ",
  str_homestory_816401001_35_dialog_content = "คำภาวนาควรช่วยเหลือเธอในช่วงเวลาอันหม่นหมองแบบนี้",
  str_homestory_816401001_36_dialog_content = "อืม... แล้วในที่สุดฉันก็เข้าใจความจริงบางอย่าง",
  str_homestory_816401001_37_dialog_content = "ทำไมเราถึงต้องสร้างเทพเจ้าให้กับทุกสิ่งทุกอย่างด้วย?",
  str_homestory_816401001_38_dialog_content = "นั่นก็เพราะว่าเรามีคำถามเกี่ยวกับโลกใบนี้มากมายเกินไป แต่แทบจะไม่มีคำตอบเลย",
  str_homestory_816401001_39_dialog_content = "การภาวนาก็คือการพบกันครึ่งทาง <sprite=emo_sikao size=60 />",
  str_homestory_816401001_40_dialog_content = "ถึงจะไม่อาจแก้ปัญหาหรือให้คำตอบใด ๆ",
  str_homestory_816401001_41_dialog_content = "แต่ก็นำความสงบมาสู่จิตใจ และช่วยให้เราลุกขึ้นยืนได้อีกครั้ง",
  str_homestory_816401001_42_dialog_content = "ใช่... พวกเขาช่วยได้เยอะจริง ๆ",
  str_homestory_816401001_43_dialog_content = "คราวหน้าฉันน่าจะลองสวดภาวนาดูบ้าง",
  str_homestory_816401001_44_dialog_content = "เอาสิ แล้วมาเล่าความรู้สึกของนายให้ฉันฟังบ้างนะ",
  str_homestory_811101001_0_dialog_content = "เบริล...",
  str_homestory_811101001_1_dialog_content = "...",
  str_homestory_811101001_2_dialog_content = "เบริล!",
  str_homestory_811101001_3_dialog_content = "หืม? มีอะไรเหรอ?",
  str_homestory_811101001_4_dialog_content = "ฉันเห็นเธอยืนมองแม่น้ำ มีอะไรไม่สบายใจรึเปล่า?",
  str_homestory_811101001_5_dialog_content = "คุณเป็นห่วงฉันเหรอคะ?",
  str_homestory_811101001_6_option_content = "ใช่",
  str_homestory_811101001_7_dialog_content = "คุณคิดว่าฉันไม่สบายใจเพราะว่ายืนอยู่ริมแม่น้ำ อย่างนั้นเหรอ? <sprite=emo_wuzui size=60 />",
  str_homestory_811101001_8_dialog_content = "เอ่อ ไม่ใช่แบบนั้นหรอก",
  str_homestory_811101001_9_dialog_content = "ฉันก็มาเดินเล่นริมแม่น้ำเหมือนกัน อย่างที่เห็น วันนี้อากาศดีใช่มั้ยล่ะ?",
  str_homestory_811101001_10_dialog_content = "คุณทำตัวแปลกจังแฮะ",
  str_homestory_811101001_11_option_content = "ไม่ใช่แบบนั้นนะ",
  str_homestory_811101001_12_dialog_content = "คือ ฉันไม่รู้ว่าเธอทำอะไรอยู่น่ะ เพราะเห็นเธอยืนอยู่นานมาก ๆ",
  str_homestory_811101001_13_dialog_content = "ถ้าฉันมาที่แม่น้ำ ปกติถ้าไม่เดินเล่นก็จะตกปลา แต่คงไม่ยืนเฉย ๆ แบบนี้",
  str_homestory_811101001_14_dialog_content = "นั่นแหละ... ฉันก็เลยอยากรู้ว่าเธอทำอะไรอยู่?",
  str_homestory_811101001_15_dialog_content = "ฉันกำลังคิดเรื่องคริสตัลกับสวนลอยฟ้าอยู่น่ะค่ะ",
  str_homestory_811101001_16_dialog_content = "คริสตัล...",
  str_homestory_811101001_17_dialog_content = "ค่ะ ไวซ์บอกว่าคุณเครียดเรื่องการพัฒนาสวนลอยฟ้า",
  str_homestory_811101001_18_dialog_content = "แล้วก็บอกว่าคุณไม่ค่อยมีเงินทุน <sprite=emo_baiyebi size=60 /> ฉันก็เลยคิดหาวิธีจะทำให้คุณรวยอยู่น่ะ",
  str_homestory_811101001_19_dialog_content = "แล้วฉันก็นึกถึงพลังคริสตัลของตัวเอง",
  str_homestory_811101001_20_dialog_content = "ถ้าฉันเปลี่ยนหินในสวนลอยฟ้าให้เป็นคริสตัล แล้วขายให้ร้านอัญมณีในอัมบราตัน...",
  str_homestory_811101001_21_dialog_content = "มันจะเป็นไปได้จริง ๆ เหรอ?",
  str_homestory_811101001_22_dialog_content = "ค่ะ ฉันรู้มาว่าถ้าทำให้คริสตัลแตกเป็นเศษผลึกแล้ว มันจะขายได้ราคาดีมาก",
  str_homestory_811101001_23_dialog_content = "จ-จริงเหรอ?",
  str_homestory_811101001_24_dialog_content = "ล้อเล่นหรอกค่ะ...",
  str_homestory_811101001_25_dialog_content = "ว้าว! เดี๋ยวนี้เธอก็มีมุกตลกเหมือนกันนะเนี่ย!",
  str_homestory_811101001_26_dialog_content = "ฉันอาจจะเปลี่ยนไปหลังจากได้มาที่นี่ค่ะ สวนลอยฟ้าเป็นที่ที่ผ่อนคลายจิตใจจริง ๆ",
  str_homestory_811101001_27_dialog_content = "โดยเฉพาะเวลาได้มองปลาในแม่น้ำ...",
  str_homestory_811101001_28_dialog_content = "ถ้าอยากดูปลา เธอก็ไปที่น้ำพุแห่งความหวังได้นี่ เบริล?",
  str_homestory_811101001_29_dialog_content = "ที่นั่นมีปลาเยอะนะ แล้วก็มีสวย ๆ หลายตัวเลย",
  str_homestory_811101001_30_dialog_content = "ตรงนี้ฉันเห็นแต่ปลาตัวเล็ก ๆ น่ะสิ",
  str_homestory_811101001_31_dialog_content = "ฉันมาดูปลาพวกนั้นแหละ",
  str_homestory_811101001_32_dialog_content = "ยิ่งเวลาที่มันแหวกว่ายฝ่าพืชน้ำ หรือพักผ่อนข้างก้อนหิน",
  str_homestory_811101001_33_dialog_content = "ได้เห็นพวกมันกลมกลืนกับธรรมชาติเป็นอย่างดี มันทำให้ฉันสบายใจมากเลย",
  str_homestory_811101001_34_dialog_content = "เธอใส่ใจในรายละเอียดดีจัง",
  str_homestory_811101001_35_dialog_content = "แล้วเธอก็ต้องตาดีมาก ๆ ด้วย ถึงตามความเร็วของพวกมันทัน",
  str_homestory_811101001_36_dialog_content = "พวกมันไม่ได้ว่ายน้ำตลอดเวลาหรอกค่ะ ที่จริงมันใช้เวลาพักผ่อนอยู่ที่ก้นแม่น้ำเป็นส่วนมาก",
  str_homestory_811101001_37_dialog_content = "บางตัวก็มุดเข้าไปในร่องหินแล้วก็โผล่แต่หัวออกมา",
  str_homestory_811101001_38_dialog_content = "บางตัวก็ว่ายตามพืชน้ำที่โบกไหว นั่นยิ่งทำให้ฉันรู้สึก... เป็นอิสระ",
  str_homestory_811101001_39_dialog_content = "เข้าใจแล้ว เธอไม่ได้แค่ดูปลา แต่กำลังศึกษาวิถีชีวิตของพวกมันอยู่",
  str_homestory_811101001_40_dialog_content = "วิถีชีวิต?",
  str_homestory_811101001_41_dialog_content = "พวกเขาไม่ยึดติดกับอะไรเลยและใช้ชีวิตอย่างไร้กังวล",
  str_homestory_811101001_42_dialog_content = "ค่ะ ฉันไม่เคยรู้สึกแบบนั้นที่ไหนมาก่อนเลย",
  str_homestory_811101001_43_dialog_content = "ฉันนึกถึงเรื่องนี้ครั้งแรกตอนที่มาถึงสวนลอยฟ้า แล้วก็ได้เจอพวกมันในแม่น้ำ",
  str_homestory_811101001_44_dialog_content = "นี่คงจะเป็นเสน่ห์ของสวนลอยฟ้าล่ะมั้ง?",
  str_homestory_811101001_45_dialog_content = "ไม่ใช่เสน่ห์หรอก แต่เป็นการผ่อนคลายต่างหาก...",
  str_homestory_811101001_46_dialog_content = "จริงด้วย การผ่อนคลาย <sprite=emo_pugongying size=60 />...",
  str_homestory_816501001_0_dialog_content = "เซียล...",
  str_homestory_816501001_1_dialog_content = "หวัดดี! มีงานให้ฉันทำรึเปล่า?",
  str_homestory_816501001_2_option_content = "ก็มีนะ แต่...",
  str_homestory_816501001_3_dialog_content = "งานอะไรเหรอ? ค่าจ้างเท่าไหร่?",
  str_homestory_816501001_4_dialog_content = "ฉันไม่แน่ใจว่ามันเหมาะกับเธอรึเปล่านะ... เป็นงานตกแต่งน่ะ",
  str_homestory_816501001_5_dialog_content = "เธออาจจะไม่ได้ใช้พรสวรรค์อย่างเต็มที่น่ะสิ",
  str_homestory_816501001_6_option_content = "ไม่มีหรอก",
  str_homestory_816501001_7_dialog_content = "ไม่มีเลยเหรอ?",
  str_homestory_816501001_8_dialog_content = "ปกติสวนลอยฟ้าก็ไม่ค่อยมีงานเท่าไหร่ แล้วงานส่วนใหญ่ก็เป็นหน้าที่ของพวกชับบ์",
  str_homestory_816501001_9_dialog_content = "มีงานที่มันสเกลใหญ่กว่านั้นมั้ย? อย่างพวกขุดอุโมงค์หรือเจาะภูเขาน่ะ",
  str_homestory_816501001_10_dialog_content = "หุ่นของฉันมีไว้เพื่องานพวกนั้นโดยเฉพาะเลยนะ! <sprite=emo_dianzan size=60 />",
  str_homestory_816501001_11_dialog_content = "ไม่มีหรอก ว่าแต่ทำไมอยู่ ๆ ก็หางานทำล่ะ? พักผ่อนจนเบื่อแล้วเหรอ?",
  str_homestory_816501001_12_dialog_content = "ฉันจะพักไม่ได้หรอก เพราะฉันต้องการเงิน",
  str_homestory_816501001_13_dialog_content = "เงิน? อิลลูมินาก็มีเบี้ยเลี้ยงให้เรื่อย ๆ นี่ เธออยากเก็บเงินซื้ออะไรเหรอ?",
  str_homestory_816501001_14_dialog_content = "ฉัน... ฉันอยากได้เครื่องคิดเลขเชิงกลน่ะ เคยเห็นอยู่ครั้งนึงในแล็บวิจัย",
  str_homestory_816501001_15_dialog_content = "ทำไมไม่สร้างเองเลยล่ะ? ที่สวนลอยฟ้าเธอมีเวลาว่างเยอะแยะอยู่แล้วไม่ใช่เหรอ?",
  str_homestory_816501001_16_dialog_content = "ไม่ได้หรอก เครื่องนั่นไม่ได้ใช้ชิ้นส่วนมาตรฐาน แล้วโครงสร้างก็ซับซ้อนเกินไป",
  str_homestory_816501001_17_dialog_content = "ถ้าให้ฉันสร้างชิ้นส่วนเอง มันก็จะกินเวลานานเกินไป",
  str_homestory_816501001_18_dialog_content = "แถมยังสิ้นเปลืองเงินกว่าเดิมด้วย",
  str_homestory_816501001_19_dialog_content = "แต่ฉันอยากได้จริง ๆ นะ ก็เลยต้องหางานเสริมที่พอจะทำได้ไงล่ะ",
  str_homestory_816501001_20_dialog_content = "ทำไมจู่ ๆ ถึงอยากได้เครื่องคิดเลขขึ้นมาล่ะ?",
  str_homestory_816501001_21_dialog_content = "เพราะฉันคิดว่าพิมพ์เขียวมันมีข้อผิดพลาดน่ะสิ มีอยู่จุดนึงที่คำนวณเท่าไหร่ก็ออกมาไม่ตรง ทั้ง ๆ ที่ลองใหม่ตั้งหลายครั้ง",
  str_homestory_816501001_22_dialog_content = "สูตรคำนวณนั่นซับซ้อนมาก เพราะงั้นคนอาจผิดพลาดได้ แต่เครื่องจักรไม่มีวันผิดแน่นอน",
  str_homestory_816501001_23_dialog_content = "เธออยากยืนยันตัวเลขนี่เอง",
  str_homestory_816501001_24_dialog_content = "ใช่! ฉันสร้างหุ่นยนต์ไดนามิกตามพิมพ์เขียว...",
  str_homestory_816501001_25_dialog_content = "แต่เพราะความผิดพลาด หุ่นก็เลยพังจนเกือบจะเผาพิมพ์เขียวไปด้วย",
  str_homestory_816501001_26_dialog_content = "ฉันหยิบพิมพ์เขียวออกจากกองไฟทัน แต่...",
  str_homestory_816501001_27_dialog_content = "พอสร้างไม่ได้ผล ฉันเลยคิดว่าตัวพิมพ์เขียวเองมันมีส่วนที่ขาดหายไปรึเปล่า <sprite=emo_daomei size=60 />",
  str_homestory_816501001_28_dialog_content = "เพราะพอสร้างหุ่นยนต์ตามพิมพ์เขียวนั่นทีไร มันจะต้องมีบางจุดที่ทำงานขัดข้อง",
  str_homestory_816501001_29_dialog_content = "แต่ถ้าคิดตามเหตุผลแล้ว... ถ้าพิมพ์เขียวมีข้อมูลไม่ครบจริง เธอก็ไม่น่าจะสร้างหุ่นยนต์ขึ้นมาได้เลยนี่นา?",
  str_homestory_816501001_30_dialog_content = "มันก็ใช่นะ",
  str_homestory_816501001_31_dialog_content = "หรือจะเป็นปัญหาเรื่องมุมมองการทำความเข้าใจรึเปล่า?",
  str_homestory_816501001_32_dialog_content = "มีอยู่ครั้งนึงที่สายเชื่อมต่อของโคลอสซัสมันดูผิดปกติ ฉันพยายามแก้ตั้งนานก็ไม่หาย",
  str_homestory_816501001_33_dialog_content = "จากนั้นพอหิ่งห้อยมา มันก็ซ่อมได้ทันทีเลย",
  str_homestory_816501001_34_dialog_content = "มุมมองงั้นเหรอ...",
  str_homestory_816501001_35_dialog_content = "เข้าใจแล้ว! เหมือนกับ <sprite=emo_baiyebi size=60 /> เหรียญไงล่ะ!",
  str_homestory_816501001_36_dialog_content = "เหรียญอะไรเหรอ?",
  str_homestory_816501001_37_dialog_content = "เมื่อวานฉันเจอเหรียญอยู่ริมแม่น้ำ หรือไม่ก็อาจจะเป็นฝาขวดหรือเศษเหล็กละมั้ง",
  str_homestory_816501001_38_dialog_content = "เอาเถอะ นั่นไม่ใช่เรื่องสำคัญหรอก ที่สำคัญก็คืออยู่ ๆ มันก็เด้งลงแม่น้ำเอง!",
  str_homestory_816501001_39_dialog_content = "พอมาคิดดูแล้ว ถึงผิวน้ำจะสงบ แต่ข้างล่างอาจจะมีกระแสน้ำปั่นป่วนก็ได้...",
  str_homestory_816501001_40_dialog_content = "เพราะฉะนั้น สูตรคำนวณก็อาจเป็นแนวทางการออกแบบเฉย ๆ",
  str_homestory_816501001_41_dialog_content = "เดี่๋ยวนะ เธอบอกว่าเจอเหรียญอยู่ริมแม่น้ำงั้นเหรอ?",
  str_homestory_816501001_42_dialog_content = "หืม? ใช่ เอาล่ะ ฉันไปออกแบบหุ่นยนต์ก่อนนะ แล้วเจอกัน!",
  str_homestory_816501001_43_dialog_content = "ได้สิ แล้วเจอกัน...",
  str_homestory_810001001_0_dialog_content = "คิดอะไรอยู่เหรอ?",
  str_homestory_810001001_1_dialog_content = "ซิคาเร?",
  str_homestory_810001001_2_dialog_content = "อ้าว เจ้าไก่อ่อนนี่เอง ฉันกำลังตามหานายอยู่พอดี",
  str_homestory_810001001_3_dialog_content = "มีอะไรเหรอครับ",
  str_homestory_810001001_4_dialog_content = "นายคิดยังไงกับสวนลอยฟ้าบ้าง?",
  str_homestory_810001001_5_dialog_content = "หา? นั่นมันน่าจะเป็นคำพูดของผมนะ จู่ ๆ โดนถามแบบนี้... ขอคิดก่อนนะ",
  str_homestory_810001001_6_option_content = "บ้าน",
  str_homestory_810001001_7_dialog_content = "แน่นอนอยู่แล้ว ที่นี่เป็นบ้านของผม",
  str_homestory_810001001_8_option_content = "สถานที่พักผ่อน",
  str_homestory_810001001_9_dialog_content = "เป็นที่ที่เหมาะกับการพักผ่อนสุด ๆ",
  str_homestory_810001001_10_dialog_content = "งั้นรึ...",
  str_homestory_810001001_11_dialog_content = "นายไม่คิดว่ามันเหมือนคุกเหรอ?",
  str_homestory_810001001_12_dialog_content = "เหมือนกับสุสานแห่งดวงดาราที่ฉันคอยปกป้องอยู่ไง",
  str_homestory_810001001_13_dialog_content = "ผมตามคุณไม่ทันแล้วแฮะ",
  str_homestory_810001001_14_dialog_content = "เพราะมันสบายเกินไปน่ะสิ สบายจนทำให้เราไม่อยากคิดเรื่องอื่น",
  str_homestory_810001001_15_dialog_content = "เหมือนคนอื่นก็เคยบอกผมประมาณนี้เหมือนกัน",
  str_homestory_810001001_16_dialog_content = "มันก็ดีนะ เหมือนคำพังเพยที่ทุกคนในดินแดนรู้จักกันดี",
  str_homestory_810001001_17_dialog_content = "ดาบที่ร้ายกาจที่สุดก็คือเตียงอันนุ่มสบาย มันสังหารผู้กล้ามาแล้วนับไม่ถ้วน",
  str_homestory_810001001_18_dialog_content = "ยิ่งสบายเท่าไหร่ คนเราก็ยิ่งหลงลืมหน้าที่ของตน โดยเฉพาะพวกโง่ที่ไม่คิดการณ์ไกล <sprite=emo_wuyu size=60 />",
  str_homestory_810001001_19_dialog_content = "ทำไมคุณถึงคิดเรื่องนี้ขึ้นมาล่ะ?",
  str_homestory_810001001_20_dialog_content = "เมื่อวานฉันเดินอยู่ริมแม่น้ำ แล้วก็เห็นพืชน้ำโบกพลิ้วตามกระแสน้ำ",
  str_homestory_810001001_21_dialog_content = "ในกอพืชน้ำพวกนั้นมีเศษเหล็กอะไรบางอย่างติดอยู่ แล้วมันก็ลอยขึ้น ๆ ลง ๆ ไปพร้อมกัน",
  str_homestory_810001001_22_dialog_content = "ผมว่าผมเข้าใจที่คุณพูดแล้ว",
  str_homestory_810001001_23_dialog_content = "ไม่ต้องห่วงนะ ถ้าคุณคิดประโยคนั้นออกมาได้ คุณก็ไม่ใช่เหล็กที่ติดกับพืชน้ำหรอก",
  str_homestory_810001001_24_dialog_content = "เพราะถึงยังไงเรามีสิทธิ์จะทำอะไรก็ได้ตามใจชอบไม่ใช่เหรอ?",
  str_homestory_810001001_25_dialog_content = "ว่าแล้วว่าฉันมองคนไม่ผิด เจ้าไก่อ่อน นายก็ไม่ได้ซื่อบื้อนี่นา",
  str_homestory_816601001_0_dialog_content = "เยี่ยมเลย...",
  str_homestory_816601001_1_dialog_content = "ดูท่าทางวันนี้ฟีญ่าอารมณ์ดีมาก ๆ",
  str_homestory_816601001_2_dialog_content = "เธอเริ่มชินกับการอยู่ที่นี่แล้วใช่มั้ย?",
  str_homestory_816601001_3_dialog_content = "อย่าพยายามเดาอารมณ์ของนักสัตว์มหัศจรรย์วิทยามืออาชีพเลยน่า!",
  str_homestory_816601001_4_dialog_content = "ฉันยังไม่ได้พูดอะไรแม้แต่คำเดียว... <sprite=emo_shengqi size=60 />",
  str_homestory_816601001_5_dialog_content = "แต่การกระทำของเธอมันฟ้องว่าเธอ \"อารมณ์ดีสุด ๆ\"",
  str_homestory_816601001_6_dialog_content = "หา?",
  str_homestory_816601001_7_dialog_content = "ตรงไหนล่ะ? ฉันไม่เชื่อนายหรอก",
  str_homestory_816601001_8_dialog_content = "เอ่อ... เอาเถอะ ฉันมีคำถามมาถามผู้เชี่ยวชาญพอดี",
  str_homestory_816601001_9_dialog_content = "คำถาม?",
  str_homestory_816601001_10_dialog_content = "เอาสิ จะพยายามตอบให้นะ",
  str_homestory_816601001_11_dialog_content = "เวลาหมา <sprite=emo_goutou size=60 /> ดีใจ พวกมันจะทำท่าทางยังไงเหรอ?",
  str_homestory_816601001_12_dialog_content = "เรื่องแค่นี้ก็ไม่รู้เหรอเนี่ย?",
  str_homestory_816601001_13_dialog_content = "เจ้าหมาน้อยอารมณ์ดีเป็นประจำอยู่แล้ว เวลาพวกมันดีใจ มันจะกระดิกหาง",
  str_homestory_816601001_14_dialog_content = "แล้วแมว <sprite=emo_baimao size=60 /> ล่ะ?",
  str_homestory_816601001_15_dialog_content = "นั่นก็ดูง่ายเหมือนกัน",
  str_homestory_816601001_16_dialog_content = "ถึงพวกมันจะขี้ระแวง แต่ถ้านายทำให้มันดีใจ...",
  str_homestory_816601001_17_dialog_content = "มันก็จะเข้ามาหา แล้วก็ร้องครืดคราดในลำคอ",
  str_homestory_816601001_18_dialog_content = "แล้วสัตว์มหัศจรรย์อย่างไคโลล่ะ?",
  str_homestory_816601001_19_dialog_content = "เวลาไคโลดีใจนี่ดูออกง่ายจะตาย ฮ่าฮ่าฮ่า",
  str_homestory_816601001_20_dialog_content = "ขนาดหลับตาฉันยังรู้เลย!",
  str_homestory_816601001_21_dialog_content = "อืมม ไม่ว่าจะเป็นสัตว์มหัศจรรย์หรือไม่ใช่...",
  str_homestory_816601001_22_dialog_content = "สัตว์ทุกชนิดล้วนมีวิธีแสดงความพอใจออกมาภายนอกทั้งนั้นสินะ",
  str_homestory_816601001_23_dialog_content = "...ที่ถามเมื่อกี้ต้องมีเป้าหมายอะไรแน่ ๆ เลยใช่มั้ย?",
  str_homestory_816601001_24_dialog_content = "เปล่าซะหน่อย!",
  str_homestory_816601001_25_dialog_content = "แค่อยากทดสอบว่าสิ่งที่สังเกตจากฟีญ่ามันถูกต้องรึเปล่า",
  str_homestory_816601001_26_dialog_content = "สังเกต... ฉัน?",
  str_homestory_816601001_27_dialog_content = "ฉันเป็นนักสัตว์มหัศจรรย์วิทยา ปกติต้องเป็นฝ่ายสังเกตสัตว์ตัวเล็กตัวน้อย...",
  str_homestory_816601001_28_dialog_content = "แล้วนายมาสังเกตดูฉันทำไม?",
  str_homestory_816601001_29_dialog_content = "นั่นอาจเป็นเพราะว่า...",
  str_homestory_816601001_30_option_content = "ฉันสงสัย",
  str_homestory_816601001_31_dialog_content = "เธอแสดงอารมณ์ความรู้สึกเยอะกว่าฉันมาก ๆ ก็เลยสนใจน่ะ",
  str_homestory_816601001_32_option_content = "ฉันอยากหาอะไรทำแก้เบื่อ",
  str_homestory_816601001_33_dialog_content = "เธอเป็นเด็กที่น่าสนใจมาก ฉันก็เลยอยากสังเกตพฤติกรรมดู",
  str_homestory_816601001_34_dialog_content = "แล้วที่ฉันเห็น...",
  str_homestory_816601001_35_dialog_content = "หูกระต่ายของเธอจะตั้งขึ้น เวลาเธออารมณ์ดี",
  str_homestory_816601001_36_dialog_content = "หวาาา! <sprite=emo_hanshui size=60 /> ย-อย่านะ อย่ามองหูฉันนะ!",
  str_homestory_816601001_37_dialog_content = "...",
  str_homestory_816601001_38_dialog_content = "เดี๋ยวก่อน!",
  str_homestory_816601001_39_dialog_content = "หูกระต่ายมันคือกิ๊บติดผมของฉัน ปกติมันก็ตั้งอยู่แล้ว!",
  str_homestory_816601001_40_dialog_content = "แต่ที่เธอพยายามปิดมันไว้ ก็แสดงว่าตอนนี้อารมณ์ดีจริง ๆ ใช่มั้ยล่ะ?",
  str_homestory_816601001_41_dialog_content = "หน็อย! นี่แกล้งหลอกฉันเรอะ PlayerName!",
  str_homestory_816601001_42_dialog_content = "โอเค โอเค ขอโทษ",
  str_homestory_816601001_43_dialog_content = "เพื่อเป็นการไถ่โทษ เดี๋ยวฉันไปเล่นสไลเดอร์ด้วยก็แล้วกัน",
  str_homestory_816601001_44_dialog_content = "...เอางั้นก็ได้",
  str_homestory_816701001_0_dialog_content = "คุณหลับอยู่รึเปล่าเนี่ย?",
  str_homestory_816701001_1_dialog_content = "เป็นคำถามที่ดี",
  str_homestory_816701001_2_dialog_content = "หากสายลมคือการหายใจของโลกใบนี้...",
  str_homestory_816701001_3_dialog_content = "ถ้าเช่นนั้น ตอนนี้โลกก็คงจะง่วงนอนอยู่ล่ะมั้ง <sprite=emo_kun size=60 />",
  str_homestory_816701001_4_dialog_content = "อา ยังไม่หลับสินะ",
  str_homestory_816701001_5_dialog_content = "ผมนึกว่าคุณหลับบนเก้าอี้ไปแล้ว",
  str_homestory_816701001_6_dialog_content = "มหาสมุทรนั้นไม่ต่างจากทรราชที่หลับใหลไม่มีวันตื่น",
  str_homestory_816701001_7_dialog_content = "คลื่นลมทะเลโหมคลั่งราวกับคมดาบ หากนายโชคดีพอ มันอาจจะบาดนายแค่เพียงไรผม...",
  str_homestory_816701001_8_dialog_content = "เจโน่?",
  str_homestory_816701001_9_dialog_content = "ว่าไง ผู้แสวงหาโชคชะตาที่รัก?",
  str_homestory_816701001_10_dialog_content = "ผมว่าผมไม่เข้าใจคำพูดของคุณเท่าไหร่",
  str_homestory_816701001_11_dialog_content = "ไม่สิ ไม่เข้าใจเลยมากกว่า",
  str_homestory_816701001_12_dialog_content = "เมื่อวาจาถูกเปล่งออกไปแล้ว มันก็ไม่ผูกมัดกับคอที่เอ่ยมันอีกต่อไป",
  str_homestory_816701001_13_dialog_content = "ในวินาทีที่คำพูดผ่านเข้าหู สมองก็จะตีความคำพูดนั้นตามความต้องการของผู้ฟัง",
  str_homestory_816701001_14_dialog_content = "โลกใบนี้คืองานเทศกาลขนาดมหึมา",
  str_homestory_816701001_15_dialog_content = "อย่างน้อยฉันก็คิดแบบนั้นมาเสมอ",
  str_homestory_816701001_16_option_content = "(ไม่เห็นจะเข้าใจเลย)",
