  str_homestory_817201001_19_dialog_content = "ฉันจำบทที่ฉันประทับใจเกี่ยวกับ Eraveil และประเพณีของมันได้!",
  str_homestory_817201001_20_dialog_content = "โอ้ว้าว! ปรากฎว่ามีภาพยนตร์แบบนั้นอยู่ที่นั่น?",
