  str_homestory_817301001_25_dialog_content = "ฉันเพิ่งเสร็จสิ้นการฝึกของพวกเขาเมื่อคุณมาถึง",
  str_homestory_817301001_26_dialog_content = "คุณคือ... ฝึกเทียน?",
  str_homestory_817301001_27_dialog_content = "อย่างแท้จริง. เป็นเทคนิคที่รู้กันเฉพาะพ่อบ้านผู้มากประสบการณ์ ที่อุทิศเวลาหลายปีในการให้บริการ...",
  str_homestory_817301001_28_dialog_content = "ไม่ว่าเฟอร์นิเจอร์ชิ้นหนึ่งจะมีราคาแพงแค่ไหน หรือเครื่องประดับที่ดูบอบบางเพียงใด...",
  str_homestory_817301001_29_dialog_content = "ด้วยเทคนิคที่ถูกต้อง พวกเขาทั้งหมดสามารถได้รับการฝึกฝนเพื่อให้บริการผู้อื่นได้ดียิ่งขึ้นภายในพื้นที่ของตน",
  str_homestory_817301001_30_dialog_content = "ยกตัวอย่างเทียนเหล่านี้",
  str_homestory_817301001_31_dialog_content = "พวกเขามีกลไกที่ช่วยให้พวกเขาสว่างขึ้นและดับโดยอัตโนมัติ",
  str_homestory_817301001_32_dialog_content = "เมื่อไม่ถูกตรวจสอบ เทียนเหล่านี้จะเปิดใช้งานและปิดใช้งานแบบสุ่ม โดยไม่มีลำดับแม้แต่น้อย",
  str_homestory_817301001_33_dialog_content = "แต่ไม่ต้องกังวล โดยการเข้าหาพวกเขาในลำดับที่เหมาะสม...",
  str_homestory_817301001_34_dialog_content = "ตอนนี้พวกเขาจะสว่างขึ้นอย่างมีความสุขต่อหน้าคุณ",
  str_homestory_817301001_35_dialog_content = "ท-น่าทึ่งมาก...",
  str_homestory_817301001_36_dialog_content = "อา! ขอโทษด้วย...",
  str_homestory_817301001_37_dialog_content = "ในฐานะแขกของคุณ ฉันไม่ควรทำอะไรอย่างฝึกเฟอร์นิเจอร์ของคุณ...",
  str_homestory_817301001_38_dialog_content = "ไม่ต้องห่วง.",
  str_homestory_817301001_39_dialog_content = "ถ้าไม่ใช่เพราะคุณ ฉันจะไม่มีทางรู้เลยว่าฉันสามารถทำเช่นนี้กับเทียนเหล่านี้ได้!",
  str_homestory_817301001_40_dialog_content = "ขอบคุณที่มองข้ามความผิดของฉัน",
  str_homestory_817301001_41_dialog_content = "แม้จะอดไม่ได้ที่จะรู้สึกขอบคุณในความผิดพลาดของตัวเอง...",
  str_homestory_817301001_42_dialog_content = "ด้วยเหตุนี้ ฉันจึงสวมบทบาทเป็นแขกที่ไม่สมบูรณ์ได้อย่างสมบูรณ์แบบ",
  str_homestory_817301001_43_dialog_content = "แต่ฉันหวังแค่การแสดงของฉัน<sprite=emo_baimao size=60 /> เป็นที่พอใจของคุณนาวิเกเตอร์",
  str_homestory_815901001_0_dialog_content = "เฮ้ ซาดี้!",
  str_homestory_815901001_1_dialog_content = "โอ้ มันคือคุณ อย่าบอกนะว่ามีคนมาหาฉัน?",
  str_homestory_815901001_2_dialog_content = "ไม่ ฉันถูกดึงดูดโดยดนตรี<sprite=emo_yinfu size=60 /> ก่อนหน้านี้.",
  str_homestory_815901001_3_dialog_content = "จังหวะที่ไพเราะและจังหวะเร้าใจนั้น...",
  str_homestory_815901001_4_dialog_content = "ฉันอดไม่ได้ที่จะเต้นไปกับเสียงเพลง!",
  str_homestory_815901001_5_dialog_content = "ดูเหมือนว่าคุณจะหลงรักเสน่ห์ฮิปฮอปที่ไม่อาจต้านทานได้!",
  str_homestory_815901001_6_dialog_content = "แต่มันเป็นเรื่องปกติมากเพราะใครไม่รักฮิปฮอป?",
  str_homestory_815901001_7_dialog_content = "นี่มันฮิปฮอป...?",
  str_homestory_815901001_8_dialog_content = "อย่าบอกนะว่าไม่เคยได้ยินมาก่อน PlayerName?",
  str_homestory_815901001_9_option_content = "(ยืนยัน)",
  str_homestory_815901001_10_dialog_content = "ฉันไม่ค่อยฟังฮิปฮอปเท่าไหร่ เลยพูดไม่ได้ว่าฉันเข้าใจมันดีนัก",
  str_homestory_815901001_11_option_content = "(ปฏิเสธ)",
  str_homestory_815901001_12_dialog_content = "ไม่มีทาง ฉันชอบดนตรีทุกประเภท!",
  str_homestory_815901001_13_dialog_content = "แต่เพลงฮิปฮอปเพลงเดียวที่ฉันได้ยินคือเพลงแร็พของคุณ...",
  str_homestory_815901001_14_dialog_content = "นั่นเป็นเหตุผลที่ฉันไม่ค่อยเข้าใจแนวเพลงมากนัก",
  str_homestory_815901001_15_dialog_content = "ยังเป็นเหตุผลที่ฉันบอกไม่ได้ว่ามันเป็นฮิปฮอปในทันที",
  str_homestory_815901001_16_dialog_content = "นั่นเป็นความอัปยศที่แท้จริง ไม่น่าแปลกใจเลยที่ฉันคิดว่ามีบางอย่างขาดหายไปเมื่อมาถึงที่นี่ครั้งแรก",
  str_homestory_815901001_17_dialog_content = "ทันทีที่ฉันเห็นกลองนี้ จู่ๆ ฉันก็รู้สึกว่าสถานที่แห่งนี้ต้องการฮิปฮอป!",
  str_homestory_815901001_18_dialog_content = "ฉันไม่เคยรู้มาก่อนว่ากลองเดียวสามารถสร้างจังหวะที่เคลื่อนไหวได้...",
  str_homestory_815901001_19_dialog_content = "ดูเหมือนว่าคุณจะหลงใหลไปกับมัน PlayerName.",
  str_homestory_815901001_20_dialog_content = "ฉันเดาว่าเจ้าชู้อย่างฉันไม่มีทางเลือกอื่นนอกจากยื่นมือให้คุณ",
  str_homestory_815901001_21_dialog_content = "ให้ฉันยืมมือ?",
  str_homestory_815901001_22_dialog_content = "ถูกตัอง! ฉันจะสอนตีกลองให้ถูกวิธี!",
  str_homestory_815901001_23_dialog_content = "ด้วยวิธีนี้ คุณสามารถฟังจังหวะฮิปฮอปแสนหวานได้ทุกเมื่อที่ต้องการ!",
  str_homestory_815901001_24_dialog_content = "เอ๊ะ? เดี๋ยวนะ ถ้าฉันสอนเธอให้ทำแบบนั้น...",
  str_homestory_815901001_25_dialog_content = "นั่นไม่ได้หมายความว่าทุกคนใน Cloud Gardens จะได้ยินจังหวะฮิปฮอปที่คุณสร้างใช่หรือไม่!",
  str_homestory_815901001_26_dialog_content = "ฉันไม่อยากจะเชื่อเลยว่าฉันจะเริ่มเทรนด์ฮิปฮอปใน Astra!",
  str_homestory_815901001_27_dialog_content = "ข-ขอโทษที่ขัดจังหวะ ซาดี...",
  str_homestory_815901001_28_dialog_content = "แต่ฉันเพิ่งเริ่มต้นเมื่อพูดถึงฮิปฮอปหรือกลอง",
  str_homestory_815901001_29_dialog_content = "ฉันไม่คิดว่าการสอนฉันจะเป็นเรื่องง่าย",
  str_homestory_815901001_30_dialog_content = "โอ้คุณไม่ต้องกังวลเรื่องนั้น! ท้ายที่สุด นักเรียนที่ดีที่สุดคือคนที่กระตือรือร้นที่จะเรียนรู้<sprite=emo_dianzan size=60 />!",
  str_homestory_815901001_31_dialog_content = "ตอนนี้ สองแง่มุมที่สำคัญที่สุดของฮิปฮอปคือจังหวะและจังหวะ",
  str_homestory_815901001_32_dialog_content = "จังหวะจะเป็นไปตามธรรมชาติตราบใดที่คุณเล่นตามจังหวะ",
  str_homestory_815901001_33_dialog_content = "ตอนนี้ ลองนึกภาพตัวเองเป็นไม้ตีกลองและดึงจังหวะในหัวใจออกมา",
  str_homestory_815901001_34_dialog_content = "ท้ายที่สุด hip-hop ที่ดีที่สุดมักจะมาจากใจเสมอ!",
  str_homestory_815901001_35_dialog_content = "คุณกำลังพูดว่าฉันจะแสดงได้เหมือนคุณถ้าฉันทำตามหัวใจของฉัน?",
  str_homestory_815901001_36_dialog_content = "อย่างแน่นอน! ทำไมคุณไม่ลองดูล่ะ",
  str_homestory_815901001_37_dialog_content = "เพียงแค่อยู่ในจังหวะและตีกลองออกไป เพลงจะไหลออกมาเอง!",
  str_homestory_815901001_38_dialog_content = "เจ-แค่ตีกลองต่อไป ฮะ...",
  str_homestory_815901001_39_dialog_content = "คุณไม่ต้องการที่จะช่วยให้ผู้คนจำนวนมากขึ้นตระหนักถึงความน่าทึ่งของฮิปฮอปหรือไม่?",
  str_homestory_815901001_40_dialog_content = "แน่นอนฉันทำ แต่ตอนนี้ฉันเหนื่อยมากแล้ว",
  str_homestory_815901001_41_dialog_content = "ฉันเดาว่าคุณยังมีหนทางอีกยาวไกลก่อนที่จะเป็นซุปเปอร์สตาร์ฮิปฮอป PlayerName.",
  str_homestory_815901001_42_dialog_content = "ให้เรียกมันสำหรับวันนี้ใช่มั้ย?",
  str_homestory_815901001_43_dialog_content = "ท-ขอบคุณ...",
  str_homestory_807901001_0_dialog_content = "มิเชนนี่...",
  str_homestory_807901001_1_dialog_content = "มิเชนนี่?",
  str_homestory_807901001_2_dialog_content = "สวัสดี PlayerName",
  str_homestory_807901001_3_dialog_content = "ฮิฮิ...มาชื่นชมการตกแต่งด้วยเหรอ?",
  str_homestory_807901001_4_dialog_content = "ในฐานะผู้เก็บภาษีที่มีจิตสำนึกอย่างมีเหตุผล คำว่า \"ชื่นชม\" นั้นซาบซึ้งเกินไป",
  str_homestory_807901001_5_dialog_content = "ฉันมาเพื่อประเมินมูลค่าของสินค้าชิ้นนี้ ไม่มีอะไรมากไปกว่านี้",
  str_homestory_807901001_6_dialog_content = "อา... นี่ไม่ใช่ลูโมโพลิส รู้ไหม? ฉันคิดว่าแม้คุณสามารถที่จะพักผ่อนบ้างเป็นครั้งคราว Michenny<sprite=emo_sikao size=60 />.",
  str_homestory_807901001_7_dialog_content = "การใช้ความคิดอย่างมีเหตุผลไม่ใช่เรื่องเล็ก",
  str_homestory_807901001_8_dialog_content = "โดยเฉพาะอย่างยิ่งเมื่อเป้าหมายคือการเป็นนักวิชาการชั้นนำด้านกฎหมายภาษีอากร",
  str_homestory_807901001_9_dialog_content = "ฉันไม่ได้ตั้งใจจะเปลืองประสบการณ์ทางวิชาการหลายปีเพียงเพื่อจะหย่อนยานแม้เพียงครู่เดียว",
  str_homestory_807901001_10_dialog_content = "ไม่ได้หมายความว่าฉันไม่มีเวลาว่าง ถ้าคุณต้องการ ฉันสามารถช่วยคุณเรื่องภาษีของ Cloud Gardens ในเวลาว่าง",
  str_homestory_807901001_11_dialog_content = "ฉันไม่คิดว่าเรามีปัญหาด้านภาษีใน Cloud Gardens ในตอนนี้...",
  str_homestory_807901001_12_dialog_content = "น้ำเสียงของคุณนุ่มนวล และคุณฟังดูไม่แน่นอน ประมาณภาษี 10 ไนเที่ยม<sprite=emo_baiyebi size=60 /> ห่างไกลจากความตั้งใจ",
  str_homestory_807901001_13_dialog_content = "ดูเหมือนว่าคุณจะปฏิเสธบริการของฉันโดยสิ้นเชิง",
  str_homestory_807901001_14_option_content = "ยอมรับ",
  str_homestory_807901001_15_dialog_content = "ไม่ใช่ว่าฉันอยากปฏิเสธคุณ มิเชนนี่ เพียงแต่ว่า... Cloud Gardens ไม่สามารถจ่ายเงินให้คนเก็บภาษีแบบคุณได้จริงๆ",
  str_homestory_807901001_16_dialog_content = "อา ขาด Nightium อย่างที่เคยเป็นมา ฉันเห็น",
  str_homestory_807901001_17_dialog_content = "คุณไม่จำเป็นต้องกังวลเกี่ยวกับเรื่องนั้น ฉันสามารถให้คำแนะนำด้านภาษีแก่คุณได้โดยไม่เสียค่าใช้จ่าย",
  str_homestory_807901001_18_dialog_content = "ท้ายที่สุด การประเมินคุณค่าของ Cloud Gardens อย่างถูกต้องจะช่วยให้วัดคุณค่าทางอารมณ์ได้เช่นกัน",
  str_homestory_807901001_19_option_content = "ปฏิเสธ",
  str_homestory_807901001_20_dialog_content = "ป-เปล่าซะหน่อย!",
  str_homestory_807901001_21_dialog_content = "ถ้า Cloud Gardens ต้องการคนเก็บภาษี คุณจะเป็นคนแรกที่ฉันโทรหา Michenny!",
  str_homestory_807901001_22_dialog_content = "ภาษีต้องมีอยู่ทุกที่ที่มีการจัดการที่ดินและทำธุรกรรม",
  str_homestory_807901001_23_dialog_content = "เนื่องจากคุณให้ความไว้วางใจในตัวฉันมาก ฉันจะประเมินคุณค่าของ Cloud Gardens ต่อไป",
  str_homestory_807901001_24_dialog_content = "ส-แน่...",
  str_homestory_807901001_25_dialog_content = "กลับเข้าเรื่องกันดีกว่า บอกฉันที... คุณรู้เรื่องการตกแต่งชิ้นนี้มากแค่ไหน?",
  str_homestory_807901001_26_dialog_content = "ฉันต้องการข้อมูลเพิ่มเติมเพื่อทำการประเมินอย่างยุติธรรม",
  str_homestory_807901001_27_dialog_content = "เรียกว่า Windelion Nest",
  str_homestory_807901001_28_dialog_content = "แม้ว่าเปลือกไข่ยักษ์เหล่านี้จะเป็นเพียงของประดับตกแต่งสัตว์มากมาย<sprite=emo_gezitou size=60 /> ชอบใช้วางไข่",
  str_homestory_807901001_29_dialog_content = "อืม. ไม่สร้างมูลค่าทางเศรษฐกิจโดยตรง และใช้พื้นที่",
  str_homestory_807901001_30_dialog_content = "นอกจากนี้ สิ่งมีชีวิตที่พวกเขาเลี้ยงดูในที่สุดจะเริ่มกินทรัพยากรอาหารของ Cloud Gardens",
  str_homestory_807901001_31_dialog_content = "ข้อสรุปของฉันคือวัตถุนี้และสิ่งมีชีวิตขนาดเล็กที่อาศัยอยู่ในนั้นไม่มีค่าใดๆ",
  str_homestory_807901001_32_dialog_content = "ตรงกันข้าม พวกเขาเป็นภาระทางเศรษฐกิจของ Cloud Gardens",
  str_homestory_807901001_33_dialog_content = "B-แต่ข้างในไข่มีสิ่งมีชีวิตอยู่!",
  str_homestory_807901001_34_dialog_content = "คุณจะประเมินคุณค่าของชีวิตพวกเขาโดยใช้ตรรกะได้อย่างไร?",
  str_homestory_807901001_35_dialog_content = "ถ้าคุณถามฉัน ชีวิตของพวกเขาไม่มีค่า",
  str_homestory_807901001_36_dialog_content = "ไร้ค่าคุณพูด?",
  str_homestory_807901001_37_dialog_content = "เดี๋ยวก่อน... เข้าใจแล้ว!",
  str_homestory_807901001_38_dialog_content = "คุณต้องการดูแล Windelion Nest, Michenny อย่างไร?",
  str_homestory_807901001_39_dialog_content = "ดีมาก. ฉันต้องทำอย่างไร?",
  str_homestory_807901001_40_dialog_content = "รออยู่ที่นี่จนกว่าเจ้าตัวเล็กเหล่านี้จะฟักเป็นตัว และดูแลพวกมันจนกว่าพวกมันจะโต!",
  str_homestory_807901001_41_dialog_content = "ฉันสามารถให้คุณยืมหนังสือที่สอนคุณเกี่ยวกับการดูแลสัตว์ได้",
  str_homestory_807901001_42_dialog_content = "หนังสือเรียนจะมีประโยชน์มากที่สุดใช่",
  str_homestory_807901001_43_dialog_content = "ปล่อยให้ฉัน. ฉันสัญญาว่าฉันจะไม่ทำให้คุณผิดหวัง",
  str_homestory_817601001_0_dialog_content = "เบเร็ตต้า!",
  str_homestory_817601001_1_dialog_content = "คุณกำลังทำอะไรเบเร็ตต้า?",
  str_homestory_817601001_2_dialog_content = "โอ้สวัสดี PlayerName!",
  str_homestory_817601001_3_dialog_content = "ฉันกำลังออกกำลังกาย",
  str_homestory_817601001_4_dialog_content = "ตอนที่ฉันวิ่งมาที่นี่ ฉันคิดว่าฉันเห็นเลดี้ราฟาเอล",
  str_homestory_817601001_5_dialog_content = "เลยหยุดดูอีกรอบ...",
  str_homestory_817601001_6_dialog_content = "และสังเกตเห็นรูปของเธอในการ์ดใบนี้!",
  str_homestory_817601001_7_dialog_content = "อ่า นั่นคือโปสการ์ดที่ทุกคนส่งมาให้ฉันก่อนหน้านี้!",
  str_homestory_817601001_8_dialog_content = "บางส่วนเป็นของฝากที่ซื้อกลับมาจากที่ใหม่ๆ",
  str_homestory_817601001_9_dialog_content = "ฉันคิดว่าภาพนี้ถ่ายตอนที่ราฟาเอลลากไมเคิลไปเที่ยวไกลๆ",
  str_homestory_817601001_10_dialog_content = "ฉันสงสัยว่าทำไมไมเคิลถึงดูแย่มาก!<sprite=emo_wuzui size=60 />",
  str_homestory_817601001_11_dialog_content = "คุณดูค่อนข้างเป็นที่นิยม",
  str_homestory_817601001_12_dialog_content = "คุณมีหลายอย่างที่นี่... ฉันยังเห็นอันที่มีลายเซ็นของ Lady Hedy อยู่ด้วย",
  str_homestory_817601001_13_dialog_content = "เฮ้ นี่คือภาพถ่ายทิวทัศน์ของทะเลทราย Rediesel ใช่ไหม",
  str_homestory_817601001_14_dialog_content = "ก็ใช่",
  str_homestory_817601001_15_dialog_content = "อันนี้ของฝากจากการเยี่ยมชม Rediesel Wrench",
  str_homestory_817601001_16_option_content = "และอันนี้มาจากนอร์ธแลนด์...",
  str_homestory_817601001_17_dialog_content = "ว้าว ทะเลทรายและหิมะ... งดงามมาก!",
  str_homestory_817601001_18_option_content = "และอันนี้มาจากชายหาด...",
  str_homestory_817601001_19_dialog_content = "ว้าว ทะเลทรายและชายหาด... สุดยอด!",
  str_homestory_817601001_20_dialog_content = "ฉันอิจฉาที่คุณได้ไปหลายที่ PlayerName!",
  str_homestory_817601001_21_dialog_content = "คุณไม่เดินทาง เบเร็ตต้า?",
  str_homestory_817601001_22_dialog_content = "ไม่ เพราะงานของฉัน ฉันจึงไม่สามารถพักผ่อนได้เต็มที่แม้ในขณะที่เลิกงาน",
  str_homestory_817601001_23_dialog_content = "ท้ายที่สุดแล้ว ผู้ป่วยไม่ได้หยุดป่วยหรือบาดเจ็บเพียงเพราะคุณอยู่ในช่วงพักร้อน",
  str_homestory_817601001_24_dialog_content = "แม้จะต้องเดินทางก็เพื่อช่วยเหลือค่ารักษาพยาบาล",
  str_homestory_817601001_25_dialog_content = "การเป็นหมอมันยากจริงๆ...",
  str_homestory_817601001_26_dialog_content = "มันยาก",
  str_homestory_817601001_27_dialog_content = "แต่เมื่อฉันคิดว่าฉันจะบรรเทาความเจ็บปวดของใครบางคนหรือแม้แต่ช่วยชีวิตได้อย่างไร...",
  str_homestory_817601001_28_dialog_content = "ไม่ใช่เรื่องยากอีกต่อไป!",
  str_homestory_817601001_29_dialog_content = "ไม่ต้องพูดถึงฉันต้องทำงานมากขึ้นเพื่อให้ดีขึ้น",
  str_homestory_817601001_30_dialog_content = "ด้วยวิธีนี้ฉันสามารถสร้างทีมแพทย์เดินทางของฉันเองเพื่อรักษาผู้ป่วยทั่วทั้งทวีป",
  str_homestory_817601001_31_dialog_content = "จากนั้น ไม่เพียงแต่ฉันจะได้ช่วยเหลือผู้คนมากขึ้นเท่านั้น แต่ฉันยังจะได้เห็นทิวทัศน์ที่ฉันไม่เคยเห็นมาก่อนด้วย!",
  str_homestory_817601001_32_dialog_content = "นกสองตัวกับหินก้อนเดียว!<sprite=emo_guilian size=60 />",
  str_homestory_817601001_33_dialog_content = "ฉันประทับใจเบเร็ตต้า!",
  str_homestory_817601001_34_dialog_content = "คุณมีประกายบางอย่างเกี่ยวกับตัวคุณเมื่อคุณพูดถึงงานของคุณ!",
  str_homestory_817601001_35_dialog_content = "ฮ่าฮ่าฮ่า แต่ฉันยังมีหนทางอีกยาวไกล!",
  str_homestory_817601001_36_dialog_content = "เป้าหมายของฉันคือการเป็นแพทย์ที่ยอดเยี่ยมเหมือน Lady Raphael หรือ Mr. John",
  str_homestory_817601001_37_dialog_content = "แต่ฉันยังมีอีกมากที่ต้องเรียนรู้",
  str_homestory_817601001_38_dialog_content = "ไม่ใช่แค่ในด้านการแพทย์เท่านั้น แต่ยังรวมถึงความแข็งแกร่งทางร่างกายและจิตใจด้วย",
  str_homestory_817601001_39_dialog_content = "ตอนที่คุณหมอจอห์นทำการผ่าตัดให้ฉัน เขายืนอยู่ข้างโต๊ะผ่าตัดเป็นเวลาสามวันเต็มๆ!",
  str_homestory_817601001_40_dialog_content = "เป็นไปไม่ได้ที่ฉันจะทำตอนนี้",
  str_homestory_817601001_41_dialog_content = "อา ฉันเลิกพูดแล้วไปฝึกต่อดีกว่า!",
  str_homestory_817601001_42_dialog_content = "แล้วเจอกัน PlayerName",
  str_homestory_817601001_43_dialog_content = "ฉันจะส่งไปรษณียบัตรให้คุณเมื่อฉันเริ่มรักษาผู้คน!",
  str_homestory_817601001_44_dialog_content = "เฮียยังรีบเหมือนเดิม",
  str_homestory_817601001_45_dialog_content = "ฉันเฝ้ารอวันนั้น คุณทำได้ เบเร็ตต้า",
