  str_homestory_817501001_1_dialog_content = "สวัสดี Axelia",
  str_homestory_817501001_2_dialog_content = "สวัสดี PlayerName",
  str_homestory_817501001_3_dialog_content = "รู้สึกดีขึ้นเมื่อเร็ว ๆ นี้?",
  str_homestory_817501001_4_dialog_content = "ฉันเห็นคุณค่อนข้างบ่อยใน Cloud Gardens",
  str_homestory_817501001_5_dialog_content = "ใช่<sprite=emo_chidai size=60 />... เมื่อฉันสำรวจ Cloud Gardens เสร็จแล้ว ฉันต้องกลับไปที่ห้องชะงักงัน",
  str_homestory_817501001_6_dialog_content = "แต่มีหลายสิ่งหลายอย่างที่ฉันพบว่าน่าสนใจ",
  str_homestory_817501001_7_dialog_content = "เช่นกลองใบนี้ที่คุณไปบ่อย?",
  str_homestory_817501001_8_dialog_content = "*แค่ก*",
  str_homestory_817501001_9_dialog_content = "คุณเคยดูฉันไหม PlayerName?",
