  str_homestory_817501001_11_dialog_content = "Cubes อยู่กับคุณเสมอ ดังนั้นจึงไม่ควรเกิดเหตุร้ายขึ้น",
  str_homestory_817501001_12_dialog_content = "แต่ฉันรู้สึกว่าฉันควรคำนึงถึงสภาพของคุณ",
