  str_homestory_817501001_25_dialog_content = "พวกเขาสามารถดื่มด่ำกับจังหวะของดนตรีได้โดยไม่จำเป็นต้องใส่อารมณ์มากเกินไปในเรื่องราวบางประเภท",
