  str_homestory_817501001_27_dialog_content = "ถึงพ่อจะเย้ยหยันแต่ผมว่าเมื่อเทียบกับดนตรีอื่นๆ...",
  str_homestory_817501001_28_dialog_content = "เทคโนเป็นตัวอย่างของการผสมผสานอย่างมีเหตุผลของความคิดสร้างสรรค์และโน้ตดนตรีที่ตรงไปตรงมา",
  str_homestory_817501001_29_dialog_content = "คุณรู้ไหม มันสมเหตุสมผลเมื่อคุณพูดแบบนั้น",
  str_homestory_817501001_30_dialog_content = "เพลงแนวนี้ดูไม่ปลุกอารมณ์รุนแรงในตัวผมเลย...",
