  str_homestory_805401001_1_dialog_content = "PlayerName!",
  str_homestory_805401001_2_dialog_content = "ทำไมคุณถึงยืนอยู่ที่นี่คนเดียว?",
  str_homestory_805401001_3_dialog_content = "ทำไมคุณไม่อยู่ในหอพักกับคนอื่นๆ หรือไปตกปลาที่อื่นใกล้ๆ ล่ะ",
