  str_homestory_805401001_8_dialog_content = "เฮ้ เดี๋ยวก่อน—",
  str_homestory_805401001_9_dialog_content = "ฉันจำไม่ได้ว่าเคยขอให้คุณเป็น Nightwatch ของ Cloud Gardens <sprite=emo_yueliang size=60 />.",
