  str_homestory_805401001_13_dialog_content = "ฉันไม่เคยคิดว่าตัวเองจะได้เป็นเพื่อนสนิทของคนดังอย่างคุณ",
  str_homestory_805401001_14_dialog_content = "น้อยกว่ามากที่ออกจาก Lumopolis ไปยังที่ห่างไกลอย่าง Cloud Gardens",
  str_homestory_805401001_15_dialog_content = "แต่ฉันไม่มีเงินหรือทักษะพิเศษ... ฉันไม่รู้จะตอบแทนคุณอย่างไร",
