  str_homestory_805401001_17_dialog_content = "ดังนั้นฉันจึงตัดสินใจว่านี่คือวิธีที่ฉันจะแสดงความขอบคุณต่อคุณ PlayerName!",
  str_homestory_805401001_18_option_content = "ขอบคุณเธอ",
  str_homestory_805401001_19_dialog_content = "ขอบคุณนาดีน ฉันรู้สึกประทับใจที่ได้ยินคุณพูดแบบนั้น",
  str_homestory_805401001_20_dialog_content = "แต่ฉันไม่สามารถให้แขกทำงานที่นี่ให้ฉันได้",
  str_homestory_805401001_21_option_content = "ปลอบเธอ",
  str_homestory_805401001_22_dialog_content = "ความสุขของคุณคือการตอบแทนที่ดีที่สุดสำหรับฉัน!",
  str_homestory_805401001_23_dialog_content = "คุณไม่จำเป็นต้องผลักดันตัวเองมาก",
  str_homestory_805401001_24_dialog_content = "ไม่ต้องกังวล ฉันชินกับมันแล้ว ไม่ใช่เรื่องยากสำหรับฉัน",
  str_homestory_805401001_25_dialog_content = "แล้วก็นะ...",
