  str_homestory_805401001_31_dialog_content = "ฉันรู้สึกเป็นหน้าที่ที่นี่เพราะฉันคิดว่าที่นี่เป็นบ้าน",
  str_homestory_805401001_32_dialog_content = "ฉันต้องการปกป้อง Cloud Gardens บ้านของเราจากอันตรายทั้งหมด!",
