  str_homestory_805401001_36_dialog_content = "ขอบคุณฉันคิดว่า",
  str_homestory_805401001_37_dialog_content = "ฉันจะพยายามชดเชยให้คุณไม่ทางใดก็ทางหนึ่ง",
