  str_homestory_817801001_0_dialog_content = "เฮ้ วิก",
  str_homestory_817801001_1_dialog_content = "ไม่ใช่ทุกวันที่เราจะได้เห็นคุณออกไปผจญภัยนอกบ้าน!",
