  str_homestory_817801001_3_dialog_content = "ว้าว คุณคิดกับฉันอย่างนั้นจริงๆเหรอ",
  str_homestory_817801001_4_dialog_content = "มันเจ็บนะ... ฉันเป็นนักสัตววิทยาเอก คุณรู้ไหม...",
  str_homestory_817801001_5_dialog_content = "เมื่อใดก็ตามที่ฉันอยู่ในห้อง ฉันมักจะจัดเรียงเนื้อหาหรือทำงานเกี่ยวกับหนังสือเล่มใหม่",
  str_homestory_817801001_6_dialog_content = "ฉันมีใจจดจ่อกับเรื่องสำคัญๆ อยู่เสมอ การดื่มช่วยให้จิตใจฉันกว้างขึ้นเท่านั้น!",
  str_homestory_817801001_7_dialog_content = "โอ้ใช่? แล้วหนังสือเล่มใหม่ของคุณเป็นอย่างไรบ้าง?",
  str_homestory_817801001_8_dialog_content = "อะแฮ่ม... ฉันว่านะ สภาพแวดล้อมที่นี่ดีขึ้นทุกวันจริงๆ",
  str_homestory_817801001_9_dialog_content = "นั่นเป็นวิธีหนึ่งในการเปลี่ยนเรื่อง",
  str_homestory_817801001_10_dialog_content = "ไม่ ไม่ คุณรู้ไหมว่าฉันมาทำอะไรที่นี่",
  str_homestory_817801001_11_dialog_content = "อืม... นอกจากเดินมึนๆ",
  str_homestory_817801001_12_dialog_content = "...",
  str_homestory_817801001_13_dialog_content = "ฉันกำลังตรวจสอบชนิดและปริมาณของสิ่งมีชีวิตในป่าของคุณ",
  str_homestory_817801001_14_dialog_content = "คุณทำอย่างนั้นเพื่ออะไร?",
  str_homestory_817801001_15_dialog_content = "อย่าประเมินความสำคัญของข้อมูลนี้ต่ำไป!",
  str_homestory_817801001_16_dialog_content = "อาจเปิดเผยปรากฏการณ์ที่มีความสำคัญยิ่ง",
  str_homestory_817801001_17_dialog_content = "เช่น จะบอกว่าสิ่งมีชีวิตประเภทไหนเหมาะกับสิ่งแวดล้อมที่นี่",
  str_homestory_817801001_18_dialog_content = "ปฏิสัมพันธ์ทางชีวภาพระหว่างสัตว์และพืชที่นี่และอื่นๆ",
  str_homestory_817801001_19_dialog_content = "คุณรู้อะไรไหม มันเพิ่งเกิดขึ้นกับฉัน<sprite=emo_wuzui size=60 />—",
  str_homestory_817801001_20_dialog_content = "สถานที่แห่งนี้เหมาะสำหรับการสืบสวนและการวิจัย!",
  str_homestory_817801001_21_dialog_content = "ฉันวางแผนที่จะแนะนำสัตว์ร้ายบางตัวที่นี่",
  str_homestory_817801001_22_dialog_content = "ด้วยวิธีนี้หนังสือของฉันจะมีมากขึ้น ...",
  str_homestory_817801001_23_dialog_content = "เดี๋ยวก่อน... คุณต้องการทำอะไร?",
  str_homestory_817801001_24_dialog_content = "ฮะ? รวบรวมข้อมูลแล้วเขียนลงในสมุดของฉัน...?",
  str_homestory_817801001_25_dialog_content = "ไม่ ฉันหมายถึงอย่างอื่น",
  str_homestory_817801001_26_dialog_content = "คุณต้องการที่จะเลี้ยงสัตว์มหัศจรรย์ในป่า?",
  str_homestory_817801001_27_dialog_content = "ฉันให้ห้องตัวเองไปตั้งเยอะแล้ว ยังไม่พออีก!?",
  str_homestory_817801001_28_dialog_content = "ทุกที่ที่อยู่ใกล้สิ่งเดียวกันจากระยะไกลเป็นอย่างไร",
  str_homestory_817801001_29_dialog_content = "ทิวทัศน์ในร่มเทียมไม่สามารถเทียบได้กับสภาพแวดล้อมจริงของโลกภายนอก",
  str_homestory_817801001_30_dialog_content = "พฤติกรรมของสัตว์สามารถสังเกตได้ในสภาพที่แท้จริงเมื่อตัวแบบอยู่ในที่อยู่อาศัยตามธรรมชาติเท่านั้น",
  str_homestory_817801001_31_dialog_content = "นั่นไม่ใช่ประเด็นของฉัน!",
  str_homestory_817801001_32_dialog_content = "คุณนำสัตว์มหัศจรรย์มากมายมาสู่ยักษ์ใหญ่แล้ว ฉันได้รับการร้องเรียนมากมายจากคนอื่นๆ รู้ไหม!",
  str_homestory_817801001_33_dialog_content = "ไม่ต้องพูดถึง คุณไม่พบวิธีแก้ปัญหาสำหรับเสียงสัตว์มหัศจรรย์อย่างต่อเนื่องที่ปลุกทุกคนให้ตื่นขึ้นในตอนเช้า",
  str_homestory_817801001_34_dialog_content = "และคุณไม่เคยทำความสะอาดขี้และขนที่ทิ้งไว้ทั่วสถานที่",
  str_homestory_817801001_35_dialog_content = "ตอนนี้คุณต้องการสร้างปัญหาให้ฉันมากยิ่งขึ้น!?",
  str_homestory_817801001_36_dialog_content = "คุณหนาวมาก PlayerName.",
  str_homestory_817801001_37_dialog_content = "คุณคิดว่านี่เป็นปัญหาได้อย่างไร?",
  str_homestory_817801001_38_dialog_content = "ลองนึกถึงการอุทิศส่วนนี้ให้กับองค์กรสัตว์ร้ายทั่วทวีปสิ!",
  str_homestory_817801001_39_dialog_content = "คุณกำลังทำตัวไร้สาระ!<sprite=emo_shengqi size=60 />",
  str_homestory_817801001_40_dialog_content = "คุณไม่ได้รับอนุญาตให้นำความหายนะทางสรีรวิทยาของคุณมาที่ป่าแห่งนี้ และนั่นคือจุดจบ",
  str_homestory_817801001_41_dialog_content = "ทุ่งหญ้า หุบเขา และแม่น้ำก็อยู่นอกขอบเขตเช่นกัน!",
  str_homestory_817801001_42_dialog_content = "เฮ้อ...ก็ได้",
  str_homestory_817801001_43_dialog_content = "จริงอยู่ คนหนุ่มสาวสมัยนี้ไม่มีความอดทนต่อผู้อาวุโส",
  str_homestory_817701001_0_dialog_content = "โกลดี้!",
  str_homestory_817701001_1_dialog_content = "อา ในที่สุดฉันก็พบคุณแล้ว โกลดี้! <sprite=emo_yaosu size=60 />",
  str_homestory_817701001_2_dialog_content = "PlayerNameฉันเพิ่งร้องเพลงใหม่บนเวที",
  str_homestory_817701001_3_dialog_content = "โอ้ ฉันประหม่ามาก อยากรู้ว่าทุกคนชอบไหม...",
  str_homestory_817701001_4_dialog_content = "คุณคิดอย่างไรกับมัน",
  str_homestory_817701001_5_dialog_content = "มันฟังดูน่าทึ่ง!",
  str_homestory_817701001_6_dialog_content = "ฉันแน่ใจว่าทุกคนรักมัน!",
  str_homestory_817701001_7_dialog_content = "ฮี่ฮี่... ขอบคุณค่ะ ฉันเดาว่าฉันคงสบายใจได้แล้ว",
  str_homestory_817701001_8_dialog_content = "พูดตามตรง ตอนนี้มีบางอย่างอยู่ในใจของฉัน",
  str_homestory_817701001_9_dialog_content = "ฉันหวังว่าคุณจะสามารถให้คำแนะนำแก่ฉันได้",
  str_homestory_817701001_10_dialog_content = "ว่าไง? ฉันไม่ค่อยเห็นคุณขัดแย้งกัน",
  str_homestory_817701001_11_dialog_content = "มันเกี่ยวกับซิงเกิลนำในอัลบั้มใหม่ของฉัน...",
  str_homestory_817701001_12_dialog_content = "มีเพลงที่เขียนในแบบฉบับของฉัน เต็มไปด้วยแสงแดด <sprite=emo_taiyang size=60 /> และคิดบวก",
  str_homestory_817701001_13_dialog_content = "แล้วมีเสียงอื่น ๆ ที่เย็นกว่านี้ <sprite=emo_mojing size=60 /> เพลงที่ฉันกำลังคิดที่จะแทนที่ด้วยความพยายามที่จะลองอะไรใหม่ๆ",
  str_homestory_817701001_14_dialog_content = "คุณคิดว่าฉันต้องเปลี่ยนมันไหม PlayerName?",
  str_homestory_817701001_15_option_content = "คุณควรทำมัน",
  str_homestory_817701001_16_dialog_content = "เป็นการดีที่จะลองสไตล์ใหม่ๆ สักครั้ง!",
  str_homestory_817701001_17_option_content = "ไม่จำเป็นต้องเปลี่ยน",
  str_homestory_817701001_18_dialog_content = "ใช่ ฉันสามารถจัดการกับสไตล์ที่คุ้นเคยได้อย่างมั่นใจมากขึ้น!",
  str_homestory_817701001_19_dialog_content = "อย่างไรก็ตาม ทั้งหมดขึ้นอยู่กับธีมของอัลบั้มโดยรวมใช่ไหม?",
  str_homestory_817701001_20_dialog_content = "ถูกต้อง! ธีมของอัลบั้มใหม่คือ \"Growing Pains\"",
  str_homestory_817701001_21_dialog_content = "บริษัทใช้เงินมหาศาลเพื่อเผยแพร่อัลบั้มนี้!",
  str_homestory_817701001_22_dialog_content = "ตัวแทนของคุณคิดอย่างไร?",
  str_homestory_817701001_23_dialog_content = "ตัวแทนของฉันบอกว่าฉันไม่ต้องเปลี่ยนอะไร",
  str_homestory_817701001_24_dialog_content = "เพราะแฟนผมบางคนอาจจะรับสไตล์ใหม่ไม่ได้...",
  str_homestory_817701001_25_dialog_content = "เป็นคำแนะนำที่ค่อนข้างอนุรักษ์นิยม",
  str_homestory_817701001_26_dialog_content = "แต่ฉันคิดว่าแฟนๆ ของคุณชอบให้คุณซื่อสัตย์ต่อตัวเองมากกว่า",
  str_homestory_817701001_27_dialog_content = "ไม่ว่าคุณจะเปลี่ยนไปหรือไม่ก็ตาม แฟนๆ ของคุณจะสนับสนุนคุณเหมือนเช่นเคย!",
  str_homestory_817701001_28_dialog_content = "ดังนั้นคุณก็อาจจะทำตามหัวใจของคุณเช่นกัน",
  str_homestory_817701001_29_dialog_content = "เลือกสไตล์ที่คุณชอบ",
  str_homestory_817701001_30_dialog_content = "ได้เลย!",
  str_homestory_817701001_31_dialog_content = "ที่ชำระมัน! ฉันจะเลือก—",
  str_homestory_817701001_32_dialog_content = "คุณจะเลือก—",
  str_homestory_817701001_33_dialog_content = "เพลงแสงแดดในเชิงบวกของฉัน!",
  str_homestory_817701001_34_dialog_content = "หา?",
  str_homestory_817701001_35_dialog_content = "เพราะนั่นคือสิ่งที่ฉันเป็นจริงๆ!",
  str_homestory_817701001_36_dialog_content = "นั่นคือสิ่งที่เหมาะกับฉันที่สุด!",
  str_homestory_817701001_37_dialog_content = "ฉันเดาว่าตัวแทนของคุณคงรู้จักคุณ เพราะฉนั้น...",
  str_homestory_818001001_0_dialog_content = "บรั่นดี?",
  str_homestory_818001001_1_dialog_content = "อืม...? ฉันควรวางแท่งไฟนี้ไว้ที่นี่หรือไม่? มันแปลกเหรอ?",
  str_homestory_818001001_2_dialog_content = "เธอกำลังทำอะไรน่ะ",
  str_homestory_818001001_3_dialog_content = "เฮ้! คุณทันเวลา!",
  str_homestory_818001001_4_dialog_content = "ช่วยดูให้หน่อย ฉันควรวางแท่งไฟนี้ไว้ทางซ้ายหรือขวาดี?",
  str_homestory_818001001_5_option_content = "ทางซ้าย.",
  str_homestory_818001001_6_dialog_content = "มันจะดูดีขึ้นทางด้านขวา",
  str_homestory_818001001_7_option_content = "มันเหมือนกันหมด",
  str_homestory_818001001_8_dialog_content = "คุณถูก. ฉันจะใส่มันไว้ทางขวา",
  str_homestory_818001001_9_dialog_content = "...",
  str_homestory_818001001_10_dialog_content = "คุณทำสิ่งนี้เพื่ออะไร",
  str_homestory_818001001_11_dialog_content = "ฉันกำลังถ่ายรูปสำหรับบทความ \"Goldie Takes Cloud Gardens By Storm\"",
  str_homestory_818001001_12_dialog_content = "ตอนนี้ฉันกำลังถ่ายภาพสินค้าสำหรับแฟนๆ ของโกลดี",
  str_homestory_818001001_13_dialog_content = "มีทั้งแท่งไฟ ป้ายไฟนีออน สติ๊กเกอร์ การ์ดพอร์เทรตจิ๋ว...",
  str_homestory_818001001_14_dialog_content = "มีแม้กระทั่งเสื้อยืดที่มีใบหน้าของโกลดี้อยู่ด้วย มันน่ารักมาก ๆ!",
  str_homestory_818001001_15_dialog_content = "ลองคิดดูสิ ฉันรู้สึกว่าฉันยังขาดสแตนดี้โกลดี้ขนาดเท่าของจริง",
  str_homestory_818001001_16_dialog_content = "ฉันแค่ต้องจับมันแล้วย่องกลับไปที่ห้องของฉัน... <sprite=emo_sikao size=60 />",
  str_homestory_818001001_17_dialog_content = "ไม่นะ! ไม่ควรมีสแตนดี้โกลดี้ขนาดเท่าคนจริงอยู่ที่นี่สักแห่ง!?",
  str_homestory_818001001_18_dialog_content = "มันอาจจะถูกแฟนโสโครกฉกไปหรือเปล่า?",
  str_homestory_818001001_19_dialog_content = "ทึ่ง! ทุกคนสามารถทำสิ่งนี้ได้อย่างไร?",
  str_homestory_818001001_20_dialog_content = "คุณแค่บอกว่านั่นคือสิ่งที่คุณอยากทำ...",
  str_homestory_818001001_21_dialog_content = "ลืมมันไป ผมจะลงรูปพวกนี้ก่อน",
  str_homestory_818001001_22_dialog_content = "เธอยืนอยู่ข้างๆ คุณ ทำไมคุณต้องถ่ายรูปสินค้า?",
  str_homestory_818001001_23_dialog_content = "ฉันไม่คิดว่าคุณกำลังทำสิ่งนี้ในทางที่ถูกต้อง",
  str_homestory_818001001_24_dialog_content = "คุณไม่เข้าใจ นี่เป็นวิธีเพิ่มระดับความเปรียบต่าง แสดงออกได้เต็มที่...",
  str_homestory_818001001_25_dialog_content = "เอ๊ะ? รอสักครู่!",
  str_homestory_818001001_26_dialog_content = "มีอะไรเหรอ",
  str_homestory_818001001_27_dialog_content = "เงาจากต้นไม้กระทบกับป้ายไฟนีออนในจุดที่เหมาะสม",
  str_homestory_818001001_28_dialog_content = "แสงและเงาร่ายรำไปทั่วกระดาน ทำให้ฉากมีชีวิตชีวาด้วยภาพเงาของต้นไม้",
  str_homestory_818001001_29_dialog_content = "นี่เป็นช่วงเวลาที่เหมาะสำหรับการถ่ายรูป!",
  str_homestory_818001001_30_dialog_content = "ยิงอะไร! ฉันไม่เคยเห็นรูปถ่ายที่สมบูรณ์แบบเช่นนี้มาก่อน!",
  str_homestory_818001001_31_dialog_content = "นี่เป็นเพียงภาพที่บทความข่าวของฉันต้องการ!",
  str_homestory_818001001_32_dialog_content = "ฉันคิดว่าบทความข่าวของคุณต้องมีรูปถ่ายของโกลดี้ตัวจริง...",
  str_homestory_818001001_33_dialog_content = "ฉันเสร็จแล้ว! ฉันจะกลับไปพัฒนารูปพวกนี้",
  str_homestory_818001001_34_dialog_content = "ฉันจำได้ว่าเห็นอะไรบางอย่างในน้ำระหว่างทางมาที่นี่ คุณควรไปดู",
  str_homestory_818001001_35_dialog_content = "คุณไม่ฟังฉันเลยใช่ไหม...",
  str_homestory_818101001_0_dialog_content = "จงซู?",
  str_homestory_818101001_1_dialog_content = "เธอกำลังมองหาอะไร",
  str_homestory_818101001_2_dialog_content = "ตรวจสอบชั้นวาง",
  str_homestory_818101001_3_dialog_content = "มีอะไรพิเศษเกี่ยวกับมัน? <sprite=emo_sikao size=60 />",
  str_homestory_818101001_4_dialog_content = "เดี๋ยวก่อน ฉันเห็นอี้ซิน!",
  str_homestory_818101001_5_dialog_content = "เขาคลานขึ้นไปบนชั้นวางโดยที่ฉันไม่สนใจ",
  str_homestory_818101001_6_dialog_content = "ช่างเป็นแมวที่ซุกซน!",
  str_homestory_818101001_7_dialog_content = "Yimeng และ Yinuo ก็อยู่ที่นั่นด้วย",
  str_homestory_818101001_8_dialog_content = "พวกเขาชอบชั้นวางของมากขนาดนั้น?",
  str_homestory_818101001_9_dialog_content = "อาจเป็นเพราะพวกเขาชอบที่มืดและแคบ",
