  str_homestory_818401001_1_dialog_content = "...",
  str_homestory_818401001_2_dialog_content = "เยริ? สวัสดี...?",
  str_homestory_818401001_3_dialog_content = "หืม? อา คาเลสไทต์ตัวน้อย",
  str_homestory_818401001_4_dialog_content = "คุณกำลังทำอะไร? คุณดูมีสมาธิมาก",
  str_homestory_818401001_5_dialog_content = "ใช่... ฉันแค่ฝันกลางวัน",
  str_homestory_818401001_6_dialog_content = "ฝันกลางวัน?",
  str_homestory_818401001_7_dialog_content = "ฉันบอกแล้วไงว่าฉันเคยไปที่ซากปรักหักพังใกล้ที่นี่มาก่อน?",
  str_homestory_818401001_8_dialog_content = "ในเวลานั้นคุณยังไม่กลับมา",
  str_homestory_818401001_9_dialog_content = "ที่นี่มีแต่ซากปรักหักพังและสุริยุปราคา <sprite=emo_kulou size=60 />.",
  str_homestory_818401001_10_dialog_content = "ผู้ชาย ฉันไม่อยากจะพูดเลยว่าต้องใช้เวลาและความพยายามมากแค่ไหนในการทำความสะอาดที่นี่!",
  str_homestory_818401001_11_dialog_content = "ขวา. ที่ไม่ง่ายเลย",
  str_homestory_818401001_12_dialog_content = "เมื่อพูดถึงเรื่องนี้ ฉันอยากจะถามคุณบางอย่าง",
  str_homestory_818401001_13_dialog_content = "คุณคิดว่าการปรับปรุง Cloud Gardens เป็นความพยายามที่มีความหมายหรือไม่?",
  str_homestory_818401001_14_dialog_content = "มันสวยงามในตอนนี้ แต่ถ้ามันถูกโจมตี หรืออีกร้อยปีจากนี้เมื่อคุณจากไป...",
  str_homestory_818401001_15_dialog_content = "ทุกสิ่งทุกอย่างที่นี่สามารถกลับคืนสู่ซากปรักหักพังได้",
  str_homestory_818401001_16_option_content = "มันมีความหมาย",
  str_homestory_818401001_17_dialog_content = "อย่างน้อยตอนนี้เราก็สามารถสนุกได้ตามต้องการที่นี่",
  str_homestory_818401001_18_dialog_content = "หากมีศัตรูมา ข้าจะขับไล่พวกมันออกไปให้หมด",
  str_homestory_818401001_19_dialog_content = "ถ้าฉันดูแลที่นี่ไม่ได้ ฉันจะปล่อยให้คนที่ไว้ใจได้ดูแล",
  str_homestory_818401001_20_dialog_content = "จะมีวิธีเสมอ!",
  str_homestory_818401001_21_dialog_content = "คุณเป็นคนมองโลกในแง่ดีอย่างแน่นอน",
  str_homestory_818401001_22_option_content = "อาจจะไม่.",
  str_homestory_818401001_23_dialog_content = "มันอาจจะไร้ความหมายหากจุดประสงค์ของเราคือการทำให้ Cloud Gardens ดำรงอยู่ตลอดไป",
  str_homestory_818401001_24_dialog_content = "ฉันรู้ถึงขีดจำกัดของความสามารถของฉัน...",
  str_homestory_818401001_25_dialog_content = "แต่อย่างน้อยตอนนี้เราก็มีความสุขแล้ว",
  str_homestory_818401001_26_dialog_content = "นั่นก็เพียงพอแล้วสำหรับฉัน!",
  str_homestory_818401001_27_dialog_content = "แนวคิดการใช้ชีวิตในปัจจุบันนี้น่ายกย่อง",
  str_homestory_818401001_28_dialog_content = "เมื่อฉันมาที่ Eraveil เป็นครั้งแรก ฉันคิดว่ามันเป็นสถานที่ที่น่าเศร้ามากจริงๆ",
  str_homestory_818401001_29_dialog_content = "เครื่องใช้บนโต๊ะอาหารคว่ำ บานเปิดครึ่ง เสื้อผ้ากองระเกะระกะ...",
  str_homestory_818401001_30_dialog_content = "พวกเขาเตือนฉันว่ากาลครั้งหนึ่งนานมาแล้ว คนธรรมดาเคยมีความสุขในชีวิตที่นี่",
  str_homestory_818401001_31_dialog_content = "สมัยนั้น...โป๊ะแตก เหมือนดอกแดนดิไลอัน <sprite=emo_pugongying size=60 />พวกเขาปลิวหายไปในสายลม",
  str_homestory_818401001_32_dialog_content = "นั่นสินะ...",
  str_homestory_818401001_33_dialog_content = "แต่ดอกแดนดิไลอันนำพาเมล็ดพันธุ์แห่งความหวังไปยังดินแดนอันไกลโพ้น",
  str_homestory_818401001_34_dialog_content = "ทั้งหมดนี้ไม่เคยไร้ความหมาย!",
  str_homestory_818401001_35_dialog_content = "จริง. คุณก็เหมือนเมล็ดพืชเล็กๆ ที่กลับมาแตกหน่ออีกครั้ง",
  str_homestory_818401001_36_dialog_content = "การพูดคุยกับคุณเป็นประสบการณ์ที่ไม่เหมือนใครเสมอ",
  str_homestory_818401001_37_dialog_content = "ฮี่ ฮี่ ปลื้มปริ่ม",
  str_homestory_818401001_38_dialog_content = "อืม... ในทางกลับกัน ให้ฉันบอกคุณบางสิ่งที่คุณอาจสนใจ",
  str_homestory_818401001_39_dialog_content = "เมื่อฉันอยู่ที่แม่น้ำก่อนหน้านี้ ฉันเห็นบางสิ่งส่องแสงในน้ำ",
  str_homestory_818401001_40_dialog_content = "บางทีคุณอาจจะไปดูก็ได้ คิดว่ามันคือการผจญภัย!",
  str_homestory_818401001_41_dialog_content = "ฟังดูน่าสนใจ... ขอบคุณ Jeriah!",
  str_homestory_818501001_0_dialog_content = "เป็นอะไรไปล่ะ",
  str_homestory_818501001_1_dialog_content = "ฉันนั่งอยู่ในแก้วกาแฟที่กำลังหมุนอยู่ และตอนนี้ฉันรู้สึกวิงเวียนนิดหน่อย <sprite=emo_xuanyun size=60 />...",
  str_homestory_818501001_2_dialog_content = "วิงเวียน? เครื่องจักรต้องปรับแต่งหรือไม่?",
  str_homestory_818501001_3_dialog_content = "ฉันจำได้ว่าความเร็วถูกตั้งค่าเป็นการตั้งค่าที่ช้าที่สุดแล้ว ฉันจะไปตรวจสอบในภายหลัง",
  str_homestory_818501001_4_dialog_content = "สิ่งเหล่านั้นอันตรายมาก! โปรดระวัง!",
  str_homestory_818501001_5_dialog_content = "อันตราย?",
  str_homestory_818501001_6_dialog_content = "สิ่งเหล่านี้มีไว้สำหรับเด็กอายุสี่ขวบขึ้นไปไม่ใช่หรือ",
  str_homestory_818501001_7_dialog_content = "สงสัยจะเหมาะกับเด็กอายุ 20 ปีขึ้นไป...",
  str_homestory_818501001_8_dialog_content = "บางคนไม่ชินกับความรู้สึกปั่นป่วน เป็นเรื่องปกติอย่างสมบูรณ์",
  str_homestory_818501001_9_dialog_content = "การพักผ่อนที่ดีน่าจะช่วยได้",
  str_homestory_818501001_10_dialog_content = "ตกลง. ฉันจะไปพักผ่อน ฉันยังต้องส่งจดหมายไปทางเหนือต่อไป...",
  str_homestory_818501001_11_dialog_content = "รอ. เหนือใต้...",
  str_homestory_818501001_12_dialog_content = "ไม่นะ! ฉันไม่สามารถแยกทิศทางของฉันออกจากกันได้อีกต่อไป!",
  str_homestory_818501001_13_dialog_content = "ฉันเคยภูมิใจในทิศทางของตัวเองมาก! เป็นไปได้ยังไง!?",
  str_homestory_818501001_14_dialog_content = "*ที่ร้องไห้* <sprite=emo_daku size=60 />ถ้าฉันส่งจดหมายไม่ได้ อาชีพของฉันจะเป็นอย่างไร",
  str_homestory_818501001_15_dialog_content = "เอ่อ นั่นมันดราม่าไปหน่อย...",
  str_homestory_818501001_16_dialog_content = "PlayerNameบอกฉันได้ไหมว่าทางไหนอยู่ทางเหนือ?",
  str_homestory_818501001_17_option_content = "ไปทางซ้าย",
  str_homestory_818501001_18_dialog_content = "ใช่ไหม? ฉันไม่สามารถบอกได้เลย...",
  str_homestory_818501001_19_option_content = "ฉันก็ไม่รู้เหมือนกัน",
  str_homestory_818501001_20_dialog_content = "จ-แม้แต่คุณ...",
  str_homestory_818501001_21_dialog_content = "เราจะจบลงที่นี่หรือไม่?",
  str_homestory_818501001_22_dialog_content = "???",
  str_homestory_818501001_23_dialog_content = "มันนับว่าถูกกักขังเมื่อคุณยังอยู่ในบ้านของคุณเองหรือไม่?",
  str_homestory_818501001_24_dialog_content = "ตอนนี้ฉันยังไม่แน่ใจเลยว่าฉันอยู่ที่ไหน...",
  str_homestory_818501001_25_dialog_content = "รหัส Courier Union กล่าวว่าเราต้องรักษาทิศทางอยู่เสมอ",
  str_homestory_818501001_26_dialog_content = "คนส่งของจำนวนมากต้องตกอยู่ในสถานการณ์อันตรายโดยที่ไม่มีที่ให้วิ่งหนีเพียงเพราะพวกเขาหลงทาง",
  str_homestory_818501001_27_dialog_content = "ฉันคิดว่าเรื่องแบบนั้นจะเกิดขึ้นก็ต่อเมื่อคุณออกไปอยู่ในถิ่นทุรกันดาร เช่น ป่าใหญ่",
  str_homestory_818501001_28_dialog_content = "เราอยู่ใน Cloud Gardens! คุณเห็นประตูไหม",
  str_homestory_818501001_29_dialog_content = "มันอยู่ตรงนั้น เพียงไม่กี่ก้าวคุณก็จะออกไปจากที่นี่",
  str_homestory_818501001_30_dialog_content = "แต่ถ้าฉันออกไปที่นั่นในถิ่นทุรกันดารและเวียนหัวเหมือนตอนนี้ล่ะ",
  str_homestory_818501001_31_dialog_content = "มีถ้วยกาแฟอยู่ในถิ่นทุรกันดารหรือไม่?",
  str_homestory_818501001_32_dialog_content = "โอ๊ะ จริงด้วยแฮะ...",
  str_homestory_818501001_33_dialog_content = "และแม้ว่าจะมีก็อย่าขี่เข้าไป",
  str_homestory_818501001_34_dialog_content = "ใช่! คุณฉลาดมาก!",
  str_homestory_818501001_35_dialog_content = "ฮะ แน่นอน...",
  str_homestory_818501001_36_dialog_content = "เมื่อฉันกลับไป ฉันจะเพิ่มกฎใหม่ให้กับรหัส Courier Union—",
  str_homestory_818501001_37_dialog_content = "\"ถ้าคุณเจอถ้วยกาแฟหมุนอยู่ในถิ่นทุรกันดาร อย่านั่งในนั้น!\"",
  str_homestory_818501001_38_dialog_content = "โอกาสเจอแก้วกาแฟหมุนๆในป่าน่าจะน้อยมาก...",
  str_homestory_818501001_39_dialog_content = "\"—มารยาททางปัญญาของ Caeleste\"",
  str_homestory_818501001_40_dialog_content = "!!!",
  str_homestory_818501001_41_dialog_content = "คุณต้องการให้ฉันจ่ายเท่าไหร่เพื่อไม่ให้ชื่อของฉันหายไป!?",
  str_homestory_818501001_42_dialog_content = "อะไร นี่เป็นคำแนะนำที่มีประโยชน์จริงๆ! ยังไงฉันก็ไป...",
  str_homestory_818501001_43_dialog_content = "เยี่ยมมาก... ฉันจะเป็นตัวตลกของ Courier Union...<sprite=emo_tanqi size=60 />",
  str_homestory_802901001_0_dialog_content = "กาเบรียล?",
  str_homestory_802901001_1_dialog_content = "คิดว่าตัวเองกำลังทำอะไรอยู่น่ะ",
  str_homestory_802901001_2_dialog_content = "ฉันกำลังงีบหลับอยู่ใต้ต้นไม้ <sprite=emo_kun size=60 />เพียงแค่สูดลมหายใจของต้นไม้",
  str_homestory_802901001_3_dialog_content = "ลมหายใจของต้นไม้?",
  str_homestory_802901001_4_dialog_content = "ถูกต้องครับ...ต้นไม้ก็เป็นสิ่งมีชีวิตเหมือนกัน",
  str_homestory_802901001_5_dialog_content = "ฉันสัมผัสได้ถึงรูปแบบการหายใจสม่ำเสมอของมัน คุณรู้สึกไหม, PlayerName?",
  str_homestory_802901001_6_option_content = "ยอมรับ",
  str_homestory_802901001_7_dialog_content = "เมื่อใบของมันสั่น มันจะรู้สึกว่ามันหายใจเร็วขึ้น",
  str_homestory_802901001_8_dialog_content = "คิดว่าเป็นแค่ลม...",
  str_homestory_802901001_9_option_content = "ปฏิเสธ",
  str_homestory_802901001_10_dialog_content = "โอ้ ฉันไม่รู้สึกถึงอะไรเลย...",
  str_homestory_802901001_11_dialog_content = "ดูเหมือนว่าคุณเป็นคนเดียวที่มีความสามารถพิเศษในการสัมผัสพืช กาเบรียล...",
  str_homestory_802901001_12_dialog_content = "ต้นไม้ทุกต้นมีความแตกต่างกันเช่นเดียวกับทุกคน",
  str_homestory_802901001_13_dialog_content = "ตราบใดที่คุณรู้สึกด้วยหัวใจของคุณ... คุณจะรู้โลกภายในของพวกเขาได้",
  str_homestory_802901001_14_dialog_content = "ตัวอย่างเช่น การหายใจของต้นไม้นี้ค่อนข้างลำบาก... ดูเหมือนจะป่วยเล็กน้อย...",
  str_homestory_802901001_15_dialog_content = "ฉันเดาว่าคงเป็นสาเหตุว่าทำไมใบของมันจึงมีสีเหลืองเล็กน้อยเมื่อเทียบกับต้นไม้อื่นๆ",
  str_homestory_802901001_16_dialog_content = "มันดูไร้ชีวิตชีวาไปหน่อย",
  str_homestory_802901001_17_dialog_content = "ต้นไม้แถวนี้เจริญงอกงามดีจริงๆ พวกมันบังแสงแดด... <sprite=emo_taiyang size=60 />",
  str_homestory_802901001_18_dialog_content = "ดูเหมือนว่าเจ้าตัวน้อยจะมีปัญหาในการสังเคราะห์แสง!",
  str_homestory_802901001_19_dialog_content = "คุณคิดว่าเราควรย้ายต้นไม้นี้ไปที่อื่นหรือไม่?",
  str_homestory_802901001_20_dialog_content = "ไม่ พืชมีวิธีการทำสิ่งต่างๆ ของมันเอง",
  str_homestory_802901001_21_dialog_content = "ต้นไม้ต้นนี้ไม่ทำงานหนักพอที่จะเติบโตสูง ต้นไม้อื่นๆ จึงขโมยแสงแดดของมันไป...",
  str_homestory_802901001_22_dialog_content = "มันต้องพึ่งตัวเองถึงจะเติบโตและแข็งแกร่งขึ้น... เราไม่ควรสปอยล์มันมากเกินไป!",
  str_homestory_802901001_23_dialog_content = "ฉันเข้าใจแล้ว... นั่นสมเหตุสมผลมาก กาเบรียล!",
  str_homestory_802901001_24_dialog_content = "เฮ้ ฉันกังวลว่ามันอาจจะยากเกินไปสำหรับคุณที่จะเข้าใจ PlayerName...",
  str_homestory_802901001_25_dialog_content = "ฉันเข้าใจ! แต่สิ่งที่ฉันรู้สึกประหลาดใจเล็กน้อยก็คือ—",
  str_homestory_802901001_26_dialog_content = "ปกติคุณดูเหมือนเดินงุนงงอยู่ตลอดเวลา เกเบรียล แต่วันนี้คุณดูจริงจังมาก",
  str_homestory_802901001_27_dialog_content = "ฉันคิดว่ามันถูกต้องกว่าที่จะบอกว่าฉันทำตัวตามสภาพแวดล้อมของฉันเสมอ...",
  str_homestory_802901001_28_dialog_content = "พืชก็มีชะตากรรมของมันเช่นกัน...",
  str_homestory_802901001_29_dialog_content = "พรหมลิขิต...?",
  str_homestory_802901001_30_dialog_content = "ขวา. การพบกันใต้ต้นไม้นี้เป็นส่วนหนึ่งของโชคชะตาของต้นไม้",
  str_homestory_802901001_31_dialog_content = "จะว่าไปแล้วเมื่อกี้ฉันเดินไปตามแม่น้ำ ฉันเห็นอะไรบางอย่างส่องแสง...",
  str_homestory_802901001_32_dialog_content = "คุณเห็นไหมว่ามันคืออะไร?",
  str_homestory_802901001_33_dialog_content = "ฉันแค่ตั้งใจจะแวะเข้าป่าเพื่องีบสักหน่อย!",
  str_homestory_802901001_34_dialog_content = "การที่ฉันไม่ได้ตรวจสอบสิ่งที่อยู่ในแม่น้ำก็เป็นส่วนหนึ่งของแผนแห่งโชคชะตาเช่นกัน!",
  str_homestory_802901001_35_dialog_content = "ฉันคิดว่าฉันเข้าใจสิ่งที่คุณหมายถึงเกี่ยวกับโชคชะตา...",
  str_homestory_818901001_0_dialog_content = "ทำอะไรน่ะลีน?",
  str_homestory_818901001_1_dialog_content = "เฮ้! เลย์!",
  str_homestory_818901001_2_dialog_content = "เหล้าช็อกโกแลต, ศูนย์ผลไม้ <sprite=emo_sikao size=60 />...ห๊ะ?",
  str_homestory_818901001_3_dialog_content = "โอ้สวัสดี.",
  str_homestory_818901001_4_dialog_content = "มองอะไร ลีน? คุณดูมุ่งมั่นมาก",
  str_homestory_818901001_5_dialog_content = "ไม่มีอะไรจริง ๆ ฉันเพิ่งเห็นกล่องช็อคโกแลตนี้",
  str_homestory_818901001_6_dialog_content = "สิ่งเหล่านี้มาจาก Mooncrown Day",
  str_homestory_818901001_7_dialog_content = "ถ้านายอยากจะกินมันล่ะก็ ลีน ช่วยตัวเองด้วย!",
  str_homestory_818901001_8_dialog_content = "ไม่ ฉันไม่อยากกินมัน ฉันสนใจแค่กระบวนการผลิต",
  str_homestory_818901001_9_dialog_content = "ฉันมักจะทำขนมช็อคโกแลตที่บ้านด้วย",
  str_homestory_818901001_10_dialog_content = "แต่ฉันมักจะใช้ช็อคโกแลตละลายในการตกแต่ง",
  str_homestory_818901001_11_dialog_content = "ฉันไม่รู้มาก่อนว่าของหวานมาไกลถึงเพียงนี้ในแง่ของศิลปะ",
  str_homestory_818901001_12_dialog_content = "ฉันบอกว่าคุณชอบช็อคโกแลตไหม",
  str_homestory_818901001_13_option_content = "ชอบมาก!",
  str_homestory_818901001_14_dialog_content = "ในกรณีนั้น ทันทีที่ฉันเรียนรู้เทคนิคใหม่ๆ ฉันจะให้คุณลองทำดู",
  str_homestory_818901001_15_dialog_content = "เร็วไปหน่อยที่คุณจะดื่มเหล้าช็อกโกแลต...",
  str_homestory_818901001_16_dialog_content = "ฉันจะเอาผลไม้มาให้คุณ",
  str_homestory_818901001_17_option_content = "ไม่ชอบครับ...",
  str_homestory_818901001_18_dialog_content = "โห... น่าเสียดายจัง",
  str_homestory_818901001_19_dialog_content = "ครั้งหน้าฉันจะนำขนมอื่น ๆ มาให้คุณ",
  str_homestory_818901001_20_dialog_content = "ถ้ามีอะไรที่คุณอยากกิน โปรดบอกฉัน ทุกเวลาที่คุณต้องการ",
  str_homestory_818901001_21_dialog_content = "หวาน! ขอบคุณ Leyn!",
  str_homestory_818901001_22_dialog_content = "อืมม...",
  str_homestory_818901001_23_dialog_content = "เกิดอะไรขึ้น? ทำไมคุณยังคงจ้องมองที่ช็อคโกแลตเหล่านั้น?",
  str_homestory_818901001_24_dialog_content = "คุณ... อยากกินบ้างมั้ย?",
  str_homestory_818901001_25_dialog_content = "ฉันแค่สงสัยนิดหน่อยว่ามันจะมีรสชาติยังไง! <sprite=emo_hanshui size=60 />",
  str_homestory_818901001_26_dialog_content = "ฉันคิดว่าฉันจะซื้อกล่องเพื่อทำการวิจัยเพิ่มเติมให้ตัวเอง!",
  str_homestory_818901001_27_dialog_content = "เฮ้ทำไมคุณยังสุภาพอยู่",
  str_homestory_818901001_28_dialog_content = "ถ้าอยากกินก็แค่กิน!",
  str_homestory_818901001_29_dialog_content = "ทุกคนต้องทำตามใจตัวเองสักครั้ง",
  str_homestory_818901001_30_dialog_content = "ผม... เอิ่ม...",
  str_homestory_818901001_31_dialog_content = "ขอขอบคุณสำหรับความมีน้ำใจของคุณ. ถ้าอย่างนั้นฉันจะช่วยเอง...",
  str_homestory_818601001_0_dialog_content = "ทีน่า?",
  str_homestory_818601001_1_dialog_content = "นายมาที่นี่ทำไม?",
  str_homestory_818601001_2_dialog_content = "สวัสดี, PlayerName!",
  str_homestory_818601001_3_dialog_content = "เก้าอี้ตัวนี้มีความอยากรู้อยากเห็นอย่างมาก",
  str_homestory_818601001_4_dialog_content = "คุณหมายถึง เก้าอี้ชายหาดตัวนั้น ?",
  str_homestory_818601001_5_dialog_content = "ค่ะ...ก็เก้าอี้ชายหาดนี่คะ...",
  str_homestory_818601001_6_dialog_content = "บอกตามตรง ผมไม่รู้อะไรเกี่ยวกับทะเลเลย ฉันใช้เวลาส่วนใหญ่ใน Lumopolis Hall of Justice",
  str_homestory_818601001_7_dialog_content = "คุณไปทะเลบ่อยไหม PlayerName?",
  str_homestory_818601001_8_option_content = "ฉันไปตลอดเวลา",
  str_homestory_818601001_9_dialog_content = "ฉันไปทะเลบ่อย",
  str_homestory_818601001_10_dialog_content = "ชายทะเลเป็นที่สุด!",
  str_homestory_818601001_11_option_content = "ไม่ขนาดนั้น",
  str_homestory_818601001_12_dialog_content = "จริง ๆ เปล่า ฉันไม่ได้ไปบ่อย",
  str_homestory_818601001_13_dialog_content = "แต่เที่ยวทะเลก็สนุกดี ฉันมีความทรงจำดีๆ ในช่วงเวลาบนชายหาด",
  str_homestory_818601001_14_dialog_content = "อย่างนี้นี่เอง!",
  str_homestory_818601001_15_dialog_content = "ถ้าฉันสามารถไปเที่ยวทะเลกับคุณได้ PlayerNameที่จะบวม!",
  str_homestory_818601001_16_dialog_content = "แต่ฉันยังมีอีกหลายคดีที่ต้องจัดการใน Hall of Justice ฉันยุ่งชะมัด!",
  str_homestory_818601001_17_dialog_content = "เราอาจจะมีโอกาสได้ไปด้วยกันในอนาคต",
  str_homestory_818601001_18_dialog_content = "แต่ชุดว่ายน้ำที่ใครๆ ก็ใส่กันที่ชายหาด... คุณแน่ใจหรือว่าโอเคกับมัน?",
  str_homestory_818601001_19_dialog_content = "ชุดว่ายน้ำ... เคยอ่านเจอในหนังสือ พวกเขาค่อนข้างขี้เหนียว<sprite=emo_qunzi size=60 />พวกเขาไม่ได้?",
  str_homestory_818601001_20_dialog_content = "ใช่แล้ว... ชุดขุนนางแห่งลูโมโปลิสอาจจะดูอับๆ ไปหน่อยสำหรับชายทะเล...",
  str_homestory_818601001_21_dialog_content = "ฉันเข้าใจอย่างถ่องแท้ว่าเสื้อผ้าที่แตกต่างกันควรสวมใส่ในโอกาสต่างๆ กัน แต่ฉันไม่ได้สนใจเรื่องนั้นเลย",
  str_homestory_818601001_22_dialog_content = "อย่างไรก็ตาม พวกผู้ใหญ่อาจกล่าวหาว่าฉันละทิ้งจรรยาบรรณของพวกเขา แค่คิดคำเยาะเย้ยของพวกเขาก็ทำให้ฉันหนาวสั่น ...",
  str_homestory_818601001_23_dialog_content = "*ไอ* เธอไม่ต้องคิดไปไกลถึงอนาคตหรอก ทีน่า...",
  str_homestory_818601001_24_dialog_content = "ไม่รู้จะได้ไปทะเลเมื่อไหร่...",
  str_homestory_818601001_25_dialog_content = "ถูกต้องที่สุด",
  str_homestory_818601001_26_dialog_content = "งั้น... คุณอยากลองเก้าอี้ชายหาดตัวนั้นหรืออะไร?",
  str_homestory_818601001_27_dialog_content = "ใช่! ฉันอยากจะลองดูสิ!",
  str_homestory_818601001_28_dialog_content = "มันไม่นุ่มเท่าเก้าอี้ปรับเอนแบบพิเศษของฉัน แต่ก็ยังสบายมาก!",
  str_homestory_818601001_29_dialog_content = "วัสดุนี้ทำให้ใช้งานได้จริงมากขึ้นสำหรับชายหาด",
  str_homestory_818601001_30_dialog_content = "เฮ้ ทีน่า! คุณกำลังฟังฉัน?",
  str_homestory_818601001_31_dialog_content = "เธอหลับสนิท...",
  str_homestory_819001001_0_dialog_content = "มาติเยอ?",
  str_homestory_819001001_1_dialog_content = "เจ้ามาได้ทันเวลาพอดีเลยนะ",
  str_homestory_819001001_2_dialog_content = "ศาลาเก่าที่ได้รับการบูรณะใหม่นี้ไม่โทรมเกินไป ไม่โทรมเลย... เป็นสถานที่ที่เหมาะสำหรับการจิบชาและอ่านหนังสือดีๆ สักเล่ม",
  str_homestory_819001001_3_dialog_content = "แต่ก็ยังต้องการบางสิ่งที่จะทำให้มันสมบูรณ์แบบยิ่งขึ้น—",
  str_homestory_819001001_4_dialog_content = "ว่าไง",
  str_homestory_819001001_5_dialog_content = "ตอนนี้มันจืดชืดไปหน่อย คุณจะไม่พูดเหรอ?",
  str_homestory_819001001_6_option_content = "แต่ผมไม่คิดอย่างนั้นนะ...",
  str_homestory_819001001_7_option_content = "ฉันสามารถตกแต่งเพิ่มเติมได้อีกเล็กน้อย",
  str_homestory_819001001_8_dialog_content = "ฉันจะเอาหมอนอิงมาสองสามใบ ก็น่าจะเพียงพอแล้วใช่ไหม?",
  str_homestory_819001001_9_dialog_content = "ฉันวางแผนที่จะตกแต่งด้วยดอกไม้และพืชหายากและชุดน้ำชาสีทองและสีเงินสำหรับใช้ของขุนนางบนเรือ",
  str_homestory_819001001_10_dialog_content = "ดอกไม้และพืชหายาก ชุดน้ำชาสีทองและสีเงิน... นั่นจะไม่ฟุ่มเฟือยเกินไปหน่อยเหรอ?",
  str_homestory_819001001_11_dialog_content = "คุณกังวลเกี่ยวกับค่าใช้จ่ายหรือไม่? <sprite=emo_baiyebi size=60 /> คุณเป็น Caelestite ที่ประหยัดจริง ๆ ใช่ไหม?",
  str_homestory_819001001_12_dialog_content = "คุณไม่ต้องกังวลเกี่ยวกับเงิน ฉันจะดูแลเรื่องนั้น",
  str_homestory_819001001_13_dialog_content = "มันไม่ใช่แค่เงิน แน่นอนว่าจะต้องใช้เงินจำนวนมากก็เป็นปัญหาในตัวมันเอง",
  str_homestory_819001001_14_dialog_content = "แต่เนื่องจากคุณสามารถดูแลได้ จึงไม่เป็นปัญหา อย่างไรก็ตาม...",
  str_homestory_819001001_15_dialog_content = "ตกลงจะพูดอะไรกันแน่",
  str_homestory_819001001_16_dialog_content = "นี่คือ Cloud Gardens สถานที่ที่ทุกคนพยายามอย่างเต็มที่ที่จะอยู่ร่วมกัน",
  str_homestory_819001001_17_dialog_content = "ไม่ใช่ทุกคนที่จะสนใจสิ่งต่างๆ เช่น ช่อดอกไม้และถ้วยชามทองคำและเงิน..",
  str_homestory_819001001_18_dialog_content = "ฉันไม่ต้องการทำให้มันหรูหราเกินไป และฉันก็ไม่ต้องการทำให้ชาวออโรเรียนบางคนรู้สึกไม่สบายใจ",
  str_homestory_819001001_19_dialog_content = "คุณกำลังคิดถึงคนที่ไม่มีความสุขกับชีวิตประจำวันอยู่หรือเปล่า?",
  str_homestory_819001001_20_dialog_content = "การถูกห้อมล้อมด้วยดอกไม้และเงินๆทองๆ ไม่ได้หมายถึงชีวิตประจำวัน...",
  str_homestory_819001001_21_dialog_content = "อย่างไรก็ตาม ฉันจะส่งคนไปเริ่มงานตกแต่งทันที",
  str_homestory_819001001_22_dialog_content = "รอสักครู่... ฉันรับผิดชอบที่นี่—ฉันเป็นผู้ตัดสินในการตัดสินใจทั้งหมด",
  str_homestory_819001001_23_dialog_content = "หากคุณต้องการอาศัยอยู่ที่นี่กับเราต่อไป คุณต้องเรียนรู้วิธีการอยู่ร่วมกันกับผู้คนที่แตกต่างกัน",
  str_homestory_819001001_24_dialog_content = "อืม? ทำไมจู่ ๆ ถึงได้พูดจริงจังแบบนี้?",
  str_homestory_819001001_25_dialog_content = "เดี๋ยวก่อน... คุณแค่... <size=45>เลียนแบบ Schwab</size>!?",
  str_homestory_819001001_26_dialog_content = "อืม? คุณกำลังพูดถึงอะไร",
  str_homestory_819001001_27_dialog_content = "ฉันได้ยินมาว่าชวาบชอบอ่านหนังสือในศาลาที่เต็มไปด้วยดอกไม้ และมักจะมีเด็กสาวจำนวนมากมาหาเขาเสมอเมื่อเขาอ่านหนังสือ",
  str_homestory_819001001_28_dialog_content = "คุณก็พยายามทำให้สาวๆ คลั่งไคล้คุณเหมือนกันเหรอ?",
  str_homestory_819001001_29_dialog_content = "คุณต้องการเป็นที่นิยมเหมือน Schwab ดังนั้นคุณกำลังคัดลอกเขา",
  str_homestory_819001001_30_dialog_content = "อ้อเหรอ...",
  str_homestory_819001001_31_dialog_content = "อะไร!? อย่ามองฉันแบบนั้น—เหมือนคุณเพิ่งไขคดีใหญ่! <sprite=emo_shengqi size=60 />",
  str_homestory_819001001_32_dialog_content = "ไม่เป็นเช่นนั้นเลย! ทำไมฉันถึงอยากเป็นคนโง่แบบนั้น?",
  str_homestory_819001001_33_dialog_content = "คำว่า \"โง่\" ฟังดูเหมือนดูถูกในตอนแรก",
  str_homestory_819001001_34_dialog_content = "แต่บางคนใช้มันเพื่อปกปิดความชอบของพวกเขาสำหรับคนอื่น ๆ",
  str_homestory_819001001_35_dialog_content = "เริ่มไม่สบายขึ้นมาทันใด...",
  str_homestory_819001001_36_dialog_content = "ฉันเป็นนักวิชาการที่โดดเด่นของ Dawn Academy!",
  str_homestory_819001001_37_dialog_content = "ทำไมฉันต้องเลียนแบบคนโง่ที่เอาแต่ใส่ใจกับการรักษาภาพลักษณ์ของตัวเองต่อหน้ากลุ่มผู้หญิงที่ไม่แน่นอน!?",
  str_homestory_819001001_38_dialog_content = "แล้วทำไมต้องตกแต่งศาลาเก่าด้วยดอกไม้และชุดน้ำชาแฟนซี?",
  str_homestory_819001001_39_dialog_content = "แน่นอนว่ามันเป็นเรื่องของความชอบของฉันในฐานะขุนนาง!",
  str_homestory_819001001_40_dialog_content = "ลืมมันไป ตกแต่งตามที่คุณต้องการ",
  str_homestory_819001001_41_dialog_content = "ก็ช่างมันสิ",
  str_homestory_819001001_42_dialog_content = "(ประท้วงมากเกินไป? เมื่อดูว่าเขาเริ่มหงุดหงิด เขาคงแนะนำทั้งหมดนี้เพียงเพราะเขาอยากอ่านที่ไหนสักแห่งไม่ได้ใช่ไหม)",
  str_homestory_819101001_0_dialog_content = "ฮาติ?",
  str_homestory_819101001_1_dialog_content = "ทำอะไรอยู่เหรอ?",
  str_homestory_819101001_2_dialog_content = "โอ้ แค่คุยกับหนังสือบนชั้นหนังสือ",
  str_homestory_819101001_3_dialog_content = "เอ่อ... คุณพูดกับหนังสือว่าอย่างไร?<sprite=emo_yihuo size=60 />",
  str_homestory_819101001_4_dialog_content = "ง่าย! คุณเพียงแค่ถามคำถามและคำตอบจะปรากฏบนหน้าเว็บ! บางทีก็ตอบเกินจริงจนขนลุก",
  str_homestory_819101001_5_dialog_content = "แล้วคุณถามมันว่าอะไร?",
  str_homestory_819101001_6_dialog_content = "ฉันอยากฟังนิทานเรื่องหนึ่ง ฉันจึงขอให้มันเล่าให้ฉันฟังสักเรื่องหนึ่ง",
  str_homestory_819101001_7_dialog_content = "เรื่องราวแบบไหน? มันน่ากลัวไหม?",
  str_homestory_819101001_8_dialog_content = "คุณไม่กลัวเหรอ?",
  str_homestory_819101001_9_option_content = "ก็นิดหน่อยน่ะครับ...",
  str_homestory_819101001_10_dialog_content = "แต่ถึงกระนั้นฉันก็อยากรู้อยากเห็น",
  str_homestory_819101001_11_option_content = "ไม่มีทาง!",
  str_homestory_819101001_12_dialog_content = "คุณกำลังล้อเล่น? คนแกร่งอย่างฉันจะกลัวหนังสือได้ยังไง",
  str_homestory_819101001_13_dialog_content = "เรื่องที่เล่าเมื่อกี้ก็ประมาณนี้...",
  str_homestory_819101001_14_dialog_content = "\"ในคืนฤดูหนาวที่หนาวเย็น คุณยืนอยู่หน้าชั้นหนังสือ กำลังอ่านหนังสือ All-knowledge ...\"",
  str_homestory_819101001_15_dialog_content = "\"เมื่อจู่ๆ คุณสังเกตเห็นบางสิ่งเคลื่อนไหวอยู่ข้างหลังคุณ นั่นคือตอนที่คำต่างๆ ค่อยๆ ปรากฏขึ้นบนหน้ากระดาษ...\"",
  str_homestory_819101001_16_dialog_content = "“อย่าหันกลับมา <size=45>บางคน</size> อยู่ข้างหลังคุณ”",
  str_homestory_819101001_17_dialog_content = "\"ทั้งๆที่คุณกลัว คุณก็อดไม่ได้ที่จะหันไปมอง\"",
  str_homestory_819101001_18_dialog_content = "นั่นคือเท่าที่ฉันได้รับในเรื่อง พอผมหันไปดูก็เดินเข้ามาในห้องพอดี",
  str_homestory_819101001_19_dialog_content = "ฮ่าฮ่าฮ่า! ฟังดูเหมือนนวนิยายระทึกขวัญทั่วไป แต่มีการหักมุมในชีวิตจริง จะเกิดอะไรขึ้นต่อไป?",
  str_homestory_819101001_20_dialog_content = "“คนที่อยู่ข้างหลังคุณไม่ใช่ใครอื่นนอกจากเจ้าของบ้านของคุณ”",
  str_homestory_819101001_21_dialog_content = "“แต่ไม่จำเป็นต้องกลัว เจ้าของบ้านของคุณอ่อนแอ และคุณสามารถส่งเขาปลิวไปได้ด้วยหมัดเดียว”",
  str_homestory_819101001_22_dialog_content = "รออะไร?! ตอนนี้คุณกำลังสร้างสิ่งต่างๆ!",
  str_homestory_819101001_23_dialog_content = "แต่ถึงกระนั้นก็เกือบจะน่ากลัวว่าเรื่องราวจะเป็นอย่างไร! นั่นเป็นเหตุผลที่ฉันไม่สามารถวางเรื่องนี้ลงได้!",
  str_homestory_819101001_24_dialog_content = "\"เพื่อให้พอๆ กับเจ้าของบ้านที่ทำให้คุณตกใจ คุณตัดสินใจกระทุ้งเขาเร็วๆ\"",
  str_homestory_819101001_25_dialog_content = "\"โชคไม่ดีที่หมัดเบาๆ ของคุณทำให้เขาล้มลงกับพื้น เพื่อเป็นการตอบโต้ เขาเตะคุณออกจากบ้านไปที่ถนนที่เย็นยะเยือก ซึ่งคุณจะเป็นหวัดและเสียชีวิต\"",
  str_homestory_819101001_26_dialog_content = "มันน่าขนลุกใช่มั้ย? โอ้ ไม่ต้องกังวล คุณเจ้าของบ้าน ฉันไม่เคยฝันที่จะตีคุณ",
  str_homestory_819101001_27_dialog_content = "และฉันก็จะไม่ไล่คุณออกเช่นกัน! ไม่ เดี๋ยวก่อน ไม่มีทางที่คุณจะทำให้ฉันสลบได้ด้วยหมัดเดียว!",
  str_homestory_819101001_28_dialog_content = "อยากลองไหม",
  str_homestory_819101001_29_dialog_content = "มาทำกันเถอะ!<sprite=emo_dianzan size=60 />",
  str_homestory_819101001_30_dialog_content = "ก็ได้ แต่คุณขอมัน! ปล่อยให้ฉันคลายข้อมือออก",
  str_homestory_819101001_31_dialog_content = "II กำลังพูดถึงหนังสือที่รอบรู้!",
  str_homestory_819101001_32_dialog_content = "โอ้? แล้วคุณอยากจะถามมันว่าอะไร?",
  str_homestory_819101001_33_dialog_content = "ตอบโจทย์ได้จริงหรือ?",
  str_homestory_819101001_34_dialog_content = "คุณเห็นไหมว่าตอนนี้ฉันค่อนข้างผูกมัด Vice ขอให้ฉันจัดการการเงินของ Colossus สำหรับเดือนนี้...",
  str_homestory_819101001_35_dialog_content = "ฉันได้ยินคุณพูดถึงเรื่องนั้นในโรงอาหาร ใช่",
  str_homestory_819101001_36_dialog_content = "นั่นเป็นสิ่งแรกที่ฉันถาม และมันตอบว่า—",
  str_homestory_819101001_37_dialog_content = "\"ฉันเป็นแค่หนังสือ ฉันไม่มีทรัพย์สิน ดังนั้นฉันไม่มีทางช่วยคุณสร้างสมดุลทางการเงินได้\"",
  str_homestory_819101001_38_dialog_content = "Tch... และที่นี่ฉันคิดว่ามันสามารถตอบคำถามใด ๆ !",
  str_homestory_819101001_39_dialog_content = "ไม่จำเป็นต้องถามผู้รู้ทั้งหลาย ฉันสามารถตอบคำถามของคุณได้ ไม่มีปัญหา",
  str_homestory_819101001_40_dialog_content = "โอ้จริงเหรอ? ลองมาฟังกัน",
  str_homestory_819101001_41_dialog_content = "ค่าใช้จ่ายของ Colossus อยู่เหนือการควบคุมโดยสิ้นเชิง และคุณก็ใกล้จะล้มละลายแล้ว ในที่สุด คุณจะต้องจบลงบนถนนที่เย็นยะเยือก ที่ซึ่งคุณเป็นหวัดและเสียชีวิต",
  str_homestory_819101001_42_dialog_content = "อย่าเพิ่งขโมยจากหนังสือที่รอบรู้!",
  str_homestory_819101001_43_dialog_content = "มันเป็นคำตอบที่ค่อนข้างเหมาะสม คุณว่ามั้ย?",
  str_homestory_819101001_44_dialog_content = "ไม่ใช่สิ่งที่คุณ... คาดหวัง? โฮ...",
  str_homestory_817702001_0_dialog_content = "เฮ้ ฉันคิดว่าฉันได้ยินโกลดี้ร้องเพลง!",
  str_homestory_817702001_1_dialog_content = "♪ ลา ลา ลา ลา! ♪",
  str_homestory_817702001_2_dialog_content = "โอ้, PlayerName! สวัสดี.",
  str_homestory_817702001_3_dialog_content = "สวัสดี โกลดี้!",
  str_homestory_817702001_4_dialog_content = "ขอโทษ ฉันไม่ได้รบกวนคุณใช่ไหม",
  str_homestory_817702001_5_dialog_content = "ไม่เลย ไม่เลย!",
  str_homestory_817702001_6_dialog_content = "ฉันอดไม่ได้ที่จะร้องเพลงเมื่อเห็นไวโอลินที่นี่!",
  str_homestory_817702001_7_dialog_content = "พูดตามตรง ฉันรู้สึกประหลาดใจจริงๆ ที่พบว่าคุณมี PlayerName.",
  str_homestory_817702001_8_dialog_content = "เป็นไปได้ไหมว่า... คุณสนใจเครื่องดนตรี?",
  str_homestory_817702001_9_option_content = "ฉัน!",
  str_homestory_817702001_10_dialog_content = "แน่นอน! ฉันรักเครื่องดนตรี!",
  str_homestory_817702001_11_dialog_content = "แต่ฉันเล่นไม่เป็นเลย มันเลยไม่ใช่งานอดิเรกเท่าไหร่ ฮิฮิ...",
  str_homestory_817702001_12_dialog_content = "แต่นั่นก็ยังเป็นสิ่งที่ยอดเยี่ยม!",
  str_homestory_817702001_13_dialog_content = "ดูเหมือนว่าเรามีอีกอย่างที่เหมือนกัน PlayerName!",
  str_homestory_817702001_14_option_content = "ไม่ขนาดนั้น",
  str_homestory_817702001_15_dialog_content = "ฉันจะไม่เรียกมันว่าดอกเบี้ยจริงๆ...",
  str_homestory_817702001_16_dialog_content = "แต่ถ้าฉันเคยหัดเล่นเครื่องดนตรี คุณจะเป็นคนแรกที่ได้ยินมัน!",
  str_homestory_817702001_17_dialog_content = "จริงหรือ ฮี่ฮี่... เป็นเกียรติมาก! ขอบคุณ!",
  str_homestory_817702001_18_dialog_content = "ฉันควรจะพูดถึงบางสิ่งแม้ว่า ...",
  str_homestory_817702001_19_dialog_content = "นี่ไม่ใช่แค่ไวโอลินธรรมดาๆ",
  str_homestory_817702001_20_dialog_content = "มันเป็นส่วนหนึ่งของคอลเลกชันของนักสืบชื่อดัง!",
  str_homestory_817702001_21_dialog_content = "นักสืบ?",
  str_homestory_817702001_22_dialog_content = "ถูกตัอง! เห็นได้ชัดว่านักสืบคนนี้ชอบเล่นมันทุกครั้งที่ไม่ได้สืบสวนคดี",
  str_homestory_817702001_23_dialog_content = "ฉันไม่รู้อะไรมากเกี่ยวกับพวกเขา ...",
  str_homestory_817702001_24_dialog_content = "แต่เป็นนักสืบที่มีความหลงใหลในศิลปะ ฟังดูโรแมนติก <sprite=emo_aixin size=60 />!",
  str_homestory_817702001_25_dialog_content = "ฉันเห็นด้วย!",
  str_homestory_817702001_26_dialog_content = "นักสืบผู้สุขุมและมีเหตุผล ผู้ใช้เวลาทั้งคืนเพียงลำพัง โดยไม่มีอะไรนอกจากไวโอลินเป็นเพื่อน...",
  str_homestory_817702001_27_dialog_content = "เดี๋ยวก่อน... แค่นั้นแหละ! นั่นคือแรงบันดาลใจที่ฉันต้องการ!",
  str_homestory_817702001_28_dialog_content = "แรงบันดาลใจอะไร?",
  str_homestory_817702001_29_dialog_content = "แรงบันดาลใจของฉัน <sprite=emo_yinfu size=60 /> เพลงใหม่!",
  str_homestory_817702001_30_dialog_content = "ฉันจะต้องสั่งชุดใหม่และออกแบบท่าเต้นใหม่ด้วย!",
  str_homestory_817702001_31_dialog_content = "แค่คิดก็ตื่นเต้นแล้ว!",
  str_homestory_817702001_32_dialog_content = "คอนเสิร์ตไอดอลแนวนักสืบเหรอ?",
  str_homestory_817702001_33_dialog_content = "ฉันพนันเลยว่ามันจะฮิตมาก!",
  str_homestory_817702001_34_dialog_content = "ถ้ามีใครดึงมันออกได้ นั่นคือคุณโกลดี้!",
  str_homestory_817702001_35_dialog_content = "ฮิฮิ! หวังว่าจะได้พบคุณในฐานะผู้ชมเมื่อวันนั้นมาถึง!",
  str_homestory_811602001_0_dialog_content = "เฟลอร์ไปทำอะไรที่นั่น?",
  str_homestory_811602001_1_dialog_content = "เฮ้ เฟลอร์! คุณกำลังทำอะไร?",
  str_homestory_811602001_2_dialog_content = "เฮ้ ผู้นำทาง",
  str_homestory_811602001_3_dialog_content = "ฉันกำลังปรับแต่งเครื่องประดับ",
  str_homestory_811602001_4_dialog_content = "หยิบมาเล่นเมื่อกี้...",
  str_homestory_811602001_5_dialog_content = "และมันก็ส่งเสียงดังแปลกๆ",
  str_homestory_811602001_6_dialog_content = "เสียงแปลกๆ?",
  str_homestory_811602001_7_dialog_content = "ถูกตัอง. อาจขันสกรูตัวใดตัวหนึ่งแน่นเกินไป หรืออาจต้องใช้น้ำมันเพียงเล็กน้อย...",
  str_homestory_811602001_8_dialog_content = "ล้อนี้ส่งเสียงดังเอี๊ยดอ๊าด",
  str_homestory_811602001_9_option_content = "อย่างนี้นี่เอง!",
  str_homestory_811602001_10_dialog_content = "เมื่อคุณพูดถึงมันแล้ว เครื่องประดับชิ้นนี้ก็ดูจะธรรมดาไปหน่อย...",
  str_homestory_811602001_11_dialog_content = "ถ้ามันทำเสียงแบบนั้น แสดงว่าชิ้นส่วนของมันเสียหรือเปล่า?",
  str_homestory_811602001_12_dialog_content = "ใช่แล้ว!",
  str_homestory_811602001_13_dialog_content = "คนส่วนใหญ่มีช่วงเวลาที่ยากลำบากในการทำความเข้าใจเรื่องนี้ แต่ดูเหมือนว่าคุณอาจมีความสามารถพิเศษในการซ่อมเครื่องจักร",
  str_homestory_811602001_14_dialog_content = "ย-คุณคิดอย่างนั้นเหรอ? ฮิฮิฮิ...",
  str_homestory_811602001_15_option_content = "ฉันไม่รู้...",
  str_homestory_811602001_16_dialog_content = "นายคิดงั้นเหรอ...?",
  str_homestory_811602001_17_dialog_content = "ปล่อยให้ผู้เชี่ยวชาญเช่นคุณคิดออก เฟลอร์ ฉันหมดหวังเมื่อต้องเจอเรื่องแบบนี้",
  str_homestory_811602001_18_dialog_content = "ฉันเข้าใจแล้ว... ฉันหวังว่าจะได้คุยกับคุณเกี่ยวกับเครื่องจักร แต่ฉันเดาว่านั่นไม่ใช่คำถาม",
  str_homestory_811602001_19_dialog_content = "ไม่ต้องกังวล ฉันยังสามารถแก้ไขสิ่งนี้ได้ด้วยตัวเอง",
  str_homestory_811602001_20_dialog_content = "อืม... ดูเหมือนว่าฉันจะคิดถูก สกรูตัวนี้แน่นเกินไป...",
  str_homestory_811602001_21_dialog_content = "น่าเสียดายที่ฉันไม่มีเครื่องมือที่จะคลายมันในตอนนี้",
  str_homestory_811602001_22_dialog_content = "ฉันจะกลับมาแก้ไขเมื่อพบเครื่องมือที่เหมาะสม โอเค?",
  str_homestory_811602001_23_dialog_content = "แน่นอน เฟลอร์ ขอบคุณอีกครั้ง!",
  str_homestory_811602001_24_dialog_content = "อย่าพูดถึงมัน มันเป็นเพียงสกรูเล็กน้อย",
  str_homestory_811602001_25_dialog_content = "ถึงกระนั้น สกรูตัวเล็กเพียงตัวเดียวอาจหมายถึงโลกแห่งความแตกต่างเมื่อพูดถึงเครื่องจักร คุณรู้หรือไม่?",
  str_homestory_811602001_26_dialog_content = "ขอบคุณพระเจ้า มันก็แค่ของเล่น ถ้ามันเป็นรถเข็นจริงๆ...",
  str_homestory_811602001_27_dialog_content = "ล้อจะพังอยู่แล้ว! ฮ่าฮ่าฮ่า!",
  str_homestory_811602001_28_dialog_content = "ไม่ได้ล้อเล่น. คนธรรมดาอย่างเรารู้แค่ว่าบางอย่างต้องซ่อมเมื่อมันพัง...",
  str_homestory_811602001_29_dialog_content = "ถ้าเครื่องจักรทุกเครื่องสามารถชี้ปัญหาให้เราได้เหมือน Soroz...",
  str_homestory_811602001_30_dialog_content = "งั้นเหรอ?",
  str_homestory_811602001_31_dialog_content = "ถ้าคุณถามฉัน คนเข้าใจยากกว่ามาก <sprite=emo_sikao size=60 />...",
  str_homestory_811602001_32_dialog_content = "อย่าเข้าใจฉันผิด การมอบบุคลิกภาพให้กับเครื่องจักรทุกเครื่องจะเป็นความสำเร็จที่ยิ่งใหญ่...",
  str_homestory_811602001_33_dialog_content = "แต่สิ่งสุดท้ายที่ฉันต้องการคือให้เครื่องจักรโกหกฉันในขณะที่ฉันกำลังทำงานกับมัน!",
  str_homestory_811602001_34_dialog_content = "ฮิฮิ จริงด้วย",
  str_homestory_811602001_35_dialog_content = "ถ้าวันนั้นมาถึง ฉันแน่ใจว่าคุณจะรู้ทันปัญหา",
  str_homestory_808401001_0_dialog_content = "คุณชอบปริศนาเหมือนกัน Istvan?",
  str_homestory_808401001_1_dialog_content = "คุณมาทันเวลา เพื่อนสาวของฉัน",
  str_homestory_808401001_2_dialog_content = "บอกฉันที คุณคิดอย่างไรกับภาพนี้",
  str_homestory_808401001_3_dialog_content = "ฉันจะทำอย่างไร ให้ฉันดู...",
  str_homestory_808401001_4_option_content = "ดูท้าทายไม่น้อย",
  str_homestory_808401001_5_dialog_content = "ฉันคิดว่าเงื่อนงำบางอย่างดูน่าสงสัยเล็กน้อย <sprite=emo_sikao size=60 />.",
  str_homestory_808401001_6_dialog_content = "ฉันพนันได้เลยว่าฉันสามารถคิดออกได้โดยใช้เวลามากกว่านี้!",
  str_homestory_808401001_7_option_content = "ไม่เข้าใจแฮะ",
  str_homestory_808401001_8_dialog_content = "เอ่อ... ฉันแก้ปริศนาไม่เก่งที่สุด <sprite=emo_tanqi size=60 />.",
  str_homestory_808401001_9_dialog_content = "ฉันไม่สามารถคาดศีรษะรอบนี้ได้เลย ...",
  str_homestory_808401001_10_dialog_content = "เข้าใจแล้ว",
  str_homestory_808401001_11_dialog_content = "ขอโทษด้วย. คุณถามคำถามฉันก่อน และฉันก็ตอบด้วยคำถามอื่น",
  str_homestory_808401001_12_dialog_content = "ฉันน่าจะให้คำตอบที่แท้จริงกับคุณได้...",
  str_homestory_808401001_13_dialog_content = "ไม่ เพื่อนของฉัน ฉันไม่ชอบปริศนาเลย",
  str_homestory_808401001_14_dialog_content = "ฮะ? แล้วทำไมคุณยังพยายามที่จะคิดออก!",
  str_homestory_808401001_15_dialog_content = "วางใจได้ เพื่อนสาวของฉัน มีคำอธิบายที่สมเหตุสมผลอย่างยิ่งสำหรับเรื่องนี้",
  str_homestory_808401001_16_dialog_content = "เมื่อพิจารณาจากคำพูดของคุณเองในตอนนี้ คุณคิดว่าภาพนี้เป็นคำใบ้ของปริศนา",
  str_homestory_808401001_17_dialog_content = "ซึ่งหมายความว่าคุณมองจากมุมมองของนักสืบโดยไม่ได้ตั้งใจ",
  str_homestory_808401001_18_dialog_content = "เอ่อ... ถูกต้อง ฉันเดา?",
  str_homestory_808401001_19_dialog_content = "อย่างไรก็ตาม มีตัวละครอีกหลายตัวที่เกี่ยวข้องกับคดีนี้",
  str_homestory_808401001_20_dialog_content = "นักสืบ ผู้กระทำความผิด เหยื่อ...",
  str_homestory_808401001_21_dialog_content = "และแน่นอนผู้ยุยง",
  str_homestory_808401001_22_dialog_content = "ผู้ยุยง?",
  str_homestory_808401001_23_dialog_content = "อย่างแท้จริง. เช่นเดียวกับคนเลี้ยงแกะ ผู้ยุยงมีหน้าที่รับผิดชอบทุกอย่างและได้รับประโยชน์จากมันมากกว่าใครอื่น",
  str_homestory_808401001_24_dialog_content = "เลี้ยงแกะด้วยมืออย่างระมัดระวัง ต้อนฝูงแกะกับสุนัขผู้ซื่อสัตย์ ปกป้องพวกมันจากหมาป่าผู้หิวโหย...",
  str_homestory_808401001_25_dialog_content = "ผู้เลี้ยงแกะที่ดีไม่เคยยอมจำนนต่อฝูงแกะของเขาต่อโชคชะตา",
  str_homestory_808401001_26_dialog_content = "ซึ่งเป็นเหตุผลว่าทำไม แทนที่จะไขปริศนา ผู้ยุยงจึงเลือกคำตอบที่เป็นประโยชน์แก่เขามากที่สุดแทน",
  str_homestory_808401001_27_dialog_content = "ท-ซับซ้อนชะมัด!",
  str_homestory_808401001_28_dialog_content = "แต่ฉันคิดว่าฉันเข้าใจสิ่งที่คุณพยายามจะพูด อิสต์วาน...",
  str_homestory_808401001_29_dialog_content = "สำหรับผู้นำอย่างคุณ บางครั้งความจริงก็ไม่สำคัญเท่ากับผลลัพธ์สุดท้าย จริงไหม?",
  str_homestory_808401001_30_dialog_content = "ทักษะการหักเงินของคุณเฉียบคมเช่นเคย",
  str_homestory_808401001_31_dialog_content = "แม้ว่าคุณจะยังอายุน้อย แต่ความเป็นไปได้ในอนาคตของคุณแทบไม่มีขีดจำกัด",
  str_homestory_808401001_32_dialog_content = "ฉันหวังเพียงว่า Navigator เช่นคุณเรียนรู้วิธีย้ายชิ้นส่วนอื่น ๆ เพื่อประโยชน์ของคุณเอง",
  str_homestory_808401001_33_dialog_content = "การดื่มด่ำกับความสุขของคนธรรมดาคือแกะจำนวนมากไม่ใช่คนเลี้ยงแกะ",
  str_homestory_808401001_34_dialog_content = "ฮี่ฮี่ฮี่... ขอบคุณ แต่ฉันคิดว่ามันยังเร็วเกินไปสำหรับฉันที่จะคิดเรื่องแบบนั้น...",
  str_homestory_808401001_35_dialog_content = "... บางทีคุณอาจพูดถูก การเร่งรีบสิ่งเหล่านี้อาจส่งผลเสียได้ในบางกรณี",
  str_homestory_808401001_36_dialog_content = "ในกรณีนั้น ทำไมฉันไม่เสนองานที่เหมาะสมกับวัยให้มากกว่านี้ล่ะ",
  str_homestory_808401001_37_dialog_content = "ขณะที่ฉันกำลังยืนอยู่ริมแม่น้ำ ฉันสังเกตเห็นเหรียญที่ส่องประกายระยิบระยับอยู่ในน้ำ <sprite=emo_baiyebi size=60 />.",
  str_homestory_808401001_38_dialog_content = "ฉันไม่แน่ใจในตอนนั้น แต่มีโอกาสที่มันจะเป็นเครื่องประดับที่ค่อนข้างหายาก",
  str_homestory_808401001_39_dialog_content = "ทำไมคุณไม่ไปดู",
  str_homestory_808401001_40_dialog_content = "แน่นอน! ขอบคุณ Istvan!",
  str_homestory_819301001_0_dialog_content = "คริสเตน?",
  str_homestory_819301001_1_dialog_content = "ว่าไง คริสเตน?",
  str_homestory_819301001_2_dialog_content = "อืม-อืม-อืม! <sprite=emo_yinfu size=60 />",
  str_homestory_819301001_3_dialog_content = "ไม่มีอะไร แค่ฟังเพลง!",
  str_homestory_819301001_4_dialog_content = "เครื่องเล่นแผ่นเสียงของคุณสวยมาก ฉันเลยต้องลองเล่นดู!",
  str_homestory_819301001_5_dialog_content = "ดังนั้นสิ่งที่คุณคิดว่า?",
  str_homestory_819301001_6_dialog_content = "มันเจ๋งมาก! คุณภาพเสียงน่าทึ่งมาก... คุณเลือกตัวที่ดีจริงๆ!",
  str_homestory_819301001_7_dialog_content = "คุณเป็นคนรักดนตรีมานานแค่ไหนแล้ว PlayerName?",
  str_homestory_819301001_8_dialog_content = "ฉันค่อนข้างชอบฟังเพลงอยู่แล้ว แต่ฉันมักจะหยิบจับสิ่งที่น่าสนใจในระหว่างการเดินทางของฉัน... ชอบเครื่องเล่นแผ่นเสียงนี้จัง!",
  str_homestory_819301001_9_dialog_content = "แม้ว่าฉันจะแน่ใจว่าไม่มีอะไรเทียบได้กับคอลเลกชันของคุณเอง",
  str_homestory_819301001_10_dialog_content = "บ้านของครอบครัวฉันมีคอลเลคชันเครื่องเล่นเพลงมากมายทีเดียว... หนึ่งในนั้นมีขนาดใหญ่มากด้วย!",
  str_homestory_819301001_11_dialog_content = "ฉันจะเดิมพัน ...",
  str_homestory_819301001_12_dialog_content = "มันคงสูงพอๆกับประตูทางเข้า Hall of Justice",
  str_homestory_819301001_13_dialog_content = "อ-อะไรกัน?!",
  str_homestory_819301001_14_dialog_content = "ทางเข้า Hall of Justice... ใหญ่โตมาก!",
  str_homestory_819301001_15_dialog_content = "คุณอาจจะจัดคอนเสิร์ตใหญ่ขนาดนั้นก็ได้!",
  str_homestory_819301001_16_dialog_content = "พ่อของฉันเป็นหนึ่งในขุนนางประเภทนักสะสม รู้ไหม? บางครั้งมันก็หลุดมือไปเล็กน้อย!",
  str_homestory_819301001_17_dialog_content = "แต่คุณก็เป็นขุนนางเหมือนกัน คริสเตน...",
  str_homestory_819301001_18_dialog_content = "ใช่ แต่ฉันกับพ่อต่างกัน!",
  str_homestory_819301001_19_dialog_content = "หรือคุณคิดว่าฉันเป็นเหมือนขุนนางเก่าที่น่าเบื่อคนหนึ่ง?",
  str_homestory_819301001_20_option_content = "คุณไม่!",
  str_homestory_819301001_21_dialog_content = "คุณมักจะมองหาสิ่งใหม่ ๆ และเป็นที่นิยมอยู่เสมอ",
  str_homestory_819301001_22_dialog_content = "เช่น เพลง เป็นต้น!",
  str_homestory_819301001_23_option_content = "ก็นิดหน่อยน่ะครับ...",
  str_homestory_819301001_24_dialog_content = "ฉันหมายความว่า คุณมีการศึกษาดีจริงๆ เหมือนกับขุนนางทุกคนที่ฉันเคยพบ",
  str_homestory_819301001_25_dialog_content = "ฮิฮิ! คุณคิดอย่างนั้นจริงๆ PlayerName?",
  str_homestory_819301001_26_dialog_content = "ไม่สามารถพูดได้ว่าฉันไม่เห็นด้วย",
  str_homestory_819301001_27_dialog_content = "ใช่ การเกิดของฉันทำให้ฉันเป็นส่วนหนึ่งของชนชั้นสูงและ...",
  str_homestory_819301001_28_dialog_content = "แต่ในใจของฉัน ฉันต้องการมีชีวิตของตัวเอง ตามเงื่อนไขของฉันเอง!",
  str_homestory_819301001_29_dialog_content = "และเพลงใหม่นี้ทำให้ฉันมีแรงบันดาลใจที่จะเดินหน้าต่อไป!",
  str_homestory_819301001_30_dialog_content = "เดี๋ยวนะ!",
  str_homestory_819301001_31_dialog_content = "ย-เธอจะแสดงที่นี่เหรอ คริสเตน? ตอนนี้?!",
  str_homestory_819301001_32_dialog_content = "ถูกตัอง! เพลงนี้เหมาะสำหรับการตีโน้ตสูงๆ ด้วยเช่นกัน! ลั้ลลา— <sprite=emo_yinfu size=60 />",
  str_homestory_819301001_33_dialog_content = "H-เดี๋ยวก่อน!",
  str_homestory_819301001_34_dialog_content = "อ๋อ จะดูเวลาเหรอ? ฉันลืมไปเสียสนิทว่าฉันมีเรื่องสำคัญที่ต้องทำ! แล้วเจอกัน!",
  str_homestory_819301001_35_dialog_content = "R-ตอนนี้เหรอ?",
  str_homestory_819301001_36_dialog_content = "ใช่! แต่ไปข้างหน้าและสนุกกับเครื่องเล่นแผ่นเสียง! ลาก่อน!",
  str_homestory_819201001_0_dialog_content = "สิงห์?",
  str_homestory_819201001_1_dialog_content = "ฉันแค่มองหาแว่นขยาย และนี่คือ",
  str_homestory_819201001_2_dialog_content = "คุณจะใช้มันเพื่ออะไร?",
  str_homestory_819201001_3_dialog_content = "เพื่อดูแผนที่นี้",
  str_homestory_819201001_4_dialog_content = "ผู้ใต้บังคับบัญชาของฉันสำรวจตำแหน่งของป้อมทหารต่างๆ ตามแนวชายแดน เมื่อเร็วๆ นี้",
  str_homestory_819201001_5_dialog_content = "พวกเขาเพิ่งวาดแผนที่นี้เสร็จในวันนี้และส่งไปให้",
  str_homestory_819201001_6_dialog_content = "แต่ลายมือบนแผนที่นี้สกปรกและเล็กมาก มันทำให้ฉันปวดหัว <sprite=emo_xuanyun size=60 />",
  str_homestory_819201001_7_dialog_content = "มีหลายคำที่เขียนบนแผนที่หรือไม่?",
  str_homestory_819201001_8_dialog_content = "ดูด้วยตัวคุณเอง",
  str_homestory_819201001_9_dialog_content = "\"การแสดงการสำรวจและการวิเคราะห์ป้อมปราการทางทหารในระยะ 80 กิโลเมตรในช่วงพลบค่ำ...\"",
  str_homestory_819201001_10_dialog_content = "นอกจากนี้ยังมีบรรทัดที่สอง",
  str_homestory_819201001_11_dialog_content = "\"... และข้อมูลรายละเอียด เช่น การกระจายเชิงพื้นที่ ปริมาณ ลักษณะเชิงคุณภาพ และความสัมพันธ์\"",
  str_homestory_819201001_12_dialog_content = "ฮึ่ม...ฮึ่ม... <sprite=emo_kun size=60 />",
  str_homestory_819201001_13_dialog_content = "D-ชื่อแผนที่ทั้งหมด...ซับซ้อนจัง?",
  str_homestory_819201001_14_dialog_content = "อ่านรวดเดียวแทบหยุดหายใจ",
  str_homestory_819201001_15_dialog_content = "แน่นอนว่าไม่จำเป็นต้องซับซ้อนขนาดนี้ แต่คราวนี้คนเขียนแผนที่ละเอียดมาก ดังนั้นเขาจึงเขียนให้มากที่สุดเท่าที่จะทำได้...",
  str_homestory_819201001_16_dialog_content = "มันไม่จำเป็นจริงๆ",
  str_homestory_819201001_17_dialog_content = "ไม่น่าแปลกใจที่นักยุทธศาสตร์หลายคนพกแว่นขยายติดตัวไปด้วย",
  str_homestory_819201001_18_dialog_content = "หากพวกเขาเคยต้องพึ่งพานักทำแผนที่ที่ละเอียดถี่ถ้วนเช่นเดียวกับผู้ชายคนนี้ แว่นขยายคือความหวังเดียวที่พวกเขาจะสามารถอ่านแผนที่ของพวกเขาได้อย่างชัดเจน",
  str_homestory_819201001_19_dialog_content = "(แต่แม้หลังจากสามารถอ่านชื่อที่ตลกขบขันนี้ได้แล้ว คุณคงจะหงุดหงิดยิ่งกว่านี้อีก)",
  str_homestory_819201001_20_dialog_content = "มีผู้นำหลายคนที่ชอบใช้แว่นขยาย",
  str_homestory_819201001_21_dialog_content = "ไม่เพียงขยายข้อความและรูปภาพและช่วยในการสังเกตเท่านั้น แต่ยังสามารถช่วยในการจุดไฟเมื่อดวงอาทิตย์ส่องแสง",
  str_homestory_819201001_22_dialog_content = "อาจกล่าวได้ว่าเป็นเครื่องมืออเนกประสงค์ที่จำเป็นสำหรับกองทหารในการเดินทัพ",
  str_homestory_819201001_23_dialog_content = "อย่างไรก็ตาม ฉันมีข้อสงวนเกี่ยวกับแว่นขยาย",
  str_homestory_819201001_24_dialog_content = "ทำไมละ",
  str_homestory_819201001_25_dialog_content = "คุณเองก็เป็นผู้บัญชาการในการสู้รบ บางทีคุณอาจเดาสาเหตุได้?",
  str_homestory_819201001_26_option_content = "พวกเขาขึ้นอยู่กับแสง",
  str_homestory_819201001_27_dialog_content = "ใช้งานยากในเวลากลางคืนหรือในที่มืด",
  str_homestory_819201001_28_dialog_content = "นี่เป็นปัญหาอย่างแท้จริง แต่ตราบใดที่มีแหล่งกำเนิดแสง ก็สามารถหลีกเลี่ยงปัญหานี้ได้",
  str_homestory_819201001_29_option_content = "พวกมันสามารถจำกัดขอบเขตการมองเห็นของคุณได้",
  str_homestory_819201001_30_dialog_content = "ก็จริงนะ",
  str_homestory_819201001_31_dialog_content = "แว่นขยายจะขยายพื้นที่ ให้ผู้สังเกตเห็นรายละเอียดได้แม่นยำยิ่งขึ้น",
  str_homestory_819201001_32_dialog_content = "แต่ในขณะเดียวกันขอบเขตการมองเห็นของผู้สังเกตก็จำกัดอยู่ในขอบเขตของแว่นขยาย",
  str_homestory_819201001_33_dialog_content = "สิ่งนี้ทำให้ไม่สามารถสังเกตสภาพแวดล้อมที่กว้างขึ้นรอบตัวพวกเขาได้",
  str_homestory_819201001_34_dialog_content = "แต่การทำสงครามมักจะต้องใช้กองกำลังจากมุมมองที่กว้างขึ้น",
  str_homestory_819201001_35_dialog_content = "บางครั้งฉันจงใจหลีกเลี่ยงการใช้แว่นขยายเพื่อป้องกันไม่ให้ลานสายตาของฉันโฟกัสมากเกินไป",
  str_homestory_819201001_36_dialog_content = "คุณเป็นนักยุทธศาสตร์ที่สร้างแรงบันดาลใจอย่างแท้จริง",
  str_homestory_819201001_37_dialog_content = "มันเป็นแค่นิสัยส่วนตัว ตัวอย่างเช่น ฉันไม่มีทางเลือกอื่นนอกจากขอแว่นขยายในสถานการณ์ปัจจุบันของเรา",
  str_homestory_819201001_38_dialog_content = "คุณสามารถใช้แว่นขยายที่นี่ได้ทุกเมื่อที่คุณต้องการ",
  str_homestory_819201001_39_dialog_content = "แต่โปรดแน่ใจว่าคุณใส่กลับเข้าไปในกล่องหลังจากใช้งานเสร็จ",
  str_homestory_819201001_40_dialog_content = "หากโดนแสงแดดโดยตรงอาจทำให้เกิดไฟไหม้ได้ <sprite=emo_nuhuo size=60 />",
  str_homestory_819201001_41_dialog_content = "ฮ่าฮ่า เป็นเรื่องดีที่คุณมีความรู้เรื่องความปลอดภัยจากอัคคีภัย",
  str_homestory_819201001_42_dialog_content = "ท้ายที่สุด ฉันทำงานอย่างหนักเพื่อทำให้ที่นี่เป็นที่ที่ฉันสามารถเรียกว่าบ้านได้",
  str_homestory_819201001_43_dialog_content = "ถ้าเงินทั้งหมดของฉันลุกเป็นไฟ... เอาล่ะ การทำงานหนักของฉันก็จะสูญเปล่า",
  str_homestory_819901001_0_dialog_content = "อิงเกล?",
  str_homestory_819901001_1_dialog_content = "โอ้, PlayerName. ฉันกำลังจะลองกาแฟตัวนี้",
  str_homestory_819901001_2_dialog_content = "คุณชงเองหรือเปล่า",
  str_homestory_819901001_3_dialog_content = "นั่นสินะ",
  str_homestory_819901001_4_dialog_content = "เมื่อกี้เห็นแก้วกาแฟสวยๆ เลยคิดว่าจะลองชงเองดูบ้าง",
  str_homestory_819901001_5_dialog_content = "มันมีกลิ่นที่น่าทึ่ง! <sprite=emo_dianzan size=60 />",
  str_homestory_819901001_6_dialog_content = "เห็นลวดลายบนพื้นผิวไหม? นี่สินะที่เขาเรียกว่าลาเต้อาร์ต",
  str_homestory_819901001_7_dialog_content = "ใช่ ฉันเห็นแล้ว! มันสวย!",
  str_homestory_819901001_8_dialog_content = "ทรงนี้แบบว่า...อ๊าาา?",
  str_homestory_819901001_9_dialog_content = "คุณสามารถบอกได้ว่าเป็น Aoha? ฉันคิดว่าฉันไม่สามารถเรียกความพยายามนี้ว่าล้มเหลวได้แล้ว",
  str_homestory_819901001_10_dialog_content = "แน่นอนว่าไม่ใช่ความล้มเหลว! มันเหลือเชื่อ!",
  str_homestory_819901001_11_dialog_content = "คุณทำมันได้อย่างไร Yingel?",
  str_homestory_819901001_12_dialog_content = "การทำลาเต้ไม่ใช่เรื่องยากเลย และส่วนผสมก็ธรรมดามาก",
  str_homestory_819901001_13_dialog_content = "ก่อนอื่นคุณต้องเทเอสเปรสโซถ้วยเล็ก ๆ ลงในแก้วกาแฟ...",
  str_homestory_819901001_14_dialog_content = "จากนั้นตีฟองนมสดแล้วเติมลงในเอสเปรสโซ่",
  str_homestory_819901001_15_dialog_content = "เมื่อใส่โฟมแล้วให้ปรับรูปทรงโดยเลื่อนถ้วยนม",
  str_homestory_819901001_16_dialog_content = "และเช่นเดียวกันคุณควรจะได้ลาเต้ที่มีลวดลายสวยงาม",
  str_homestory_819901001_17_dialog_content = "คุณทำให้มันฟังดูง่าย แต่ฉันแน่ใจว่ามันไม่ง่ายอย่างที่คิด...",
  str_homestory_819901001_18_dialog_content = "ฝึกฝนบ่อยๆทำให้เก่ง. ลองสักครั้งแล้วคุณจะสบายดี",
  str_homestory_819901001_19_dialog_content = "เมื่อไหร่ก็ตามที่ฉันรู้สึกเหนื่อยจากการทำงาน ฉันจะชงลาเต้ให้ตัวเอง",
  str_homestory_819901001_20_dialog_content = "นมปั่นกับกาแฟกลมกล่อมเป็นอะไรที่เข้ากันสุดๆ",
  str_homestory_819901001_21_dialog_content = "PlayerNameคุณต้องการลองดูไหม<sprite=emo_yaosu size=60 />",
  str_homestory_819901001_22_option_content = "แน่นอนสิ",
  str_homestory_819901001_23_dialog_content = "ท้ายที่สุดคุณทำกาแฟด้วยตัวเอง",
  str_homestory_819901001_24_option_content = "ไม่",
  str_homestory_819901001_25_dialog_content = "ถ้าฉันดื่มกาแฟตอนนี้ ฉันเกรงว่าจะนอนไม่หลับ",
  str_homestory_819901001_26_dialog_content = "มีนมมากกว่าสองในสาม ดังนั้นจะไม่ให้คุณตื่น",
  str_homestory_819901001_27_dialog_content = "จริงหรือ ในกรณีนั้น ฉันชอบที่จะลองดู",
  str_homestory_819901001_28_dialog_content = "เป็นไงบ้างครับ?",
  str_homestory_819901001_29_dialog_content = "รสชาติให้สิบเต็มสิบค่ะ!",
  str_homestory_819901001_30_dialog_content = "ถ้าฉันทำลาเต้ได้อร่อยขนาดนี้",
  str_homestory_819901001_31_dialog_content = "คุณควรลองทำดู—ฉันรู้ว่าคุณทำได้",
  str_homestory_819901001_32_dialog_content = "แต่ดูเหมือนนมจะหมดแล้ว...",
  str_homestory_819901001_33_dialog_content = "อะไรนะ มันหายไปหมดแล้วเหรอ?",
  str_homestory_819901001_34_dialog_content = "ตอนนี้ฉันกระหายน้ำมาก ฉันเลยดื่มมันจนหมด",
  str_homestory_819901001_35_dialog_content = "เอิ่ม ยัยเกล... เอาแต่ซดนมเหมือนน้ำเปล่าไม่ได้นะ...",
  str_homestory_820001001_0_dialog_content = "อนาโตลีกำลังจ้องมองที่ตะเกียงกลางแจ้งนั่นหรือ?",
  str_homestory_820001001_1_dialog_content = "คุณกำลังทำอะไร อนาโตลี?",
  str_homestory_820001001_2_dialog_content = "ฉันกำลังสังเกตโคมไฟนี้อยู่",
  str_homestory_820001001_3_option_content = "สังเกตโคมไฟ?",
  str_homestory_820001001_4_dialog_content = "ฉันพบว่ามันยังคงเปิดอยู่แม้ในระหว่างวัน",
  str_homestory_820001001_5_dialog_content = "แม้ว่าแสงที่ปล่อยออกมาจะสว่างน้อยกว่าแสงแดดมาก แต่ก็ไม่เคยดับลง",
  str_homestory_820001001_6_dialog_content = "มีคนคอยเติมน้ำมันตะเกียงอยู่เรื่อยๆ หรือเปล่า?",
  str_homestory_820001001_7_dialog_content = "เอ่อ ฉันก็ไม่รู้คำตอบเหมือนกัน...",
  str_homestory_820001001_8_option_content = "ทำไมละ",
  str_homestory_820001001_9_dialog_content = "เพราะมันเปิดตลอดเวลาทั้งกลางวันและกลางคืน",
  str_homestory_820001001_10_dialog_content = "แม้จะไม่เด่นในตอนกลางวัน แต่ก็ส่องสว่างในความมืดในตอนกลางคืน <sprite=emo_taiyang size=60 />",
  str_homestory_820001001_11_dialog_content = "ถูกต้อง!",
  str_homestory_820001001_12_dialog_content = "มันดีมากที่มีไฟส่องสว่างตามท้องถนนในตอนกลางคืน!",
  str_homestory_820001001_13_dialog_content = "อย่างไรก็ตาม...การเปิดไฟทิ้งไว้ในตอนกลางวันดูจะสิ้นเปลืองไปสักหน่อย",
  str_homestory_820001001_14_dialog_content = "ครับ...มีแน่นอนครับ",
  str_homestory_820001001_15_dialog_content = "ท้ายที่สุด นี่ไม่ใช่ Eternal Night... ไม่จำเป็นต้องเปิดไฟตลอดเวลา",
  str_homestory_820001001_16_dialog_content = "ตอนนี้ฉันจะดับมันและจุดไฟให้สว่างขึ้นในตอนเย็น",
  str_homestory_820001001_17_dialog_content = "มันจะดีกว่าถ้าคุณเก็บไว้",
  str_homestory_820001001_18_dialog_content = "หือ? ทำไมล่ะ?",
  str_homestory_820001001_19_dialog_content = "เราอาจไม่รู้ว่าใครเป็นคนเติมน้ำมันในตะเกียงนี้ แต่พวกเขาต้องมีเหตุผล",
  str_homestory_820001001_20_dialog_content = "จะดีกว่าถ้าเราไม่รบกวนกิจวัตรของพวกเขา",
  str_homestory_820001001_21_dialog_content = "ที่พูดมาก็มีเหตุผล",
  str_homestory_820001001_22_dialog_content = "อยากรู้จริงๆ ว่าบุคคลปริศนาคนนี้คือใคร!",
  str_homestory_820001001_23_dialog_content = "ลองสังเกตให้มากขึ้น แล้ววันหนึ่งคุณจะพบพวกเขา",
  str_homestory_820001001_24_dialog_content = "ฉันจำได้ว่าคุณเป็นอัจฉริยะตัวจริงในเรื่องของการใช้เหตุผลและการวิเคราะห์...",
  str_homestory_820001001_25_dialog_content = "คุณมีความคิดเกี่ยวกับไฟแช็กลึกลับของใครบ้าง?",
  str_homestory_820001001_26_dialog_content = "ฉันมีการคาดเดาของฉัน",
  str_homestory_820001001_27_dialog_content = "เช่นอะไร?",
  str_homestory_820001001_28_dialog_content = "ต้องเป็นคนที่อดทนมาก ยืนหยัดทำสิ่งใดสิ่งหนึ่งได้นาน",
  str_homestory_820001001_29_dialog_content = "และพวกเขาควรมีความทรงจำที่ดี เพราะพวกเขาไม่เคยลืมงานเล็กน้อยเช่นนี้เลย",
  str_homestory_820001001_30_dialog_content = "ประการสุดท้าย พวกเขาดูจะชอบวัตถุที่เปล่งแสงพอประมาณมาก",
  str_homestory_820001001_31_dialog_content = "ใช่ มันสมเหตุสมผลแล้ว...",
  str_homestory_820001001_32_dialog_content = "มันทำให้ฉันนึกถึงคนไม่กี่คน",
  str_homestory_820001001_33_dialog_content = "เดี๋ยวก่อน ฉันได้มันแล้ว!",
  str_homestory_820001001_34_dialog_content = "คุณไม่ได้แค่พูดถึงตัวเองเหรอ!",
  str_homestory_820001001_35_dialog_content = "การหักเงินที่ยอดเยี่ยม",
  str_homestory_820001001_36_dialog_content = "เหตุใดคุณจึงจุดไฟนี้ไว้",
  str_homestory_820001001_37_dialog_content = "นี่มันกลางวันชัดๆเลยไม่ต้องใช้หลอดไฟ...",
  str_homestory_820001001_38_dialog_content = "แม้ว่าแสงริบหรี่ที่จางที่สุดอาจดูเหมือนแทบไม่เห็นในแสงแดด แต่ก็ยังมีบางอย่างที่ทำได้เท่านั้น",
  str_homestory_820001001_39_dialog_content = "นี่คือสิ่งที่ฉันเชื่อ",
  str_homestory_802801001_0_dialog_content = "ฉันรู้จักเสียงนั้น...",
  str_homestory_802801001_1_dialog_content = "ราฟาเอล!",
  str_homestory_802801001_2_dialog_content = "หวือ! หวือ! หวือ!",
  str_homestory_802801001_3_dialog_content = "PlayerName! ดีใจที่ได้พบคุณ!",
  str_homestory_802801001_4_dialog_content = "เฮ้! ลองยา Brain Booster ใหม่ของฉัน!",
  str_homestory_802801001_5_dialog_content = "สิ่งเล็กน้อยเหล่านี้สามารถเติมพลังให้คุณได้ทันที! พวกเขาอาจทำให้คุณรู้สึกถึงการมีอยู่ของสมบัติลึกลับ!",
  str_homestory_802801001_6_dialog_content = "รุ่นลิมิเต็ด! อย่าพลาดโอกาสครั้งหนึ่งในชีวิตนี้!",
  str_homestory_802801001_7_option_content = "ฉันไม่คิดว่าฉันต้องการมัน ขอบคุณ...",
  str_homestory_802801001_8_dialog_content = "ฉันค้นหาอย่างสูงและต่ำมาระยะหนึ่งแล้ว และในที่สุดฉันก็พบคุณ!",
  str_homestory_802801001_9_dialog_content = "คุณไม่ต้องการให้การทดลองเล็ก ๆ ของฉันล้มเหลวใช่ไหม",
  str_homestory_802801001_10_dialog_content = "บอกตามตรงว่าฉันไม่ได้คิดเรื่องนั้นเลย...",
  str_homestory_802801001_11_option_content = "ให้ฉันลองดูสิ!",
  str_homestory_802801001_12_dialog_content = "ฮิฮิ! วันนี้คุณอารมณ์ดีอย่างไม่คาดคิด PlayerName!",
  str_homestory_802801001_13_dialog_content = "ฉันจะนำมาให้คุณอีกในวันพรุ่งนี้!",
  str_homestory_802801001_14_dialog_content = "เอิ่ม... ช่วงนี้ไม่มีอะไรทำจริงๆ เหรอ?",
  str_homestory_802801001_15_dialog_content = "เปิดปากบอกเลยว่า “อื้อหือ”!",
  str_homestory_802801001_16_dialog_content = "ว-เดี๋ยวก่อน!",
  str_homestory_802801001_17_dialog_content = "กลิ่นนั้น... นั่นไม่ใช่อาหารของ Vice เหรอ?",
  str_homestory_802801001_18_dialog_content = "(เอ่อ พวกที่ถูกไฟไหม้... <sprite=emo_hanshui size=60 />)",
  str_homestory_802801001_19_dialog_content = "ฮะ?! คุณไม่เชื่อใจฉันเหรอ",
  str_homestory_802801001_20_dialog_content = "เอิ่ม... ฉันหมายความว่า... คุณเห็น...",
  str_homestory_802801001_21_dialog_content = "ฉันเข้าใจ ฉันเข้าใจ! คุณชอบเพื่อนที่ไว้ใจได้ ไว้ใจได้ ใช่ไหม PlayerName?",
  str_homestory_802801001_22_dialog_content = "ฉันพยายามอย่างดีที่สุดเพื่อเป็นเพื่อนคู่คิดที่ไว้ใจได้!",
  str_homestory_802801001_23_dialog_content = "ผู้ที่สามารถทำยา Brain Booster—",
  str_homestory_802801001_24_dialog_content = "ฮิฮิ แต่ฉันไม่ควรโม้เลยจริงๆ",
  str_homestory_802801001_25_dialog_content = "(เธอมองโลกในแง่ดีอย่างน่าประหลาดใจ...)",
  str_homestory_802801001_26_dialog_content = "เอาไงดี ราฟาเอล—เธอไปทำอย่างอื่นเพิ่มสิ แล้ววันหลังให้คาร์ลีนลองดูก็ได้!",
  str_homestory_802801001_27_dialog_content = "เธอทำงานหนักมากเสมอ... เธออาจจะชอบ Brain Boosters บางคนจริงๆ",
  str_homestory_802801001_28_dialog_content = "ฮะ? คาร์ลีน?",
  str_homestory_802801001_29_dialog_content = "ฉันไม่คิดอย่างนั้น!",
  str_homestory_802801001_30_dialog_content = "เธอหมายความว่าไง",
  str_homestory_802801001_31_dialog_content = "เพราะถ้าฉันพาพวกเขาไปหาคาร์ลีน ฉันรู้ว่าเธอจะบอกว่า—",
  str_homestory_802801001_32_dialog_content = "“ราฟาเอล! อย่ากล้าให้ขนมแปลก ๆ ของคุณกับฉันอีก - และอย่าถามว่าทำไม”",
  str_homestory_802801001_33_dialog_content = "ทำไมละ",
  str_homestory_802801001_34_dialog_content = "ฉันหวังว่าฉันจะรู้! <sprite=emo_sikao size=60 /> แต่คาร์ลีนไม่ให้ฉันถามด้วยซ้ำ",
  str_homestory_802801001_35_dialog_content = "เออใช่ แล้วก็...",
  str_homestory_802801001_36_dialog_content = "ยาเหล่านี้ถูกสร้างขึ้นมาโดยเฉพาะสำหรับคุณและความสามารถทางจิตของคุณ PlayerName!",
  str_homestory_802801001_37_dialog_content = "เอาล่ะ ฉันเข้าใจแล้ว...",
  str_homestory_802801001_38_dialog_content = "(ถ้าเป็นแค่ขนม...)",
  str_homestory_802801001_39_dialog_content = "ฮิฮิ! ฉันรู้ว่ามันสมบูรณ์แบบสำหรับคุณ PlayerName!",
  str_homestory_802801001_40_dialog_content = "แล้วเป็นยังไงบ้าง...? เป็นยังไงบ้าง?! คุณสังเกตเห็นการเปลี่ยนแปลงหรือไม่?",
  str_homestory_802801001_41_dialog_content = "คุณเคยเห็นอะไรแวววาวไหม? ชอบสมบัติ?",
  str_homestory_802801001_42_dialog_content = "การมองเห็นของฉันชัดเจนขึ้น และฉันมองเห็นได้ไกลขึ้น—",
  str_homestory_802801001_43_dialog_content = "ในแม่น้ำ! มีบางสิ่งที่แวววาวอยู่ในแม่น้ำ!",
  str_homestory_802801001_44_dialog_content = "ใช่! ในแม่น้ำ! ฉันรู้แล้ว!",
  str_homestory_802801001_45_dialog_content = "การทดลอง Brain Booster ของฉันประสบความสำเร็จ! <sprite=emo_aixin size=60 />",
  str_homestory_820201001_0_dialog_content = "นายมาทำอะไรที่นี่",
  str_homestory_820201001_1_dialog_content = "อยู่นี่ไง.",
  str_homestory_820201001_2_dialog_content = "บัลลังก์นี้ตั้งขึ้นเพื่อเราโดยเฉพาะหรือ?",
  str_homestory_820201001_3_dialog_content = "นั่นสิ...",
  str_homestory_820201001_4_dialog_content = "ฉันเห็นด้วยกับความคิด",
  str_homestory_820201001_5_dialog_content = "แม้ว่าจะไม่ได้อยู่ในระดับบัลลังก์ที่แท้จริงในสวนลุมโปลิส...",
  str_homestory_820201001_6_dialog_content = "อย่างไรก็ตาม มันก็เพียงพอแล้วสำหรับสถานะของฉัน",
  str_homestory_820201001_7_dialog_content = "ดีใจที่คุณชอบมัน!",
  str_homestory_820201001_8_dialog_content = "คุณต้องการอะไรอีกไหม",
  str_homestory_820201001_9_dialog_content = "แล้วการสร้างพระราชวังลูโมโปลิสแห่งใหม่ที่นี่ล่ะ? <sprite=emo_sikao size=60 />",
  str_homestory_820201001_10_dialog_content = "เนื่องจากเรามีราชสมบัติอยู่แล้ว ก็อาจสร้าง พระราชวังขึ้นตามเสด็จด้วยก็ได้",
  str_homestory_820201001_11_dialog_content = "คุณต้องการสร้างพระราชวังที่นี่หรือไม่?",
  str_homestory_820201001_12_dialog_content = "ฉันไม่คิดว่ามีที่ว่างพอ...",
  str_homestory_820201001_13_dialog_content = "อืม เป็นเรื่องจริง มันยังใหญ่ไม่พอ",
  str_homestory_820201001_14_dialog_content = "แล้วการปรับปรุงที่ได้รับทุนจากฉันล่ะ?",
  str_homestory_820201001_15_option_content = "ไม่เป็นไร",
  str_homestory_820201001_16_dialog_content = "ฉันชื่นชมความคิด",
  str_homestory_820201001_17_option_content = "คุณจะ?",
  str_homestory_820201001_18_dialog_content = "นอกจากวัสดุแล้ว ยังต้องใช้แรงงานจำนวนมากในการขยายอีกด้วย",
  str_homestory_820201001_19_dialog_content = "ฉันไม่คิดว่าโครงการนี้จะรับประกันได้หากคุณแค่แวะมาเป็นครั้งคราว",
  str_homestory_820201001_20_dialog_content = "มันเป็นเรื่องเล็กน้อยสำหรับฉัน",
  str_homestory_820201001_21_dialog_content = "แต่เราสามารถลืมมันได้ถ้าคุณไม่ต้องการมัน",
  str_homestory_820201001_22_dialog_content = "เดี๋ยวก่อน ฉันคิดว่าฉันได้กลิ่นอะไรบางอย่าง... <sprite=emo_wuzui size=60 />",
  str_homestory_820201001_23_dialog_content = "มันคืออะไร? กลิ่นแปลกๆ?",
  str_homestory_820201001_24_dialog_content = "ฉันไม่ได้กลิ่นอะไรเลย",
  str_homestory_820201001_25_dialog_content = "นั่นคือสิ่งที่ขาดหายไป",
  str_homestory_820201001_26_dialog_content = "คุณควรเพิ่มกลิ่นหอมเพื่อทำให้อากาศมีกลิ่นที่สะอาดและสะอาดขึ้น",
  str_homestory_820201001_27_dialog_content = "ฉันไม่ค่อยสนใจเรื่องกลิ่น...",
  str_homestory_820201001_28_dialog_content = "หากนักท่องเที่ยวไม่รู้สึกถึงบรรยากาศหรูหราเมื่อมาที่นี่...",
  str_homestory_820201001_29_dialog_content = "ผิดมารยาทอย่างแรง!",
  str_homestory_820201001_30_dialog_content = "ในกรณีนี้ ฉันจะหาคนมาจัดการ",
  str_homestory_820201001_31_dialog_content = "ฉันหวังว่าจะเห็นการเปลี่ยนแปลงเมื่อฉันไปอีกครั้ง",
  str_homestory_820201001_32_dialog_content = "ได้สิ...",
  str_homestory_820301001_0_dialog_content = "จาคีน?",
  str_homestory_820301001_1_dialog_content = "อ้อเหรอ...",
  str_homestory_820301001_2_dialog_content = "เธอกำลังทำอะไรน่ะ",
  str_homestory_820301001_3_dialog_content = "อะไรนะ... คุณอยู่ที่นี่มานานแค่ไหนแล้ว?",
  str_homestory_820301001_4_dialog_content = "คุณเห็นการอ่านที่ฉันเพิ่งอ่านไหม",
  str_homestory_820301001_5_dialog_content = "เพิ่งเข้ามาไม่เห็นมีอะไรเลย",
  str_homestory_820301001_6_dialog_content = "คุณกำลังอ่านหนังสือสำหรับสิ่งที่เป็นส่วนตัวมากหรือไม่?",
  str_homestory_820301001_7_dialog_content = "ฉันขอโทษ ฉันจะออกไปเดี๋ยวนี้",
  str_homestory_820301001_8_dialog_content = "มันเป็นสิ่งที่เป็นส่วนตัวมาก อย่างไรก็ตาม...",
  str_homestory_820301001_9_dialog_content = "มันเกี่ยวข้องกับคุณ",
  str_homestory_820301001_10_dialog_content = "กับฉัน?",
  str_homestory_820301001_11_dialog_content = "ใช่. ฉันได้ยินบทสนทนาที่คุณมีกับ Vice",
  str_homestory_820301001_12_dialog_content = "ช่วงนี้คุณมีปัญหาทางการเงิน?",
