  str_homestory_820301001_14_dialog_content = "ฉันกังวล ฉันเลยอ่านหนังสือให้คุณฟัง",
  str_homestory_820301001_15_dialog_content = "ถ้าคุณไม่อยากรู้ ฉันจะเก็บผลลัพธ์ไว้เป็นความลับ",
