  str_homestory_820301001_22_dialog_content = "ฮะ? คุณโกหกฉันเหรอ",
  str_homestory_820301001_23_dialog_content = "แค่ตอบมาว่าเชื่อไหม?",
  str_homestory_820301001_24_option_content = "ฉันทำ",
  str_homestory_820301001_25_dialog_content = "ได้เลย! นั่นคือทัศนคติที่ดีที่สุด!",
  str_homestory_820301001_26_option_content = "ฉันไม่",
  str_homestory_820301001_27_dialog_content = "ทำไมจะไม่ล่ะ? คุณกำลังทำให้ฉันโกรธตอนนี้!",
