  str_homestory_820301001_37_dialog_content = "แต่ไม่ว่าอย่างไรก็ตาม ฉันมองเห็นอนาคตที่สดใสสำหรับคุณ <sprite=emo_taiyang size=60 />.",
  str_homestory_820301001_38_dialog_content = "เข้าใจแล้วครับ",
  str_homestory_820301001_39_dialog_content = "อนาคตเต็มไปด้วยตัวแปร แต่ทั้งหมดขึ้นอยู่กับที่นี่และเดี๋ยวนี้",
  str_homestory_820301001_40_dialog_content = "ว้าว เยี่ยมมาก... ฉันต้องเขียนมันลงในบันทึกของฉัน",
