  str_homestory_807501001_14_dialog_content = "ฉันสามารถบอกได้ว่ามันมีเกียร์ภายในที่ซับซ้อนและการเดินสายไฟภายนอก",
  str_homestory_807501001_15_dialog_content = "ฉันไม่คิดว่าไฟถนนใน Lumopolis จะทำงานแบบนั้น...",
  str_homestory_807501001_16_dialog_content = "ฉันบอกคุณแล้วคุณคงไม่เข้าใจ",
  str_homestory_807501001_17_dialog_content = "ไม่ คุณไม่ได้บอกฉันเรื่องนั้น",
  str_homestory_807501001_18_dialog_content = "ฉันเห็นว่าคุณเก่งขึ้นในการสังหาร",
  str_homestory_807501001_19_dialog_content = "โอเค คุณตัดสินใจแล้วว่าจะเก็บแสงนี้ไว้ ใช่ไหม?",
  str_homestory_807501001_20_dialog_content = "ถ้าอย่างนั้นเราไปกันเลย",
  str_homestory_807501001_21_dialog_content = "แล้วเราจะมาดูกันว่าฉันจะตีคุณให้ทำงานผิดปกติได้หรือไม่!",
  str_homestory_807501001_22_dialog_content = "ฉันไม่ใช่เครื่องจักร ฉันทำงานผิดพลาดไม่ได้!",
  str_homestory_807501001_23_dialog_content = "สายเคเบิลของคุณเป็นสิ่งเดียวที่จะทำงานผิดพลาดได้",
  str_homestory_807501001_24_dialog_content = "คุณขู่ฉัน?",
  str_homestory_807501001_25_dialog_content = "ผมเพียงชี้แจงข้อเท็จจริง...",
  str_homestory_807501001_26_dialog_content = "อย่าดูถูกเราเรื่องเทคโนโลยี คุณอาจเป็น Caelestite แต่ฉันก็ยังจะ...",
  str_homestory_807501001_27_dialog_content = "???",
  str_homestory_807501001_28_dialog_content = "อ๊ะ ฉันไม่รู้จะขู่คุณด้วยอะไร<sprite=emo_sikao size=60 />",
  str_homestory_807501001_29_dialog_content = "ฮ่าฮ่าฮ่า...",
  str_homestory_807501001_30_dialog_content = "เฮ้ หัวเราะเยาะฉันอีกแล้ว ฉันจะเรียกตัวสำรอง!",
  str_homestory_807501001_31_dialog_content = "ฮ่าฮ่าฮ่าฮ่าฮ่า",
  str_homestory_807501001_32_dialog_content = "หยุดหัวเราะ ไม่งั้นฉันจะโดนซินซามาทับ!",
  str_homestory_807501001_33_dialog_content = "คุณแน่ใจเหรอว่าซินซาจะเข้าข้างคุณ?",
  str_homestory_807501001_34_dialog_content = "เอ่อ...ก็ไม่เชิง...",
  str_homestory_807501001_35_dialog_content = "งั้นคุณแค่ต้องการศึกษาแสงนี้เหรอ?",
  str_homestory_807501001_36_dialog_content = "ใช่. ดูน่าสนใจพอที่จะทำลายลงและดู",
  str_homestory_807501001_37_dialog_content = "แต่ตอนนี้มันทำงานได้ดีมาก ดังนั้นภายในก็น่าจะดีด้วย",
  str_homestory_807501001_38_dialog_content = "ทำไมคุณไม่รอจนกว่ามันจะไม่ทำงาน แล้วฉันจะขอให้คุณซ่อมมัน",
  str_homestory_807501001_39_dialog_content = "นั่นไม่ใช่ความคิดที่ไม่ดี การแก้ไขคือสิ่งที่ฉันทำ!",
  str_homestory_807501001_40_dialog_content = "ได้ ฉันจะไม่แยกมันออกจากกันในตอนนี้",
  str_homestory_807501001_41_dialog_content = "ให้ฉันขอบคุณในนามของแสงสว่าง",
  str_homestory_807501001_42_dialog_content = "เมื่อพูดถึงเรื่องนั้น ฉันเพิ่งเห็นแสงระยิบระยับในน้ำ อาจเป็นกลไกอะไรสักอย่าง!",
  str_homestory_807501001_43_dialog_content = "ฉันควรจะควักมันออกมาแยก!",
  str_homestory_807501001_44_dialog_content = "เอ่อ บางทีฉันควรจะไปช่วยสิ่งที่อยู่ในน้ำ...",
  str_homestory_820601001_0_dialog_content = "เธอกำลังทำอะไร?",
  str_homestory_820601001_1_dialog_content = "คุณจ้องอะไรอยู่น่ะ?<sprite=emo_yihuo size=60 />",
  str_homestory_820601001_2_dialog_content = "มองเห็นจากที่สูงนี่ ยอดเลย!",
  str_homestory_820601001_3_dialog_content = "คุณมองมานานแล้วนะ คุณแน่ใจหรือว่าเพียงแค่ชอบดูเท่านั้น?",
  str_homestory_820601001_4_dialog_content = "อย่าเป็นห่วงเรื่องนั้น คุณสนใจที่จะมาทำงานกับฉันไหม?",
  str_homestory_820601001_5_dialog_content = "ความรู้สึกคมเชิงของคุณในเรื่องเคเลสไทต์ จะช่วยฉันในการแข่งขันธุรกิจในอนาคตอย่างแน่นอน!",
  str_homestory_820601001_6_dialog_content = "ช่วยคุณ? การแข่งขัน?",
  str_homestory_820601001_7_dialog_content = "พวกเขาบอกว่า \"ธุรกิจคือสงคราม\" และความสามารถของคุณเป็นสิ่งที่ฉันต้องการอย่างแน่นอน!",
  str_homestory_820601001_8_dialog_content = "ฉันนำโครงการโบนัสและตัวเลือกหุ้นมาให้ คุณเข้าร่วมหรือไม่?",
  str_homestory_820601001_9_dialog_content = "นั้นขึ้นอยู่กับโครงการและปริมาณหุ้น—",
  str_homestory_820601001_10_dialog_content = "รอสักครู่ ฉันยังไม่ได้ตอบว่าเรียบร้อยแล้วนะ!",
  str_homestory_820601001_11_dialog_content = "การแข่งขันธุรกิจคืออะไร? และมันเกี่ยวข้องอย่างไรกับทิวทัศน์ที่นี่?",
  str_homestory_820601001_12_dialog_content = "ฉันจริง ๆ แค่คิดไอเดียธุรกิจที่น่าสนใจ... อย่าบอกใครนะ",
  str_homestory_820601001_13_dialog_content = "ฉัน-ฉันจะไม่",
  str_homestory_820601001_14_dialog_content = "นี่เป็นการผจญภัยเข้าสู่ทะเลสีน้ำเงิน!",
  str_homestory_820601001_15_option_content = "ทะเลสีน้ำเงิน?",
  str_homestory_820601001_16_dialog_content = "ทะเล ตามที่บอกเลยครับ!",
  str_homestory_820601001_17_dialog_content = "เอาหรือไม่ คุณต้องการเข้าสู่อุตสาหกรรมการขนส่ง?",
  str_homestory_820601001_18_option_content = "อุตสาหกรรมการขนส่ง?",
  str_homestory_820601001_19_dialog_content = "ไม่!",
  str_homestory_820601001_20_dialog_content = "ทะเลสีน้ำเงินเป็นอุปมาคำ, คำเปรียบเสมือน!",
  str_homestory_820601001_21_dialog_content = "มันเป็นตัวอุปมาสัญลักษณ์ของอะไร?",
  str_homestory_820601001_22_dialog_content = "ในธุรกิจนั้นหมายความว่าเป็นดินแดนที่ไม่เคยมีใครสำรวจ และเต็มไปด้วยโอกาสที่น่าสนใจ!",
  str_homestory_820601001_23_dialog_content = "แต่มันเกี่ยวอะไรกับนายที่เฝ้ามองจากหอสังเกตการณ์?",
  str_homestory_820601001_24_dialog_content = "ฉันตระหนักว่าเกาะในทะเลยังไม่ได้รับการพัฒนาเท่าที่ควรเลย!",
  str_homestory_820601001_25_dialog_content = "ไม่ว่าจะเป็นตัวอย่างหรือคำพูดเสียง, ทั้งคู่เป็นทะเลสีน้ำเงิน!",
  str_homestory_820601001_26_dialog_content = "ถ้าฉันสามารถค้นพบเกาะในมหาสมุทรและเปลี่ยนเป็นรีสอร์ท...",
  str_homestory_820601001_27_dialog_content = "วันหยุดฤดูร้อน, การผจญภัย, ล่าสมบัติ, กีฬา, ว่ายน้ำ, สวนเด็กเล่น...",
  str_homestory_820601001_28_dialog_content = "ฉันสามารถพูดไปว่าเรื่องราวต่าง ๆ มีมากมายเพียงอย่างเดียว!",
  str_homestory_820601001_29_dialog_content = "คุณต้องการพัฒนาเกาะใช่ไหม? มีอะไรเฉพาะตอนนี้ไหม?",
  str_homestory_820601001_30_dialog_content = "ยังไม่มีคู่ค้าที่เหมาะสมเลย นั่นเป็นเหตุผลที่ฉันต้องการหาเรือและไปค้นหาคู่ค้าที่ดี.",
  str_homestory_820601001_31_dialog_content = "ตัวอย่างใหญ่เท่าทะเลก็ต้องมีเกาะที่ไม่มีคนอยู่ที่ไหนสักแห่ง!",
  str_homestory_820601001_32_dialog_content = "เราเพียงแค่ต้องทำให้ทุกคนพ่ายแพ้และรับเกาะนั้น หลังจากนั้นเราก็สามารถสร้างมันตามที่เราต้องการ!",
  str_homestory_820601001_33_dialog_content = "เรา? ฉันกำลังไปเหมือนกัน?",
  str_homestory_820601001_34_dialog_content = "เคยเห็นสิ! สายตาและการได้ยินที่แปลกประหลาดของคุณจะเป็นประโยชน์มากเลยครับ",
  str_homestory_820601001_35_dialog_content = "ฉันดูน่าสนใจมากในคำอธิบายนั้น",
  str_homestory_820601001_36_dialog_content = "ดังนั้นขั้นตอนแรกคือการหาเกาะที่เหมาะสมใช่ไหม?",
  str_homestory_820601001_37_dialog_content = "ถูกต้องครับ ฉันกำลังสงสัยว่าถ้าเราย้ายหอระวังภัยขึ้นเรือ เราจะมองเห็นไกลขึ้นหรือไม่",
  str_homestory_820601001_38_dialog_content = "และเนื่องจากคุณอยู่ที่นี่ มาต่อรองราคากันเถอะ",
  str_homestory_820601001_39_dialog_content = "ฉันไม่ได้ตั้งใจจะขายมันเลย...<sprite=emo_tanqi size=60 />",
  str_homestory_820601001_40_dialog_content = "เราจะเรียกมันว่าส่วนแบ่งเงินเมล็ดพันธุ์ของคุณล่ะกันนะ? คุณดูสนใจในโครงการนี้มากเลยอ๋อ",
  str_homestory_820601001_41_dialog_content = "นั่นไม่ใช่สิ่งที่ฉันหมายถึง",
  str_homestory_820601001_42_dialog_content = "ต้องการเวลาเพิ่มเติมในการคิดหรือไม่? ไม่มีปัญหา ยังไม่มีสัญญาที่เขียนขึ้น ดังนั้นทุกอย่างยังสามารถต่อรองกันได้ก่อนที่จะลงลายมือชื่อ",
  str_homestory_820601001_43_dialog_content = "ฉันจะรวบรวมแผนให้เร็วที่สุดเท่าที่ฉันสามารถ คุณเพียงพยายามตัดสินใจอย่างรวดเร็ว!",
  str_homestory_820601001_44_dialog_content = "..อ-ได้เลย งั้นไว้เจอกันใหม่.",
  str_homestory_820701001_0_dialog_content = "เขากำลังขี่มันหรือ?",
  str_homestory_820701001_1_dialog_content = "ดูเหมือนว่าคุณกำลังสนุกสนานเสียจริงๆ",
  str_homestory_820701001_2_dialog_content = "นี่เป็นเรื่องที่เท่ห์มากที่คุณได้รับการขับขี่ใหม่เข้าสู่ Cloud Gardens! ดูเท่มากเลย!",
  str_homestory_820701001_3_dialog_content = "แต่ฉันได้ยินว่ามันดีขึ้นเมื่อมีสองคน",
  str_homestory_820701001_4_dialog_content = "ฉันได้ยินมาว่าการเล่นเป็นคู่สามารถใช้เป็นบททดสอบได้ โดยเฉพาะอย่างยิ่งสำหรับคู่รัก...<sprite=emo_sikao size=60 />",
  str_homestory_820701001_5_dialog_content = "ทดสอบหรือไม่?",
  str_homestory_820701001_6_dialog_content = "สองคนที่อยู่ด้วยกันขึ้นไปขี่สำหรับหลายรอบ...",
  str_homestory_820701001_7_dialog_content = "และหากพวกเขายังสามารถถามว่าคนอื่นๆ สบายดีไหมทันทีหลังจากที่เขาเดินออกจาก...",
  str_homestory_820701001_8_dialog_content = "นั่นหมายความว่าความสัมพันธ์มั่นคง ไม่งั้น ชิ...",
  str_homestory_820701001_9_dialog_content = "แล้วทำไมคุณขี่สิ่งนี้คนเดียว? คุณกำลังเตรียมตัวสำหรับการทดสอบในอนาคตหรือเปล่า?",
  str_homestory_820701001_10_dialog_content = "ผิด, เพื่อน!",
  str_homestory_820701001_11_dialog_content = "มันเป็นการขับขี่ที่ทำให้หัวหมุน คลื่นไส้ แต่ก็น่าสนใจมากด้วย",
  str_homestory_820701001_12_dialog_content = "น่าสนใจพอที่ฉันจะคิดกลับไปในวันเก่าๆ...",
  str_homestory_820701001_13_dialog_content = "ฉันไม่คิดว่าฉันอยากทราบเรื่องที่คุณผ่านมา แต่ฉันเดาว่านี่เป็นเวลาเล่าเรื่องเสียที",
  str_homestory_820701001_14_dialog_content = "ฉันเคยเป็นนักล่า มีความเชี่ยวชาญในการไล่ล่าคนร้ายบางคน",
  str_homestory_820701001_15_dialog_content = "คุณหมายถึงเหมือนกับผู้พิทักษ์กฎหรือคะ? แต่คุณไม่ใช่มาจากทะเลทรายเรดีเซลหรือคะ?",
  str_homestory_820701001_16_dialog_content = "ไม่น่าจะมีอะไรแบบนั้น แก๊งค์เช่นเรดีเซล เวรนช์เท่านั้นที่จะเดินเล่นรอบ ๆ ที่นี่",
  str_homestory_820701001_17_dialog_content = "ฉันทำมันด้วยตัวเอง นั่นเป็นเหตุผลที่ฉันพูดว่านักล่า ไม่ใช่ผู้พิทักษ์กฎ",
  str_homestory_820701001_18_dialog_content = "งั้นคุณไล่ตามคนร้ายชนิดไหนกันบ้าง? มันเกี่ยวข้องกับอดีตของคุณหรือเปล่า?",
  str_homestory_820701001_19_dialog_content = "ฉันได้ยินว่าเมืองหนึ่งในหุบเขา Denuo เคยถูกปล้นในอดีต พวกเขาเกี่ยวข้องกันหรือไม่?",
  str_homestory_820701001_20_dialog_content = "เริ่มจากไหนดีนะ... เรามาเริ่มด้วยเนื้อเรื่องกันเถอะ",
  str_homestory_820701001_21_dialog_content = "ว่าไง",
  str_homestory_820701001_22_dialog_content = "เมื่อครั้งหนึ่งนานมาแล้ว มีชาวประมงที่ยิ่งใหญ่ที่มีทักษะในการตกปลาที่ไม่เหมือนใคร",
  str_homestory_820701001_23_dialog_content = "ข้อความคือเครือข่ายที่เขาทำขึ้นนั้นแข็งแรงและแน่นหนามาก ไม่มีปลาตัวใดสามารถหลุดหนีได้",
  str_homestory_820701001_24_dialog_content = "เขาได้รับปลามากทุกครั้งที่ออกไปในทะเล ทำให้เขามีความมั่งคั่ง",
  str_homestory_820701001_25_dialog_content = "แต่หลังจากนั้นเขาก็จับปลาได้น้อยลงเรื่อย ๆ...",
  str_homestory_820701001_26_dialog_content = "หมดปลาแล้ว?",
  str_homestory_820701001_27_dialog_content = "นั่นสิ~ ตาข่ายแน่นมาก จนตัวเล็กๆ ก็ไม่พ้นหนี้เสียด้วยเลย",
  str_homestory_820701001_28_dialog_content = "ดังนั้นปริมาณปลาจึงลดลงจนหมดสิ้น จนกระทั่งวันหนึ่ง...",
  str_homestory_820701001_29_dialog_content = "เห็นเรื่องพลิกผันกำลังจะมาครับ<sprite=emo_yaosu size=60 />",
  str_homestory_820701001_30_dialog_content = "ลูกชายของชาวประมงเห็นปลาสวยงามอยู่ในปะการังที่ซ่อนเร้น!",
  str_homestory_820701001_31_dialog_content = "ขนาดของมันบ่งบอกว่ามันยังเด็ก แต่สวยงามจริงๆ",
  str_homestory_820701001_32_dialog_content = "ลูกชายไม่สามารถไม่บอกพ่อของเขาที่เป็นชาวประมงเมื่อเขาถึงบ้าน",
  str_homestory_820701001_33_dialog_content = "ฉันเดิมพันว่าชาวประมงคงไปตามมันทันที",
  str_homestory_820701001_34_dialog_content = "ครั้งนี้เขานำตาข่ายที่แข็งแรงและแน่นที่สุดที่เขามีมา พันธะจะจับปลาครั้งนี้",
  str_homestory_820701001_35_dialog_content = "เพราะเขารู้ว่ามันเป็นปลาในตู้ปลาที่มีค่าและสามารถขายได้ราคาดีมาก",
  str_homestory_820701001_36_dialog_content = "ด้วยการแนะนำจากลูกชายของเขา เขาสามารถหาที่พักผ่อนที่มิดชิดกับปะการัง...",
  str_homestory_820701001_37_dialog_content = "ฉันเดาว่านี่เป็นเวลาที่ปัญหาเริ่มต้น",
  str_homestory_820701001_38_dialog_content = "ถูกต้อง! พวกเขาได้เห็นปลาอีกครั้ง ยกเว้นว่ามันใหญ่และสวยยิ่งขึ้น!",
  str_homestory_820701001_39_dialog_content = "มันเป็นพ่อแม่ของปลาที่ลูกชายเห็นหรือไม่?",
  str_homestory_820701001_40_dialog_content = "คงจะเป็นอย่างนั้น",
  str_homestory_820701001_41_dialog_content = "เมื่อปลาใหญ่สวยงามเห็นเรือ มันเริ่มหลบหลีกและหลบหลีกในรีฟ",
  str_homestory_820701001_42_dialog_content = "ชาวประมงไล่ล่ามันในการไล่ล่าที่ร้อนแรง...",
  str_homestory_820701001_43_dialog_content = "เพียงเพื่อชนเรือลงบนรีฟ",
  str_homestory_820701001_44_dialog_content = "เรือล่ม ทั้งนายประมงและลูกชายตาย",
  str_homestory_820701001_45_dialog_content = "โอย...",
  str_homestory_820701001_46_dialog_content = "งั้นคนร้ายที่คุณพูดถึงคือใครเนื่องจากชาวประมงและลูกชายของเขาตายในเรื่องนี้?",
  str_homestory_820701001_47_dialog_content = "นั่นเป็นเหตุผลว่ามันเป็นแค่เรื่องเล่า อย่าอ่านมากเกินไป",
  str_homestory_820801001_0_dialog_content = "เธอหลงใหลมานานแล้ว...",
  str_homestory_820801001_1_dialog_content = "ทำอะไรอยู่เหรอ?",
  str_homestory_820801001_2_dialog_content = "หืมม... โอ้! เธอคือ! คุณสังเกตเห็นฉันเนี่ยนะ?!<sprite=emo_wuzui size=60 />",
  str_homestory_820801001_3_dialog_content = "นั่นเพราะคุณมองอนุสาวรีย์มานานแล้ว ตาของคุณเหนื่อยไหม?",
  str_homestory_820801001_4_dialog_content = "ฉันรู้สึกตอนนี้เมื่อคุณพูดถึงมัน...",
  str_homestory_820801001_5_dialog_content = "รอสักครู่ ข้อสำคัญคือคุณสังเกตเห็นฉัน!",
  str_homestory_820801001_6_dialog_content = "นี่เป็นพลังของอนุสาวรีย์หรือไม่ ที่ทำให้คนอื่นสังเกตคนที่ไม่สำคัญ?",
  str_homestory_820801001_7_dialog_content = "ไม่ นี่เป็นเพราะคุณยืนอยู่ที่นี่นานเกินไปจริงๆ",
  str_homestory_820801001_8_dialog_content = "เช็ครูปภาพที่มันดูสิ! คุณเข้าใจว่ามันหมายความอะไรบ้างไหม, PlayerName?",
  str_homestory_820801001_9_dialog_content = "ไม่ค่อยจะเป็นอย่างนั้นนะ... ดูเหมือนว่าเป็นของโบราณเลยครับ",
  str_homestory_820801001_10_dialog_content = "มันเก่ามาก ฉันไม่คิดว่าใครสามารถบอกได้ว่ามันควรจะสื่ออะไร",
  str_homestory_820801001_11_dialog_content = "งั้นรึเหรอ... เฮ้อ...",
  str_homestory_820801001_12_dialog_content = "ทำไมหน้ายาวเลยครับ? คุณดูเหมือนเศร้า...",
  str_homestory_820801001_13_dialog_content = "นั่นเพราะฉันกำลังคิดเกี่ยวกับอนาคตของเรดีเซล เวรนช์",
  str_homestory_820801001_14_option_content = "คุณหมายถึงอะไรคืออนาคต?",
  str_homestory_820801001_15_dialog_content = "ฉันยังไม่ได้ตัดสินใจ แต่ฉันรู้ว่ามันต้องเป็นเป้าหมายระยะยาว ไม่ใช่การเล่นหมากับที่เราทำตอนนี้",
  str_homestory_820801001_16_dialog_content = "แต่นั่นคือสไตล์ของเรดีเซล! ผู้คนเยอะมากเข้าร่วมเพราะสิ่งนั้น",
  str_homestory_820801001_17_dialog_content = "จริง แต่การมีแผนก็เสมอน่าสนใจ! ฉันยังคิดไม่ออกเลย แต่เราต้องมีแผนหนึ่ง!",
  str_homestory_820801001_18_option_content = "คุณคิดมากเกินไปไหม?",
  str_homestory_820801001_19_dialog_content = "...",
  str_homestory_820801001_20_dialog_content = "บ็อปเปอร์?",
  str_homestory_820801001_21_dialog_content = "ฉันไม่รู้ว่าทำไม แต่ฉันรู้สึกว่ามีคนต้องทำมัน!",
  str_homestory_820801001_22_dialog_content = "ออกไปเที่ยวและเล่นเลิกทุกวันโดยมีเป้าหมายสุ่ม ๆ ... นั่นเป็นการขาดวินัยเสียงาน",
  str_homestory_820801001_23_dialog_content = "ดูเหมือนว่าคุณได้คิดอย่างจริงจังเกี่ยวกับสิ่งนี้...",
  str_homestory_820801001_24_dialog_content = "ฉันไม่คิดว่ามันอยู่ในวาระงานของซินซาเลย",
  str_homestory_820801001_25_dialog_content = "ฉันเข้าใจว่าในฐานะเจ้าของร้าน เขาเพียงต้องเป็นผู้นำที่เท่ห์เท่านั้น",
  str_homestory_820801001_26_dialog_content = "ในขณะที่มันขึ้นอยู่กับฉันในการวางแผนงานในฐานะนักกลยุทธ์",
  str_homestory_820801001_27_dialog_content = "แต่สิ่งนั้นมีความเกี่ยวข้องกับอนุสาวรีย์อย่างไร?",
  str_homestory_820801001_28_dialog_content = "ยกให้ความสุ่มสัมพันธ์!</span>",
  str_homestory_820801001_29_dialog_content = "ฉันได้ยินว่ามีอนุสาวรีย์เช่นนี้ในลูโมโพลิส, สหพันธรัฐอิลลูมินา และแม้กระทั่งนอร์ธแลนด์",
  str_homestory_820801001_30_dialog_content = "สร้างเพื่อระลึกถึงบุคคลที่มีชื่อเสียง ความดี หรือความสำเร็จ!",
  str_homestory_820801001_31_dialog_content = "แต่เราเรดีเซล เวรนช์ไม่มีอะไรเช่นนี้เลย...",
  str_homestory_820801001_32_dialog_content = "เพิ่มเติม, เราไม่ได้เป็นเจ้าของพื้นที่ของเราเองเหมือนกับพวกเขา...",
  str_homestory_820801001_33_dialog_content = "แล้วจะเกิดอะไรขึ้นหากในอนาคตมีปัญหาหรือทุกคนเข้าไปในการทะเลาะกันใหญ่ ๆ แล้วไปตามทางของตัวเอง?",
  str_homestory_820801001_34_dialog_content = "นั่นดูเหมือนว่าเป็นความเป็นห่วงที่ถูกต้องจริงๆ",
  str_homestory_820801001_35_dialog_content = "ดูนี่!",
  str_homestory_820801001_36_dialog_content = "แต่คุณได้คิดเกี่ยวกับวิธีการสร้างอนุสาวรีย์ควรมีรูปร่างอย่างไรบ้างหรือไม่?",
  str_homestory_820801001_37_dialog_content = "รูปร่าง?",
  str_homestory_820801001_38_dialog_content = "ไม่จำเป็นต้องเป็นอนุสาวรีย์เสมอไป แค่สิ่งที่แทนความหมายของเรดีเซล เวรนช์ก็พอ",
  str_homestory_820801001_39_dialog_content = "คุณหมายถึงอย่างเช่น...",
  str_homestory_820801001_40_dialog_content = "กราฟฟิตี้บนรถ?",
  str_homestory_820801001_41_dialog_content = "ถ้ามันตรงกับสไตล์ของคุณ คุณสามารถบอกได้เสมอว่ามันคือเรดีเซล เวรนช์ ไม่ว่าคุณจะอยู่ที่ไหน",
  str_homestory_820801001_42_dialog_content = "หรือเหมือนเราฆ่าหนอนทราย สามารถวาดหนึ่งตัวพร้อมตัว X ทับได้",
  str_homestory_820801001_43_dialog_content = "ใช่เลย ความคิดที่ดีมาก!",
  str_homestory_820801001_44_dialog_content = "ยิ่งไม่ต้องพูดถึงว่า เรดีเซล เวรนช์ มีศิลปินสเปรย์สีที่น่าสนใจเต็มไปหมด!",
  str_homestory_820801001_45_dialog_content = "ฉันต้องไปหาคำตอบเกี่ยวกับแผนงานสำหรับการประกวดวาดกราฟฟิติรถยนต์เรดีเซลเวรนช์ที่ยอดเยี่ยม!<sprite=emo_yaosu size=60 />",
  str_homestory_820901001_0_dialog_content = "เธอกำลังมองอะไรอยู่น่ะ?",
  str_homestory_820901001_1_dialog_content = "ผู้บัญชาการวราธ... เธอทำอะไรที่นี่เนี่ย?",
  str_homestory_820901001_2_dialog_content = "ฉันไม่ได้ทำอะไร แค่เห็นอะไรน่าสนใจจริง ๆ",
  str_homestory_820901001_3_dialog_content = "เสียงนี้เป็นวิธีที่อิลลูมินาสรรหาบุคลากรในปัจจุบันเหรอ...",
  str_homestory_820901001_4_dialog_content = "คุณไม่ใช่ท่านจอมทัพเหรอคะ? ทำไมดูเหมือนคุณเพิ่งรู้เรื่องนี้เองอยู่นะ...?",
  str_homestory_820901001_5_dialog_content = "เพราะว่าท่านจอมทัพไม่มีหน้าที่ดูแลการเกณฑ์ทหารภายนอก...",
  str_homestory_820901001_6_dialog_content = "นั่นคือสิ่งที่ฉันคาดเดา... คุณคิดยังไงล่ะ?",
  str_homestory_820901001_7_option_content = "ก็จริงนะ",
  str_homestory_820901001_8_dialog_content = "ฉันไม่คิดว่าท่านจอมทัพจริงๆ จะมีเวลาสำหรับสิ่งเล็กน้อยเช่นนั้น",
  str_homestory_820901001_9_option_content = "ทำไมถามฉันแบบนี้เนี่ย?!",
  str_homestory_820901001_10_dialog_content = "คุณคือท่านจอมทัพ! แต่คุณยังคงเดาว่าหน้าที่ของคุณควรจะเป็นอย่างไรเหรอ?",
  str_homestory_820901001_11_dialog_content = "ครั้งแรกที่ฉันทำหลังจากกลายเป็นจอมพลคือการนำกำลังสำรวจไปในที่ต่าง ๆ",
  str_homestory_820901001_12_dialog_content = "แต่ตอนนี้... ถึงเวลาที่เราควรสนใจเรื่องอื่นๆ แล้ว",
  str_homestory_820901001_13_dialog_content = "ตัวอย่างเช่น—คุณพวกนี้พบสิ่งนี้ที่ไหนเนี่ย?",
  str_homestory_820901001_14_dialog_content = "เมื่ออยู่ในอัมบราตัน... เรากำลังถ่ายทำภาพยนตร์ในขณะนั้นค่ะ",
  str_homestory_820901001_15_dialog_content = "หนังเหรอ? ฉันเข้าใจแล้ว... <sprite=emo_sikao size=60 />",
  str_homestory_820901001_16_dialog_content = "คิดอะไรขึ้นมาเหรอ?",
  str_homestory_820901001_17_dialog_content = "โฆษณาเรียกเกณฑ์ทหารเหล่านี้... พวกเขาคาดหวังว่าจะได้ทหารที่ดีที่สุดและกล้าหาญของประเทศเข้ารับใช้ในกองทัพด้วยกระดานน่าสงสารเช่นนั้นหรือ?",
  str_homestory_820901001_18_dialog_content = "ขณะที่ฉันควบคุมอยู่ ฉันต้องการทำให้อิลลูมินาแข็งแกร่งมากขึ้นเสมอมาก่อน",
  str_homestory_820901001_19_dialog_content = "แล้วยังไงเหรอ",
  str_homestory_820901001_20_dialog_content = "เราจะทำหนังเกี่ยวกับทหารอิลลูมินากันเถอะ สร้างสื่อประชาสัมพันธ์เพื่อช่วยสรรหาคนรุ่นใหม่ของวีรบุรุษประเทศนี้...",
  str_homestory_820901001_21_option_content = "คุณกำลังพูดจริงใช่ไหมตอนนี้?",
  str_homestory_820901001_22_dialog_content = "แม้ว่าคุณจะพูดอย่างนั้น... การถ่ายทำหนังก็ยังไม่ดูเหมือนเป็นเรื่องของอิลลูมินาเลยนะ",
  str_homestory_820901001_23_dialog_content = "เป็นความจริงที่ว่าวิธีการศึกษาของอิลลูมินามีแนวโน้มที่เน้นไปที่เทคโนโลยีและศิลปะการสู้รบมากกว่าศิลปะเชิงประยุกต์เอง...",
  str_homestory_820901001_24_dialog_content = "ฉันยอมรับเป็นคนแรกเลยว่าเรื่องนั้น",
  str_homestory_820901001_25_dialog_content = "นั่นเป็นเหตุผลที่ฉันอยากให้คุณยิงสิ่งนี้ครับ",
  str_homestory_820901001_26_option_content = "เพราะงั้นมาลองดูกันเถอะ",
  str_homestory_820901001_27_dialog_content = "ถึงแม้คำขวัญทั้งหมดนั้นอาจจะน่าสนใจและเป็นแรงบันดาลใจ แต่ก็ไม่สามารถเทียบได้กับภาพยนตร์",
  str_homestory_820901001_28_dialog_content = "ถ้าเราสามารถแสดงความกล้าหาญของวีรชนอิลลูมินาที่แท้จริงบนจอใหญ่ เราจะส่งคลื่นกระเสือกไปทั่วทวีปทั้งหมด",
  str_homestory_820901001_29_dialog_content = "ฉันรอไม่ไหวแล้วที่จะทำให้สิ่งนี้เกิดขึ้น!",
  str_homestory_820901001_30_dialog_content = "ดีที่ชำระมัน! เรื่องหนังนี้ที่เหลืออยู่ในมือคุณแล้ว ฉันจะไปหาเงินทุนและเตรียมเงินเดือนให้คุณ",
  str_homestory_820901001_31_dialog_content = "แต่... ฉันไม่รู้เรื่องแรกเกี่ยวกับการสร้างภาพยนตร์เลย!",
  str_homestory_820901001_32_dialog_content = "ฉันคิดว่าคุณเป็นคนที่มีความคิดสร้างสรรค์ใช่ไหม? ฉันยังจำได้ว่าคุณเคยแต่งบทกวีเมื่อก่อนด้วยนะ",
  str_homestory_820901001_33_dialog_content = "การเขียนบทกวีและการสร้างภาพยนตร์เป็นสองเรื่องที่แตกต่างกันอย่างมาก! นอกจากนี้ บทกวีของฉันยังไม่ดีเลย...",
  str_homestory_820901001_34_dialog_content = "ตามความเข้าใจของฉัน ศิลปะทุกประเภทน่าจะเชื่อมโยงกันอยู่ใช่ไหม?",
  str_homestory_820901001_35_dialog_content = "ไม่ใช่ปัญหาที่นี่!",
  str_homestory_820901001_36_dialog_content = "นอกจากนี้ ยังไม่มีโรงภาพยนตร์เดียวในอิลลูมินาเลย!",
  str_homestory_820901001_37_dialog_content = "เอาล่ะ มีห้องฉายหนังนะ แต่เปิดเฉพาะวันหยุดเท่านั้น",
  str_homestory_820901001_38_dialog_content = "ดังนั้นคนก็จะไม่มีโอกาสได้ดูหนังเลย...",
  str_homestory_820901001_39_dialog_content = "อิลลูมินาสมัครพลเมืองของตัวเองทั้งหมดอยู่แล้ว แคมเปญสรรหาคนเช่นนี้เป็นไปเพื่อความน่าสนใจของผู้สมัครที่อยู่นอกสหพันธ์เป็นหลัก",
  str_homestory_820901001_40_dialog_content = "แต่ตอนนี้ที่คุณพูดถึง การให้คนอิลลูมินาเห็นสหพันธ์ผ่านเลนส์ของผู้กำกับอาจช่วยเพิ่มความมั่นใจให้พวกเขาได้บ้างนะครับ",
  str_homestory_820901001_41_dialog_content = "และถ้าเป็นอย่างนั้น... มันจะเป็นโอกาสที่หายากจริงๆ นั่นแหละ—ฉันต้องเข้าร่วมแสดงในเรื่องนี้แน่นอน",
  str_homestory_820901001_42_dialog_content = "เราจะเชิญ Reinhardt มาที่นี่แล้วดูว่าใครมีความสามารถในการโชว์ตัวบนจอมากที่สุดกันเถอะ?",
  str_homestory_820901001_43_dialog_content = "เฮ้ย, ถ้าเรามีผู้บัญชาการหลายคนขึ้นหน้าจอ มันอาจจะปลุกให้เกิดการแข่งขันเล็ก ๆ น้อย ๆ ในหมู่กองทัพกันเนอะ",
  str_homestory_820901001_44_dialog_content = "เธอนี่เพลินไปมากเลยนะ...",
  str_homestory_820901001_45_dialog_content = "โอ้ ใช่เลย คุณยังสามารถแสดงและกำกับสิ่งนี้พร้อมกันในเวลาเดียวกันได้ด้วย",
  str_homestory_820901001_46_dialog_content = "ในฐานะ Caelestite เดียวและผู้กำกับ คุณแน่นอนควรมีบทบาทเด่นในเรื่องนี้",
  str_homestory_820901001_47_dialog_content = "คุณไม่ฟังฉันเลยใช่ไหม? อาจจะควรยอมแพ้เถอะ... <sprite=emo_yundao size=60 />",
  str_homestory_820901001_48_dialog_content = "โอ้ ใช่เลย ฉันเพิ่งคิดชื่อที่เหมาะสมสำหรับหนังเรื่องนี้เสร็จเมื่อกี้",
  str_homestory_820901001_49_dialog_content = "\"การปกป้องเคเลสไทต์ PlayerName\"... คุณคิดยังไงล่ะ?",
  str_homestory_821001001_0_dialog_content = "โจเซลีนกำลังสวดภาวนาหน้าธง...",
  str_homestory_821001001_1_dialog_content = "โจเซลีน?",
  str_homestory_821001001_2_dialog_content = "ไม่ต้องยืนรออยู่ตรงนั้นนานขนาดนั้น คุณสามารถเรียกฉันได้เลย",
  str_homestory_821001001_3_dialog_content = "ฉันกลัวว่าฉันอาจจะรบกวนคุณ",
  str_homestory_821001001_4_dialog_content = "พระเจ้าแห่งแสงสว่างไม่ได้สงสัยศรัทธาของเราเพียงเพราะคำอธิษฐานของเราถูกขัดขวาง",
  str_homestory_821001001_5_dialog_content = "และฉันจะไม่โกรธเรื่องเล็กน้อยเช่นนี้ คุณต้องการให้ฉันช่วยอะไรหรือไม่?",
  str_homestory_821001001_6_dialog_content = "ไม่ ฉันแค่เห็นคุณยืนหน้าธงนี้แล้วคิดว่าจะแวะมาหา",
  str_homestory_821001001_7_dialog_content = "เมื่อกี้คุณสวดภาวนากับธงนี้ใช่มั้ย?",
  str_homestory_821001001_8_dialog_content = "สวดภาวนาเหรอ? ก็จริงที่ว่า ถ้ามีการสวดภาวนาผ่านสื่อที่เฉพาะเจาะจง คำภาวนาของเราก็จะถูกได้ยินอย่างชัดเจนมากขึ้น",
  str_homestory_821001001_9_option_content = "ธงปานกลางแบบนี้เหรอ?",
  str_homestory_821001001_10_dialog_content = "อืม การศรัทธาในเทพเจ้าแห่งแสงสว่างเสมอมาเป็นส่วนหนึ่งของวิถีชีวิตประเพณีในลูโมโพลิส...",
  str_homestory_821001001_11_dialog_content = "เลยเดาว่ามันสมเหตุสมผลที่คุณจะใช้ธงของลูโมโพลิสเป็นสื่อในการสวดภาวนา",
  str_homestory_821001001_12_option_content = "คุณหมายถึงเหมือนวัตถุมงคล?",
  str_homestory_821001001_13_dialog_content = "จากที่ฉันเข้าใจ คนที่ต้องการสื่อสารกับเทพเจ้าของตัวเองมักพยายามทำเช่นนั้นโดยใช้วัตถุมงคลใช่ไหม?",
  str_homestory_821001001_14_dialog_content = "ในทางนี้ เขาสามารถสื่อสารกับพระผู้เป็นเจ้าตัวต่อตัวได้ ฟังดูเหมือนจะมีประสิทธิภาพมากเลย!",
  str_homestory_821001001_15_dialog_content = "จริงๆ แล้ว วัตถุใดก็สามารถใช้เป็นสื่อกลางในการสร้างเอฟเฟกต์เดียวกันได้",
  str_homestory_821001001_16_dialog_content = "ความกรุณาของแสง<sprite=emo_taiyang size=60 /> กระจายไปทั่วแผ่นดิน ทุกสิ่งที่อยู่ภายใต้แสงอาทิตย์เชื่อมต่อกับแสงสว่างของพระเจ้า",
  str_homestory_821001001_17_dialog_content = "ฉันมักอธิษฐานต่อดอกมะเขือเทศเวลาดูแลสวนผัก",
  str_homestory_821001001_18_dialog_content = "จริงเหรอครับ?",
  str_homestory_821001001_19_dialog_content = "อย่างไรก็ตาม การเลือกหัวข้อที่เหมาะสมในการสวดภาวนาเฉพาะกิจเป็นสิ่งสำคัญ",
  str_homestory_821001001_20_dialog_content = "แล้วคุณสวดภาวนาอะไรขณะที่คุณมองไปที่ธงลูโมโพลิส?",
  str_homestory_821001001_21_dialog_content = "...",
  str_homestory_821001001_22_dialog_content = "โทษนะ ฉันแค่อยากรู้เฉย ๆ",
  str_homestory_821001001_23_dialog_content = "ถ้าฉันพูดอะไรผิดพลาด ขอให้เพิกเฉยฉันเถอะ โจเซลีน",
  str_homestory_821001001_24_dialog_content = "ไม่, ไม่... ยังไงซะ หน้าที่ของฉันก็คือการเผยแผ่ความเมตตาของเทพแห่งแสงสว่างให้กับทุกคน",
  str_homestory_821001001_25_dialog_content = "เมื่อพูดถึงศรัทธา ฉันยินดีที่จะแบ่งปันทุกสิ่งที่ฉันรู้",
  str_homestory_821001001_26_dialog_content = "แต่เมื่อกี้ ฉัน...",
  str_homestory_821001001_27_dialog_content = "แกอะไร...?",
  str_homestory_821001001_28_dialog_content = "ฉันเพียงอยากจะดูงานเย็บในธงให้ละเอียดขึ้นเท่านั้น",
  str_homestory_821001001_29_dialog_content = "ลูโมโพลิสจริงๆ แล้วมีความส่องสว่างในด้านการสร้างสิ่งของที่เกี่ยวข้องกับศาสนา",
  str_homestory_821001001_30_dialog_content = "โดยเฉพาะธงเช่นนี้ พวกมันเป็นเสาสัญญาณที่นำทางให้กับผู้ที่มองเห็น แน่นอนว่า พวกมันต้องมีความทนทานอย่างเหมาะสม",
  str_homestory_821001001_31_dialog_content = "ถ้าฉันหาวิธีพัฒนาทักษะการเย็บปักถักร้อยของฉัน ฉันจะสามารถช่วยเสริมคนที่ต้องการความช่วยเหลือที่นั่นมากขึ้น",
  str_homestory_821001001_32_dialog_content = "เฮ้ย, และตอนนี้ฉันก็นึกภาพคุณชักธงอย่างกล้าหาญขึ้นสู่ท้องฟ้าออกจากหัวไม่ได้เลย...",
  str_homestory_821001001_33_dialog_content = "คุณจะไม่พบฉันชูธงเลย มันไม่ง่ายอย่างที่ดูนะครับ?",
  str_homestory_821001001_34_dialog_content = "ถึงแม้ชาวบ้านจะเรียกฉันว่า \"นักบุญหญิง\" แต่ฉันก็ยังห่างไกลจากการเป็นผู้นำทางจิตวิญญาณที่พวกเขาต้องการ",
  str_homestory_821001001_35_dialog_content = "ณ ตอนนี้ ฉันต้องเริ่มต้นด้วยการเย็บป้ายของอัศวินไอรอนธอร์น",
  str_homestory_821001001_36_dialog_content = "ใช่ครับ การทำธงที่ดีเพื่อนำการรบเป็นเรื่องสำคัญเท่ากับการโบกธง ฉันยินดีที่จะช่วยด้วยถ้าคุณต้องการ",
  str_homestory_821001001_37_dialog_content = "เธอรู้วิธีเย็บผ้าด้วยเหรอ?",
  str_homestory_821001001_38_dialog_content = "เมื่อฉันยังเด็ก ฉันได้เรียนรู้เทคนิคเล็ก ๆ บ้างจากโซรอซ...",
  str_homestory_821001001_39_dialog_content = "ฉันจะสอนคุณทุกอย่างที่ฉันเรียนรู้ นี่ควรจะเสริมและปรับปรุงทักษะของฉันด้วย",
  str_homestory_821001001_40_dialog_content = "ของแรกที่ต้องทำคือ - นำเสื้อผ้าทั้งหมดของคุณมาให้ฉันด้วย",
  str_homestory_821001001_41_dialog_content = "A-ทั้งหมด?",
  str_homestory_821001001_42_dialog_content = "วิธีเดียวในการเรียนรู้พื้นฐานอย่างละเอียดคือการฝึกฝนอย่างกว้างขวาง",
  str_homestory_821001001_43_dialog_content = "การพูดเยอะๆ โดยไม่มีการกระทำจะนำเราไปสู่ความมืดมิดมากขึ้น ที่แม้กระทั่งพระเจ้าแห่งแสงสว่างยังไม่สามารถช่วยเสียก็ตาม",
  str_homestory_821001001_44_dialog_content = "ฉันเชื่อว่าคุณไม่ใช่เคเลสไทต์แบบนั้นใช่ไหม?",
  str_homestory_821001001_45_dialog_content = "แน่นอนว่าฉันไม่เป็น! เดี๋ยวฉันจะไปเอาเสื้อผ้าเหล่านั้นทันทีเลยนะ!",
  str_homestory_821201001_0_dialog_content = "แอนโทนี?",
  str_homestory_821201001_1_dialog_content = "แอนโทนี คุณยืนอยู่ที่ทางเดินฟอสซิลมาครึ่งชั่วโมงแล้ว",
  str_homestory_821201001_2_dialog_content = "คุณสนใจสิ่งนี้เหรอ?",
  str_homestory_821201001_3_dialog_content = "โอ้... สวัสดี, PlayerName.",
  str_homestory_821201001_4_dialog_content = "ต้องรับความจริงว่า ฉันก็สนใจในเรื่องนี้ค่อนข้างมากเหลือเกิน",
  str_homestory_821201001_5_dialog_content = "ครั้งแรกที่ฉันมองเห็นมัน ฉันมั่นใจในสิ่งหนึ่ง—",
  str_homestory_821201001_6_dialog_content = "ไม่มีใครปฏิเสธคุณค่าทางการวิจัยของมัน!",
  str_homestory_821201001_7_dialog_content = "ขอถามหน่อยครับ กระดูกเหล่านี้มาจากสัตว์ประเภทใดเนี่ยครับ?",
  str_homestory_821201001_8_dialog_content = "ตอนนี้นี่คือคำถามที่ทำให้ฉันคิดไม่ออกเลย...",
  str_homestory_821201001_9_dialog_content = "ในขณะนี้ คณะลูกขุนยังไม่มีข้อสรุปเกี่ยวกับประเด็นนี้ มีความคิดเห็นหลากหลายเกี่ยวกับกระดูกเหล่านี้",
  str_homestory_821201001_10_dialog_content = "ในความคิดเห็นส่วนตัวของคุณ เชื่อว่าพวกเขาคือกระดูกชนิดใด?",
  str_homestory_821201001_11_dialog_content = "ฉันเชื่อในวิจารณญาณของคุณ",
  str_homestory_821201001_12_dialog_content = "ขอคิดก่อนนะ<sprite=emo_sikao size=60 />... บางทีพวกเขาอาจจะ...",
  str_homestory_821201001_13_option_content = "กระดูกของสัตว์บางชนิด",
  str_homestory_821201001_14_dialog_content = "กระดูกสัตว์?",
  str_homestory_821201001_15_dialog_content = "ฉันเดินทางไปหลายที่และไม่เคยเห็นกระดูกแบบนี้มาก่อน",
  str_homestory_821201001_16_dialog_content = "ในกรณีนั้น พวกนี้อาจเป็นซากของสัตว์ประหลาดที่สูญพันธุ์แล้ว!",
  str_homestory_821201001_17_dialog_content = "จริงเหรอ...",
  str_homestory_821201001_18_option_content = "นี่คือกระดูกหลังของโคลอสซัส",
  str_homestory_821201001_19_dialog_content = "อะไรนะ!",
  str_homestory_821201001_20_dialog_content = "พูดเป็นเล่นน่า?",
  str_homestory_821201001_21_dialog_content = "ห-หรือว่านี่จะเป็นกระดูกที่เคยใช้ในการสร้างโคลอสซัสจริง ๆ หรือ?!",
  str_homestory_821201001_22_dialog_content = "แค่เดาน่ะ นั่นแหละ",
  str_homestory_821201001_23_dialog_content = "ไม่, ไม่, คุณเป็นเคเลสไทต์! คุณไม่อาจผิดได้!",
  str_homestory_821201001_24_dialog_content = "ยังไงก็ตาม ฉันต้องศึกษาทางเดินฟอสซิลนี้ให้รอบคอบ!",
  str_homestory_821201001_25_dialog_content = "ฉันขอย้ายส่วนหนึ่งของมันไปห้องฉันเพื่อช่วยในการวิจัยของฉันได้ไหม?!",
  str_homestory_821201001_26_dialog_content = "เฮ้ย! คุณอย่าย้ายของไปห้องของคุณนะ! โอเคมั้ย?!",
  str_homestory_821201001_27_dialog_content = "เสียงไง ที่นี่ก็เป็นทรัพย์สินสาธารณะ...",
  str_homestory_821201001_28_dialog_content = "ถึงอย่างไรก็ตาม ฉันก็แอบสงสัยเกี่ยวกับความจริงที่แท้จริงนะ",
  str_homestory_821201001_29_dialog_content = "เอาล่ะ คุณสามารถทำการวิจัยที่นี่ได้ และถ้าคุณต้องการความช่วยเหลือ ฉันแน่ใจว่าคุณจะหาคนที่ยินดีช่วยคุณได้",
  str_homestory_821201001_30_dialog_content = "ไม่ต้องห่วง!",
  str_homestory_821201001_31_dialog_content = "ฉันรู้ว่าฉันจะหาคำตอบได้!<sprite=emo_dianzan size=60 />",
  str_homestory_821101001_0_dialog_content = "ซาร์ยา นี่เธอทำอะไรอยู่น่ะ?",
  str_homestory_821101001_1_dialog_content = "โอ้, PlayerName, คุณมีความคิดเห็นว่านี่คืออะไรบ้างเหรอ?",
  str_homestory_821101001_2_dialog_content = "มันเขียนว่า \"รถของนักสืบ\" บนมัน",
  str_homestory_821101001_3_dialog_content = "อะไรคือ... รถ?",
  str_homestory_821101001_4_dialog_content = "อย่างง่ายๆ แล้ว มันเป็นวิธีการขนส่งที่สะดวกครับ",
  str_homestory_821101001_5_dialog_content = "นี่เป็นวิธีการเดินทาง?",
  str_homestory_821101001_6_dialog_content = "คนไม่ใช้รถม้าแล้วหรือ...?",
  str_homestory_821101001_7_dialog_content = "ในบางที่พวกเขายังใช้รถม้าอยู่ แต่คุณจะพบว่าคนร่ำรวยในพื้นที่ส่วนใหญ่ โดยทั่วไปขับรถยนต์",
  str_homestory_821101001_8_dialog_content = "โอ๊ะ...",
  str_homestory_821101001_9_dialog_content = "คุณสนใจเรื่องรถม้าหรือครับ ซารย่า?",
  str_homestory_821101001_10_dialog_content = "ฉันสนใจที่จะดูว่ามันเป็นอะไรที่ฉันไม่เคยเห็นมาก่อน",
  str_homestory_821101001_11_dialog_content = "คุณพาฉันไปดูเรื่องจริงในภายหลังได้ไหม",
  str_homestory_821101001_12_option_content = "ได้สิ",
  str_homestory_821101001_13_dialog_content = "แต่คุณต้องสัญญาว่าคุณจะนั่งที่นั่งด้านหลังและประพฤติตัวเองให้ดี",
  str_homestory_821101001_14_dialog_content = "ไม่มีกรณีใด ๆ ที่อนุญาตให้คุณขับรถ",
  str_homestory_821101001_15_option_content = "แต่ผมไม่คิดอย่างนั้นนะ...",
  str_homestory_821101001_16_dialog_content = "ฮะ? ทำไมไม่...?<sprite=emo_yihuo size=60 />",
  str_homestory_821101001_17_dialog_content = "ฉันรู้สึกว่าคุณเสมอเป็นคนที่อยู่ใกล้กับการทำสิ่งที่อันตรายมาก ๆ",
  str_homestory_821101001_18_dialog_content = "เช่นการควบคุมรถม้า",
  str_homestory_821101001_19_dialog_content = "น่าประทับใจมาก, PlayerName.",
  str_homestory_821101001_20_dialog_content = "รู้ได้ยังไงว่าฉันอยากขี่มันน่ะ?",
  str_homestory_821101001_21_dialog_content = "ขี่?",
  str_homestory_821101001_22_dialog_content = "คุณไม่ได้พูดว่ามันเป็นวิธีการขนส่ง... เหมือนกับรถม้าทั่วไปใช่ไหม?",
  str_homestory_821101001_23_dialog_content = "นั่นควรเป็นหลักการเดียวกันใช่ไหม?",
  str_homestory_821101001_24_dialog_content = "คุณต้องทำเพียงแค่เล็กน้อยด้วยแส้ แล้วมันจะพาคุณไปที่คุณต้องการ",
  str_homestory_821101001_25_dialog_content = "หรือคุณต้องให้คำสั่งกับมันเหรอ?",
  str_homestory_821101001_26_dialog_content = "ฉันไม่ได้เป็นผู้เชี่ยวชาญในการควบคุม Luminatics ของฉัน แต่ฉันรู้วิธีจัดการกับม้า!",
  str_homestory_821101001_27_dialog_content = "...",
  str_homestory_821101001_28_dialog_content = "หือ? ทำไมเงียบไป?",
  str_homestory_821101001_29_dialog_content = "ฉันรู้สึกว่าคุณต้องการปรับปรุงความรู้เกี่ยวกับโลกสมัยใหม่จริง ๆ...",
  str_homestory_821101001_30_dialog_content = "หา?",
  str_homestory_821301001_0_dialog_content = "หมายเลข 33?",
  str_homestory_821301001_1_dialog_content = "คุณวางแผนจะไปปิกนิกหรือเปล่า?",
  str_homestory_821301001_2_dialog_content = "ใช่ค่ะ ดูเห็นไหม",
  str_homestory_821301001_3_dialog_content = "เนื่องจากเหตุผลนี้ ฉันกำลังเตรียมการที่จำเป็น",
  str_homestory_821301001_4_dialog_content = "อย่าบอกฉันว่าเธอวางแผนจะไปคนเดียวเหรอ?",
  str_homestory_821301001_5_dialog_content = "คุณดูเหมือนจะเข้าใจผิดฉันนะ",
  str_homestory_821301001_6_dialog_content = "แน่นอน ฉันจะเชิญเพื่อนออโรเรียนคนอื่น ๆ ของฉันเข้าร่วมด้วย",
  str_homestory_821301001_7_dialog_content = "แน่นอนรวมถึงคุณด้วย",
  str_homestory_821301001_8_dialog_content = "มันจะเป็นเกียรติของฉัน",
  str_homestory_821301001_9_dialog_content = "...",
  str_homestory_821301001_10_dialog_content = "พูดถึงนี้ทำไมคุณไม่เชิญไวซ์และคนอื่น ๆ ด้วยล่ะ?",
  str_homestory_821301001_11_dialog_content = "ฉันกำลังดำเนินการวิเคราะห์งานที่สำคัญ",
  str_homestory_821301001_12_dialog_content = "โดยถามคนรอบข้าง ฉันได้เรียนรู้เกี่ยวกับมาตรฐานอาหารในปิกนิกก่อนหน้าของคุณ",
  str_homestory_821301001_13_dialog_content = "จากอาหารปิกนิกที่ได้รับจากเพื่อนออโรเรียนของฉัน ฉันได้สรุปอย่างน่าตกใจว่า:",
  str_homestory_821301001_14_dialog_content = "การบริโภคแคลอรี่เกินไปสามารถส่งผลเสียต่อสุขภาพของคนอย่างรุนแรง",
  str_homestory_821301001_15_dialog_content = "หา?",
  str_homestory_821301001_16_dialog_content = "นายคิดว่าไง PlayerName?",
  str_homestory_821301001_17_option_content = "จริงด้วยสินะ",
  str_homestory_821301001_18_dialog_content = "ถ้าคุณมองจากมุมมองทางโภชนาการเพียงอย่างเดียว แน่นอนว่าอาหารประเภทนี้มีแคลอรี่มากเกินไปครับ",
  str_homestory_821301001_19_dialog_content = "ไม่ค่อยมีโอกาสที่คุณจะเห็นด้วยกับมุมมองของฉันอย่างเต็มใจเลย",
  str_homestory_821301001_20_dialog_content = "แต่กลับ...",
  str_homestory_821301001_21_option_content = "ไม่จริง.",
  str_homestory_821301001_22_dialog_content = "เกี่ยวกับคำพูดของคุณว่า \"นั่นไม่เป็นความจริง\" คุณใช้วิธีวิเคราะห์อะไรในการสรุปแบบนั้น?",
  str_homestory_821301001_23_dialog_content = "ฉันคิดว่าการตัดสินที่ฉันแชร์กับคุณนั้นเป็นอย่างที่ดีและเสถียรที่สุด",
  str_homestory_821301001_24_dialog_content = "เมื่อเราไปปิกนิก เป้าหมายของเราก็เพียงแค่ปลดปล่อยความเครียดเท่านั้น",
  str_homestory_821301001_25_dialog_content = "คุณจะไม่สามารถบรรลุเป้าหมายนั้นหากคุณใช้เวลากังวลเรื่องเล็ก ๆ น้อย ๆ",
  str_homestory_821301001_26_dialog_content = "เหงื่อเรื่องเล็กๆ น้อยๆ หรือคะ? ระบายความเครียดบ้างเถอะ?",
  str_homestory_821301001_27_dialog_content = "ฉันรู้ว่าเจตนาของคุณดี หมายเลข 33 แต่บางครั้งคุณต้องปลดปล่อยตัวเองบ้าง",
  str_homestory_821301001_28_dialog_content = "คุณสามารถเข้มงวดเมื่อถึงเวลาที่ต้องเข้มงวด และพยายามผ่อนคลายเมื่อถึงเวลาที่ต้องผ่อนคลาย ด้วยวิธีนี้คนอื่น ๆ จะชอบคุณมากขึ้น",
  str_homestory_821301001_29_dialog_content = "ได้รับข้อมูลแล้ว กำลังวิเคราะห์ข้อมูล...",
  str_homestory_821301001_30_dialog_content = "เข้าใจ",
  str_homestory_821301001_31_dialog_content = "แล้วฉันจะปรับปรุงสูตรอาหารปิกนิกของฉันใหม่",
  str_homestory_821301001_32_dialog_content = "โปรดรอคำเชิญของฉัน",
  str_homestory_821401001_0_dialog_content = "เรเบคก้า?",
  str_homestory_821401001_1_dialog_content = "ผู้นำทาง...",
  str_homestory_821401001_2_dialog_content = "คุณอยากนั่งเก้าอี้แขวนเหรอ?",
  str_homestory_821401001_3_dialog_content = "ไม่... ฉันแค่รู้สึกคิดถึงเวลาเก่าๆ นิดหน่อย...",
  str_homestory_821401001_4_dialog_content = "ในอดีต... ในสนามบ้านของฉันเคยมีเก้าอี้แขวนที่คล้ายกันอยู่เช่นกัน",
  str_homestory_821401001_5_dialog_content = "ตอนนั้น พี่สาวของฉัน อีลีนอร์ กับฉันเราเคยเล่นด้วยกันบ่อย ๆ บนเก้าอี้แขวนค่ะ",
  str_homestory_821401001_6_dialog_content = "แต่มีแค่สองคนที่สามารถนั่งเล่นได้เนื่องจากเก้าอี้แขวนขนาดเล็กและมีพื้นที่จำกัด...",
  str_homestory_821401001_7_dialog_content = "นั่นหมายความว่า คนใดคนหนึ่งในพวกเราก็จะต้องพลาดเสมอ...",
  str_homestory_821401001_8_dialog_content = "จริงเหรอ? แล้วคุณตัดสินใจยังไงว่าใครจะพลาดโอกาสนี้ล่ะ?",
  str_homestory_821401001_9_dialog_content = "เราเล่นเป่ายิ้งฉุบกัน",
  str_homestory_821401001_10_dialog_content = "แปลกใจเมื่อคิดถึงเลย ฉันไม่เคยแพ้ตอนนั้น เลย แม้แต่ครั้งเดียว",
  str_homestory_821401001_11_dialog_content = "บางทีพวกเขาอาจจะคุยเรื่องนี้กันระหว่างพวกเขาแล้วเหรอ?",
  str_homestory_821401001_12_dialog_content = "นั่นเป็นไปได้ ต้องรับอยู่ว่าความสัมพันธ์ระหว่างพี่สาวของฉันกับเอลีนอร์... ไม่เคยดีนักเลย...",
  str_homestory_821401001_13_dialog_content = "ฉันยังจำได้ว่าเคยมีช่วงเวลาที่ฉันลงจากเก้าอี้แขวนเพื่อโยกมัน...",
  str_homestory_821401001_14_dialog_content = "ในที่สุด พี่สาวของฉันกับเอลีนอร์เกือบทะเลาะกันบนเก้าอี้แขวน",
  str_homestory_821401001_15_dialog_content = "ครั้งนั้นพวกเขาเกือบทำลายมันเหมือนกัน...",
  str_homestory_821401001_16_dialog_content = "ดูเหมือนว่าคุณคิดถึงเวลานั้นจริงๆ นะ <sprite=emo_sikao size=60 />.",
  str_homestory_821401001_17_dialog_content = "คุณอยากนั่งลงบนมันมั้ย?",
  str_homestory_821401001_18_dialog_content = "หา? ฉันเหรอ? งั้น...",
  str_homestory_821401001_19_dialog_content = "ฉันคิดว่าฉันจะผ่าน",
  str_homestory_821401001_20_option_content = "ทำไมละ",
  str_homestory_821401001_21_option_content = "ลองดูสักครั้งสิ",
  str_homestory_821401001_22_dialog_content = "จริง ๆ แล้ว... พิษของฉันก็รู้สึกกระสับกระส่ายเมื่อเร็ว ๆ นี้...",
  str_homestory_821401001_23_dialog_content = "ถ้าฉันเผลอหลับขณะนั่งอยู่บนมัน ฉันกลัวว่าพิษจะหกออกมาและทำลายเก้าอี้แขวน",
  str_homestory_821401001_24_dialog_content = "งั้นฉันจะดูมันหน่อยค่ะ",
  str_homestory_821401001_25_dialog_content = "ถ้าฉันยืนใกล้ๆ แล้วหลับตา มันรู้สึกเหมือนทุกอย่างกลับไปเหมือนในอดีต...",
  str_homestory_821401001_26_dialog_content = "ไม่ต้องห่วงนะ ฉันอยู่นี่แล้ว",
  str_homestory_821401001_27_dialog_content = "ฉันจะปลุกคุณทันทีถ้าคุณหลับ",
  str_homestory_821401001_28_dialog_content = "มันจะสร้างปัญหาให้คุณมากเกินไปรึเปล่า...?",
  str_homestory_821401001_29_dialog_content = "มันจะดี",
  str_homestory_821401001_30_dialog_content = "เอ่อ... คุณรอฉันอีกสักครู่ได้มั้ย?",
  str_homestory_821401001_31_dialog_content = "ฉันมีธุระที่ต้องทำที่คลินิกบ้าง ฉันจะไปหาคุณทันทีหลังจากที่ทำเสร็จแล้วนะ!",
  str_homestory_821401001_32_dialog_content = "ขอบคุณนะ ผู้นำทาง",
  str_homestory_821501001_0_dialog_content = "ไอซ่า?",
  str_homestory_821501001_1_dialog_content = "โอ้ นายนี่เอง",
  str_homestory_821501001_2_dialog_content = "มีอะไรผิดปกติกับรถนี้หรือ? คุณมองมันตลอดเวลาเลย",
  str_homestory_821501001_3_dialog_content = "อ๊ะ! เป็นคำถามที่ดีเลย",
  str_homestory_821501001_4_dialog_content = "คุณไม่คิดว่ารถคันนี้... เจ๋งมากใช่มั้ยละ?",
  str_homestory_821501001_5_option_content = "ไม่ขนาดนั้น",
  str_homestory_821501001_6_dialog_content = "ฉันคิดว่าคุณสามารถพูดได้ว่ามันสวย",
  str_homestory_821501001_7_option_content = "ใช่ ฉันเห็นด้วย",
  str_homestory_821501001_8_dialog_content = "ในความหมายหนึ่ง มันสามารถถือว่าเป็นเรื่องเท่ได้",
  str_homestory_821501001_9_dialog_content = "เพื่อน รถคันนี้เหมาะกับสไตล์ของฉันเลย!",
  str_homestory_821501001_10_dialog_content = "ถ้าฉันขับรถคันนี้ไปรับเรเบคก้า...",
  str_homestory_821501001_11_dialog_content = "เธอจะตื่นเต้นมากแน่นอน!",
  str_homestory_821501001_12_dialog_content = "คุณคิดจะไปรับเรเบคก้าด้วยรถคันนี้หรือเปล่า?",
  str_homestory_821501001_13_dialog_content = "ใช่ รีเบคก้าไม่สบาย",
  str_homestory_821501001_14_dialog_content = "แต่เธอยังต้องเดินไปทำงานทุกวันอยู่ คุณไม่คิดว่าเธอกำลังทำร้ายตัวเองเกินไปหรือเปล่า?",
  str_homestory_821501001_15_dialog_content = "มันฟังดูยากจริงๆ",
  str_homestory_821501001_16_dialog_content = "ใช่ไหม? นี่คือสิ่งที่ฉันคิดขึ้นมาหลังจากพิจารณาอย่างรอบคอบ",
  str_homestory_821501001_17_dialog_content = "เรเบคก้ามักจะพูดว่าฉันไม่รู้ว่าเธอต้องการอะไร ฮีฮี แน่นอนว่าเธอต้องการเครื่องมือขนส่งครั้งนี้แน่ๆ",
  str_homestory_821501001_18_dialog_content = "แต่... รถคันนี้สีสันเกินไป รีเบคก้าคงไม่ชอบนะ",
  str_homestory_821501001_19_dialog_content = "ไม่ต้องห่วงนะ ฉันเข้าใจเธอดี ฉันแน่ใจว่าฉันรู้ว่าเธอชอบอะไร",
  str_homestory_821501001_20_dialog_content = "เรเบคก้าชอบดอกไม้ ดูดอกไม้ที่อยู่ทั่วรถเถอะ ไม่มีทางเธอจะเกลียดมันหรอกค่ะ",
  str_homestory_821501001_21_dialog_content = "... เอ่อ, ลองทำดูเลยล่ะ?",
  str_homestory_821501001_22_dialog_content = "เอาล่ะ ฉันจะบอกเรเบคก้าตอนนี้",
  str_homestory_821501001_23_dialog_content = "เธอจะดีใจแน่นอน",
  str_homestory_821501001_24_dialog_content = "ขอให้โชคดีนะ",
  str_homestory_821601001_0_dialog_content = "มันผิดพลาดอย่างไรกับเครื่องนี้เนี่ย หวั่นจิ?",
  str_homestory_821601001_1_dialog_content = "ในอดีตเคยถูกใช้โดยเคเลสไทต์ สนใจไหม?",
  str_homestory_821601001_2_dialog_content = "นี่เป็น<color=#FFB400>เครื่องทอ</color>จักรกลใช่มั้ย?",
  str_homestory_821601001_3_dialog_content = "ใช่ มีบันทึกเกี่ยวกับมันบนโซรอซครับ",
  str_homestory_821601001_4_dialog_content = "อีราเวลเคยใช้เครื่องจักรเช่นนี้ในการผลิตผ้า ทำให้สามารถดำรงชีวิตอยู่ด้วยตัวเองได้",
  str_homestory_821601001_5_dialog_content = "คงต้องการการดูแลอย่างสม่ำเสมอ แต่ดูเหมือนว่าไม่ได้ใช้งานมานานแล้ว...",
  str_homestory_821601001_6_dialog_content = "ซวนจิอยากใช้มันใช่มั้ย?",
  str_homestory_821601001_7_dialog_content = "ไม่ขนาดนั้น",
  str_homestory_821601001_8_dialog_content = "มันดูน่านึกถึงความหลังสำหรับฉันเลยน่ะ",
  str_homestory_821601001_9_dialog_content = "นึกถึงความหลัง?",
  str_homestory_821601001_10_dialog_content = "มันนึกให้ฉันคิดถึงเครื่องจักรสำหรับการสอนที่ฉันใช้เมื่อเรายังเด็กๆ",
  str_homestory_821601001_11_dialog_content = "อาจารย์จะเริ่มสอนเราเด็กนักเรียนด้วยโมเดลต้นแบบ",
  str_homestory_821601001_12_dialog_content = "เครื่องทอแบบนี้เป็นที่นิยม คุณยังสามารถเรียกมันว่าเป็นอาจารย์คนที่สองของฉันเลย",
  str_homestory_821601001_13_dialog_content = "ไม่น่าแปลกใจที่คุณคิดว่ามันน่าสนใจ",
  str_homestory_821601001_14_dialog_content = "นอกจากนี้ ตัวต้นแบบมักจะเปราะบางมากด้วย",
  str_homestory_821601001_15_dialog_content = "นั่นก็เป็นกรณีกับที่ถูกให้ฉันด้วย โดยมีโครงสร้างที่เหมือนกันบางอย่างเช่นกัน...",
  str_homestory_821601001_16_dialog_content = "พวกเขาก็ทำเช่นนั้นเพื่อให้เรารักษาความคุ้มค่าของงานฝีมือ",
  str_homestory_821601001_17_dialog_content = "ฉันก็อยากทะนุถนอมมันเหมือนกัน แต่มันพังบ่อยกว่าที่จะไม่พังเสียอีก!",
  str_homestory_821601001_18_option_content = "เพราะคุณพยายามปรับแต่งมันเหรอ?",
  str_homestory_821601001_19_dialog_content = "ถูกเผง",
  str_homestory_821601001_20_option_content = "มันเปราะมาก",
  str_homestory_821601001_21_dialog_content = "ไม่ค่ะ เพราะฉันปรับแต่งมันเยอะเลย...",
  str_homestory_821601001_22_dialog_content = "ดังนั้นมันไม่อยู่จนถึงวันที่ฉันจบการศึกษา",
  str_homestory_821601001_23_dialog_content = "เมื่อฉันสามารถทำได้ดีพอแล้ว มันก็เสียหายเกินกว่าจะซ่อมได้",
  str_homestory_821601001_24_dialog_content = "เข้าใจแล้ว",
  str_homestory_821601001_25_dialog_content = "เอาละ อยากให้ฉันซ่อมเครื่องทอนี้มั้ย",
  str_homestory_821601001_26_dialog_content = "สำหรับเวอร์ชันปัจจุบันของฉัน มันควรจะง่ายมาก",
  str_homestory_821601001_27_dialog_content = "ฉันยังสามารถปรับปรุงการออกแบบให้มันทำงานและบำรุงรักษาตัวเองได้ดีที่สุดเท่าที่จะเป็นไปได้",
  str_homestory_821601001_28_dialog_content = "อืม<sprite=emo_sikao size=60 />, ไม่จำเป็นนะคะ",
  str_homestory_821601001_29_dialog_content = "แม้ว่าจะซ่อมได้ ก็ยังยากที่จะหาวัตถุดิบให้มันประมวลผล",
  str_homestory_821601001_30_dialog_content = "ยิ่งจะพูดถึงว่าตอนนี้เราสามารถหาผ้าที่ราคาไม่แพงแต่สวยงามจากร้านค้าได้ง่ายขึ้น",
  str_homestory_821601001_31_dialog_content = "จริงๆ นี่คือเหมือนกันในหลงโจว",
  str_homestory_821601001_32_dialog_content = "สำหรับคนธรรมดา กิลด์มีความสำคัญมากกว่าช่างฝีมือในปัจจุบัน",
  str_homestory_821601001_33_dialog_content = "นั่นคือความคืบหน้าใช่ไหม?",
  str_homestory_821601001_34_dialog_content = "อืม, ไม่สามารถโต้แย้งได้ คงต้องยอมรับว่าเครื่องจักรนี้ใช้งานไม่ได้แล้ว",
  str_homestory_821601001_35_dialog_content = "งั้น ปล่อยให้มันหลับให้สงบเถอะนะ",
  str_homestory_818702001_0_dialog_content = "เทียนเซียน? อาจารย์หลี่?",
  str_homestory_818702001_1_dialog_content = "เธอหลับยืนได้ยังไงเนี่ย?",
  str_homestory_818702001_2_dialog_content = "ตื่นขึ้นแล้วกลับไปห้องนะ",
  str_homestory_818702001_3_dialog_content = "อ๊ะ!",
  str_homestory_818702001_4_dialog_content = "ฉันเพิ่งไปคุยกับทูตสวรรค์บนฟ้าเมื่อครู่นี้",
  str_homestory_818702001_5_dialog_content = "ฉันตกกลับมายังโลกเร็วแค่ไหนนะ...",
  str_homestory_818702001_6_dialog_content = "เดาว่าฉันยังต้องเดินทางอีกไกลนะ",
  str_homestory_818702001_7_dialog_content = "ยอมแพ้ละ คุณไม่สังเกตเหรอ?",
  str_homestory_818702001_8_dialog_content = "สิ่งที่คุณหลับไปข้างๆ และเกือบเอียงตัวพิง...",
  str_homestory_818702001_9_dialog_content = "เป็นนาฬิกา",
  str_homestory_818702001_10_dialog_content = "ไม่น่าเชื่อเลย! ทำไมคุณถึงหลับสนิทข้างๆนาฬิกาใหญ่ขนาดนี้...",
  str_homestory_818702001_11_dialog_content = "ตรงข้ามครับ พี่ชาย.",
  str_homestory_818702001_12_dialog_content = "ตามที่ฉันทราบ คนหลายคนใน Astra วางนาฬิกาปลุกข้างหมอนของพวกเขา",
  str_homestory_818702001_13_dialog_content = "อย่างไรก็ตาม ฉันชอบใช้ท้องฟ้าเป็นผ้าห่ม ดินแดนเป็นเตียงนอน และนาฬิกาทรายเป็นนาฬิกาปลุกของฉัน",
  str_homestory_818702001_14_dialog_content = "ดังนั้นในกรณีนี้ ฉันกำลังปรับตัวให้เข้ากับสิ่งที่คนท้องถิ่นทำ",
  str_homestory_818702001_15_dialog_content = "แต่พวกเขาทำเพื่อตื่นขึ้นตรงเวลา ส่วนคุณก็แค่พยายามหาเวลางีบหลับเท่านั้นเอง<sprite=emo_kun size=60 />!",
  str_homestory_818702001_16_dialog_content = "คุณไม่รู้สึกเวลาผ่านไปอย่างรวดเร็วเลยหรือ?",
  str_homestory_818702001_17_dialog_content = "เพราะเวลาล้ำค่าและชีวิตสั้น คนเราจึงต้องยึดโอกาสเมื่อมีโอกาสปรากฏตัว",
  str_homestory_818702001_18_dialog_content = "คุณควรนอนเมื่อรู้สึกง่วง ไม่ต้องรอจนหาวนะ",
  str_homestory_818702001_19_dialog_content = "ทำไมไม่เอนตัวแล้วงีบหลับสักหน่อยล่ะ? แล้วคุณจะเข้าใจเอง",
  str_homestory_818702001_20_option_content = "ไม่นี่",
  str_homestory_818702001_21_dialog_content = "ยังเด็กและขาดประสบการณ์อยู่เห็นไหม",
  str_homestory_818702001_22_dialog_content = "ฉันเคยเห็นโลกมากพอและจะไม่เสียโอกาสหลับตาพักผ่อนเสียเลย",
  str_homestory_818702001_23_option_content = "ฉันจะลองดูนะ",
  str_homestory_818702001_24_dialog_content = "คุณสุดท้ายก็รู้สึกตื่นตัวแล้ว!",
  str_homestory_818702001_25_dialog_content = "แต่ถึงแม้ฉันจะพังที่นี่ ฉันก็ต้องเตรียมตัว",
  str_homestory_818702001_26_dialog_content = "ฉันต้องเอาถุงนอน เสื่อปิกนิก และอุปกรณ์อื่น ๆ ครบถ้วนมาด้วย",
  str_homestory_818702001_27_dialog_content = "คุณแน่นอนรู้วิธีสนุกกับชีวิต ส่วนฉันแทบไม่มีอะไรเพื่อความสบายใจเลย",
  str_homestory_818702001_28_dialog_content = "อืม, ฉันคิดว่านาฬิกาแดดน่าจะเป็นสิ่งที่โชคดีที่สุดในทั้งหมดนะ",
  str_homestory_818702001_29_dialog_content = "มันมีวัตถุประสงค์เดียวกันไม่ว่าจะอยู่ในหลงโจวหรือแอสตร้า",
  str_homestory_818702001_30_dialog_content = "มันมีเวลาพักตราบใดที่ดวงอาทิตย์ยังไม่ขึ้น",
  str_homestory_818702001_31_dialog_content = "คุณอิจฉาหินจนถึงขั้นนี้เลยเหรอ?",
  str_homestory_818702001_32_dialog_content = "อย่าดูถูกหินเลยนะ มีฮีโร่ตำนานที่กำเนิดมาจากหินอีกด้วย!",
  str_homestory_818702001_33_dialog_content = "แต่น่าเสียดายที่ฉันสามารถกลายเป็นหินได้เฉพาะในความฝันเท่านั้น",
  str_homestory_818702001_34_dialog_content = "พูดถึงนั้น ฉันรู้สึกว่ากำลังจะง่วงอีกแล้ว",
  str_homestory_818702001_35_dialog_content = "ยังไม่เห็นความรู้สึกเร่งด่วนเลยนะ...",
  str_homestory_818702001_36_dialog_content = "อย่าเอาทุกอย่างมาเคร่งเครียดเสมอนะ PlayerName",
  str_homestory_818702001_37_dialog_content = "มีอะไรผิดหากลดความเร็วในการทำงานและหยุดเพื่อได้สัมผัสความงามของชีวิตบ้างล่ะ?<sprite=emo_qingsong size=60 />",
  str_homestory_818702001_38_dialog_content = "จริง... นั่นคือ Li Tianxian ที่ฉันรู้จัก",
  str_homestory_818802001_0_dialog_content = "ดันตัง?",
  str_homestory_818802001_1_dialog_content = "งานฝีมือในการทำว่าวนี้มีเอกลักษณ์ค่อนข้างเป็นเอกลักษณ์",
  str_homestory_818802001_2_dialog_content = "ลวดลายมุมและโทนสีเรียบง่าย...",
  str_homestory_818802001_3_dialog_content = "มันคล้ายกับสายพันธุ์ที่พบบ่อยที่สุดในหลงโจว",
  str_homestory_818802001_4_dialog_content = "เคเลสไทต์ชอบความสง่างามที่คล้ายกันเหรอ? นั่นคือสิ่งที่หายากจริง ๆ",
  str_homestory_818802001_5_option_content = "คนในหลงโจวชอบเล่นว่าวไหม?",
  str_homestory_818802001_6_dialog_content = "แน่นอน",
  str_homestory_818802001_7_option_content = "Dantang คุณเคยเล่นว่าวมาก่อนหรือไม่?",
  str_homestory_818802001_8_dialog_content = "ใช่ค่ะ ฉันรักว่าวมากเลยค่ะ",
  str_homestory_818802001_9_dialog_content = "ในหลงโจว การเล่นว่าวเป็นกิจกรรมที่เด็กๆ ชื่นชอบมากที่สุด",
  str_homestory_818802001_10_dialog_content = "ตอนที่ฉันยังเด็ก ๆ การได้เล่นว่าวกับพี่สาวเป็นความสุขที่หายาก",
  str_homestory_818802001_11_dialog_content = "ในอดีต ว่าวของเรามักจะเป็นกันและกัน",
  str_homestory_818802001_12_dialog_content = "บางครั้ง มันยังทำให้เกิดการทะเลาะกันด้วย",
  str_homestory_818802001_13_dialog_content = "ถึงแม้เราจะปรับความเข้าใจกันในที่สุดเสมอ,",
  str_homestory_818802001_14_dialog_content = "ดันตั้ง คุณเคยเล่นว่าวประเภทไหนบ้าง?",
  str_homestory_818802001_15_dialog_content = "ว่าวของฉันเหรอ? โอ้ ฉันเคยเล่นว่าวหลายครั้งเลยครับ",
  str_homestory_818802001_16_dialog_content = "พี่สาวของฉันชอบวนที่มีรูปแบบเป็นนก แต่สำหรับฉันนั้นคือดอกไม้",
  str_homestory_818802001_17_dialog_content = "ฉันไม่เคยเห็นว่าวแบบนั้นเลย",
  str_homestory_818802001_18_dialog_content = "เสียงเชียร์, ว่าวในหลงโจวมีลักษณะที่หลากหลายมาก",
  str_homestory_818802001_19_dialog_content = "ยกตัวอย่างเช่นราชอาณาจักรเย พวกเขาชอบแนบอุปกรณ์ต่าง ๆ ให้กับว่าว",
  str_homestory_818802001_20_dialog_content = "ซึ่งจะทำให้ทุกส่วนเคลื่อนไหวและเต้นรำ",
  str_homestory_818802001_21_dialog_content = "ว่าวทั้งหมดที่ฉันเคยบินในเวลานั้นถูกสร้างขึ้นโดยช่างฝีมือในวัง",
  str_homestory_818802001_22_dialog_content = "ตกแต่งอย่างฟุ่มเฟือยด้วยความหรูหราและความสง่างาม",
  str_homestory_818802001_23_dialog_content = "ฉันคิดถึงมากเลย... อยากจะไปเล่นว่าวอีกครั้งนะ",
  str_homestory_818802001_24_dialog_content = "ฉันขอโทษ ว่าวตัวนี้ที่นี่ไม่สามารถเทียบเท่ากับที่คุณเคยมีได้ค่ะ",
  str_homestory_818802001_25_dialog_content = "ไม่เป็นไรหรอก สิ่งที่ฉันคิดถึงคือช่วงเวลาไร้กังวลในอดีต",
  str_homestory_818802001_26_dialog_content = "การเล่นว่าวเป็นเรื่องที่บังเอิญเสียจริงๆ",
  str_homestory_818802001_27_dialog_content = "อืม, ฉันไม่มีงานและธุระที่ต้องทำแล้ว",
  str_homestory_818802001_28_dialog_content = "ฉันสามารถหยุดพักได้ และเวลานี้เหมาะสมที่สุดในการปล่อยว่าวบิน",
  str_homestory_818802001_29_dialog_content = "งั้น อยากไปเล่นว่าวกับฉันมั้ย?",
  str_homestory_818802001_30_dialog_content = "บินคนเดียวไม่มีความสนุกเลยนะ",
  str_homestory_818802001_31_dialog_content = "เสียดายที่เรามีแค่หนึ่งที่นี่...",
  str_homestory_818802001_32_dialog_content = "ไม่เป็นปัญหา คุณสามารถสลับกันทำ หรือฉันสามารถทำเองได้",
  str_homestory_822001001_0_dialog_content = "เวอร์จิล?",
  str_homestory_822001001_1_dialog_content = "ทำไมคุณถึงมองตุ๊กตาฟางอยู่เรื่อยๆ แบบนั้น Vergil?",
  str_homestory_822001001_2_dialog_content = " scarecrow นี้...<sprite=emo_sikao size=60 />",
  str_homestory_822001001_3_dialog_content = "เรื่องนี้ล่ะ? อย่าบอกฉันว่าหุ่นไล่กานี้เป็นของโบราณนะ!",
  str_homestory_822001001_4_dialog_content = "แวบแรก, มันดูเหมือนจะเป็น...",
  str_homestory_822001001_5_dialog_content = "จริงเหรอ? มีอะไรพิเศษเกี่ยวกับหุ่นไล่กานี้หรือ?",
  str_homestory_822001001_6_dialog_content = "อุปกรณ์ตกแต่งที่อยู่บนมัน... มันอาจจะเป็นของเก่านะ",
  str_homestory_822001001_7_dialog_content = "ของเก่า? จริงเหรอ?",
  str_homestory_822001001_8_dialog_content = "ใช่ เสื้อกั๊กนี้ควรจะเป็นสินค้าจำนวนจำกัดจากแบรนด์ Umbraton น่ะ",
  str_homestory_822001001_9_dialog_content = "มันเป็นที่นิยมเมื่อ 50 ปีที่แล้ว",
  str_homestory_822001001_10_dialog_content = "คุณลักษณะที่สำคัญที่สุดของการเสนอข้อเสนอจำกัดนี้คือ...",
  str_homestory_822001001_11_dialog_content = "ลายสีขาวบนผ้าสีดำของมันคือลายเส้นสีขาวที่ย้อมบนผ้าสีดำ",
  str_homestory_822001001_12_dialog_content = "แทนที่จะเป็นลายปกติ มีลายเส้นสีดำพิมพ์บนผ้าสีขาว",
  str_homestory_822001001_13_dialog_content = "และยังมีตัวเลขถักไว้ด้านหลังคอเสื้อด้วยด้ายทองคำด้วย",
  str_homestory_822001001_14_dialog_content = "ฉันเห็นมันนะ...<sprite=emo_wuzui size=60 />",
  str_homestory_822001001_15_dialog_content = "นอกจากนี้ ถ้าคุณมองใกล้ ๆ คุณจะเห็นว่าตาของหุ่นไล่กาทำจากหินออบซิเดียน",
  str_homestory_822001001_16_dialog_content = "การขัดและสีทั้งสองเป็นคุณภาพของอัญมณี",
  str_homestory_822001001_17_dialog_content = "ขุนนางในลูโมโพลิสมักจะทำเพชรพลอยเหล่านี้เป็นกระดุมตั้งแต่หลายทศวรรษที่แล้ว",
  str_homestory_822001001_18_dialog_content = "สองคนนี้ไม่ไกลจากนั้นเท่าไหร่",
  str_homestory_822001001_19_dialog_content = "ผมไม่ได้สังเกตจนกว่าคุณจะพูดมา",
  str_homestory_822001001_20_dialog_content = "สุดท้าย ท่อนไม้ที่ยกหุ่นไล่กาขึ้น...",
  str_homestory_822001001_21_dialog_content = "ดูเหมือนว่าจะเป็นไม้หอม",
  str_homestory_822001001_22_dialog_content = "ถึงแม้ว่ามันจะบางกว่า แต่คุณยังสามารถดมกลิ่นหอมจาง ๆ ได้เมื่อคุณเข้าใกล้มัน",
  str_homestory_822001001_23_dialog_content = "ไม้กฤษณามีค่ามาก",
  str_homestory_822001001_24_dialog_content = "ว้าว, นั่นหมายความว่าหุ่นไล่กาตัวนี้ประเมินค่าไม่ได้เลยเหรอ?",
  str_homestory_822001001_25_dialog_content = "เอาจริงๆ ของเก่านั้นถูกตัดสินจากทั้งหมดนะ",
  str_homestory_822001001_26_dialog_content = "ชุดทั้งหมดจะมีค่าที่ไม่วัดได้ แต่จะมีค่าน้อยลงมากเมื่อส่วนประกอบเพียงหนึ่งชิ้นหายไป",
  str_homestory_822001001_27_dialog_content = "และก็ตรงกันข้าม เหมือนกับหุ่นไล่กาตัวนี้ การรวมตัวของวัตถุที่ไม่เกี่ยวข้องกันเลย",
  str_homestory_822001001_28_dialog_content = "แม้จากมุมมองของงานศิลปะ...",
  str_homestory_822001001_29_dialog_content = "มันเป็นเกรดสามที่ดีที่สุด ไม่มีค่าอะไรในตอนนี้เลย",
  str_homestory_822001001_30_dialog_content = "นั่นเป็นเรื่องน่าเสียดาย...<sprite=emo_tanqi size=60 />",
  str_homestory_822001001_31_dialog_content = "ยกเว้นว่า...",
  str_homestory_822001001_32_dialog_content = "เว้นแต่ว่าอะไร?",
  str_homestory_822001001_33_dialog_content = "เว้นแต่ว่าคุณจะแกะมันออก คุณต้องการทำเช่นนั้นหรือไม่?",
  str_homestory_822001001_34_dialog_content = "ไม่หรอกนะ",
  str_homestory_822001001_35_dialog_content = "ฉันชอบที่มันเป็นอยู่แบบนี้ ที่เราสามารถสนุกกับมันได้เหมือนเดิม",
  str_homestory_822001001_36_dialog_content = "ฉันรู้ว่าคุณจะพูดแบบนั้น PlayerName.",
  str_homestory_821901001_0_dialog_content = "เป็นอะไรไปล่ะ",
  str_homestory_821901001_1_dialog_content = "ท่าทางของคุณ... หรือว่า...",
  str_homestory_821901001_2_dialog_content = "คุณต้องชอบนาฬิกานี้มากใช่ไหม",
  str_homestory_821901001_3_dialog_content = "นี่เป็นสไตล์ที่ฉันไม่เคยเห็นมาก่อน",
  str_homestory_821901001_4_dialog_content = "นี่เป็นนาฬิกาเคเลสไทต์หรือไม่?",
  str_homestory_821901001_5_dialog_content = "ฉันว่างั้นแหละ",
  str_homestory_821901001_6_dialog_content = "ทุกอย่างบนโซรอซคือเคเลสไทต์",
  str_homestory_821901001_7_dialog_content = "มันไม่ใช่เครื่องจักร แต่ใช้การสะท้อนแสงอาทิตย์",
  str_homestory_821901001_8_dialog_content = "ช่างเป็นแนวคิดที่ยอดเยี่ยมจริงๆ...",
  str_homestory_821901001_9_dialog_content = "อาจเรียกว่าศิลปะแห่งเงามืด",
  str_homestory_821901001_10_dialog_content = "คุณชอบนาฬิกานี้จริงๆ นะ ฉันเห็นนั่นเลย",
  str_homestory_821901001_11_dialog_content = "ฉันประทับใจในเวลาที่ผ่านไปอย่างรวดเร็ว",
  str_homestory_821901001_12_dialog_content = "ดังนั้นฉันก็ชอบสะสมนาฬิกาที่มีแบรนด์ต่าง ๆ ด้วย",
  str_homestory_821901001_13_dialog_content = "อะไร? คุณหมายถึงว่ามีนาฬิกาหลายประเภทอยู่ในโลกภายนอกเหรอ?",
  str_homestory_821901001_14_dialog_content = "นาฬิกาในลูโมโพลิสมีลักษณะที่คลาสสิกและสง่างาม",
  str_homestory_821901001_15_dialog_content = "นาฬิกาของนอร์ธแลนด์นั้นเรียบง่ายและประยุกต์ใช้สะดวก",
  str_homestory_821901001_16_dialog_content = "นาฬิกาทะเลทรายเรดีเซลเต็มไปด้วยของเล่นและอุปกรณ์เพิ่มเติม",
  str_homestory_821901001_17_dialog_content = "และนาฬิกาของอัมบราตันนั้นเงียบๆ แต่ยังสวยงามอย่างน่าทึ่ง",
  str_homestory_821901001_18_dialog_content = "ฉันเข้าใจแล้ว คุณนี่ชอบสะสมของจริงๆนะ",
  str_homestory_821901001_19_dialog_content = "ฉันไม่เคยคิดเลยว่าสิ่งของธรรมดาๆ จะมีอะไรมากมายขนาดนี้",
  str_homestory_821901001_20_dialog_content = "คุณได้เปิดตาฉัน",
  str_homestory_821901001_21_dialog_content = "นาฬิกาที่ฉันกล่าวถึงนั้นเป็นผลิตภัณฑ์ทั้งหมดของยุคสมัยใหม่",
  str_homestory_821901001_22_dialog_content = "ในขณะที่นาฬิกาของ Caeleste ทำให้ฉันตระหนักถึงความหนักแน่นของอดีต",
  str_homestory_821901001_23_dialog_content = "ความรู้สึกนั้นเป็นเอกลักษณ์และพิเศษ",
  str_homestory_821901001_24_dialog_content = "ถ้าคุณรู้สึกอย่างนั้น...<sprite=emo_sikao size=60 />",
  str_homestory_821901001_25_dialog_content = "ฉันอยากจะมอบมันให้คุณ",
  str_homestory_821901001_26_dialog_content = "ทำไมคุณจะทำเช่นนั้น?",
  str_homestory_821901001_27_option_content = "เพราะเราเป็นเพื่อนกัน",
  str_homestory_821901001_28_dialog_content = "เพื่อมิตรภาพงั้นเหรอ?",
  str_homestory_821901001_29_dialog_content = "นั่นคือคำแสดงความจริงใจ",
  str_homestory_821901001_30_option_content = "ดูเหมือนว่าคุณชอบมันมากนะ",
  str_homestory_821901001_31_dialog_content = "แม้กระนั้น ฉันก็ไม่อยากเอามันไปเฉย ๆ",
  str_homestory_821901001_32_dialog_content = "แค่นั้นฉันก็ปลื้มใจมากแล้วนะ",
  str_homestory_821901001_33_dialog_content = "แต่ทำไมเราไม่ให้มันอยู่ \"บ้าน\" ไปเถอะ?",
  str_homestory_821901001_34_dialog_content = "ฉันไม่เข้าใจ คุณไม่ชอบเหรอ?",
  str_homestory_821901001_35_dialog_content = "ฉันมีนาฬิกาอื่นๆที่นี่ด้วย ดังนั้น...",
  str_homestory_821901001_36_dialog_content = "ฉันยินดีมากที่รู้ว่าคุณยินดีที่จะแบ่งปันทุกอย่างกับเพื่อน",
  str_homestory_821901001_37_dialog_content = "อย่างไรก็ตาม, ฉันคิดว่ามันควรจะไม่อยู่ที่ไหนอื่นนอกจากที่นี่",
  str_homestory_821901001_38_dialog_content = "อดีตแทนที่ความทรงจำ และความทรงจำประกอบด้วยประวัติศาสตร์",
  str_homestory_821901001_39_dialog_content = "ทุกอย่างเกี่ยวกับ Caelestite อยู่ที่นี่, PlayerName.",
  str_homestory_821901001_40_dialog_content = "ทั้งหมดนี้มีความหมายสำหรับคุณ",
  str_homestory_821901001_41_dialog_content = "ฉันไม่ต้องการเอาอะไรไปเลย",
  str_homestory_821901001_42_dialog_content = "อีสต์วาน...",
  str_homestory_821901001_43_dialog_content = "ลาก่อน ขอเงามืดจงเฝ้ามองเจ้า",
  str_homestory_821801001_0_dialog_content = "คุณเชโอล?",
  str_homestory_821801001_1_dialog_content = "ยินดีที่ได้พบคุณที่นี่! นี่เป็นสัญญาณว่าวันนี้จะมีสิ่งดีๆ เกิดขึ้น",
  str_homestory_821801001_2_dialog_content = "คุณเห็นด้วยไหมล่ะ, PlayerName?",
  str_homestory_821801001_3_dialog_content = "ไม่น่าแปลกใจเลยค่ะ คุณเชโอล คุณรู้ไหมว่าเราอยู่ที่ Cloud Gardens นะ...",
  str_homestory_821801001_4_dialog_content = "แน่นอนฉันทำ.",
  str_homestory_821801001_5_dialog_content = "แต่คุณต้องการเหตุการณ์บังเอิญที่เกิดขึ้นบ้าง ไม่ว่าจะเป็นในธุรกิจหรือในชีวิต",
  str_homestory_821801001_6_dialog_content = "ขอโทษนะ ฉันยังไม่เข้าใจเลย",
  str_homestory_821801001_7_dialog_content = "ไม่เป็นไร ฉันจะอธิบายให้ฟัง",
  str_homestory_821801001_8_dialog_content = "ตัวอย่างเช่น คุณต้องการปรับปรุงสวนลอยฟ้าและกิลด์เหนือเมฆ...",
  str_homestory_821801001_9_dialog_content = "เพียงแค่บังเอิญมีแผนสำหรับสิ่งนั้น",
  str_homestory_821801001_10_dialog_content = "จะไม่ใช่เรื่องบังเอิญหรือ?",
  str_homestory_821801001_11_dialog_content = "แล้วที่คุณพูดแบบนั้น คุณหมายความว่า...?",
  str_homestory_821801001_12_dialog_content = "สวนลอยฟ้ามีความพิเศษจริงๆ แต่คุณไม่คิดว่าหอพักดูน่าเบื่อไปหน่อยเหรอ?",
  str_homestory_821801001_13_option_content = "เขาเป็นไหม?",
  str_homestory_821801001_14_dialog_content = "แน่นอน ไม่งั้นฉันจะพูดถึงเรื่องนั้นทำไมล่ะ?",
  str_homestory_821801001_15_dialog_content = "คุณอาจจะชินกับมันแล้ว จึงไม่รู้สึกอย่างนั้น",
  str_homestory_821801001_16_dialog_content = "แต่ฉันคิดว่าหอพักธรรมดาไม่เหมาะกับสวนลอยฟ้าเลย",
  str_homestory_821801001_17_option_content = "ฉันก็รู้สึกเหมือนกัน",
  str_homestory_821801001_18_dialog_content = "ว่าแล้วเชียว!",
  str_homestory_821801001_19_dialog_content = "ถ้าเป็นเช่นนั้น คุณไม่คิดว่าเราควรทำอะไรเกี่ยวกับมันบ้างเหรอ?",
  str_homestory_821801001_20_dialog_content = "เช่นการปรับปรุงพวกเขาล่ะ?",
  str_homestory_821801001_21_dialog_content = "ที่ฉันหมายความคือ เราสามารถทำให้หอพักดูหรูหราขึ้นได้",
  str_homestory_821801001_22_dialog_content = "ดีขึ้น?",
  str_homestory_821801001_23_dialog_content = "ไม่ใช่ความคิดที่ไม่ดี แต่งบประมาณ<sprite=emo_baiyebi size=60 /> ค่อนข้างแน่น...",
  str_homestory_821801001_24_dialog_content = "อย่ากังวล! คุณสามารถไว้วางใจโปรเจคนี้ให้กับกิลด์เหนือเมฆของฉัน!",
  str_homestory_821801001_25_dialog_content = "ฉันจะปรับปรุงหอพักให้เข้ากับความงดงามของสวนลอยฟ้าฟรี!",
  str_homestory_821801001_26_dialog_content = "ฟรีเหรอ? ทั้งหมดเลยเหรอ?!",
  str_homestory_821801001_27_dialog_content = "ไม่แน่ใจเรื่องนั้นนะ...",
  str_homestory_821801001_28_dialog_content = "ฉันรู้ว่าเราเป็นเพื่อน แต่การทำแบบนี้ก็เหมือนเอาประโยชน์จากคุณเกินไปนะ Lady Sheol.",
  str_homestory_821801001_29_dialog_content = "เช่นที่คุณทราบ ฉันไม่ทำข้อตกลงที่ไม่ได้กำไร",
  str_homestory_821801001_30_dialog_content = "เมื่อหอพักสร้างเสร็จแล้ว เราจะเปลี่ยนแบรนด์สวนลอยฟ้าให้เป็นโรงแรมรีสอร์ท",
  str_homestory_821801001_31_dialog_content = "โรงแรมรีสอร์ต?!",
  str_homestory_821801001_32_dialog_content = "นั่งสบายๆ แล้วปล่อยทุกอย่างให้เป็นหน้าที่ฉันเถอะ",
  str_homestory_821801001_33_dialog_content = "หรือให้ฉันพูดอีกแบบหนึ่ง ฉันรับประกันว่าคุณจะต้องนับเงินจนเบื่อมันเลย!",
  str_homestory_821801001_34_dialog_content = "นับเงินจนเบื่อหรือเปล่า?!",
  str_homestory_821801001_35_dialog_content = "นี่คือโครงการที่คุณพูดถึงก่อนหน้านี้หรือไม่?",
  str_homestory_821801001_36_dialog_content = "นี่คือข้อเสนอที่ฉันไม่สามารถปฏิเสธได้จริงๆ<sprite=emo_aixin size=60 />!",
  str_homestory_821801001_37_dialog_content = "ยอดมาก, ถ้างั้นก็รับปากแล้ว...",
  str_homestory_821801001_38_dialog_content = "รอสักครู่, เลดี้เชล!",
  str_homestory_821801001_39_dialog_content = "ขอโทษนะ แต่ฉันแค่อยากให้สวนลอยฟ้ายังคงเป็นอย่างที่มันเป็นอยู่ตอนนี้เท่านั้นเอง",
  str_homestory_821801001_40_dialog_content = "ฉันไม่แน่ใจว่าชาวสวนลอยฟ้าจะรับข่าวนี้อย่างไร...",
  str_homestory_821801001_41_dialog_content = "ดังนั้นถ้าเราเพียงรีบเข้าสู่โครงการทันที...",
  str_homestory_821801001_42_dialog_content = "เข้าใจแล้ว. ฉันรู้เรื่องแล้ว.",
  str_homestory_821801001_43_dialog_content = "นั่นหมายความว่าเรามีโอกาสทำให้การท่องเที่ยวกลายเป็นสิ่งที่เกิดขึ้นในอนาคต ใช่ไหม?",
  str_homestory_821801001_44_dialog_content = "ท่องเที่ยว?",
  str_homestory_821801001_45_dialog_content = "จากนั้น ฉันจะรอฟังจากคุณนะ!",
  str_homestory_822101001_0_dialog_content = "สนใจหรือไม่?",
  str_homestory_822101001_1_dialog_content = "ฉันเห็นคุณมองมันตลอดเวลา ดูเหมือนจะตื่นเต้นมากเลยนะ",
  str_homestory_822101001_2_dialog_content = "นี่คือ<sprite=emo_sikao size=60 />...",
  str_homestory_822101001_3_dialog_content = "ถังขยะที่สามารถจัดเรียงขยะรีไซเคิลโดยอัตโนมัติได้หรือ?",
  str_homestory_822101001_4_dialog_content = "ว้าว! คุณรู้ได้ยังไงเนี่ย?!",
  str_homestory_822101001_5_dialog_content = "มันเป็นถังขยะแบบ Caelestite ที่แตกต่างจากประเภททั่วไปที่คุณเคยเห็น",
  str_homestory_822101001_6_dialog_content = "แต่ฉันยังคิดว่ามันคงจะไม่ถูกจำแนกออกมาได้ง่ายๆ",
  str_homestory_822101001_7_dialog_content = "ฮี่, กำลังดูถูกฉันอีกเหรอ?",
  str_homestory_822101001_8_dialog_content = "ฉันจะอธิบายเกี่ยวกับการวิเคราะห์ของฉันให้ละเอียดเลย",
  str_homestory_822101001_9_dialog_content = "ขั้นแรกที่สุด, ฉันเจาะระบบโปรแกรมควบคุมของมันและลองมองดูสักหน่อย...",
  str_homestory_822101001_10_dialog_content = "อะไร? ทำไมคุณถึงทำแบบนั้นกับเฟอร์นิเจอร์ของคนอื่น?!",
  str_homestory_822101001_11_dialog_content = "มันเป็นภาษาโปรแกรมมิ่งอื่นที่ทันสมัยและกระชับ แน่นอนว่าเป็นผลงานชิ้นเอกของเทคโนโลยีชั้นสูงของเคเลสไทต์!",
  str_homestory_822101001_12_dialog_content = "แต่เมื่อพูดถึงฟังก์ชัน ฉันสามารถรับรู้ถึงความคล้ายคลึงกับระบบจัดเรียงอัตโนมัติในโรงอาหาร Illumina",
  str_homestory_822101001_13_dialog_content = "ซึ่งหมายความว่าสิ่งนี้ก็มีฟีเจอร์การจัดหมวดหมู่ที่เหมือนกัน",
  str_homestory_822101001_14_dialog_content = "เห็นแก่นั้น ฉันเขียนโปรแกรมสำหรับโรงอาหารของ Illumina นะ",
  str_homestory_822101001_15_dialog_content = "มันสามารถจัดเรียงและแจกจ่ายอาหารตามระดับสารอาหารได้!",
  str_homestory_822101001_16_dialog_content = "ดี.",
  str_homestory_822101001_17_dialog_content = "ฉันสงสัยว่าจะมีส่วนผสมที่มีคุณค่าทางโภชนาการหรือไม่ที่สามารถลดความปรารถนาในการยุ่งเกี่ยวกับเฟอร์นิเจอร์ของเพื่อน.",
  str_homestory_822101001_18_dialog_content = ".... ไม่เลวที่คุณจะเชื่อมโยงคำว่า \"การแยก\" กับถังขยะนะ",
  str_homestory_822101001_19_dialog_content = "อืม, มีเหตุผลที่ชัดเจนมากขึ้นสำหรับสิ่งนั้น",
  str_homestory_822101001_20_dialog_content = "งั้นเหรอ",
  str_homestory_822101001_21_dialog_content = "มันมีภาพขยะขนาดใหญ่อยู่บนนั้น",
  str_homestory_822101001_22_dialog_content = "...",
  str_homestory_822101001_23_dialog_content = "ยอดเลย!",
  str_homestory_822101001_24_dialog_content = "การจัดเรียงอัตโนมัติไม่ได้เป็นสิ่งที่ดีที่สุดตั้งแต่มีขนมปังสไลซ์",
  str_homestory_822101001_25_dialog_content = "แต่การจัดระบบลงในปริมาตรที่เล็กแคบขนาดนี้...",
  str_homestory_822101001_26_dialog_content = "ด้วยคุณสมบัติการจัดเรียงที่ละเอียดอ่อนแบบนี้... นั่นคือสิ่งที่เทคโนโลยีของ Illumina ในปัจจุบันสามารถฝันถึงเท่านั้น",
  str_homestory_822101001_27_dialog_content = "ชาวเคเลสไทต์นั้นเป็นคนที่ยอดเยี่ยมจริง ๆ!",
  str_homestory_822101001_28_dialog_content = "อืม...",
  str_homestory_822101001_29_option_content = "เธอคิดแบบนั้นจริง ๆ เหรอ?",
  str_homestory_822101001_30_dialog_content = "มันแค่ถังขยะเท่านั้นเอง",
  str_homestory_822101001_31_dialog_content = "\"แค่ถังขยะ\" นั่นแหละที่ทำให้มันเจ๋ง",
  str_homestory_822101001_32_option_content = "ฉันไม่คิดว่าคุณจะชอบ \"ถังรีไซเคิลอัตโนมัติ\" มากขนาดนี้",
  str_homestory_822101001_33_dialog_content = "นั่นทำให้ฉันตื่นเต้นทั้งหมดเลย!",
  str_homestory_822101001_34_dialog_content = "คุณควรจะเป็น!",
  str_homestory_822101001_35_dialog_content = "เทคโนโลยีล้ำสมัยมักถูกนำไปใช้ในทางทหารเป็นอันดับแรก",
  str_homestory_822101001_36_dialog_content = "เมื่อพวกเขากลายเป็นสิ่งที่มากกว่าฝุ่นแล้ว คนธรรมดาจึงจะสามารถเข้าถึงได้",
  str_homestory_822101001_37_dialog_content = "ในกรณีนี้ เพราะเท่านั้นที่ถังรีไซเคิลอัตโนมัตินี้เป็นถังขยะ...",
  str_homestory_822101001_38_dialog_content = "นั่นแสดงให้เห็นความยิ่งใหญ่ของวัฒนธรรม Caelestite!",
  str_homestory_822101001_39_dialog_content = "อ๋า! มันสมเหตุสมผลจริงๆ ตอนที่ฉันคิดถึงมัน!",
  str_homestory_822101001_40_dialog_content = "แม้ว่าฉันยังรู้สึกไม่ดีที่คุณเจาะระบบโปรแกรม...",
  str_homestory_822101001_41_dialog_content = "แต่ฉันมักจะได้เรียนรู้อะไรสักอย่างจากการคุยกับคุณเสมอ ฉันจริงจังนะ",
  str_homestory_822101001_42_dialog_content = "ขอบคุณคุณ อัลกอล.",
  str_homestory_822101001_43_dialog_content = "ไม่ต้องพูดถึงมัน! แต่ฉันยิ่งอยากให้คุณอนุญาตให้ฉันแยกถังออกเพื่อศึกษาอย่างละเอียด...",
  str_homestory_822101001_44_dialog_content = "ลืมเรื่องนั้นเถอะ!",
  str_homestory_822301001_0_dialog_content = "รูปปั้นหินนี้...",
  str_homestory_822301001_1_dialog_content = "ฉันแทบจะไม่เห็นสิ่งประดิษฐ์แบบนี้ในถ้ำของคุณเลย PlayerName.",
  str_homestory_822301001_2_dialog_content = "รูปปั้นนี้มีความหมายพิเศษอะไรสำหรับคุณหรือเปล่า?",
  str_homestory_822301001_3_dialog_content = "คุณเดาถูก... นี่คือรูปปั้นของเด็กหญิงชาวเคเลสไทต์",
  str_homestory_822301001_4_dialog_content = "เคเลสไทต์... หนึ่งในพวกของคุณจากช่วงเวลาที่ยาวนานแล้วใช่ไหม?",
  str_homestory_822301001_5_dialog_content = "ฉันสัมผัสได้ถึงลมหายใจของเวลาที่เข้ามาจากทุกๆรอยแตกและรอยขีดข่วนบนรูปปั้นนี้",
  str_homestory_822301001_6_dialog_content = "เรื่องราวกล่าวว่าเธอเป็นนักเดินทาง คนที่ได้เยือนทุกแหล่งท่องเที่ยวที่มีชื่อเสียงของทวีปของเรา",
  str_homestory_822301001_7_dialog_content = "และคุณถูกต้องนะ เฉินนี่ รูปปั้นนี้มาจากช่วงเวลาที่ยาวนานมาก...",
  str_homestory_822301001_8_dialog_content = "จะเป็นอันตรายสำหรับ Caelestite ที่จะเดินทางในโลกของเราที่เต็มไปด้วย Eclipsite <sprite=emo_kulou size=60 /> ด้วยตัวเองในตอนนี้...",
  str_homestory_822301001_9_dialog_content = "มีฉันอยู่เคียงข้างคุณ มีอะไรต้องกลัวหรือไม่",
  str_homestory_822301001_10_dialog_content = "บางวันอาจจะมีรูปปั้นถูกสร้างขึ้นเพื่อรำลึกถึงคุณเช่นกันไหม?",
  str_homestory_822301001_11_dialog_content = "หืม? ฉ-ฉันเหรอ?! ไม่ใช่เลยนะ, ฉันไม่มีอะไรพิเศษเลย...",
  str_homestory_822301001_12_dialog_content = "ทำไมไม่ล่ะ? ยกตัวอย่างเช่น ถ้าโลกนี้เกิดภัยแล้งรุนแรง แล้วฉันเรียกฝนหนักๆมา เพื่อนำความรอดรอดมาให้ทุกคน...",
  str_homestory_822301001_13_dialog_content = "แล้วหลังจากนั้นคุณพาฉันไปซื้อแตงโม...",
  str_homestory_822301001_14_dialog_content = "จากนั้นทุกคนจะเห็นคุณอยู่กับฉัน และสร้างรูปปั้นจากทั้งสองคนเรา!",
  str_homestory_822301001_15_dialog_content = "นี่เป็นตัวอย่างที่เฉพาะเจาะจงแปลก ๆ จนเหมือนว่ามันเคยเกิดขึ้นจริงในบางจุด...",
  str_homestory_822301001_16_dialog_content = "หรืออาจจะเป็นฤดูหนาวครั้งหนึ่ง ฉันได้ช่วยคนทั้งสิ้น 38 คนจากเรือที่ล่มในทะเลในครั้งเดียว!",
  str_homestory_822301001_17_dialog_content = "และเมื่อพวกมันขึ้นฝั่ง คุณจะจุดไฟและให้ผ้าห่มเพื่อให้พวกมันรอดจากความหนาวที่รุนแรง...",
  str_homestory_822301001_18_dialog_content = "พวกเขาจะวางรูปปั้นของคุณไว้ข้างๆของฉัน และคนทั่วไปจะไปสูบธูปเพื่อเป็นเกียรติแก่เราในหลายๆ รุ่น!",
  str_homestory_822301001_19_dialog_content = "...",
  str_homestory_822301001_20_dialog_content = "มีอะไรขัดใจหรือ? เรื่องราวเหล่านี้ฟังดูไม่น่าสนใจเหรอคุณ?",
  str_homestory_822301001_21_option_content = "เห็นด้วยเลย",
  str_homestory_822301001_22_dialog_content = "แต่พวกเขาก็ฟังดูเศร้าจริงๆนะ",
  str_homestory_822301001_23_option_content = "มันพูดยาก...",
  str_homestory_822301001_24_dialog_content = "ฉันรู้สึกว่านั่นไม่ใช่วิธีที่ดีในการพิจารณาเขา",
  str_homestory_822301001_25_dialog_content = "ส่วนใหญ่เพราะพวกมันไม่ได้เป็นแค่เรื่องราวเท่านั้น ใช่ไหม",
  str_homestory_822301001_26_dialog_content = "เมื่อฉันอยู่ในหลงโจว ฉันได้เห็นรูปปั้นของคุณหลายๆ ที่ในที่ต่างๆ",
  str_homestory_822301001_27_dialog_content = "ฉันนึกว่าคุณคงได้ช่วยเหลือผู้คนมากมายทั่วหลงโจว ทำให้เกิดตำนานและเรื่องราวเหมือนที่คุณเพิ่งพูดถึง",
  str_homestory_822301001_28_dialog_content = "เกี่ยวกับคนในเรื่องราวของคุณ เช่น คนที่ซื้อแตงโมให้คุณหรือคนที่ช่วยคุณช่วยชีวิตคนพวกนั้น...",
  str_homestory_822301001_29_dialog_content = "พวกเขาคงไม่ได้เป็นส่วนหนึ่งของโลกนี้อีกต่อไป... เธอคือคนเดียวที่ยังอยู่",
  str_homestory_822301001_30_dialog_content = "คุณสงสารฉันรึเปล่า PlayerName?",
  str_homestory_822301001_31_dialog_content = "ฉันเสียใจที่คุณต้องบอกลาคนรอบข้างคุณอยู่เรื่อย ๆ...",
  str_homestory_822301001_32_dialog_content = "ผิดหรือเปล่าที่ฉันรู้สึกอย่างนั้นกับเทพีมังกร?",
  str_homestory_822301001_33_dialog_content = "ในฐานะที่เป็นมนุษย์ที่มีเลือดเนื้อ การรู้สึกแบบนี้ของคุณถือว่าเป็นเรื่องปกติเลย",
  str_homestory_822301001_34_dialog_content = "ฉันก็รู้สึกเหมือนกันเกี่ยวกับคุณเช่นกัน",
  str_homestory_822301001_35_dialog_content = "เวลายาวนานอย่างไม่นึกคิดได้ และนำทุกสิ่งไปสู่จุดสิ้นสุด",
  str_homestory_822301001_36_dialog_content = "แม้ว่าฉันจะมีอายุยืนยาว แต่การมีอยู่ของฉันเพียงแค่การหยิบตาเท่านั้นเมื่อเทียบกับโลก",
  str_homestory_822301001_37_dialog_content = "แต่ความชั่วคราวของเรานั้นเองที่ทำให้การพบกันของเรามีค่าความรู้สึก การสามารถเดินข้างๆ กันคือการสานรวมชะตากรรมของเราเข้าด้วยกัน",
  str_homestory_822301001_38_dialog_content = "ถ้าฉันเห็นแก่ตัวเองและสงสารมนุษย์เพราะอายุขัยสั้น ๆ นั้นจะเป็นความโอหังของฉัน",
  str_homestory_822301001_39_dialog_content = "นั่นทำให้มีเหตุผล... ไม่รู้สาเหตุ แต่อารมณ์ฉันดีขึ้นมากในตอนนี้",
  str_homestory_822301001_40_dialog_content = "\"มิตรภาพไม่กลัวการผ่านไปของเวลา\" นั่นไม่ใช่สิ่งที่พวกเขาพูดในหลงโจวหรือไม่?",
  str_homestory_822301001_41_dialog_content = "ถูกต้องอย่างที่สุด! คุณจริงๆ ได้เรียนรู้เยอะมากในช่วงนี้นะ.",
  str_homestory_822301001_42_dialog_content = "เวลาอาจจะโหดร้าย แต่ก็มีด้านดีของมันเอง",
  str_homestory_822301001_43_dialog_content = "<sprite=emo_qingsong size=60 /> ฮีฮี... คิดว่าฉันไม่สามารถทิ้งเวลาไปโดยนั่งเฉยๆ ที่หนึ่งที่!",
  str_homestory_822301001_44_dialog_content = "นอกจากนี้ ถ้าไม่ได้เพราะการผ่านไปของเวลา เราคงไม่มีวันได้พบกัน...",
  str_homestory_822301001_45_dialog_content = "และฉันก็คงไม่มีทางได้ใช้วันที่มีความสุขมากมายที่นี่กับทุกคน",
  str_homestory_822401001_0_dialog_content = "หลั่ว ซง?",
  str_homestory_822401001_1_dialog_content = "คุณอยากใช้สิ่งนี้มั้ย?",
  str_homestory_822401001_2_dialog_content = "แน่นอนฉันทำ! มันถูกทำอย่างละเอียดอ่อนอยู่ดีเลยละ!",
  str_homestory_822401001_3_dialog_content = "สุดยอด... ทำได้เหรอ?",
  str_homestory_822401001_4_dialog_content = "ใช่! ดูที่การแสดงออกของมันสิ มันกระตุ้นความอยากทะเลาะกับมันขึ้นมา!",
  str_homestory_822401001_5_dialog_content = "และโครงของมันก็ไม่แข็งหรือนุ่มเกินไปเช่นกัน!",
  str_homestory_822401001_6_dialog_content = "ไม่ว่าคุณจะตีมันแรงแค่ไหน มันก็จะกลับสู่ตำแหน่งเดิมเสมอ...",
  str_homestory_822401001_7_dialog_content = "มันเป็นเครื่องมือฝึกฝนที่สมบูรณ์แบบสำหรับกำปั้นของฉัน!",
  str_homestory_822401001_8_option_content = "เข้าใจ",
  str_homestory_822401001_9_dialog_content = "ฉันรู้<sprite=emo_guilian size=60 /> ว่าคุณจะเข้าใจ, PlayerName.",
  str_homestory_822401001_10_option_content = "ฉัน...ไม่ค่อยเข้าใจเลย...",
  str_homestory_822401001_11_dialog_content = "ฉันก็อธิบายไม่ค่อยได้เหมือนกันนะ <sprite=emo_sikao size=60 />. คงเรียกว่าสัญชาตญาณของนักรบเหรอ?",
  str_homestory_822401001_12_dialog_content = "ในระหว่างการเดินทางของฉันในหลงโจว ฉันได้ฝึกฝนอย่างขมขื่นทุกวันๆ",
  str_homestory_822401001_13_dialog_content = "การสร้างกำลัง, การทำสมาธิ, การชกมวยเงา, คุณเรียกมันอย่างไรก็ได้.",
  str_homestory_822401001_14_dialog_content = "แม้แต่หนึ่งวันที่ไม่ได้ฝึกฝนก็สามารถทำให้คนกลายเป็นสนิมได้",
  str_homestory_822401001_15_dialog_content = "แต่จุดประสงค์ของการฝึกฝนอย่างนี้คือเพื่อเพิ่มความแข็งแกร่งให้กับร่างกาย",
  str_homestory_822401001_16_dialog_content = "มีคนบางคนที่หลงไปกับส่วนที่ \"ขม\" และในที่สุดก็ทำให้ตนเองเจ็บปวดเป็นผล",
  str_homestory_822401001_17_dialog_content = "และนั่นทำให้วัตถุประสงค์ล้มเหลวโดยสิ้นเชิง",
  str_homestory_822401001_18_dialog_content = "ใช่แล้ว!",
  str_homestory_822401001_19_dialog_content = "มันเหมือนกับบางคนที่ชนต้นไม้ซ้ำ ๆ ในขณะที่ฝึกฝนเทคนิค \"Iron Mountain Lean\"",
  str_homestory_822401001_20_dialog_content = "เนื่องจากมีความเสี่ยงสูงที่จะทำให้บาดเจ็บตัวเอง การฝึกท่านั้นโดยวิธีนี้เป็นการทำที่ไม่ฉลาดอย่างยิ่ง",
  str_homestory_822401001_21_dialog_content = "เข้าใจแล้ว ยิ่งรู้มากเท่าไหร่ หรือ...",
  str_homestory_822401001_22_dialog_content = "ในระหว่างการเดินทางของฉัน ฉันต้องใช้ต้นไม้เพื่อฝึกฝนเนื่องจากฉันไม่สามารถหาวิธีที่ดีกว่านี้",
  str_homestory_822401001_23_dialog_content = "อาจเป็นเพราะฉันยังเด็ก แต่ฉันรู้สึกเจ็บปวดหรือไม่สบายน้อยมาก",
  str_homestory_822401001_24_dialog_content = "แต่หลังจากนั้นฉันก็เริ่มฝึกอาดิงและคนอื่น ๆ",
  str_homestory_822401001_25_dialog_content = "และฉันรู้สึกเร็วว่าการปฏิบัติตามกิจวัตรของฉันเป็นวิธีง่าย ๆ ที่จะทำให้พวกเขาได้รับบาดเจ็บ",
  str_homestory_822401001_26_dialog_content = "ฉันยังรู้สึกว่าวิธีการฝึกฝนและอุปกรณ์ที่ฉันใช้ในอดีตนั้นหยาบคายเกินไป",
  str_homestory_822401001_27_dialog_content = "นั่นเหตุผลว่าทำไมฉันเริ่มใส่ใจกับความปลอดภัยในระหว่างการฝึกฝนมากขึ้น และรวมถึงสิ่งที่เช่นอุปกรณ์ป้องกัน",
  str_homestory_822401001_28_dialog_content = "ฉันยังได้สร้างอุปกรณ์ฝึกฝนที่กำหนดเองเฉพาะสำหรับอาห์ดิงและเด็กๆ อสูรคนอื่นๆ...",
  str_homestory_822401001_29_dialog_content = "ฉันใช้เวลาและความพยายามมากมายในการออกแบบอุปกรณ์โดยคำนึงถึงความต้องการของพวกเขา",
  str_homestory_822401001_30_dialog_content = "โดยเฉพาะเสาที่มีลายดอกพลัมนั้น ต้องลองทำหลายครั้งจึงจะสามารถทำให้มันสอดคล้องกับขาที่สั้น ๆ และเล็ก ๆ ของมันได้!",
  str_homestory_822401001_31_dialog_content = "คุณนี่เป็นคนมีน้ำใจจริงๆนะ",
  str_homestory_822401001_32_dialog_content = "แน่นอน นอกจากนี้ฉันก็ไม่มีงานอดิเรกอื่นนอกจากการฝึกฝนเลย",
  str_homestory_822401001_33_dialog_content = "ดังนั้นฉันก็จะทำสิ่งที่ดีที่สุดสำหรับการฝึกซ้อมของเพื่อน ๆ ของฉันด้วยเช่นกัน",
  str_homestory_822401001_34_dialog_content = "เมื่อฉันมีเวลา ฉันจะแน่นอนที่จะออกแบบสิ่งต่าง ๆ ให้คุณด้วยนะ!",
  str_homestory_822501001_0_dialog_content = "โคมไฟที่อยู่ตรงนั้น...",
  str_homestory_822501001_1_dialog_content = "คุณชอบเสาไฟทางเดินนั้นหรือเทียเร่?",
  str_homestory_822501001_2_dialog_content = "อยากดูใกล้ ๆ ก็เชิญตามสบายครับ",
  str_homestory_822501001_3_dialog_content = "นี่คือระยะที่ดีที่สุดจริงๆนะ",
  str_homestory_822501001_4_dialog_content = "มันทำให้ฉันนึกถึง Beacon ที่ Northland จากที่นี่",
  str_homestory_822501001_5_dialog_content = "ฉันเข้าใจที่คุณพูดแล้ว พอคุณพูดถึงมัน",
  str_homestory_822501001_6_dialog_content = "เป็นเรื่องน่าเสียดายที่มันเป็นแค่โคมไฟธรรมดา และไม่ได้คอยดูแลสัตว์ในนอร์ธแลนด์เหมือนประภาคาร",
  str_homestory_822501001_7_dialog_content = "...",
  str_homestory_822501001_8_dialog_content = "ฉันเคยนั่งบนยอดต้นซีดาร์และมองเห็นแสงสว่างเมื่อฉันยังเด็ก",
  str_homestory_822501001_9_dialog_content = "มันสว่างอย่างไม่น่าเชื่อ...",
  str_homestory_822501001_10_dialog_content = "ความสว่างของมันสามารถส่องถึงทุกที่ ไม่ว่าจะมืดแค่ไหนหรือมีหมอกมากแค่ไหน",
  str_homestory_822501001_11_dialog_content = "แสงไฟทำให้ป่าสนหิมะสงบและเงียบสนิท",
  str_homestory_822501001_12_dialog_content = "ไม่มีเสียงกรีดร้องจากอิคลิพไซท์ ไม่มีเสียงร้องของออโรเรียน... ความสงบนั้นมีค่าที่ไม่สามารถวัดได้",
  str_homestory_822501001_13_dialog_content = "เราชาวนอร์ธแลนด์เท่านั้นที่มี<color=#FFB400>ประภาคาร</color>พิเศษนั้น",
  str_homestory_822501001_14_dialog_content = "ฉันสามารถรู้ได้ว่าคุณทุกคนนับถือและเคารพมันมากเท่าไหร่",
  str_homestory_822501001_15_dialog_content = "จริงๆ แล้ว สิ่งที่เราชื่นชมและเคารพนับถือนั้นไม่ใช่<color=#FFB400>ประภาคาร</color>...",
  str_homestory_822501001_16_dialog_content = "ครั้งหนึ่งฉันยุ่งเหยิงไล่ล่าเหยื่อที่ฉลาดลวงจนไม่รู้ตัวว่าฉันไปไกลแค่ไหนแล้ว",
  str_homestory_822501001_17_dialog_content = "จนกระทั่งเสียงร้องของอิคลิพไซท์ทำให้ฉันตกใจ! ในตอนนั้น ฉันอยู่ห่างจากบ้านมากเกินไปแล้ว.",
  str_homestory_822501001_18_dialog_content = "นั่นคือเมื่อฉันเห็นแสงสว่างจากดวงประทีป",
  str_homestory_822501001_19_dialog_content = "คุณยังสามารถมองเห็นมันได้จากที่ห่างไกลจากบ้านหรือไม่?",
  str_homestory_822501001_20_dialog_content = "ไม่ สิ่งที่ฉันเห็นไม่ใช่ <color=#FFB400>ประภาคาร</color>ที่ปกป้องเรา",
  str_homestory_822501001_21_dialog_content = "แต่ประภาคารธรรมดาที่อยู่ริมทะเล",
  str_homestory_822501001_22_dialog_content = "มันจะกลายเป็นที่ซ่อนของอิคลิพไซท์หลังจากพระอาทิตย์ตก",
  str_homestory_822501001_23_dialog_content = "โอ้สวรรค์ดี!",
  str_homestory_822501001_24_dialog_content = "ฉันซ่อนตัวอยู่ในป่า ไม่กล้าที่จะเคลื่อนไหว",
  str_homestory_822501001_25_dialog_content = "แสงยังคงสาดผ่านฉันไปเรื่อย ๆ",
  str_homestory_822501001_26_dialog_content = "ฉันมองมันขณะที่อิคลิพไซท์เคลื่อนไหวไปที่ด้านล่าง",
  str_homestory_822501001_27_dialog_content = "คุณรู้ไหมว่าฉันตระหนักอะไรในตอนนั้น?",
  str_homestory_822501001_28_dialog_content = "ว่าไง",
  str_homestory_822501001_29_dialog_content = "ประภาคารนั้นเหมือนกับดวงประทีปที่ฉันชื่นชมและเคารพเป็นอย่างมากเลย",
  str_homestory_822501001_30_dialog_content = "...",
  str_homestory_822501001_31_dialog_content = "มันมีแสงสว่างเดียวกันที่สามารถทะลุคืนที่มืดที่สุดและหมอกที่หนาแน่น...",
  str_homestory_822501001_32_dialog_content = "แต่มันก็ปกป้องฉันไม่ได้ ตลอดทั้งคืน ถ้าฉันแม้แต่เคลื่อนไหวเล็กน้อย...",
  str_homestory_822501001_33_dialog_content = "อิคลิพไซท์คงทำให้ฉันแตกเป็นชิ้นๆ",
  str_homestory_822501001_34_dialog_content = "เทียเร่...",
  str_homestory_822501001_35_dialog_content = "ในที่สุดฉันก็เข้าใจในคืนนั้น",
  str_homestory_822501001_36_dialog_content = "ดวงประทีปเองไม่มีอะไรพิเศษ",
  str_homestory_822501001_37_dialog_content = "เหมือนกับโคมไฟธรรมดาที่เราเห็นนี้ มันเป็นแค่อาคารธรรมดา",
  str_homestory_822501001_38_dialog_content = "ถ้าไม่มีใครจุดมัน ดูแลมัน และใส่ความมุ่งมั่นลงไป มันคงจะไม่มีอะไรเกิดขึ้นเลย",
  str_homestory_822501001_39_dialog_content = "สิ่งที่คอยปกป้องชาวนอร์ธแลนด์นั้น... ไม่ใช่ประภาคารเลย...",
  str_homestory_822501001_40_dialog_content = "แต่ราชินีเบธเลเฮม",
  str_homestory_822501001_41_dialog_content = "...",
  str_homestory_822501001_42_option_content = "ความมุ่งมั่นขององค์ราชินีนั้นแข็งแกร่งอย่างไม่มีที่ติ",
  str_homestory_822501001_43_dialog_content = "แม้ไม่มีประภาคาร แต่เธอก็ยังทำทุกอย่างที่เธอสามารถเพื่อปกป้องประชาชนของเธอ",
  str_homestory_822501001_44_option_content = "คืนนั้นต้องเป็นคืนที่สำคัญในชีวิตของคุณแน่ๆ",
  str_homestory_822501001_45_dialog_content = "คืนนั้นคือเมื่อคุณสร้างความตั้งใจของคุณเอง",
  str_homestory_822501001_46_dialog_content = "นั่นสินะ",
  str_homestory_822501001_47_dialog_content = "แม้ว่าฉันจะไม่สามารถเทียบเท่ากับพระราชินี ฉันก็จะตามเธอจนถึงสุดท้าย",
  str_homestory_822501001_48_dialog_content = "ฉันได้สละชีวิตของฉันเพื่อป้องกันและปกป้องผู้คนของฉัน เช่นเธอ",
  str_homestory_822501001_49_dialog_content = "นั่นคือสิ่งที่ฉันรู้สึกเช่นกัน",
  str_homestory_822501001_50_dialog_content = "โดยเฉพาะส่วนที่ว่า \"ไม่สามารถเทียบเท่ากับองค์ราชินี\"",
  str_homestory_822501001_51_dialog_content = "ฮ่าฮ่า, ใครจะเทียบเท่ากับเธอได้ล่ะ?",
  str_homestory_822501001_52_dialog_content = "แต่ตราบใดที่เธอยังอยู่ที่นั่น ฉันจะไม่หลงทางเลย",
  str_homestory_822601001_0_dialog_content = "นี่...",
  str_homestory_822601001_1_dialog_content = "คุณไม่คิดว่าม้าโยกนี้น่าสนใจใช่มั้ย ราเชล?",
  str_homestory_822601001_2_dialog_content = "ฉันรู้ว่ามันดูเหมือนเด็กน้อยหน่อย แต่ขี่มันสนุกอย่างไม่น่าเชื่อ",
  str_homestory_822601001_3_dialog_content = "อยากลองไหม? ไปเลย!",
  str_homestory_822601001_4_dialog_content = "ผมไม่เอาดีกว่า...",
  str_homestory_822601001_5_dialog_content = "ไม่ว่าคุณจะพูดยังไง ฉันก็แก่เกินไปสำหรับเรื่องแบบนี้แล้วนะ",
  str_homestory_822601001_6_dialog_content = "เมื่อพูดถึงคุณ ฉันไม่รู้เลยว่าคุณเป็นแฟนของม้าโยกขนาดใหญ่เช่นนี้",
  str_homestory_822601001_7_dialog_content = "ฉัน-ฉันจะไม่เรียกตัวเองว่า \"แฟน\" ของพวกเขาหรืออะไร...",
  str_homestory_822601001_8_dialog_content = "(ฉันคิดว่าเธอเขินจนไม่กล้าขี่ แต่ตอนนี้ความลับของฉันถูกเปิดเผยแล้ว!)",
  str_homestory_822601001_9_dialog_content = "แต่ก็ต้องยอมรับว่า ของเล่นตัวนี้ทำดีมากเลยนะ",
  str_homestory_822601001_10_dialog_content = "เมื่อคุณมองผ่านภาพลักษณ์ที่เรียบง่าย คุณจะพบว่าการออกแบบและฝีมือช่างทั้งสองอย่างนั้นยอดเยี่ยม",
  str_homestory_822601001_11_dialog_content = "การผสมผสานที่มีพลังระหว่างอร์โกโนมิกส์และกลศาสตร์โครงสร้าง",
  str_homestory_822601001_12_dialog_content = "แม้แต่ฉันยังถูกมันดึงดูด",
  str_homestory_822601001_13_dialog_content = "ว้าว... ผมไม่เคยสังเกตเห็นอะไรเลยครับ",
  str_homestory_822601001_14_dialog_content = "คุณหมายความว่าคุณสามารถรู้เรื่องทั้งหมดเหล่านั้นได้เพียงแค่มองสิ่งนั้นเหรอ?",
  str_homestory_822601001_15_dialog_content = "ใช่ มันเป็นทักษะพื้นฐานสำหรับวิศวกรทุกคน",
  str_homestory_822601001_16_dialog_content = "ความสามารถในการวาดภาพเรนเดอร์สามมิติของวัตถุใด ๆ จากการมองเพียงครั้งเดียวนั้นสำคัญมาก",
  str_homestory_822601001_17_dialog_content = "ในที่สุด ฉันก็มีความคิดที่ดีเกี่ยวกับวิธีการทำซ้ำม้าโยกนี้แล้ว",
  str_homestory_822601001_18_dialog_content = "ฟังดูเหมือนพลังพิเศษสำหรับฉัน...",
  str_homestory_822601001_19_dialog_content = "เอาล่ะ ฉันจะให้คุณเอาไป!",
  str_homestory_822601001_20_dialog_content = "หา?",
  str_homestory_822601001_21_option_content = "คุณสามารถนำมันกลับบ้านเพื่อวัตถุประสงค์ในการวิจัยได้นะ",
  str_homestory_822601001_22_dialog_content = "ฉันเข้าใจแล้ว คุณต้องการให้ฉันออกไป เพื่อที่ฉันจะหยุดรบกวนคุณ ใช่ไหม?",
  str_homestory_822601001_23_dialog_content = "เปล่าเลยนะ!",
  str_homestory_822601001_24_option_content = "ดูเหมือนคุณจะชอบมันมากนะ",
  str_homestory_822601001_25_dialog_content = "ใช่ แต่ผมชอบโคลอสซัสของคุณมากกว่าอะไรอื่น",
  str_homestory_822601001_26_dialog_content = "โซรอซไม่ได้อยู่บนโต๊ะนะ!",
  str_homestory_822601001_27_dialog_content = "เฮ้... แค่ล้อเล่นนะคะ",
  str_homestory_822601001_28_dialog_content = "ขอบคุณที่เอื้อเฟื้อนะครับ แต่ว่า...",
  str_homestory_822601001_29_dialog_content = "ฉันอยากจะทำของขวัญให้พี่สาวด้วยมือของฉันเองสองข้าง",
  str_homestory_822601001_30_dialog_content = "... พี่คะ?",
  str_homestory_822601001_31_dialog_content = "ใช่ เมื่อผมเห็นม้าโยกตัวนี้ ผมก็ตัดสินใจที่จะทำตัวหนึ่งที่เหมือนกันให้กับน้องสาวของผมเลย",
  str_homestory_822601001_32_dialog_content = "ฉันไม่เคยมีโอกาสได้เล่นของเล่นแบบนี้ตอนเป็นเด็ก แต่อย่างน้อยน้องสาวของฉันก็จะได้...",
  str_homestory_822601001_33_dialog_content = "อาจจะเป็นเพราะวิธีของฉันในการชดเชยอดีตของตัวเองเท่านั้นเอง",
  str_homestory_822601001_34_dialog_content = "เรเชล...",
  str_homestory_822601001_35_dialog_content = "ฉันพูดจริงเมื่อกี้น่ะ",
  str_homestory_822601001_36_dialog_content = "ม้าโยกนี้... มันสนุกกว่าที่คุณคิดอยู่เยอะเลย!",
  str_homestory_822601001_37_dialog_content = "ฮ-ฮะ?",
  str_homestory_822601001_38_dialog_content = "ลองทำดูสิ! คุณไม่สามารถทำสำเนาที่สมบูรณ์แบบสำหรับพี่สาวของคุณได้ หากคุณยังไม่ได้ลองใช้ตัวจริงด้วยตัวเองใช่ไหม?",
  str_homestory_822601001_39_dialog_content = "มาเถอะ, อย่าเขินนะ!",
  str_homestory_822601001_40_dialog_content = "เอ่อ... งั้นก็ได้... แต่แค่ครั้งนี้ครั้งเดียวนะ",
  str_homestory_822601001_41_dialog_content = "ฉันแน่ใจว่าคุณก็จะติดมันเหมือนกัน!",
  str_homestory_822701001_0_dialog_content = "เซต้า?",
  str_homestory_822701001_1_dialog_content = "มันเป็นตัวอะไรกันแน่เนี่ย?",
  str_homestory_822701001_2_dialog_content = "ปีกที่น่ารักนี้, งานฝีมือชำนาญนี้...",
  str_homestory_822701001_3_dialog_content = "ถ้าคุณถามฉัน ฉันว่านี่ต้องเป็นสมบัติล้ำค่าจากอดีตที่ห่างไกลแน่ ๆ",
  str_homestory_822701001_4_dialog_content = "นี่คือตุ๊กตาวินเดเลียน",
  str_homestory_822701001_5_dialog_content = "เอาล่ะ ถ้าไม่ใช่เคเลสไทต์คนสุดท้าย! คุณมาตรงเวลาเลยนะ.",
  str_homestory_822701001_6_dialog_content = "เนื่องจากคุณรู้ชื่อของมัน คุณต้องสนิทกับสิ่งสร้างสรรค์ที่น่าทึ่งนี้มากแน่นอน",
  str_homestory_822701001_7_dialog_content = "มันเป็นแค่ของตกแต่งสำหรับเทศกาลวินเดเลียนเท่านั้น",
  str_homestory_822701001_8_dialog_content = "วินเดเลียน?",
  str_homestory_822701001_9_dialog_content = "มันคือวันหยุดของเคเลสไทต์ มีคนบอกฉันว่ามันคล้ายกับวิธีที่ออโรเรียนรำลึกถึงนักบุญและพระเจ้าแห่งแสงของพวกเขา",
  str_homestory_822701001_10_dialog_content = "นักบุญ? เทพเจ้าแห่งแสงสว่าง? ฟังดูเจ๋งจริง ๆ!",
  str_homestory_822701001_11_dialog_content = "ฉันไม่รู้เลยว่าโลกนี้มีวันหยุดที่เจ๋งขนาดนี้!",
  str_homestory_822701001_12_dialog_content = "เพื่อนของฉันก็ได้รู้จักวินเดเลียนจากหนังสือเช่นกันนะ",
  str_homestory_822701001_13_dialog_content = "สำหรับพวกเราชาวเคเลสไทต์ นี่เป็นวันหยุดที่สำคัญมากๆ",
  str_homestory_822701001_14_dialog_content = "ทุกปีในวันเทศกาลวินเดเลียน เราขอบคุณธรรมชาติโดยการจัดงานเลี้ยงอาหารที่ยิ่งใหญ่",
  str_homestory_822701001_15_dialog_content = "โอ้... ฟังแล้วมันก็ไม่ต่างจากวันหยุดอื่นๆ นักเลยนะ",
  str_homestory_822701001_16_dialog_content = "เอ่อ... ไม่ว่าอย่างไร ตุ๊กตานี้ก็เพียงแค่ของตกแต่งอีกอันที่ใช้ในการฉลองเทศกาลวินเดเลียนเท่านั้นเอง",
  str_homestory_822701001_17_dialog_content = "เราเติมลูกอมและความปรารถนาลงไปในท้องตุ๊กตา",
  str_homestory_822701001_18_dialog_content = "คุณพูดว่า... ลูกอมและความปรารถนา?",
  str_homestory_822701001_19_dialog_content = "เรามาทำกันเถอะ! ฉันอยากฉลองเทศกาลวินเดเลียนเลยตอนนี้!",
  str_homestory_822701001_20_dialog_content = "ทำไมคุณจู่ ๆ ตื่นเต้นขึ้นมาแบบนี้ล่ะ?",
  str_homestory_822701001_21_dialog_content = "ฉันก็อยากทำตุ๊กตาวินเดเลียนด้วยนะ!",
  str_homestory_822701001_22_option_content = "คุณสามารถทำพวกนั้นนอกจากช่วงเทศกาลได้นะครับ",
  str_homestory_822701001_23_dialog_content = "จริงเหรอ? งั้นแสดงให้ฉันเห็นวิธีทำหนึ่งอันนะ",
  str_homestory_822701001_24_option_content = "ได้เลย ฉันก็ไม่เห็นเหตุผลที่จะไม่จ่ายนะ",
  str_homestory_822701001_25_dialog_content = "จริงเหรอ? คุณเก่งที่สุดเลย!",
  str_homestory_822701001_26_dialog_content = "ฮี่ฮี่ และเมื่อฉันทำเสร็จแล้ว ฉันจะเติมท้องของมันด้วยผลงานล่าสุดของฉัน...",
  str_homestory_822701001_27_dialog_content = "เมื่อทุกคนเริ่มสงสัยว่ามีอะไรอยู่ข้างใน...",
  str_homestory_822701001_28_dialog_content = "ตูม! เป๊าะ! วู้ว! ควันและลูกอมจะประทุนออกมาเต็มที่!",
  str_homestory_822701001_29_dialog_content = "ห๊ะ? คุณไม่ได้จะใส่ระเบิดลงไปในนั้นใช่มั้ย?",
  str_homestory_822701001_30_dialog_content = "ใช่ ฉันคือ แต่อย่าเป็นห่วง! ฉันจะใช้เพียงพอที่จะส่งลูกอมบินไปทุกทิศทางเท่านั้น!",
  str_homestory_822801001_0_dialog_content = "บาเทีย",
  str_homestory_822801001_1_dialog_content = "คุณก็ออกมาภายนอกในที่สุด!",
  str_homestory_822801001_2_dialog_content = "อ้าว, หวัดดี...",
  str_homestory_822801001_3_dialog_content = "มีอะไรให้ช่วยมั้ย?",
  str_homestory_822801001_4_dialog_content = "ไม่ แค่ว่าคุณใช้เวลาทั้งวันอยู่ในเต็นท์เล่นเกมเท่านั้นเอง",
  str_homestory_822801001_5_dialog_content = "ฉันกำลังจะบอกให้คุณออกมาสูดอากาศบริสุทธิ์",
  str_homestory_822801001_6_dialog_content = "อ๊ะ... ฟู่...",
  str_homestory_822801001_7_dialog_content = "ที่นั่น เสร็จแล้ว แล้วเจอกัน",
  str_homestory_822801001_8_dialog_content = "W-เดี๋ยวก่อน! คุณควรจะไปเดินเล่นก่อนที่จะกลับเข้าไปในบ้าน คุณไม่คิดว่าเป็นไปอย่างนั้นหรือไม่?",
  str_homestory_822801001_9_dialog_content = "โอย, ที่กลางแจ้ง...",
  str_homestory_822801001_10_dialog_content = "ทำไมคุณถึงเกลียดการออกไปข้างนอกมากขนาดนั้น บาเทีย?",
  str_homestory_822801001_11_dialog_content = "คุณ...ไม่ชอบที่นี่เหรอ?",
  str_homestory_822801001_12_dialog_content = "ไม่เลยสักนิด! ไม่ใช่ว่าฉันไม่ชอบสถานที่นี้หรืออะไรนะ...",
  str_homestory_822801001_13_dialog_content = "ฉ-ฉันจริง ๆ แล้วชอบมันมากกว่าถนนของอัมบราตัน!",
  str_homestory_822801001_14_dialog_content = "โอ้... ดังนั้นนายเปรียบเทียบที่นี่กับอัมบราตันตลอดเวลานั้นเลยหรือ...",
  str_homestory_822801001_15_dialog_content = "ข-ขอโทษครับ ผมไม่ได้หมายความแบบนั้นนะ!",
  str_homestory_822801001_16_dialog_content = "ผ-ผมจริง ๆ แล้วคุ้นเคยกับถนนของอัมบราตันเท่านั้นครับ...",
  str_homestory_822801001_17_dialog_content = "ซึ่งเป็นเหตุผลที่ทำให้ควรไปเยือนสถานที่ต่าง ๆ มากขึ้น!",
  str_homestory_822801001_18_option_content = "แล้วเราควรไปที่ไหนดี?",
  str_homestory_822801001_19_dialog_content = "ริมแม่น้ำ.",
  str_homestory_822801001_20_dialog_content = "เราจะไปตกปลาที่แม่น้ำใกล้ๆ ได้ไหม?",
  str_homestory_822801001_21_dialog_content = "โอ้ ก็เหมือนกับเวอร์ชั่นในชีวิตจริงของ Fishing Master นี่แหละ!",
  str_homestory_822801001_22_dialog_content = "ฉันไม่แน่ใจว่าฉันจะจับปลาจริง ๆ ได้หรือไม่นะ...",
  str_homestory_822801001_23_dialog_content = "ฮ่าฮ่าฮ่า กติกาของเรานั้น มันแตกต่างจากเกมของคุณนิดหน่อยนะ",
  str_homestory_822801001_24_option_content = "ป่า.",
  str_homestory_822801001_25_dialog_content = "ไปค้างคืนในป่ากันเถอะ เราสามารถจุดค่ายไฟ เก็บผลไม้ป่า และทำอาหารกลางแจ้งได้!",
  str_homestory_822801001_26_dialog_content = "โอ้ ฟังดูเหมือนเกมแนวการจัดการเลยนะ",
  str_homestory_822801001_27_dialog_content = "วางแผนการพัฒนาค่ายของเราและปฏิบัติตามกระบวนการทำงานต่างๆ เพื่อให้มั่นใจว่ามีประสิทธิภาพสูงสุด...",
  str_homestory_822801001_28_dialog_content = "การตั้งแคมป์ไม่มีคะแนนหรือความสำเร็จนะ คุณรู้ไหม",
  str_homestory_822801001_29_dialog_content = "โอ้ โอเค ฉันคิดว่าฉันสามารถลองดูได้นะ",
  str_homestory_822801001_30_dialog_content = "แต่ฉันสามารถนำเต็นท์ของฉันไปได้หรือไม่ ถ้าเราจะออกไป?",
  str_homestory_822801001_31_dialog_content = "ถ้าเราเหนื่อย เราสามารถเข้าไปเล่นเกมในบ้านได้เสมอ",
  str_homestory_822801001_32_dialog_content = "ก็นะ ฉันคิดว่ามันคงไม่เสียหาย",
  str_homestory_822901001_0_dialog_content = "ท่านหญิงวิกตอเรีย ทำไมคุณถึงมองเก้าอี้แขวนอยู่เรื่อยๆ ครับ?",
  str_homestory_822901001_1_dialog_content = "มันมีอะไรผิดปกติหรือเปล่า?",
  str_homestory_822901001_2_dialog_content = "มันทำให้ฉันนึกถึงเก้าอี้แขวนที่คล้ายกันในทรู ออเดอร์",
  str_homestory_822901001_3_dialog_content = "นี่คือเก้าอี้ที่พวกเขาชื่นชอบที่สุด",
  str_homestory_822901001_4_dialog_content = "พวกเขาทำไมเหรอ?",
  str_homestory_822901001_5_dialog_content = "แปดครั้งจากสิบครั้งที่ผ่านไป ฉันจะเห็นเบริลนอนขดตัวอยู่ในมันและอ่านหนังสือ",
  str_homestory_822901001_6_dialog_content = "เธอหลับไปบนหนึ่งในหนังสือของเธอสำหรับอีกสองเล่ม",
  str_homestory_822901001_7_dialog_content = "งั้นเธอก็เอาไปเองสินะ!",
  str_homestory_822901001_8_dialog_content = "บางครั้งฉันเห็นเอซี่เดินรอบ ๆ มัน",
  str_homestory_822901001_9_dialog_content = "และเธอมักจะพึมพำสิ่งที่ส่วนใหญ่คนทั่วไปจะไม่เข้าใจเลย, เช่น...",
  str_homestory_822901001_10_dialog_content = "ถ้าเพิ่มหนามเหล็กใส่เบาะนั่งและพนักพิง มันจะกลายเป็นเครื่องทรมานที่สมบูรณ์แบบเลย!",
  str_homestory_822901001_11_dialog_content = "คุณต้องปกป้องเก้าอี้แขวนนั้นให้ดี ก่อนที่เธอจะได้มือถือมัน... และเบริลด้วยนะ!",
  str_homestory_822901001_12_dialog_content = "คุณไม่สามารถตำหนิเอซี่ที่คิดอย่างนั้นได้",
  str_homestory_822901001_13_dialog_content = "มันดูคล้ายกับเครื่องมือทรมานเมื่อถูกปกคลุมด้วยเลือดของเนลส์",
  str_homestory_822901001_14_dialog_content = "แม้แต่เนลส์?!",
  str_homestory_822901001_15_dialog_content = "คุณไม่สามารถตำหนิเนลส์ได้สำหรับสิ่งนั้น มันเป็นเก้าอี้ที่สบายจริง ๆ",
  str_homestory_822901001_16_dialog_content = "แม้แต่ผู้ศีลกัณฑ์ของเราก็อยากจะนั่งที่นั่นบ้างเป็นครั้งคราว",
  str_homestory_822901001_17_dialog_content = "...",
  str_homestory_822901001_18_dialog_content = "แล้ว... คุณคือคนเดียวที่ยังไม่เคยนั่งลงบนมันเหรอ?",
  str_homestory_822901001_19_dialog_content = "พอฉันคิดดูแล้ว คุณพูดถูก",
  str_homestory_822901001_20_dialog_content = "บางทีฉันกำลังหลีกเลี่ยงมัน",
  str_homestory_822901001_21_dialog_content = "หลบ... เก้าอี้เหรอ?",
  str_homestory_822901001_22_dialog_content = "มันมาจากบ้านเก่าของ Varaki และเคยเป็นของพ่อฉัน",
  str_homestory_822901001_23_dialog_content = "ฉันไม่รู้ว่าเฟาสต์คิดอะไรอยู่เมื่อเขานำมันกลับมาให้ฉัน",
  str_homestory_822901001_24_dialog_content = "การมองเห็นมันทำให้ฉันนึกถึงพ่อแม่ วัยเด็ก และโชคชะตาที่ไม่สามารถหลีเลี่ยงของ Varaki",
  str_homestory_822901001_25_dialog_content = "ฉัน... ไม่อยากจะต้องคิดถึงเรื่องราวทั้งหมดนั้นอีกต่อไป",
  str_homestory_822901001_26_dialog_content = "เฟาสต์ควรเรียนรู้วิธีการรักษารักษาตัวเอง",
  str_homestory_822901001_27_dialog_content = "เขาอาจจะพยายามเตือนฉันว่าการเผชิญหน้ากับชะตากรรมนั้นเป็นส่วนหนึ่งของความจริง",
  str_homestory_822901001_28_dialog_content = "เก้าอี้แขวนเป็นสิ่งที่ระลึกจากวัยเด็กของคุณ",
  str_homestory_822901001_29_dialog_content = "ความทรงจำเหล่านั้นอาจจะเจ็บปวด แต่ก็มีความสุขอยู่ในนั้นด้วย ใช่ไหม",
  str_homestory_822901001_30_dialog_content = "เฮ้, ฉันเดาว่า พ่อเคยกอดฉันในแขนขณะที่อ่านหนังสือบนเก้าอี้แขวน นั่นเป็นความทรงจำที่สวยงาม.",
  str_homestory_822901001_31_dialog_content = "อย่างไรก็ตาม, หลังจากที่ผ่านเหตุการณ์ล่าสุด ฉันในที่สุดก็เข้าใจแล้ว",
  str_homestory_822901001_32_dialog_content = "ความเจ็บปวดจากอดีตมีอยู่เพียงในหัวใจของฉันเท่านั้น",
  str_homestory_822901001_33_dialog_content = "ถ้าฉันสามารถเอาชนะมันได้ แล้วเก้าอี้แขวนนั้นก็จะเป็นเพียงแค่เก้าอี้แขวนเท่านั้นเอง",
  str_homestory_822901001_34_dialog_content = "เหมือนที่ภูมิปัญญาธรรมชาติของคุณชี้แนะไว้เลย",
  str_homestory_822901001_35_dialog_content = "ฉันไม่ควรจ้องมัน ฉันควรนั่งอย่างสบายบนมัน",
  str_homestory_822901001_36_dialog_content = "ย-ใช่แล้ว! นั่นแหละที่ฉันพยายามจะบอกคุณ!",
  str_homestory_822901001_37_dialog_content = "เชิญนั่งก่อนสิ คุณยินดีต้อนรับเสมอที่จะนั่งบนเก้าอี้แขวนของฉัน",
  str_homestory_822901001_38_dialog_content = "ขอบคุณสำหรับการต้อนรับนะ PlayerName",
  str_homestory_823001001_0_dialog_content = "บ้านนี้ดูแปลกๆ ใช่ไหม?",
  str_homestory_823001001_1_dialog_content = "แต่รูปลักษณ์ของมันทำให้เราหลงเชื่อ เพราะภายในมันสบายมาก!",
  str_homestory_823001001_2_dialog_content = "แปลก? ไม่เลย...",
  str_homestory_823001001_3_dialog_content = "โครงสร้างที่เหมือนหอคอยและการวางหน้าต่างทำให้มันดูเหมือนปราสาทขนาดเล็ก",
  str_homestory_823001001_4_dialog_content = "ถ้าคุณยินยอม ฉันอยากจะมาฝึกที่นี่บ้างเป็นครั้งคราว",
  str_homestory_823001001_5_dialog_content = "ได้เลย!",
  str_homestory_823001001_6_dialog_content = "ใช้สถานที่นี้ได้ทุกเมื่อที่คุณต้องการ",
  str_homestory_823001001_7_dialog_content = "ไม่มีเลย...",
  str_homestory_823001001_8_dialog_content = "ถ้าคุณสามารถรับประกันได้ว่าไม่มีเลือดที่จะหกที่นี่...",
  str_homestory_823001001_9_dialog_content = "ฉันขอขอบคุณความเอื้อเฟื้อของคุณตลอดไป",
  str_homestory_823001001_10_dialog_content = "เห trou นั้น นายวิลเฮล์มกำลังฝึกฝนอยู่ในปราสาทที่สงบใช่ไหมครับ?",
  str_homestory_823001001_11_dialog_content = "โอ้! ใ-ใช่... ทำไมคุณถึงพูดถึงที่ปรึกษาของฉันขึ้นมาอย่างกะทันหันล่ะ?",
  str_homestory_823001001_12_dialog_content = "ฉันกำลังคิดอยู่... คุณต้องการฝึกฝนในบ้านที่เหมือนปราสาทหรือไม่...",
  str_homestory_823001001_13_dialog_content = "เนื่องจากอิทธิพลของนายวิลเฮล์มหรือ?",
  str_homestory_823001001_14_dialog_content = "...",
  str_homestory_823001001_15_dialog_content = "การโกหกเป็นบาป แล้วเนื่องจากคุณเห็นทะลุเจตนาของฉัน ฉันก็สามารถยอมรับมันได้เท่านั้น",
  str_homestory_823001001_16_dialog_content = "ฉันมีความปรารถนาเล็ก ๆ น้อย ๆ ที่จะ... เลียนแบบอาจารย์ของฉัน",
  str_homestory_823001001_17_dialog_content = "แม้ว่าฉันจะสัญญากับเขาว่าฉันจะไม่ทำมัน",
  str_homestory_823001001_18_dialog_content = "การที่ผู้ไม่มีค่าเท่าฉันพยายามที่จะเป็นเหมือนอาจารย์ของฉันนั้นเป็นบาปที่น่าเกลียดชัง! ฉัน...",
  str_homestory_823001001_19_dialog_content = "นั่นไม่จริง! มันไม่ใช่เรื่องปกติหรือที่มีความปรารถนาที่จะเลียนแบบคนที่คุณเคารพหรือเปล่า?",
  str_homestory_823001001_20_dialog_content = "คุณพยายามเลียนแบบอะไรบ้าง?",
  str_homestory_823001001_21_dialog_content = "ฉัน...",
  str_homestory_823001001_22_dialog_content = "ฉันพยายาม... ปล่อยผมของฉันยาวลง",
  str_homestory_823001001_23_dialog_content = "...",
  str_homestory_823001001_24_dialog_content = "แต่ผมของฉันดูเหมือนจะไม่เหมาะสมกับสิ่งนั้น เหมือนว่ามีคู่นกกระจอกคิดว่าหัวของฉันคือรังของพวกมัน...",
  str_homestory_823001001_25_dialog_content = "ตอนที่ฉันสำนึกบาปเสร็จแล้ว ลูกไก่มันก็ฟักจากไข่บนหัวฉันแล้ว",
  str_homestory_823001001_26_dialog_content = "คุณจริงจังสำนึกบาปมานาน...",
  str_homestory_823001001_27_dialog_content = "หลังจากตัดผม ฉันพยายามถ่างตาตื่นและอ่านหนังสือทั้งคืนเหมือนอาจารย์ของฉัน",
  str_homestory_823001001_28_dialog_content = "แต่ฉันหลับไปขณะกำลังเดิน แล้วก็หกล้มลงบันได...",
  str_homestory_823001001_29_dialog_content = "เฮ้, เฮ้!",
  str_homestory_823001001_30_dialog_content = "ดาบของอาจารย์ของฉัน ที่ชื่อว่า Crimson Flow นี่เท่มากเลยนะ",
  str_homestory_823001001_31_dialog_content = "แต่พี่เลี้ยงของฉันได้หยุดฉันเมื่อฉันพยายามจำลอง Crimson Flow ด้วยเลือดของตัวเอง",
  str_homestory_823001001_32_dialog_content = "โอ้! เขาคงบอกให้คุณเป็นตัวของตัวเองใช่ไหม?",
  str_homestory_823001001_33_dialog_content = "พี่เลี้ยงของฉันถามฉันอย่างอ่อนโยน \"เนลส์ แหงนหน้าขึ้นแล้วบอกฉันสิ ว่าคุณเห็นอะไร\"",
  str_homestory_823001001_34_dialog_content = "ฉันตอบว่า \"ท้องฟ้านั่นแหละ พี่เลี้ยง พระเจ้าแห่งความจริงกำลังมองเราจากที่นั่น\"",
  str_homestory_823001001_35_dialog_content = "ครูของฉันถามว่า \"คุณรู้ไหมว่าทำไมเราถึงมองเห็นท้องฟ้าได้?\"",
  str_homestory_823001001_36_dialog_content = "ฉันตอบว่า \"เพราะท่านลอร์ดเป็นผู้สร้างมันขึ้นมา\"",
  str_homestory_823001001_37_dialog_content = "ครูของฉันบอกว่า \"เพราะคลื่นแดงของเธอเพิ่งเฉือนหลังคาของเราไป\"",
  str_homestory_823001001_38_dialog_content = "...",
  str_homestory_823001001_39_dialog_content = "ฉันสำนึกในบาปของตัวเองอย่างลึกซึ้ง",
  str_homestory_823001001_40_dialog_content = "แล้วฉันก็รู้ว่าฉันยังไม่ได้เรียนรู้สิ่งที่มีค่าที่สุดจากอาจารย์ของฉัน",
  str_homestory_823001001_41_dialog_content = "ที่ปรึกษาของฉันไม่เคยห่างไปจากความเชื่อของเขา",
  str_homestory_823001001_42_dialog_content = "และผมควรทำเช่นเดียวกัน ผมควรใช้ชีวิตตามที่ฉันเกิดมา",
  str_homestory_823001001_43_dialog_content = "ถ้าคุณสามารถสรุปได้จากการต่อเนื่องของภัยพิบัตินั้น... ฉันหมายถึงเหตุการณ์...",
  str_homestory_823001001_44_dialog_content = "คุณต้องเป็นคนที่เฉลียวฉลาดมาก",
  str_homestory_823001001_45_dialog_content = "ขอบคุณสำหรับคำชมเชย, PlayerName.",
  str_homestory_823001001_46_dialog_content = "เพื่อแลกเปลี่ยน ฉันยินดีที่จะฟังคำสารภาพของคุณในปราสาทเล็ก ๆ นี้เสมอ",
  str_homestory_823001001_47_dialog_content = "อะแฮ่ม, เรามาทำเมื่อฉันคิดเข้าใจแล้วนะ!",
  str_homestory_823101001_0_dialog_content = "นายวิลเฮล์ม ทำไมคุณจ้องศาลานั้น? ไม่มีอะไรอยู่ที่นั่นเลย",
  str_homestory_823101001_1_dialog_content = "ฉันสงสัยว่าศาลาของคุณนี้จะมีปริศนาซ่อนอยู่ใต้ดินหรือไม่?",
  str_homestory_823101001_2_dialog_content = "ปริศนา? จ-จริงหรอ...? ทำไมเธอถึงคิดแบบนั้น?",
  str_homestory_823101001_3_dialog_content = "ศาลาเดียวในดินแดนรกร้างมีความสัมพันธ์ที่เป็นธรรมชาติกับการผจญภัยและปริศนา",
  str_homestory_823101001_4_dialog_content = "เรื่องราวที่คล้ายกันเกิดขึ้นในตำนานหลายเรื่อง",
  str_homestory_823101001_5_dialog_content = "ฉันได้รับแรงบันดาลใจจากสิ่งนี้ และเคยเสนอคำถามให้กับวิกตอเรียครั้งหนึ่ง",
  str_homestory_823101001_6_dialog_content = "นะ ในศาลานั่น...",
  str_homestory_823101001_7_dialog_content = "ฉันเริ่มต้นด้วยการทำให้เธอรำคาญ...",
  str_homestory_823101001_8_dialog_content = "ทำไมคุณถึงทำเช่นนั้น!?",
  str_homestory_823101001_9_dialog_content = "มันเป็นงานที่ง่าย เนื่องจากเธอมักมีความรู้สึกอาฆาตมาใ towards ฉันเสมอ",
  str_homestory_823101001_10_dialog_content = "แต่จากที่เธอตะโกนว่า \"ไปตายสิ! ปีศาจ!\" แล้ววิ่งหนีไปด้วยดวงตาที่แดงออกเลือด...",
  str_homestory_823101001_11_dialog_content = "ฉันอาจจะไปไกลเกินไป",
  str_homestory_823101001_12_dialog_content = "ท่านหญิงวิกตอเรีย... มีชีวิตชีวามากในตอนนั้น ใช่ไหม?",
  str_homestory_823101001_13_dialog_content = "หลังจากนั้น ฉันได้ทิ้งร่องรอยต่าง ๆ อย่างตั้งใจเพื่อทำให้เธอคิดว่าวารากิมีสมบัติของบรรพบุรุษ",
  str_homestory_823101001_14_dialog_content = "และถ้าเธอหาเจอล่ะก็ เธอสามารถโค่นฉันลงและยึดคืนตำแหน่งหัวหน้าครอบครัวได้",
  str_homestory_823101001_15_dialog_content = "คุณมีความสัมพันธ์ที่บิดเบี้ยว...",
  str_homestory_823101001_16_dialog_content = "เธอไม่ทำให้ผิดหวัง เธอถอดความหมายจากเรื่องราวได้สำเร็จและสรุปได้ถูกต้อง",
  str_homestory_823101001_17_dialog_content = "ตำแหน่งของขุมทรัพย์ของบรรพบุรุษถูกเขียนไว้ที่ศาลาในส่วนที่ลึกของสวน",
  str_homestory_823101001_18_dialog_content = "แล้วเป็นยังไงต่อครับ",
  str_homestory_823101001_19_dialog_content = "แน่นอน การค้นหาศาลานั้นไม่ใช่จุดจบ",
  str_homestory_823101001_20_dialog_content = "เธอต้องแก้ปริศนาที่ถูกสลักลงบนแผ่นหินของระเบียงและเปิดเผยที่ตั้งที่แท้จริงของสมบัติ",
  str_homestory_823101001_21_dialog_content = "ฉันควรจะกล่าวว่าการทำให้แผ่นหินของฉันเก่าขึ้นด้วยวิธีที่ไม่เป็นธรรมชาติของฉันนั้นสมบูรณ์แบบ",
  str_homestory_823101001_22_dialog_content = "...",
  str_homestory_823101001_23_dialog_content = "เอาล่ะ... ปริศนาทั้งหมดนั้นคุณคิดเองเหรอ? มันคืออะไรบ้าง?",
  str_homestory_823101001_24_dialog_content = "พวกเขาไม่ใช่อะไร เพียงแค่คำถามความรู้ทั่วไปเกี่ยวกับประวัติศาสตร์, ตำนานและนิทาน, และปัญหาคณิตศาสตร์ไม่กี่ข้อเท่านั้น",
  str_homestory_823101001_25_dialog_content = "เธอจะต้องเรียนเพียงอาทิตย์เดียวก็จะผ่านมันไปได้ทั้งหมดแล้ว",
  str_homestory_823101001_26_dialog_content = "รู้สึกว่ามันจบไม่ดี...",
  str_homestory_823101001_27_dialog_content = "มันขึ้นอยู่กับวิธีที่คุณมอง และเธอสำเร็จ ดังที่ฉันคิดว่าเธอจะทำได้",
  str_homestory_823101001_28_dialog_content = "แต่ฉันจริงๆ แล้วหาคำตอบไม่ได้ว่าทำไมเธอถึงโกรธขนาดนั้นหลังจากพบสมบัติ...",
  str_homestory_823101001_29_dialog_content = "ฉันจะถามเธอตอนนี้เลย สมบัติที่เธอฝังไว้คืออะไร?",
  str_homestory_823101001_30_dialog_content = "น้ำผึ้งโปรดของวิกตอเรีย ขวดเต็มที่เพิ่งเก็บเกี่ยวในปีนั้น",
  str_homestory_823101001_31_dialog_content = "แค่นี้เหรอ!?",
  str_homestory_823101001_32_dialog_content = "นั่นไม่เพียงพอหรือ? มันเขียนไว้ชัดเจนใน \"วิธีการจัดการกับเด็กผู้หญิงวัยรุ่นที่กำลังต่อต้าน\"—",
  str_homestory_823101001_33_dialog_content = "\"เตรียมสิ่งที่เธอชอบ คุณไม่มีทางผิดหากเลือกของหวาน\"",
  str_homestory_823101001_34_dialog_content = "ฉันจริง ๆ ไม่เข้าใจว่าปัญหาคืออะไร",
  str_homestory_823101001_35_dialog_content = "ทำไมคุณไม่แค่ให้น้ำผึ้งให้เธอล่ะ?!",
  str_homestory_823101001_36_dialog_content = "จำได้ไหมว่าเธอมีความเคืองใจกับฉัน?",
  str_homestory_823101001_37_dialog_content = "การยั่วยุกันไม่น่าเบื่อเท่าไหร่ แต่มันเหนื่อยชะมัด",
  str_homestory_823101001_38_dialog_content = "ดังนั้น ฉันไม่รู้สึกว่ามันเป็นปัญหาที่จะทำให้เธอเบี่ยงเบนความสนใจไปที่อย่างอื่น",
  str_homestory_823101001_39_dialog_content = "เธอใช้เวลาอาทิตย์หนึ่งเพื่อศึกษาประวัติศาสตร์, นิทาน, และคณิตศาสตร์ ในขณะที่เต็มไปด้วยความร้อนใจ...",
  str_homestory_823101001_40_dialog_content = "แต่ในที่สุด ทั้งหมดที่เธอพบก็เพียงแค่โถน้ำผึ้งใหม่ มันไม่ต่างอะไรจากคุณที่ล้อเลียนเธอที่โดนหลอก...",
  str_homestory_823101001_41_dialog_content = "คุณยังไม่เข้าใจว่าทำไมเธอถึงโกรธหรือ?",
  str_homestory_823101001_42_dialog_content = "ที่พูดมาก็มีเหตุผล",
  str_homestory_823101001_43_dialog_content = "แต่นั่นไม่ใช่เหตุผลที่จะทำให้ฉันทาน้ำผึ้งลงบนที่นั่งของฉันก่อนการประชุมหัวหน้าครอบครัว...",
  str_homestory_823101001_44_dialog_content = "ฉันไม่มีทางเลือกเลย ต้องนั่งบนน้ำผึ้งและแสร้งทำเป็นว่าไม่มีอะไรผิดปกติตลอดเวลาที่ประชุม!",
  str_homestory_823101001_45_dialog_content = "คิดว่าไงบ้าง",
  str_homestory_823101001_46_dialog_content = "คุณสมควรได้รับมัน",
  str_homestory_823101001_47_dialog_content = "คุณได้รับสิ่งที่คุณสมควรได้รับ",
  str_homestory_823101001_48_dialog_content = "เชอะ..."
